const HERMES_CANDIDATES = {"package":"BM2 Hermes candidate import M31-M37","source_zip":"RPH-Semua-Subjek-FormatHub.zip","lesson_map_origin":"RPH Hub Supabase lesson_maps","date_reviewed":"2026-10-10","policy":"Source-first; DO NOT override Accuracy Gate or automatically promote needs_review sessions","status":"NOT_IMPORTED; REVIEW_REQUIRED","default_candidate_revision":"r1","alternative_revision":"r2","count_unique_sessions":33,"count_original_docx":66,"source_coverage":"weeks 31-37 only","missing_from_zip":"BM2 weeks 29-30 and week 38","lessons":[{"session_id":"BM2-M31-S1","week_no":31,"session_no":1,"lesson_map":{"title":"Amboi, Cantiknya!","sp":"1.2.1","page":43,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":31,"session":1,"revision":"r1","title_original":"Amboi, Cantiknya!","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.1","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat memberikan tiga penerangan lisan berkaitan kawasan rumah Hasan, termasuk tujuan benih pokok, dengan maklumat berasas gambar serta sekurang-kurangnya dua ungkapan bertatasusila.","success_criteria_original":"Tiga penerangan merangkumi keluarga yang menanam, kawasan bunga/hijau dan benih untuk dijual; nama spesies tidak direka.; Respons menjawab soalan pasangan, bukan menyebut label secara terpisah.; Ucapan selamat, permintaan sopan atau terima kasih digunakan pada tempat sesuai; bantuan guru direkod.","textbook_pages_original":"m/s 43,44","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk peta bulatan BT43 dan baca dua sumber maklumat, guru serta jabatan pertanian. Tanya siapa boleh membantu apabila kita tidak tahu cara menjaga pokok.\nAlihkan perhatian kepada halaman rumah Hasan pada BT44; minta murid menunjuk satu papan tanda tanpa meneka spesies pokok.\nTindakan murid: Sebut satu sumber maklumat pada peta bulatan dan kaitkan dengan pertanyaan tentang tanaman.\nCari papan tanda ZON BUNGA atau ZON HIJAU dan sebut apa yang boleh diketahui daripadanya.\nSemakan: Bezakan maklumat peta daripada gambar rumah. Jika murid menamakan spesies, minta bukti label; sebut pokok bunga secara umum jika tiada label.\nBahan: BT43–44 dan kad KAWASAN.","BBM/ABM":"BT43–44 dan kad KAWASAN.","PAK-21":"Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Dari mana maklumat pokok diperoleh?","execution_original":"Tindakan guru: Tunjuk peta bulatan BT43 dan baca dua sumber maklumat, guru serta jabatan pertanian. Tanya siapa boleh membantu apabila kita tidak tahu cara menjaga pokok.\nAlihkan perhatian kepada halaman rumah Hasan pada BT44; minta murid menunjuk satu papan tanda tanpa meneka spesies pokok.\nTindakan murid: Sebut satu sumber maklumat pada peta bulatan dan kaitkan dengan pertanyaan tentang tanaman.\nCari papan tanda ZON BUNGA atau ZON HIJAU dan sebut apa yang boleh diketahui daripadanya.\nSemakan: Bezakan maklumat peta daripada gambar rumah. Jika murid menamakan spesies, minta bukti label; sebut pokok bunga secara umum jika tiada label.\nBahan: BT43–44 dan kad KAWASAN.","aids_and_pak21_original":"BBM/ABM: BT43–44 dan kad KAWASAN.\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},{"phase_original":"Langkah 2\nModel dialog — Jawapan lengkap dan sopan","execution_original":"Tindakan guru: Baca dialog Seok Ling–Hasan. Berhenti selepas soalan siapa menanam dan tunjuk jawapan keluarga saya sendiri.\nModelkan respons tentang benih: contoh guru “Benih pokok itu untuk dijual.” Tunjuk papan tanda; bandingkan dengan jawapan terlalu pendek “jual” dan bincang ayat yang lebih jelas.\nTindakan murid: Baca ucapan sapaan berpasangan dan ulang satu respons lengkap dengan suara sendiri.\nTunjuk bukti bagi tujuan benih dan pilih ungkapan sopan yang sesuai selepas menerima maklumat.\nSemakan: Murid mesti memahami jawapan, bukan hafal perkataan. Tanya semula dengan bentuk “Untuk apakah benih ini?” untuk menyemak kefahaman.\nBahan: Dialog BT44, kad TUJUAN dan jalur ucapan sopan.","aids_and_pak21_original":"BBM/ABM: Dialog BT44, kad TUJUAN dan jalur ucapan sopan.\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},{"phase_original":"Langkah 3\nLatihan terbeza — Pemandu lawatan halaman Hasan","execution_original":"Tindakan guru: Agihkan laluan bantuan berdasarkan respons awal; semua menyediakan tiga penerangan menggunakan kad SIAPA–KAWASAN–TUJUAN.\nDengar murid yang memerlukan rangka dahulu, kemudian semak pasangan lain. Gunakan soalan “Ayat atau tanda mana membantu jawapan kamu?”; tarik balik kad jawapan apabila murid mula berdikari.\nTindakan murid: Pilih kata kunci sendiri sebelum melakonkan lawatan. Seok Ling bertanya, Hasan menjelaskan keadaan kawasan berdasarkan gambar.\nTukar peranan selepas tiga soalan supaya setiap murid berpeluang menerangkan, bukan seorang hanya memegang kad.\nSemakan: Jangan menganggap figura yang tidak berlabel membuktikan identiti setiap ahli keluarga. Gunakan nama daripada dialog dan huraian umum zon apabila jawapan bergantung gambar.\nBahan: Kad fokus, kad watak, BT44 dan rangka mengikut laluan.","aids_and_pak21_original":"BBM/ABM: Kad fokus, kad watak, BT44 dan rangka mengikut laluan.\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},{"phase_original":"Langkah 4\nSoalan susulan — Jawapan mesti berasas","execution_original":"Tindakan guru: Tanya “Bagaimanakah kita tahu benih itu bukan semata-mata hiasan?” dan “Apakah bukti kawasan ini dijaga?”\nTerima alasan papan tanda serta perbuatan berkebun yang jelas. Jika murid mengemukakan idea penjagaan baharu, label sebagai cadangan murid, bukan perkara yang semestinya berlaku dalam gambar.\nTindakan murid: Pasangan memilih satu soalan susulan dan memberi peluang rakan berfikir sebelum menjawab.\nPisahkan penerangan gambar daripada cadangan: “Dalam gambar …; cadangan saya …”.\nSemakan: Utamakan kejelasan penerangan. Tidak wajib menggunakan frasa pada pendapat saya bagi maklumat yang dinyatakan terus oleh papan tanda.\nBahan: BT44, kad soalan susulan dan jalur bukti.","aids_and_pak21_original":"BBM/ABM: BT44, kad soalan susulan dan jalur bukti.\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},{"phase_original":"Langkah 5\nPBD — Tiga penerangan individu","execution_original":"Tindakan guru: Dengar penerangan individu menggunakan tiga kata kunci sahaja. Rekod bukti daripada latihan terdahulu jika telah mendengar respons murid.\nTanda ketepatan maklumat, respons soalan dan dua ungkapan sopan. Murid belum didengar ditanda belum diperhatikan untuk susulan, bukan automatik lulus.\nTindakan murid: Jelaskan siapa menanam, kawasan tanaman dan tujuan benih dengan ayat sendiri.\nGunakan sapaan atau terima kasih pada giliran yang sesuai; jawab satu pertanyaan guru tanpa pasangan membisikkan jawapan.\nSemakan: Jika baru dua isi tepat, catat pencapaian separa dan ulang fokus yang hilang. Kualiti pertuturan tidak diukur melalui tulisan cantik pada kad.\nBahan: Jalur kata kunci dan senarai semak lisan.","aids_and_pak21_original":"BBM/ABM: Jalur kata kunci dan senarai semak lisan.\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},{"phase_original":"Langkah 6\nPenutup — Terima kasih atas maklumat","execution_original":"Tindakan guru: Minta seorang penanya dan seorang penerang menunjukkan cara menutup perbualan dengan sopan.\nRumusan bahawa penjelasan baik mempunyai maklumat tepat, ayat jelas dan adab bercakap. Nyatakan latihan susulan berdasarkan respons yang masih pendek.\nTindakan murid: Sebut satu ayat lengkap tentang benih atau zon dan tutup perbualan dengan ucapan sesuai.\nNyatakan satu perkara yang perlu dilihat semula sebelum memberi jawapan yakin.\nSemakan: Gunakan respons akhir untuk membezakan masalah kurang maklumat daripada masalah membina ayat lisan.\nBahan: Kad ungkapan sopan dan buku.","aids_and_pak21_original":"BBM/ABM: Kad ungkapan sopan dan buku.\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Papan tanda dan rangka ayat","implementation_original":"Tugasan: Memberikan tiga penerangan dengan kad fokus serta rangka yang dikurangkan selepas percubaan pertama.\nBahan: Kad bergambar zon bunga, zon hijau dan papan tanda benih\nRangka “Keluarga Hasan …”, “Di kawasan ini …”, “Benih ini untuk …”\nDua ucapan sopan pilihan\nBimbingan guru: Bacakan soalan satu demi satu dan tunjuk lokasi bukti, bukan memberi semua jawapan untuk dihafal.\nApabila satu jawapan tepat, tutup frasa pelengkap supaya murid cuba menyebut semula berdasarkan gambar.\nLangkah murid: Padankan kad fokus dengan bahagian gambar.\nPilih kata pelengkap dan sebut satu ayat penuh.\nLakukan tiga giliran soal jawab dengan pasangan sambil menggunakan sapaan serta terima kasih.\nTukar peranan dan cuba ulang penerangan tanpa ayat model lengkap.\nHasil individu: Tiga respons lisan individu, disokong jalur kata kunci.\nKriteria: Tiga isi tepat dan dua ungkapan sopan dengan bantuan yang dinyatakan; jika hanya satu atau dua isi, objektif penuh belum selesai.\nSusulan: Ulang soalan siapa/untuk apa secara berasingan jika tertukar, kemudian gabungkan dalam dialog sekali lagi.","aids_and_pak21_original":"BBM/ABM: Kad bergambar zon bunga, zon hijau dan papan tanda benih\nRangka “Keluarga Hasan …”, “Di kawasan ini …”, “Benih ini untuk …”\nDua ucapan sopan pilihan\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},"pembina":{"label":"Langkah 1\nPembina — Penerangan daripada gambar asal","implementation_original":"Tugasan: Memilih tiga maklumat dan melengkapkan respons dialog tanpa pilihan ayat penuh.\nBahan: BT44\nKad SIAPA–KAWASAN–TUJUAN tanpa jawapan\nKad watak Hasan dan Seok Ling\nBimbingan guru: Minta murid menunjuk papan tanda ketika menerangkan tujuan benih; semak kata ganti saya/kamu sesuai watak.\nBeri satu soalan lanjutan apabila jawapan hanya satu perkataan, tetapi jangan terus membekalkan ayat lengkap.\nLangkah murid: Perhatikan gambar dan tulis tiga kata kunci sendiri.\nJawab soalan pasangan dengan ayat lengkap serta bahasa sopan.\nTukar watak dan ajukan soalan dengan nada yang sesuai.\nDengar komen rakan tentang satu jawapan yang kurang jelas lalu perbaiki sendiri.\nHasil individu: Tiga penerangan lisan berturutan dan satu respons soalan susulan.\nKriteria: Tepat pada konteks, dapat difahami dan menggunakan sekurang-kurangnya dua ungkapan sopan; tidak perlu meniru skrip contoh perkataan demi perkataan.\nSusulan: Jika mantap, bezakan satu cadangan penjagaan daripada fakta gambar; jika belum, kembali kepada kad fokus yang belum dikuasai.","aids_and_pak21_original":"BBM/ABM: BT44\nKad SIAPA–KAWASAN–TUJUAN tanpa jawapan\nKad watak Hasan dan Seok Ling\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."},"pencabar":{"label":"Langkah 1\nPencabar — Jelaskan dan batas dakwaan","implementation_original":"Tugasan: Menerangkan tiga maklumat serta menjawab soalan yang menguji beza fakta gambar dengan andaian.\nBahan: BT44\nKad “Semua pokok ini pokok mawar” berlabel dakwaan rekaan guru\nJalur Fakta gambar/Cadangan\nBimbingan guru: Tanya bukti nama spesies pada gambar. Bimbing murid mengatakan maklumat belum pasti tanpa rasa jawapannya gagal.\nMinta satu cadangan menjaga halaman, tetapi tegaskan itu idea murid dan bukan petikan buku.\nLangkah murid: Lengkapkan dialog tiga penerangan seperti sasaran teras.\nNilai dakwaan spesies menggunakan label yang benar-benar ada.\nBina ayat sopan untuk menjelaskan batas maklumat, contohnya nama spesies tidak dinyatakan.\nBerikan satu cadangan penjagaan yang berbeza daripada fakta lalu jawab pertanyaan pasangan.\nHasil individu: Tiga penerangan, satu penilaian dakwaan dan satu cadangan berlabel.\nKriteria: Sasaran teras dicapai serta alasan membezakan fakta dengan andaian; bukan banyaknya nama tumbuhan yang diketahui.\nSusulan: Cuba soalan baharu tentang tujuan benih sambil tetap mengekalkan bukti papan tanda dan adab perbualan.","aids_and_pak21_original":"BBM/ABM: BT44\nKad “Semua pokok ini pokok mawar” berlabel dakwaan rekaan guru\nJalur Fakta gambar/Cadangan\nPAK-21: Role Play: seorang bertanya sebagai Seok Ling, seorang menjelaskan sebagai Hasan; kedua-duanya bertukar peranan. Think–Pair–Share digunakan untuk memilih bukti gambar sebelum bercakap, bukan mengulang skrip guru serentak."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian respons lisan dan simulasi bergilir.","Evidens":"Tiga penerangan oleh setiap murid, dua ungkapan sopan dan jawapan kepada pertanyaan.","Kriteria Kejayaan":"Maklumat betul, ayat jelas, adab sesuai; bantuan dicatat tanpa TP automatik."},"closure_original":"Tindakan guru: Minta seorang penanya dan seorang penerang menunjukkan cara menutup perbualan dengan sopan.\nRumusan bahawa penjelasan baik mempunyai maklumat tepat, ayat jelas dan adab bercakap. Nyatakan latihan susulan berdasarkan respons yang masih pendek.\nTindakan murid: Sebut satu ayat lengkap tentang benih atau zon dan tutup perbualan dengan ucapan sesuai.\nNyatakan satu perkara yang perlu dilihat semula sebelum memberi jawapan yakin.\nSemakan: Gunakan respons akhir untuk membezakan masalah kurang maklumat daripada masalah membina ayat lisan.\nBahan: Kad ungkapan sopan dan buku.","reflection_original":"____ / ____ murid memberi tiga penerangan; ____ memerlukan rangka ayat; ____ belum diperhatikan. Fokus yang masih keliru: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M31-S1.docx","source_docx_sha256":"e2f68dbbc5719e4ea06e75524e43ccea63eb289fdbbfdaf33230e58428d7c228","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":31,"session":1,"revision":"r2","title_original":"Amboi, Cantiknya!","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.1","sp_support_original":"—","objective_original":"Murid dapat menjelaskan cara mencantikkan halaman rumah dengan bahasa yang sopan.","success_criteria_original":"Menyebut dua cara mencantikkan halaman rumah.; Menggunakan bahasa yang sopan semasa menjawab.","textbook_pages_original":"m/s 43,44","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk gambar halaman rumah Hasan.\nGuru tanya, “Apakah yang kamu nampak?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut pokok atau bunga yang dilihat.\nSemakan: Bantu murid menyebut nama benda dalam gambar.\nBahan: Buku teks halaman 44","BBM/ABM":"Buku teks halaman 44","PAK-21":"Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},"six_phases_original":[{"phase_original":"Langkah 1\nLihat gambar","execution_original":"Tindakan guru: Guru tunjuk gambar halaman rumah Hasan.\nGuru tanya, “Apakah yang kamu nampak?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut pokok atau bunga yang dilihat.\nSemakan: Bantu murid menyebut nama benda dalam gambar.\nBahan: Buku teks halaman 44","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 44\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},{"phase_original":"Langkah 2\nDengar contoh guru","execution_original":"Tindakan guru: Guru baca dialog Seok Ling dan Hasan dengan suara yang jelas.\nGuru tunjuk contoh jawapan: “Saya menanam pokok bunga untuk mencantikkan halaman.”\nTindakan murid: Murid mendengar dialog.\nMurid mengulang contoh jawapan bersama-sama.\nSemakan: Betulkan sebutan dengan memberi contoh semula.\nBahan: Buku teks\nKad bantuan ayat","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad bantuan ayat\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru tunjuk kawasan berlabel ZON BUNGA dan ZON HIJAU.\nGuru bimbing jawapan tentang benih: “Benih pokok itu untuk dijual.”\nTindakan murid: Murid menyebut cara mencantikkan kedua-dua kawasan.\nMurid menjawab soalan tentang benih secara lisan.\nSemakan: Terima jawapan pendek yang sesuai dengan gambar.\nBahan: Gambar buku teks\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Gambar buku teks\nKad perkataan\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},{"phase_original":"Langkah 4\nBercakap dengan rakan","execution_original":"Tindakan guru: Guru beri soalan: “Bagaimanakah kamu mencantikkan halaman?”\nGuru bantu murid yang masih memerlukan contoh ayat.\nTindakan murid: Murid bertanya kepada pasangan.\nMurid menjawab menggunakan perkataan bunga atau pokok hijau. Mereka bertukar peranan.\nSemakan: Gunakan bantuan yang sesuai seperti dalam bahagian PdP terbeza.\nBahan: Buku teks\nKad bantuan ayat","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad bantuan ayat\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},{"phase_original":"Langkah 5\nCuba sendiri","execution_original":"Tindakan guru: Guru minta murid menyebut cara mencantikkan halaman berdasarkan gambar.\nGuru dengar jawapan murid semasa bergerak dari meja ke meja.\nTindakan murid: Murid menyebut dua cara yang telah dipelajari.\nMurid membaiki jawapan selepas dibantu guru.\nSemakan: Catat sama ada murid boleh menjelaskan atau masih memerlukan bantuan.\nBahan: Buku teks\nSenarai semak guru","aids_and_pak21_original":"BBM/ABM: Buku teks\nSenarai semak guru\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru ajak murid mengulang cara menjaga halaman supaya cantik.\nGuru ingatkan murid menggunakan ucapan terima kasih semasa berbual.\nTindakan murid: Murid berkongsi satu cara menjaga pokok.\nMurid mengucapkan terima kasih kepada pasangan.\nSemakan: Ulang perkataan yang masih sukar disebut.\nBahan: Kad perkataan","aids_and_pak21_original":"BBM/ABM: Kad perkataan\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Menjawab tentang pokok dalam gambar dengan bantuan ayat.\nBahan: Gambar halaman rumah\nKad bunga dan pokok hijau\nSaya menanam ___.\nBimbingan guru: Guru tunjuk satu kawasan pada satu masa.\nGuru sebut contoh ayat bersama murid.\nLangkah murid: Pilih perkataan yang sesuai.\nLengkapkan ayat secara lisan bersama guru.\nCuba sebut jawapan kepada rakan.\nHasil individu: Jawapan lisan tentang halaman.\nKriteria: Murid dapat menyampaikan maksud dengan bantuan.\nSusulan: Ulang menggunakan gambar yang sama sehingga murid lebih yakin.","aids_and_pak21_original":"BBM/ABM: Gambar halaman rumah\nKad bunga dan pokok hijau\nSaya menanam ___.\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Berbual tentang cara mencantikkan halaman rumah Hasan.\nBahan: Buku teks\nKad pokok bunga dan pokok hijau\nBimbingan guru: Guru beri contoh soalan kepada pasangan.\nGuru bantu jika murid terlupa perkataan.\nLangkah murid: Lihat kawasan dalam gambar.\nTanya dan jawab dengan rakan.\nSebut sendiri dua cara mencantikkan halaman.\nHasil individu: Dua cara yang disebut secara lisan.\nKriteria: Jawapan sesuai dengan gambar dan disampaikan dengan sopan.\nSusulan: Minta murid cuba dengan kurang bantuan apabila bersedia.","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad pokok bunga dan pokok hijau\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menambah satu ayat tentang menjaga pokok yang ditanam.\nBahan: Gambar halaman rumah\nBimbingan guru: Guru tanya, “Selepas menanam, apakah yang kita buat?”\nGuru beri pilihan perkataan siram atau jaga jika perlu.\nLangkah murid: Sebut cara mencantikkan halaman.\nTambah satu ayat tentang penjagaan pokok.\nSampaikan jawapan kepada pasangan dengan sopan.\nHasil individu: Jawapan lisan yang sedikit lebih lengkap.\nKriteria: Ayat tambahan mudah difahami dan sesuai dengan topik.\nSusulan: Beri peluang berkongsi tanpa mewajibkan jawapan panjang.","aids_and_pak21_original":"BBM/ABM: Gambar halaman rumah\nPAK-21: Perbualan berpasangan: seorang bertanya dan seorang menjawab tentang halaman rumah Hasan."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian dan soal jawab semasa latihan.","Evidens":"Jawapan lisan setiap murid.","Kriteria Kejayaan":"Murid menyebut dua cara mencantikkan halaman dengan bahasa yang sopan."},"closure_original":"Tindakan guru: Guru ajak murid mengulang cara menjaga halaman supaya cantik.\nGuru ingatkan murid menggunakan ucapan terima kasih semasa berbual.\nTindakan murid: Murid berkongsi satu cara menjaga pokok.\nMurid mengucapkan terima kasih kepada pasangan.\nSemakan: Ulang perkataan yang masih sukar disebut.\nBahan: Kad perkataan","reflection_original":"__ daripada __ murid dapat menjelaskan cara mencantikkan halaman rumah. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M31-S1.docx","source_docx_sha256":"6bb5e4cff30a0c915b6aac1e87ff779d13f97f896ab904b242f593d85d1a59be","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M31-S2","week_no":31,"session_no":2,"lesson_map":{"title":"Mudahnya Halau Serangga","sp":"2.2.1","page":45,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":31,"session":2,"revision":"r1","title_original":"Mudahnya Halau Serangga","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1(i)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat menjelaskan maksud sekurang-kurangnya lima kosa kata berwarna daripada petikan Mudahnya Halau Serangga dengan merujuk ayat yang menyokong maksud tersebut.","success_criteria_original":"Lima perkataan dan maksud dipadankan mengikut konteks petikan, bukan berdasarkan rupa kad sahaja.; Sekurang-kurangnya dua maksud diterangkan dengan frasa bukti daripada ayat; tumbuh bermaksud hidup ialah contoh yang disediakan buku.; Murid membezakan perkataan benda seperti penyembur daripada perbuatan menyembur apabila menerangkan maksud.","textbook_pages_original":"m/s 45","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca ayat tentang daun pokok paku gunung yang diserang ulat. Tanya apakah masalah pokok sebelum Encik Mahzan mencari maklumat.\nTunjuk perkataan diserang dan minta murid mencadangkan maksud dalam konteks daun, bukan serangan manusia.\nTindakan murid: Sebut ulat merosakkan atau memakan daun berdasarkan petikan.\nCari perkataan daun/ulat yang membantu mereka menerangkan maksud diserang.\nSemakan: Terima penerangan mudah yang sepadan konteks. Jika jawapan terlalu umum, baca kembali ayat sekitar perkataan.\nBahan: BT45 dan jalur ayat diserang ulat.","BBM/ABM":"BT45 dan jalur ayat diserang ulat.","PAK-21":"Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Masalah daun Encik Mahzan","execution_original":"Tindakan guru: Baca ayat tentang daun pokok paku gunung yang diserang ulat. Tanya apakah masalah pokok sebelum Encik Mahzan mencari maklumat.\nTunjuk perkataan diserang dan minta murid mencadangkan maksud dalam konteks daun, bukan serangan manusia.\nTindakan murid: Sebut ulat merosakkan atau memakan daun berdasarkan petikan.\nCari perkataan daun/ulat yang membantu mereka menerangkan maksud diserang.\nSemakan: Terima penerangan mudah yang sepadan konteks. Jika jawapan terlalu umum, baca kembali ayat sekitar perkataan.\nBahan: BT45 dan jalur ayat diserang ulat.","aids_and_pak21_original":"BBM/ABM: BT45 dan jalur ayat diserang ulat.\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},{"phase_original":"Langkah 2\nModel kamus konteks — Tumbuh bukan sekadar bunyi","execution_original":"Tindakan guru: Tunjukkan contoh buku tumbuh–hidup. Modelkan jadual tiga lajur: perkataan, maksud dan petunjuk daripada ayat.\nBandingkan frasa tumbuh subur dengan menghijau kembali. Terangkan bahawa subur menerangkan pertumbuhan baik, bukan sekadar warna; jangan memaksa semua maksud menjadi sinonim satu kata.\nTindakan murid: Baca ayat model, sebut maksud tumbuh dan tunjuk subjek pokok.\nCuba menerangkan subur dengan kata sendiri, kemudian semak sama ada maksudnya sesuai apabila dibaca dalam ayat.\nSemakan: Jika murid menyalin perkataan sama sebagai maksud, minta mereka menjelaskan kepada rakan yang belum mengenal perkataan itu.\nBahan: Contoh jadual guru, BT45 dan kad tumbuh/subur.","aids_and_pak21_original":"BBM/ABM: Contoh jadual guru, BT45 dan kad tumbuh/subur.\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},{"phase_original":"Langkah 3\nLatihan terbeza — Lima entri kamus Encik Mahzan","execution_original":"Tindakan guru: Agihkan kad dan tahap bantuan mengikut tiga laluan di bawah. Semua murid meneliti kosa kata petikan; sasaran bersama ialah lima maksud yang tepat.\nBimbing murid membaca ayat sebelum memilih maksud. Gunakan soalan “Adakah perkataan ini alat atau perbuatan?” untuk penyembur; jangan menganggap padanan kad sahaja membuktikan kefahaman.\nTindakan murid: Cari perkataan berwarna dalam ayat dan pilih lima untuk jadual sendiri; perkataan yang sama boleh dibincang tetapi ayat bukti mesti dikenal pasti.\nBergilir sebagai pencari dan penjelas. Semak pilihan maksud dengan menggantikannya secara lisan dalam konteks ayat, kemudian catat dengan frasa ringkas.\nSemakan: Pastikan perkataan yang tidak berwarna seperti menapis tidak didakwa sasaran berwarna buku. Ia boleh diterangkan sebagai sokongan tetapi tidak menggantikan senarai yang disahkan.\nBahan: Kad kosa kata, jalur ayat, jadual individu dan pilihan bantuan.","aids_and_pak21_original":"BBM/ABM: Kad kosa kata, jalur ayat, jadual individu dan pilihan bantuan.\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},{"phase_original":"Langkah 4\nUji beza makna — Alat, proses dan keadaan","execution_original":"Tindakan guru: Paparkan penyembur–menyembur serta tumbuh–subur. Modelkan satu soalan tentang fungsi perkataan tanpa mengubah objektif kepada pengelasan tatabahasa formal.\nMinta dua pasangan menerangkan mengapa racun ialah bahan dan basuhan berkaitan proses membasuh. Tegaskan bahawa maksud mesti dipilih daripada penggunaan dalam petikan.\nTindakan murid: Sebut satu perbezaan antara pasangan perkataan dengan contoh ayat asal.\nBaiki satu entri kamus jika maksud awal terlalu luas atau tidak sesuai; tulis sebab ringkas bagi pembetulan.\nSemakan: Makna alternatif yang setara diterima. Jangan menandai salah kerana murid menggunakan frasa berbeza daripada kad jawapan guru.\nBahan: Kad pasangan makna dan BT45.","aids_and_pak21_original":"BBM/ABM: Kad pasangan makna dan BT45.\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},{"phase_original":"Langkah 5\nPBD — Lima maksud, dua bukti ayat","execution_original":"Tindakan guru: Semak lima entri setiap murid dan pilih dua untuk diterangkan secara lisan atau dengan menunjuk frasa bukti.\nRekod ketepatan makna, rujukan ayat dan bantuan. Padanan yang dibantu terus oleh rakan ditanda perlu semakan kendiri.\nTindakan murid: Serahkan jadual lima perkataan dan maksud; baca semula dua ayat sumber yang berkaitan.\nJelaskan pilihan maksud atau betulkan satu padanan selepas soalan guru tanpa melihat jawapan pasangan.\nSemakan: PBD berfokus kosa kata, bukan soalan umum tentang cara membuat racun. Murid belum diperhatikan untuk penjelasan ditanda susulan.\nBahan: Kamus konteks individu dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Kamus konteks individu dan senarai semak.\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},{"phase_original":"Langkah 6\nPenutup — Cara mencari maksud seterusnya","execution_original":"Tindakan guru: Tanya urutan bantuan: baca perkataan, baca ayat sekitar, cadangkan maksud, semak semula dalam konteks.\nPilih satu perkataan yang masih sukar untuk latihan susulan, bukannya meminta murid menghafal semua maksud tanpa konteks.\nTindakan murid: Sebut satu perkataan dengan maksudnya dan satu petunjuk yang digunakan.\nPulangkan kad mengikut perkataan dan maksud serta tandakan entri yang hendak dibaca semula.\nSemakan: Gunakan kekeliruan tumbuh/subur atau alat/perbuatan untuk intervensi yang khusus.\nBahan: Kad kosa kata dan jadual kamus.","aids_and_pak21_original":"BBM/ABM: Kad kosa kata dan jadual kamus.\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Petunjuk ayat dan pilihan terhad","implementation_original":"Tugasan: Memadankan lima perkataan dengan maksud sambil belajar menggunakan ayat sekeliling sebagai petunjuk.\nBahan: Lima kad pilihan guru: tumbuh, diserang, basuhan, penyembur dan subur\nAyat sumber bergaris pada petunjuk utama\nDua pilihan maksud bagi setiap kad\nBimbingan guru: Baca satu ayat, tunjuk kata pokok/ulat/air yang memberi konteks, kemudian modelkan satu padanan sahaja.\nBagi perkataan seterusnya, minta murid memilih dan menyebut sebab sebelum mengesahkan; kurangkan pilihan jawapan apabila sudah yakin.\nLangkah murid: Cari perkataan pada jalur ayat dan sebut bersama guru.\nPilih maksud daripada dua pilihan dan uji semula dalam ayat.\nCatat lima entri dengan frasa ringkas, bukan menyalin semua perenggan.\nTerangkan dua pilihan kepada pasangan lalu cuba satu semula tanpa kad maksud.\nHasil individu: Jadual lima maksud individu dengan dua petunjuk ayat ditandai.\nKriteria: Lima padanan tepat dengan bantuan dicatat; jika baru tiga tepat, rekod kemajuan sokongan dan lanjutkan dua yang berbaki.\nSusulan: Ulang satu perkataan menggunakan objek gambar atau gerak kecil yang sesuai, kemudian kembali kepada ayat asal untuk mengelakkan padanan visual semata-mata.","aids_and_pak21_original":"BBM/ABM: Lima kad pilihan guru: tumbuh, diserang, basuhan, penyembur dan subur\nAyat sumber bergaris pada petunjuk utama\nDua pilihan maksud bagi setiap kad\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},"pembina":{"label":"Langkah 1\nPembina — Kamus tanpa pilihan jawapan","implementation_original":"Tugasan: Menjelaskan lima kata berwarna menggunakan konteks dan menyemak maksud bersama rakan.\nBahan: BT45\nJadual kosong Kosa kata–Maksud–Petunjuk\nKad soalan “Bahagian ayat mana membantu?”\nBimbingan guru: Bimbing murid menggunakan frasa makna yang mudah tanpa menyalin maksud daripada rakan secara terus.\nJika jawapan kabur, arah murid kembali kepada satu ayat sebelum dan selepas perkataan sasaran.\nLangkah murid: Pilih lima kata berwarna dan catat lokasi ayat.\nTulis maksud dengan kata sendiri berdasarkan penggunaan dalam petikan.\nBaca kepada pasangan yang meminta bukti bagi dua entri.\nBaiki maksud yang tidak sesuai dan jelaskan satu perubahan kepada guru.\nHasil individu: Lima entri kamus konteks dengan dua alasan pemilihan.\nKriteria: Maksud munasabah, perkataan dan bukti sepadan, serta murid dapat menerangkan tanpa menghafal kad jawapan.\nSusulan: Jika tepat, bandingkan subur dengan tumbuh; jika belum, gunakan satu ayat sokongan dan cuba padanan semula.","aids_and_pak21_original":"BBM/ABM: BT45\nJadual kosong Kosa kata–Maksud–Petunjuk\nKad soalan “Bahagian ayat mana membantu?”\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."},"pencabar":{"label":"Langkah 1\nPencabar — Makna hampir sama, fungsi berbeza","implementation_original":"Tugasan: Membina lima entri dan menilai perbezaan antara dua perkataan berkaitan tanpa keluar daripada konteks Encik Mahzan.\nBahan: BT45\nKad tumbuh/subur dan penyembur/menyembur\nJalur ayat contoh guru untuk perbandingan\nBimbingan guru: Minta murid menjelaskan maksud yang hilang jika subur diganti dengan tumbuh sahaja.\nTegaskan bahawa menyembur boleh digunakan untuk perbandingan guru tetapi perkataan berwarna ialah penyembur; jangan mengelirukan sumber.\nLangkah murid: Lengkapkan lima entri kamus dengan bukti.\nPilih satu pasangan dan sebut perbezaan makna atau fungsi dalam ayat.\nBina dua contoh ayat pendek berlabel contoh sendiri untuk menguji perbezaan.\nSemak ayat dengan rakan dan kekalkan atau ubah maksud berdasarkan konteks.\nHasil individu: Kamus lima entri serta satu perbandingan makna bersebab; dua contoh ayat sebagai bukti tambahan.\nKriteria: Sasaran teras dicapai dan perbezaan diterangkan dengan tepat; bukan banyaknya istilah sukar atau perkataan luar petikan.\nSusulan: Cuba menerangkan satu kata lain seperti permintaan melalui situasi jualan pokok, tanpa mereka harga atau angka jualan.","aids_and_pak21_original":"BBM/ABM: BT45\nKad tumbuh/subur dan penyembur/menyembur\nJalur ayat contoh guru untuk perbandingan\nPAK-21: Kamus konteks berpasangan: pencari menunjukkan perkataan dalam ayat, penjelas mencadangkan maksud dan memberi sebab, kemudian bertukar peranan. Hasil kamus individu tidak digantikan dengan satu padanan kumpulan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan kamus konteks dan penjelasan ringkas berdasarkan ayat.","Evidens":"Lima maksud kosa kata dan dua petunjuk ayat daripada murid sendiri.","Kriteria Kejayaan":"Makna tepat dalam konteks, tidak sekadar menyalin kata asal; bantuan direkod."},"closure_original":"Tindakan guru: Tanya urutan bantuan: baca perkataan, baca ayat sekitar, cadangkan maksud, semak semula dalam konteks.\nPilih satu perkataan yang masih sukar untuk latihan susulan, bukannya meminta murid menghafal semua maksud tanpa konteks.\nTindakan murid: Sebut satu perkataan dengan maksudnya dan satu petunjuk yang digunakan.\nPulangkan kad mengikut perkataan dan maksud serta tandakan entri yang hendak dibaca semula.\nSemakan: Gunakan kekeliruan tumbuh/subur atau alat/perbuatan untuk intervensi yang khusus.\nBahan: Kad kosa kata dan jadual kamus.","reflection_original":"____ / ____ murid menjelaskan lima maksud; ____ memerlukan petunjuk ayat; ____ perlu semakan dua penjelasan individu. Perkataan yang masih keliru: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M31-S2.docx","source_docx_sha256":"0c4b9d583b32bdfad5b73dd52f20cbc7c3c37d375f3d89d37eefa12cd0068d0d","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":31,"session":2,"revision":"r2","title_original":"Mudahnya Halau Serangga","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1(i)","sp_support_original":"—","objective_original":"Murid dapat menyatakan maksud perkataan dalam petikan dengan betul.","success_criteria_original":"Memadankan tiga perkataan dengan maksudnya.; Menyebut semula maksud perkataan yang dipelajari.","textbook_pages_original":"m/s 45","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk gambar pokok paku gunung dalam buku.\nGuru tanya, “Apakah yang berlaku pada daunnya?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut ulat atau daun berdasarkan gambar.\nSemakan: Beri perkataan yang diperlukan tanpa menuntut jawapan panjang.\nBahan: Buku teks halaman 45","BBM/ABM":"Buku teks halaman 45","PAK-21":"Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali tajuk","execution_original":"Tindakan guru: Guru tunjuk gambar pokok paku gunung dalam buku.\nGuru tanya, “Apakah yang berlaku pada daunnya?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut ulat atau daun berdasarkan gambar.\nSemakan: Beri perkataan yang diperlukan tanpa menuntut jawapan panjang.\nBahan: Buku teks halaman 45","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 45\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},{"phase_original":"Langkah 2\nBaca bersama","execution_original":"Tindakan guru: Guru baca petikan tentang Encik Mahzan.\nGuru ulang ayat yang mengandungi tumbuh, basuhan dan penyembur.\nTindakan murid: Murid ikut bacaan guru.\nMurid tunjuk tiga perkataan tersebut.\nSemakan: Bantu murid mencari perkataan dalam ayat.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},{"phase_original":"Langkah 3\nBelajar maksud","execution_original":"Tindakan guru: Guru jelaskan tumbuh bermaksud hidup dan basuhan bermaksud hasil membasuh.\nGuru jelaskan penyembur ialah alat untuk menyembur air. Guru tunjuk gambar botol penyembur.\nTindakan murid: Murid menyebut perkataan dan maksudnya.\nMurid memadankan kad bersama guru.\nSemakan: Jelaskan maksud basuhan melalui frasa air basuhan cili.\nBahan: Kad perkataan\nKad maksud\nGambar buku teks","aids_and_pak21_original":"BBM/ABM: Kad perkataan\nKad maksud\nGambar buku teks\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},{"phase_original":"Langkah 4\nPadankan dengan rakan","execution_original":"Tindakan guru: Guru edar kad perkataan dan maksud.\nGuru bantu pasangan membaca kad satu demi satu.\nTindakan murid: Murid mencari pasangan bagi tiga perkataan.\nMurid bergilir-gilir menyebut perkataan dan maksud.\nSemakan: Beri pilihan yang lebih sedikit kepada murid yang masih keliru.\nBahan: Kad padanan","aids_and_pak21_original":"BBM/ABM: Kad padanan\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},{"phase_original":"Langkah 5\nLatihan sendiri","execution_original":"Tindakan guru: Guru beri latihan padanan tiga perkataan.\nGuru semak jawapan bersama murid.\nTindakan murid: Murid memadankan perkataan dengan maksud.\nMurid membetulkan padanan yang belum tepat.\nSemakan: Simpan latihan sebagai bukti pembelajaran.\nBahan: Latihan padanan","aids_and_pak21_original":"BBM/ABM: Latihan padanan\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},{"phase_original":"Langkah 6\nUlang semula","execution_original":"Tindakan guru: Guru angkat kad perkataan secara bergilir.\nGuru minta murid menyebut maksud bersama-sama.\nTindakan murid: Murid menyebut maksud perkataan.\nMurid memilih satu perkataan untuk disebut sendiri.\nSemakan: Ulang perkataan yang masih mengelirukan.\nBahan: Kad perkataan","aids_and_pak21_original":"BBM/ABM: Kad perkataan\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Mengenal maksud dengan gambar dan dua pilihan.\nBahan: Gambar penyembur\nDua kad maksud pada satu masa\nBimbingan guru: Guru baca perkataan perlahan-lahan.\nGuru beri contoh “air basuhan ialah air selepas membasuh”.\nLangkah murid: Dengar perkataan guru.\nPilih maksud yang sesuai.\nUlang perkataan dan maksud bersama guru.\nHasil individu: Padanan kad dengan bantuan.\nKriteria: Murid dapat memilih maksud selepas diberi contoh.\nSusulan: Ulang perkataan yang sama dalam ayat buku.","aids_and_pak21_original":"BBM/ABM: Gambar penyembur\nDua kad maksud pada satu masa\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Memadankan tiga perkataan dengan maksudnya.\nBahan: Kad tumbuh, basuhan dan penyembur\nKad maksud\nBimbingan guru: Guru tunjuk satu padanan contoh.\nGuru dengar pasangan membaca kad mereka.\nLangkah murid: Baca perkataan dengan rakan.\nPadankan ketiga-tiga kad.\nLengkapkan latihan padanan sendiri.\nHasil individu: Latihan tiga padanan.\nKriteria: Tiga perkataan dipadankan dengan maksud yang betul.\nSusulan: Bimbing semula padanan yang salah menggunakan ayat asal.","aids_and_pak21_original":"BBM/ABM: Kad tumbuh, basuhan dan penyembur\nKad maksud\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menggunakan satu perkataan yang dipelajari dalam ayat lisan.\nBahan: Kad perkataan\nBuku teks\nBimbingan guru: Guru beri contoh “Saya menggunakan penyembur.”\nGuru bantu murid memilih perkataan yang mudah.\nLangkah murid: Pilih satu kad.\nSebut maksud perkataan.\nCuba satu ayat kepada rakan.\nHasil individu: Satu ayat lisan yang mudah.\nKriteria: Ayat menunjukkan murid memahami maksud perkataan.\nSusulan: Murid boleh memilih perkataan lain jika mahu.","aids_and_pak21_original":"BBM/ABM: Kad perkataan\nBuku teks\nPAK-21: Padanan berpasangan: murid mencari pasangan perkataan dan maksud."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan latihan padanan.","Evidens":"Latihan tiga perkataan.","Kriteria Kejayaan":"Tiga perkataan dipadankan dengan maksud yang betul."},"closure_original":"Tindakan guru: Guru angkat kad perkataan secara bergilir.\nGuru minta murid menyebut maksud bersama-sama.\nTindakan murid: Murid menyebut maksud perkataan.\nMurid memilih satu perkataan untuk disebut sendiri.\nSemakan: Ulang perkataan yang masih mengelirukan.\nBahan: Kad perkataan","reflection_original":"__ daripada __ murid dapat memadankan perkataan dengan maksudnya. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M31-S2.docx","source_docx_sha256":"347045f717b442815db6ce717071c554e9810d1df00c2f62f817188a67a1740f","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M31-S3","week_no":31,"session_no":3,"lesson_map":{"title":"Bucida yang Cantik","sp":"3.2.3","page":46,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":31,"session":3,"revision":"r1","title_original":"Bucida yang Cantik","sk_original":"3.2 Menulis perkataan, frasa, dan ayat yang bermakna","sp_original":"3.2.3","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat menyusun dan mencatat sekurang-kurangnya lima maklumat baharu tentang pokok Bucida dalam kategori daun, kawasan ditanam dan kelebihan dengan tepat berdasarkan petikan.","success_criteria_original":"Lima catatan meliputi ketiga-tiga kategori dan bukan hanya menyalin contoh hijau serta di pinggir jalan yang telah disediakan.; Catatan berupa kata atau frasa ringkas yang mengekalkan maksud, bukan seluruh perenggan disalin ke setiap lajur.; Sekurang-kurangnya dua catatan dapat dipadankan semula kepada ayat bukti.","textbook_pages_original":"m/s 46","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk tajuk Bucida yang Cantik dan tiga kategori buku. Letakkan kad di taman secara sengaja pada cabang daun; tanya adakah tempat itu sejenis daun.\nMinta murid membetulkan kedudukan kad dan menerangkan sebab menggunakan istilah tempat atau kawasan.\nTindakan murid: Baca label tiga kategori dan tunjuk cabang yang sesuai bagi di taman.\nSebut satu perbezaan antara ciri daun dengan tempat pokok ditanam.\nSemakan: Jika istilah kelebihan belum difahami, jelaskan sebagai kebaikan atau faedah pokok berdasarkan teks, bukan nama tempat.\nBahan: Peta tiga kategori dan kad di taman.","BBM/ABM":"Peta tiga kategori dan kad di taman.","PAK-21":"Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Lajur yang betul","execution_original":"Tindakan guru: Tunjuk tajuk Bucida yang Cantik dan tiga kategori buku. Letakkan kad di taman secara sengaja pada cabang daun; tanya adakah tempat itu sejenis daun.\nMinta murid membetulkan kedudukan kad dan menerangkan sebab menggunakan istilah tempat atau kawasan.\nTindakan murid: Baca label tiga kategori dan tunjuk cabang yang sesuai bagi di taman.\nSebut satu perbezaan antara ciri daun dengan tempat pokok ditanam.\nSemakan: Jika istilah kelebihan belum difahami, jelaskan sebagai kebaikan atau faedah pokok berdasarkan teks, bukan nama tempat.\nBahan: Peta tiga kategori dan kad di taman.","aids_and_pak21_original":"BBM/ABM: Peta tiga kategori dan kad di taman.\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},{"phase_original":"Langkah 2\nModel catatan — Ringkaskan tanpa mengubah maksud","execution_original":"Tindakan guru: Baca perenggan kedua dan ketiga. Modelkan frasa “berdaun putih” menjadi catatan “putih” di bawah daun.\nBandingkan catatan ringkas di halaman rumah dengan menyalin seluruh ayat. Tunjuk bagaimana nombor ayat membantu menyemak bukti.\nTindakan murid: Cari dua ayat tentang daun dan kawasan; tunjuk kata yang paling penting.\nCuba menukarkan satu ayat kepada frasa ringkas dan nyatakan kategori yang sesuai.\nSemakan: Catatan mesti masih bermakna. Jika murid hanya menulis “di” atau “pokok”, minta mereka menambah kata yang menentukan maklumat.\nBahan: BT46, jalur ayat dan model peta.","aids_and_pak21_original":"BBM/ABM: BT46, jalur ayat dan model peta.\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},{"phase_original":"Langkah 3\nLatihan terbeza — Peta maklumat Bucida","execution_original":"Tindakan guru: Gunakan laluan bantuan di bawah untuk menyusun lima maklumat baharu merentas tiga kategori. Contoh yang sudah dicetak tidak dikira sebagai hasil baharu.\nTanya pasangan “Ayat mana menyebutnya?” apabila kad akar kuat atau menahan angin diletakkan. Terima lebih daripada satu frasa kelebihan yang tepat dan tidak bertindih secara kosong.\nTindakan murid: Bergilir memilih fakta serta menunjukkan bukti, kemudian letakkan catatan pada cabang sesuai.\nLengkapkan peta sendiri dan semak setiap catatan sebelum membandingkan dengan rakan.\nSemakan: Jika fakta dahan bertingkat dimasukkan sebagai daun, jelaskan batas kategori; tidak semua ayat perlu dipaksa masuk semua cabang.\nBahan: Kad fakta, peta individu dan BT46.","aids_and_pak21_original":"BBM/ABM: Kad fakta, peta individu dan BT46.\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},{"phase_original":"Langkah 4\nSemak silang — Betul kategori, betul sumber","execution_original":"Tindakan guru: Paparkan kad “buahnya manis” sebagai contoh rekaan guru dan minta bukti daripada petikan.\nMinta pasangan menilai satu peta rakan: pilih satu catatan betul dan satu yang perlu dipindah atau dibuang, dengan sebab.\nTindakan murid: Tolak fakta yang tidak dinyatakan tanpa meneka buah pokok Bucida.\nBeri maklum balas khusus, seperti pindahkan di taman ke kawasan, dan baiki peta sendiri menggunakan pen lain.\nSemakan: Semakan rakan tidak cukup dengan tanda cantik. Setiap komen perlu merujuk kategori atau sumber.\nBahan: Kad gangguan guru dan peta catatan.","aids_and_pak21_original":"BBM/ABM: Kad gangguan guru dan peta catatan.\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},{"phase_original":"Langkah 5\nPBD — Lima maklumat individu","execution_original":"Tindakan guru: Semak peta setiap murid dan minta penjelasan bagi dua catatan. Rekod ketepatan, liputan kategori dan kebolehan mencari bukti.\nJika murid menyalin peta pasangan, pilih satu ayat baharu untuk dikategorikan sendiri sebelum merekod penguasaan.\nTindakan murid: Tunjuk lima catatan baharu dan dua ayat bukti.\nTerangkan satu pembetulan kategori yang dibuat serta serahkan hasil individu.\nSemakan: Jangan menilai panjang karangan kerana SP ialah menyusun dan mencatat. Murid boleh menggunakan frasa ringkas dengan ejaan yang diperbaik selepas isi tepat.\nBahan: Peta individu dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Peta individu dan senarai semak.\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},{"phase_original":"Langkah 6\nPenutup — Catatan membantu mengingat","execution_original":"Tindakan guru: Minta kelas menyebut satu catatan bagi setiap kategori tanpa membaca seluruh petikan.\nRumusan teknik: baca, pilih fakta, ringkaskan, letak kategori dan semak bukti.\nTindakan murid: Sebut contoh daun putih, kawasan taman atau faedah berteduh mengikut giliran.\nNyatakan kategori yang masih sukar dan simpan peta sebagai rujukan.\nSemakan: Gunakan kekeliruan yang sebenar untuk latihan susulan, bukannya mengisi refleksi dengan pencapaian diandaikan.\nBahan: Peta tiga kategori dan buku.","aids_and_pak21_original":"BBM/ABM: Peta tiga kategori dan buku.\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Warna kategori dan ayat bergaris","implementation_original":"Tugasan: Mengisi lima catatan baharu dengan kad fakta dan rangka peta yang membantu pengecaman kategori.\nBahan: Peta tiga warna daun/kawasan/kelebihan\nKad putih, di taman, di halaman rumah, akar kuat dan berteduh\nAyat sumber yang petunjuknya digaris\nBimbingan guru: Baca satu ayat dan tunjuk kata yang menentukan kategori, kemudian modelkan hanya satu entri.\nMinta murid memilih sendiri kad berikutnya; kurangkan warna bantuan selepas dua pengelasan tepat.\nLangkah murid: Padankan satu fakta dengan ayat bergaris.\nSebut kategori dan sebab mudah sebelum meletakkan kad.\nTulis lima catatan sendiri pada peta, bukan meninggalkan kad sebagai hasil akhir.\nTunjuk semula dua ayat bukti dan betulkan satu entri jika tersalah cabang.\nHasil individu: Peta individu lima fakta baharu dengan sumber rujukan ditandai.\nKriteria: Lima catatan merentas ketiga-tiga kategori tepat, bantuan dicatat. Jika hanya tiga catatan, rekod kemajuan tetapi sasaran belum penuh.\nSusulan: Latih dua kad yang sering tertukar, contohnya di taman dan tempat berteduh, sebelum menambah fakta baharu.","aids_and_pak21_original":"BBM/ABM: Peta tiga warna daun/kawasan/kelebihan\nKad putih, di taman, di halaman rumah, akar kuat dan berteduh\nAyat sumber yang petunjuknya digaris\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},"pembina":{"label":"Langkah 1\nPembina — Pilih, ringkas dan kategori","implementation_original":"Tugasan: Membina peta daripada petikan penuh tanpa set fakta yang telah dipilih oleh guru.\nBahan: BT46\nPeta kosong dengan dua contoh buku\nPen dua warna untuk fakta dan pembetulan\nBimbingan guru: Tanya mengapa murid memilih kata tertentu sebagai catatan dan minta mereka mengekalkan maksud ayat.\nBimbing pengelasan kelebihan melalui soalan apa kebaikannya, tanpa menyuapkan semua jawapan.\nLangkah murid: Baca petikan dan tandakan fakta yang belum diisi dalam contoh.\nRingkaskan sekurang-kurangnya lima fakta kepada kata atau frasa.\nLetakkan fakta pada tiga cabang dan semak bukti dengan pasangan.\nBaiki peta sendiri kemudian jelaskan dua hubungan fakta dengan ayat asal.\nHasil individu: Peta catatan individu ringkas dan tepat, lengkap tiga kategori.\nKriteria: Lima fakta baharu bukan salinan contoh dan dua bukti dapat ditunjukkan; susunan tidak bergantung warna bantuan.\nSusulan: Jika kukuh, terangkan mengapa satu maklumat dahan tidak sesuai cabang daun; jika belum, ulang kategori yang masih bercampur.","aids_and_pak21_original":"BBM/ABM: BT46\nPeta kosong dengan dua contoh buku\nPen dua warna untuk fakta dan pembetulan\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."},"pencabar":{"label":"Langkah 1\nPencabar — Bezakan fakta utama, faedah dan andaian","implementation_original":"Tugasan: Membina peta tepat serta menilai sama ada maklumat tambahan sesuai dengan kategori dan sumber.\nBahan: BT46\nKad dahan bertingkat-tingkat serta kad rekaan buahnya manis\nJalur Dinyatakan/Tidak dinyatakan\nBimbingan guru: Minta murid menjelaskan perbezaan fakta benar tetapi di luar kategori dengan fakta yang langsung tidak dinyatakan.\nBimbing cadangan lokasi pokok hanya sebagai pendapat berdasarkan akar kuat atau teduhan, bukan fakta baharu tentang semua lokasi.\nLangkah murid: Lengkapkan lima catatan baharu merentas tiga cabang.\nSemak dua kad tambahan dan terangkan status masing-masing.\nCadangkan satu tempat sesuai berdasarkan satu kelebihan daripada teks.\nNyatakan fakta sumber yang menyokong cadangan sambil membezakan cadangan daripada catatan buku.\nHasil individu: Peta lengkap serta satu penilaian kategori dan satu cadangan berasas.\nKriteria: Sasaran teras tepat dan murid tidak memaksa semua fakta masuk cabang sedia ada atau menganggap andaian sebagai fakta.\nSusulan: Gunakan teknik yang sama untuk menyemak catatan rakan tanpa menambah kategori sesuka hati pada tugasan asal.","aids_and_pak21_original":"BBM/ABM: BT46\nKad dahan bertingkat-tingkat serta kad rekaan buahnya manis\nJalur Dinyatakan/Tidak dinyatakan\nPAK-21: Information Sort dan semak bukti berpasangan: seorang memilih kategori, seorang mencari ayat sokongan; peranan ditukar. Gallery Check dilakukan pada peta untuk memeriksa pengelasan, bukan sekadar berjalan melihat hasil."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan peta maklumat individu serta penerangan dua bukti.","Evidens":"Lima catatan baharu dalam daun/kawasan/kelebihan dan dua ayat sokongan.","Kriteria Kejayaan":"Ketepatan fakta, pengelasan dan ringkasan bermakna; bukan panjang tulisan."},"closure_original":"Tindakan guru: Minta kelas menyebut satu catatan bagi setiap kategori tanpa membaca seluruh petikan.\nRumusan teknik: baca, pilih fakta, ringkaskan, letak kategori dan semak bukti.\nTindakan murid: Sebut contoh daun putih, kawasan taman atau faedah berteduh mengikut giliran.\nNyatakan kategori yang masih sukar dan simpan peta sebagai rujukan.\nSemakan: Gunakan kekeliruan yang sebenar untuk latihan susulan, bukannya mengisi refleksi dengan pencapaian diandaikan.\nBahan: Peta tiga kategori dan buku.","reflection_original":"____ / ____ murid mencatat lima fakta tepat; ____ masih tertukar kategori; ____ memerlukan bantuan membaca ayat. Catatan yang perlu disemak: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M31-S3.docx","source_docx_sha256":"2910453b46295b714abfc11f9c85420df212e6089a449cbf27f06219f7aee280","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":31,"session":3,"revision":"r2","title_original":"Bucida yang Cantik","sk_original":"3.2 Menulis perkataan, frasa, dan ayat yang bermakna","sp_original":"3.2.3","sp_support_original":"—","objective_original":"Murid dapat mencatat maklumat mudah tentang pokok Bucida.","success_criteria_original":"Mencatat tiga maklumat dalam peta yang disediakan.; Meletakkan maklumat pada bahagian yang sesuai.","textbook_pages_original":"m/s 46","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk gambar dan tajuk dalam buku.\nGuru tanya, “Apakah warna daun pokok yang biasa kamu lihat?”\nTindakan murid: Murid melihat gambar pokok.\nMurid menyebut warna daun yang diketahui.\nSemakan: Beri peluang menjawab dengan satu perkataan.\nBahan: Buku teks halaman 46","BBM/ABM":"Buku teks halaman 46","PAK-21":"Bincang berpasangan untuk mencari maklumat dalam petikan."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali pokok Bucida","execution_original":"Tindakan guru: Guru tunjuk gambar dan tajuk dalam buku.\nGuru tanya, “Apakah warna daun pokok yang biasa kamu lihat?”\nTindakan murid: Murid melihat gambar pokok.\nMurid menyebut warna daun yang diketahui.\nSemakan: Beri peluang menjawab dengan satu perkataan.\nBahan: Buku teks halaman 46","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 46\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."},{"phase_original":"Langkah 2\nBaca bersama","execution_original":"Tindakan guru: Guru baca petikan perlahan-lahan.\nGuru beri tumpuan pada warna daun, tempat ditanam dan kegunaan pokok.\nTindakan murid: Murid mengikuti bacaan.\nMurid menunjukkan perkataan hijau dan putih.\nSemakan: Ulang bahagian yang belum difahami.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."},{"phase_original":"Langkah 3\nIsi contoh bersama","execution_original":"Tindakan guru: Guru tunjuk tiga bahagian peta pokok.\nGuru catat hijau di bahagian daun dan di pinggir jalan di bahagian kawasan ditanam.\nTindakan murid: Murid membaca contoh pada peta.\nMurid mencadangkan tempat berteduh untuk bahagian kelebihan.\nSemakan: Terangkan tempat berteduh dengan contoh berehat di bawah pokok.\nBahan: Peta pokok di papan putih","aids_and_pak21_original":"BBM/ABM: Peta pokok di papan putih\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."},{"phase_original":"Langkah 4\nCari dengan rakan","execution_original":"Tindakan guru: Guru minta pasangan mencari warna daun yang satu lagi.\nGuru bimbing pasangan mencari tempat lain pokok Bucida ditanam.\nTindakan murid: Murid mencari putih dan taman dalam petikan.\nMurid menyebut bahagian peta yang sesuai bagi setiap jawapan.\nSemakan: Gunakan kad pilihan jika murid sukar mencari jawapan.\nBahan: Buku teks\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad perkataan\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."},{"phase_original":"Langkah 5\nCatat sendiri","execution_original":"Tindakan guru: Guru beri peta dengan tiga ruang kosong.\nGuru semak catatan murid semasa mereka menulis.\nTindakan murid: Murid mencatat putih, taman dan tempat berteduh pada bahagian yang sesuai.\nMurid membetulkan catatan selepas semakan.\nSemakan: Buku dan kad bantuan boleh digunakan.\nBahan: Peta latihan\nBuku teks","aids_and_pak21_original":"BBM/ABM: Peta latihan\nBuku teks\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tunjuk peta yang telah lengkap.\nGuru tanya, “Apakah kegunaan pokok Bucida?”\nTindakan murid: Murid membaca satu maklumat pada peta.\nMurid menyebut kepentingan menjaga pokok.\nSemakan: Ulang cara memilih bahagian peta.\nBahan: Peta pokok","aids_and_pak21_original":"BBM/ABM: Peta pokok\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Mengisi peta dengan kad jawapan.\nBahan: Peta bercontoh\nKad putih, taman, tempat berteduh\nBimbingan guru: Guru baca setiap kad.\nGuru tunjuk satu bahagian peta pada satu masa.\nLangkah murid: Dengar perkataan guru.\nLetakkan kad pada peta bersama guru.\nTulis semula jawapan pada ruangnya.\nHasil individu: Catatan pada peta dengan bantuan.\nKriteria: Maklumat diletakkan pada bahagian yang sesuai.\nSusulan: Ulang satu bahagian peta yang masih mengelirukan.","aids_and_pak21_original":"BBM/ABM: Peta bercontoh\nKad putih, taman, tempat berteduh\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Mencatat tiga maklumat daripada petikan.\nBahan: Buku teks\nPeta tiga ruang\nBimbingan guru: Guru bantu murid mencari perenggan yang berkaitan.\nGuru beri contoh bahagian daun.\nLangkah murid: Baca bahagian yang ditunjukkan.\nPilih maklumat bersama rakan.\nCatat sendiri dalam peta.\nHasil individu: Peta dengan tiga catatan.\nKriteria: Catatan sesuai dengan tajuk bahagian peta.\nSusulan: Semak semula petikan jika ada catatan tersalah tempat.","aids_and_pak21_original":"BBM/ABM: Buku teks\nPeta tiga ruang\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menambah satu maklumat pada peta.\nBahan: Buku teks\nPeta yang telah diisi\nBimbingan guru: Guru tunjuk ayat tentang akar yang kuat.\nGuru tanya bahagian peta yang sesuai.\nLangkah murid: Baca ayat bersama guru.\nPilih perkataan akar kuat.\nTambah maklumat pada bahagian kelebihan.\nHasil individu: Satu maklumat tambahan.\nKriteria: Maklumat sesuai dengan bahagian yang dipilih.\nSusulan: Beri peluang membaca catatan kepada rakan.","aids_and_pak21_original":"BBM/ABM: Buku teks\nPeta yang telah diisi\nPAK-21: Bincang berpasangan untuk mencari maklumat dalam petikan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan hasil tulisan.","Evidens":"Peta maklumat setiap murid.","Kriteria Kejayaan":"Tiga maklumat dicatat pada bahagian yang sesuai."},"closure_original":"Tindakan guru: Guru tunjuk peta yang telah lengkap.\nGuru tanya, “Apakah kegunaan pokok Bucida?”\nTindakan murid: Murid membaca satu maklumat pada peta.\nMurid menyebut kepentingan menjaga pokok.\nSemakan: Ulang cara memilih bahagian peta.\nBahan: Peta pokok","reflection_original":"__ daripada __ murid dapat mencatat maklumat tentang pokok Bucida. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M31-S3.docx","source_docx_sha256":"2f453197f9fcd20043ce01f83122dc012b6f5caf61b9b075c40d5b8266d8b4eb","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M31-S4","week_no":31,"session_no":4,"lesson_map":{"title":"Sang Pokok Kembali Ceria","sp":"4.3.2","page":47,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":31,"session":4,"revision":"r1","title_original":"Sang Pokok Kembali Ceria","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan mempersembahkannya secara Kreatif","sp_original":"4.3.2(i)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat mempersembahkan cerita Sang Pokok Kembali Ceria dengan sekurang-kurangnya tiga peristiwa mengikut urutan serta dua perubahan suara atau intonasi yang sepadan dengan watak dan suasana.","success_criteria_original":"Urutan menunjukkan masalah tanah tidak subur, bantuan Sang Cacing dan perubahan pokok menjadi subur.; Setiap murid mendapat bahagian penceritaan yang boleh didengar; sebutan jelas dan dua suasana atau watak dibezakan.; Murid menyampaikan cerita, bukan hanya menjawab soalan tentangnya; kad urutan dibenarkan dan bantuan dicatat.","textbook_pages_original":"m/s 47","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Sebut tajuk dan baca ujaran Aduhai dengan dua nada berbeza. Tanya nada mana sepadan keadaan daun kekuningan dalam cerita.\nMinta murid meramal perubahan suara yang mungkin berlaku apabila pokok kembali subur; jangan terus membekalkan seluruh pengakhiran.\nTindakan murid: Pilih nada sedih dan jelaskan petunjuk perkataan atau keadaan dalam teks.\nCuba ujaran pendek secara sukarela dengan nada yang sesuai tanpa menjerit.\nSemakan: Semak kemampuan menghubungkan suara dengan suasana, bukan keberanian tampil sahaja.\nBahan: BT47 dan ikon sedih/ceria.","BBM/ABM":"BT47 dan ikon sedih/ceria.","PAK-21":"Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Pokok sedih, pokok ceria","execution_original":"Tindakan guru: Sebut tajuk dan baca ujaran Aduhai dengan dua nada berbeza. Tanya nada mana sepadan keadaan daun kekuningan dalam cerita.\nMinta murid meramal perubahan suara yang mungkin berlaku apabila pokok kembali subur; jangan terus membekalkan seluruh pengakhiran.\nTindakan murid: Pilih nada sedih dan jelaskan petunjuk perkataan atau keadaan dalam teks.\nCuba ujaran pendek secara sukarela dengan nada yang sesuai tanpa menjerit.\nSemakan: Semak kemampuan menghubungkan suara dengan suasana, bukan keberanian tampil sahaja.\nBahan: BT47 dan ikon sedih/ceria.","aids_and_pak21_original":"BBM/ABM: BT47 dan ikon sedih/ceria.\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},{"phase_original":"Langkah 2\nFahami babak dan modelkan penceritaan","execution_original":"Tindakan guru: Baca cerita dan susun tiga kad: tanah kering/tidak subur, cacing menggembur serta membantu tanah, pokok kembali subur.\nModelkan pencerita menyambung satu babak kepada dialog Sang Cacing. Bezakan suara narator dengan watak tetapi kekalkan peristiwa asal.\nTindakan murid: Tunjuk bukti bagi setiap kad babak dan sebut siapa yang bercakap pada dialog terpilih.\nSusun kad tanpa bantuan rakan, kemudian cuba menghubungkan dua peristiwa menggunakan selepas itu.\nSemakan: Jika murid menukar Sang Tanah kepada Sang Pokok pada ayat sumber, buka teks untuk menyemak; tidak perlu menghafal semua dialog perkataan demi perkataan.\nBahan: Kad babak, watak dan BT47.","aids_and_pak21_original":"BBM/ABM: Kad babak, watak dan BT47.\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},{"phase_original":"Langkah 3\nLatihan terbeza — Pencerita dan watak","execution_original":"Tindakan guru: Jalankan laluan sokongan, teras atau cabaran di bawah. Pastikan setiap murid berlatih rangka tiga babak sebelum memberi satu watak dalam persembahan kelompok.\nDengar persembahan pendek individu ketika pasangan berlatih. Beri satu petunjuk suara atau urutan pada satu masa dan rekod kebergantungan kepada kad.\nTindakan murid: Bercerita kepada pasangan dengan kad babak sebagai panduan, tukar peranan dan perbaiki satu bahagian.\nDalam kelompok kecil, pilih watak atau narator dan latih peralihan daripada sedih kepada ceria tanpa menambah kejadian yang tiada dalam cerita.\nSemakan: Peranan memegang kad sahaja tidak memenuhi objektif persembahan. Beri murid itu giliran dialog atau naratif yang boleh didengar.\nBahan: Kad babak, jalur dialog, ikon emosi dan buku.","aids_and_pak21_original":"BBM/ABM: Kad babak, jalur dialog, ikon emosi dan buku.\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},{"phase_original":"Langkah 4\nPersembahan — Bintang dengan alasan","execution_original":"Tindakan guru: Pilih beberapa kelompok untuk mempersembahkan kepada kelompok lain; guru menumpukan murid yang belum diperhatikan sambil kumpulan lain bergilir.\nMinta penonton menyebut sebab bintang diberi, contohnya urutan jelas atau suara ceria pada pengakhiran. Elakkan undian murid paling popular.\nTindakan murid: Persembahkan cerita mengikut peranan dan dengar isyarat pasangan untuk bertukar penutur.\nPenonton memberi satu bintang aspek dan satu cadangan khusus, kemudian tukar menjadi pencerita.\nSemakan: Guru memisahkan penilaian persembahan kelompok daripada pencapaian setiap murid yang telah didengar.\nBahan: Kad bintang dan ruang persembahan kecil.","aids_and_pak21_original":"BBM/ABM: Kad bintang dan ruang persembahan kecil.\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},{"phase_original":"Langkah 5\nPBD — Tiga babak secara individu","execution_original":"Tindakan guru: Minta murid yang memerlukan bukti tambahan menceritakan semula Masalah–Bantuan–Hasil dengan dua intonasi. Gunakan catatan latihan untuk murid yang sudah didengar.\nRekod urutan, suara dan intonasi serta bantuan; jika masa tidak cukup, tandakan belum diperhatikan untuk susulan, bukan lulus secara kumpulan.\nTindakan murid: Ceritakan tiga babak ringkas dengan kata sendiri atau dialog pilihan daripada buku.\nUlang satu bahagian selepas soalan guru jika urutan terbalik atau suara tidak sesuai.\nSemakan: Tiada karangan bertulis wajib kerana sasaran ialah persembahan. Satu watak dengan satu baris sahaja belum membuktikan penceritaan tiga peristiwa.\nBahan: Kad urutan jika perlu dan rekod lisan guru.","aids_and_pak21_original":"BBM/ABM: Kad urutan jika perlu dan rekod lisan guru.\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},{"phase_original":"Langkah 6\nPenutup — Terima kasih Sang Cacing","execution_original":"Tindakan guru: Tanya perubahan paling jelas antara awal dengan akhir cerita dan bagaimana suara membantu pendengar memahaminya.\nRumusan nilai saling membantu berdasarkan perbuatan Sang Cacing, bukan nasihat umum tanpa hubungan cerita.\nTindakan murid: Sebut satu peristiwa yang menyokong nilai dan cuba ucapan terima kasih dengan intonasi sesuai.\nNyatakan satu bantuan latihan yang masih diperlukan, seperti kad babak atau model dialog.\nSemakan: Gunakan maklum balas untuk intervensi individu; angka refleksi kekal kosong sehingga bukti disemak.\nBahan: BT47 dan kad babak.","aids_and_pak21_original":"BBM/ABM: BT47 dan kad babak.\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Kad babak dan dialog pendek","implementation_original":"Tugasan: Mempersembahkan rangka tiga babak dengan bantuan gambar kata serta dua ujaran pendek yang membawa emosi.\nBahan: Kad Masalah–Bantuan–Hasil dengan kata tanah kering/cacing membantu/pokok subur\nDua jalur dialog dan ikon sedih/ceria\nKad penutur bernama\nBimbingan guru: Modelkan satu ayat naratif dahulu dan minta murid menyambung babak berikutnya, bukan mengulang guru sepanjang cerita.\nKekalkan kad urutan tetapi tutup ayat model pada percubaan kedua supaya murid bercerita sendiri.\nLangkah murid: Susun tiga kad berdasarkan teks.\nSebut satu ayat bagi setiap babak dan tambah dua ujaran dengan nada berlainan.\nLatih kepada pasangan yang hanya menunjuk kad jika terlupa.\nPersembahkan semula kepada guru tanpa suara pasangan membimbing setiap perkataan.\nHasil individu: Penceritaan tiga babak individu dengan dua perubahan suara yang dapat didengar.\nKriteria: Urutan dan intonasi sesuai dengan bantuan dicatat. Jika hanya dua babak disampaikan, rekod kemajuan separa dan latih babak yang tertinggal.\nSusulan: Ulang hubungan bantuan–hasil dengan dua kad dahulu jika murid sering melangkau sebab pokok menjadi subur.","aids_and_pak21_original":"BBM/ABM: Kad Masalah–Bantuan–Hasil dengan kata tanah kering/cacing membantu/pokok subur\nDua jalur dialog dan ikon sedih/ceria\nKad penutur bernama\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},"pembina":{"label":"Langkah 1\nPembina — Naratif tersusun dan suara watak","implementation_original":"Tugasan: Menyampaikan cerita dengan kata sendiri sambil memilih dialog yang menonjolkan konflik serta penyelesaian.\nBahan: BT47\nKad kata kunci tiga babak tanpa ayat penuh\nSenarai semak suara/urutan/intonasi\nBimbingan guru: Tanya bahagian mana patut bernada sedih dan bahagian mana berubah; minta bukti peristiwa dalam teks.\nBeri ruang murid memilih dialog, tetapi semak penutur serta urutan supaya jalan cerita tidak berubah.\nLangkah murid: Pilih satu atau dua dialog dan kenal pasti penuturnya.\nSusun naratif tiga babak dengan penghubung masa yang mudah.\nCeritakan kepada pasangan dan dengar satu komen khusus.\nBaiki suara atau urutan, kemudian persembahkan sebagai pencerita individu dan ahli kelompok.\nHasil individu: Persembahan tiga peristiwa berurutan dengan suara watak, bukan bacaan beramai-ramai sahaja.\nKriteria: Tiga babak lengkap, sebutan jelas dan dua perubahan intonasi sesuai; hafalan sempurna bukan syarat.\nSusulan: Jika kukuh, kurangkan kad; jika tidak, tandakan peralihan antara babak yang masih mengelirukan.","aids_and_pak21_original":"BBM/ABM: BT47\nKad kata kunci tiga babak tanpa ayat penuh\nSenarai semak suara/urutan/intonasi\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."},"pencabar":{"label":"Langkah 1\nPencabar — Menyampaikan perubahan watak","implementation_original":"Tugasan: Menceritakan tiga babak dengan peralihan suara terancang dan menjelaskan sebab pilihan intonasi.\nBahan: Teks penuh\nKad narator/watak\nKad maklum balas yang menumpukan peralihan emosi\nBimbingan guru: Minta murid menunjukkan perbezaan intonasi melalui satu ujaran, bukan menambah dialog panjang yang tiada dalam bahan.\nTanya bagaimana narator menyambungkan tindakan cacing kepada keadaan pokok pada akhir cerita supaya pendengar memahami sebab perubahan.\nLangkah murid: Rancang rangka tiga babak serta dua perubahan suara.\nPilih bahagian untuk memperlahankan atau menegaskan perkataan mengikut makna.\nPersembahkan tanpa terlalu bergantung pada kad dan dengar tanggapan penonton.\nTerangkan satu pilihan gaya lalu ubah jika maknanya belum jelas kepada pendengar.\nHasil individu: Penceritaan terancang dan penjelasan ringkas satu pilihan persembahan.\nKriteria: Sasaran teras dicapai serta gaya membantu makna; props, kelantangan berlebihan atau panjang cerita bukan ukuran tinggi.\nSusulan: Cuba satu persembahan yang lebih ringkas tetapi tetap lengkap tiga babak dan emosi yang sesuai.","aids_and_pak21_original":"BBM/ABM: Teks penuh\nKad narator/watak\nKad maklum balas yang menumpukan peralihan emosi\nPAK-21: Storytelling berpasangan dan persembahan kelompok kecil: semua murid menceritakan rangka tiga babak, kemudian kumpulan membahagi watak untuk persembahan bersama. Penonton memberi bintang berasaskan aspek yang diperhatikan, bukan populariti."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian persembahan individu semasa latihan, kelompok dan giliran susulan.","Evidens":"Tiga peristiwa diceritakan oleh murid dengan dua perubahan suara/intonasi.","Kriteria Kejayaan":"Urutan, kejelasan sebutan dan intonasi berpaut pada watak atau suasana; bantuan dinyatakan."},"closure_original":"Tindakan guru: Tanya perubahan paling jelas antara awal dengan akhir cerita dan bagaimana suara membantu pendengar memahaminya.\nRumusan nilai saling membantu berdasarkan perbuatan Sang Cacing, bukan nasihat umum tanpa hubungan cerita.\nTindakan murid: Sebut satu peristiwa yang menyokong nilai dan cuba ucapan terima kasih dengan intonasi sesuai.\nNyatakan satu bantuan latihan yang masih diperlukan, seperti kad babak atau model dialog.\nSemakan: Gunakan maklum balas untuk intervensi individu; angka refleksi kekal kosong sehingga bukti disemak.\nBahan: BT47 dan kad babak.","reflection_original":"____ / ____ murid mempersembahkan tiga babak; ____ memerlukan kad urutan; ____ belum diperhatikan secara individu. Intonasi/peralihan yang perlu dibantu: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M31-S4.docx","source_docx_sha256":"2cc53279ce3eb5adb41c10b9de06b6857f769448bcd692f146afa152eaa93eb5","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":31,"session":4,"revision":"r2","title_original":"Sang Pokok Kembali Ceria","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan mempersembahkannya secara Kreatif","sp_original":"4.3.2(i)","sp_support_original":"—","objective_original":"Murid dapat mempersembahkan cerita Sang Pokok Kembali Ceria dengan bahasa yang mudah.","success_criteria_original":"Menceritakan semula dua kejadian dalam cerita.; Menggunakan suara yang jelas semasa bercerita.","textbook_pages_original":"m/s 47","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk cerita.\nGuru sebut nama Sang Pokok dan Sang Cacing.\nTindakan murid: Murid menyebut nama watak.\nMurid meneka perasaan Sang Pokok berdasarkan tajuk.\nSemakan: Terima jawapan ringkas.\nBahan: Buku teks halaman 47","BBM/ABM":"Buku teks halaman 47","PAK-21":"Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali watak","execution_original":"Tindakan guru: Guru tunjuk tajuk cerita.\nGuru sebut nama Sang Pokok dan Sang Cacing.\nTindakan murid: Murid menyebut nama watak.\nMurid meneka perasaan Sang Pokok berdasarkan tajuk.\nSemakan: Terima jawapan ringkas.\nBahan: Buku teks halaman 47","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 47\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},{"phase_original":"Langkah 2\nDengar cerita","execution_original":"Tindakan guru: Guru baca cerita dengan suara sedih dan gembira.\nGuru tanya, “Siapakah yang membantu Sang Pokok?”\nTindakan murid: Murid mendengar cerita.\nMurid menyebut nama watak yang membantu.\nSemakan: Ulang bahagian Sang Cacing jika perlu.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},{"phase_original":"Langkah 3\nCerita bersama","execution_original":"Tindakan guru: Guru susun tiga kad mengikut urutan cerita.\nGuru beri contoh: “Sang Pokok bersedih. Sang Cacing datang membantu.”\nTindakan murid: Murid mengulang contoh cerita.\nMurid menambah: “Sang Pokok kembali subur.”\nSemakan: Bantu murid menyebut kejadian mengikut urutan.\nBahan: Kad bantuan cerita","aids_and_pak21_original":"BBM/ABM: Kad bantuan cerita\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru beri kad bantuan kepada pasangan.\nGuru bimbing murid menggunakan suara sedih pada awal cerita.\nTindakan murid: Murid bercerita kepada rakan menggunakan kad.\nMurid bertukar giliran sebagai pencerita dan pendengar.\nSemakan: Dengar setiap murid semasa latihan.\nBahan: Kad bantuan\nBuku teks","aids_and_pak21_original":"BBM/ABM: Kad bantuan\nBuku teks\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},{"phase_original":"Langkah 5\nBercerita sendiri","execution_original":"Tindakan guru: Guru dengar murid yang belum diperhatikan semasa latihan.\nGuru beri satu pujian dan satu bantuan sebutan.\nTindakan murid: Murid menceritakan semula dua kejadian pilihan.\nMurid mencuba semula bahagian yang dibantu guru.\nSemakan: Kad masih boleh digunakan.\nBahan: Kad bantuan\nSenarai nama","aids_and_pak21_original":"BBM/ABM: Kad bantuan\nSenarai nama\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tanya, “Apakah yang diucapkan selepas menerima bantuan?”\nGuru ajak kelas mengulang pengakhiran cerita.\nTindakan murid: Murid menyebut terima kasih.\nMurid mengulang bahagian pokok kembali subur.\nSemakan: Kukuhkan nilai saling membantu.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Bercerita dengan bantuan kad dan awal ayat.\nBahan: Kad pokok sedih dan cacing membantu\nBimbingan guru: Guru sebut satu ayat pada satu masa.\nGuru beri awal ayat “Sang Cacing...”\nLangkah murid: Lihat kad.\nUlang ayat bersama guru.\nCeritakan dua kejadian kepada rakan dengan bantuan.\nHasil individu: Cerita lisan pendek.\nKriteria: Maksud cerita dapat disampaikan dengan bantuan.\nSusulan: Ulang dua kad yang sama dalam kumpulan kecil.","aids_and_pak21_original":"BBM/ABM: Kad pokok sedih dan cacing membantu\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Menceritakan semula dua kejadian mengikut urutan.\nBahan: Tiga kad cerita\nBimbingan guru: Guru semak susunan kad.\nGuru bantu perkataan yang terlupa.\nLangkah murid: Susun kad.\nLatih cerita dengan rakan.\nBercerita sendiri menggunakan kad.\nHasil individu: Cerita lisan dua kejadian.\nKriteria: Kejadian mengikut urutan dan suara jelas.\nSusulan: Ulang bahagian yang belum lancar.","aids_and_pak21_original":"BBM/ABM: Tiga kad cerita\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menambahkan suara watak pada cerita.\nBahan: Kad cerita\nDialog pendek daripada buku\nBimbingan guru: Guru contohkan suara sedih dan gembira.\nGuru bantu memilih dialog yang pendek.\nLangkah murid: Pilih satu dialog.\nLatih suara watak.\nGunakan dialog itu semasa bercerita.\nHasil individu: Cerita dengan satu dialog watak.\nKriteria: Suara sesuai dengan perasaan watak.\nSusulan: Beri peluang berkongsi jika murid bersedia.","aids_and_pak21_original":"BBM/ABM: Kad cerita\nDialog pendek daripada buku\nPAK-21: Bercerita berpasangan dan bergilir-gilir mendengar cerita rakan."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian semasa bercerita.","Evidens":"Cerita lisan setiap murid ketika latihan dan persembahan.","Kriteria Kejayaan":"Dua kejadian diceritakan mengikut urutan dengan suara jelas."},"closure_original":"Tindakan guru: Guru tanya, “Apakah yang diucapkan selepas menerima bantuan?”\nGuru ajak kelas mengulang pengakhiran cerita.\nTindakan murid: Murid menyebut terima kasih.\nMurid mengulang bahagian pokok kembali subur.\nSemakan: Kukuhkan nilai saling membantu.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat mempersembahkan cerita dengan bahasa mudah. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M31-S4.docx","source_docx_sha256":"8b90a559a7e19c986dcca342906da4eb67b577cb53130588a0afebe0d7facf53","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M31-S5","week_no":31,"session_no":5,"lesson_map":{"title":"Harumnya Daun Kesum","sp":"5.3.1","page":48,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":31,"session":5,"revision":"r1","title_original":"Harumnya Daun Kesum","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.1(iv)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat melengkapkan tiga ruang dialog ayah–Hasan menggunakan ayat perintah yang sepadan dengan respons menyiram, memetik dan memberikan daun kesum kepada jiran.","success_criteria_original":"Tiga ayat perintah menyatakan tindakan serta objek yang sesuai dan tidak diubah menjadi ayat penyata.; Kata tolong, harap atau sila digunakan secara gramatis mengikut rangka dan konteks, tanpa menganggap semua kata wajib digunakan serentak.; Murid membaca semula pasangan perintah–respons untuk membuktikan kesepadanan maksud.","textbook_pages_original":"m/s 48","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca contoh awal buku “Hasan, tolong ambil botol plastik yang dipotong itu.” dan respons Hasan. Tanya siapa meminta tindakan dan siapa melaksanakannya.\nBandingkan ayat tolong ambil dengan saya akan mengambil; jelaskan kedua-duanya berkaitan tindakan sama tetapi fungsinya berbeza.\nTindakan murid: Tunjuk kad ayah atau Hasan mengikut ayat yang didengar.\nSebut perkataan yang menandakan permintaan dan tindakan yang perlu dilakukan.\nSemakan: Jika murid menganggap semua ayat tentang tindakan ialah perintah, ulang beza meminta dengan menyatakan tindakan sendiri.\nBahan: Dialog awal BT48 dan kad watak.","BBM/ABM":"Dialog awal BT48 dan kad watak.","PAK-21":"Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Siapa memberi arahan?","execution_original":"Tindakan guru: Baca contoh awal buku “Hasan, tolong ambil botol plastik yang dipotong itu.” dan respons Hasan. Tanya siapa meminta tindakan dan siapa melaksanakannya.\nBandingkan ayat tolong ambil dengan saya akan mengambil; jelaskan kedua-duanya berkaitan tindakan sama tetapi fungsinya berbeza.\nTindakan murid: Tunjuk kad ayah atau Hasan mengikut ayat yang didengar.\nSebut perkataan yang menandakan permintaan dan tindakan yang perlu dilakukan.\nSemakan: Jika murid menganggap semua ayat tentang tindakan ialah perintah, ulang beza meminta dengan menyatakan tindakan sendiri.\nBahan: Dialog awal BT48 dan kad watak.","aids_and_pak21_original":"BBM/ABM: Dialog awal BT48 dan kad watak.\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},{"phase_original":"Langkah 2\nModel — Baca respons sebelum mengisi","execution_original":"Tindakan guru: Tunjuk ruang “Tolong siram ___.” dan baca respons “Saya akan menyiram pokok kesum itu setiap petang.” Modelkan cara mengambil objek serta maklumat masa daripada respons.\nTulis contoh pelengkap guru “Tolong siram pokok kesum itu setiap petang.” Baca bersama respons dan terangkan bahawa ayat mesti sesuai, bukan semata-mata ada kata tolong.\nTindakan murid: Gariskan tindakan, objek dan masa pada respons di salinan guru.\nBaca pasangan lengkap dan cadangkan pelengkap lebih ringkas yang masih sesuai; jangan ubah tindakan menjadi menanam.\nSemakan: Terima variasi gramatis seperti menggugurkan masa jika respons masih menjelaskan masa, tetapi semak objek pokok kesum tetap tepat.\nBahan: Lembaran dialog, pen penanda dan kad siram/pokok kesum.","aids_and_pak21_original":"BBM/ABM: Lembaran dialog, pen penanda dan kad siram/pokok kesum.\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},{"phase_original":"Langkah 3\nLatihan terbeza — Tiga pesanan ayah","execution_original":"Tindakan guru: Agihkan tiga laluan bahan. Semua murid melengkapkan ruang menyiram, memetik dan memberikan daun kesum; bukan menulis arahan lain yang tidak menjawab dialog.\nTanya “Hasan hendak buat apa?” apabila murid tersalah objek. Tarik balik pilihan kad bagi murid yang mula dapat membina perintah sendiri.\nTindakan murid: Bergilir membaca respons Hasan dan mencadangkan perintah ayah dengan tindakan serta objek yang sepadan.\nSusun kad atau draf ayat, kemudian tulis jawapan sendiri dan semak melalui bacaan dua watak.\nSemakan: Pastikan ketiga-tiga ruang diusahakan. Jangan hanya mengulang satu arahan siram tiga kali atau menggantikan tugas dengan klasifikasi penyata/tanya sahaja.\nBahan: Kad respons, tindakan, objek dan kata perintah mengikut laluan.","aids_and_pak21_original":"BBM/ABM: Kad respons, tindakan, objek dan kata perintah mengikut laluan.\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},{"phase_original":"Langkah 4\nUji dialog — Masuk akal apabila dibaca","execution_original":"Tindakan guru: Berikan contoh salah guru “Harap kamu menyiram pokok itu” diikuti respons Hasan mahu memetik daun. Minta murid mengenal pasti ketidakpadanan tindakan.\nBincang bahawa tidak semua ayat perintah ialah larangan; halaman ini banyak menggunakan permintaan dan harapan. Tidak perlu memaksa perkataan jangan ke setiap ruang.\nTindakan murid: Pasangan membaca tiga pasangan ayat tanpa melihat model guru dan menandakan yang tidak sepadan.\nBaiki satu ayat jika tindakan, objek atau pelaku tersasar dan jelaskan perubahan kepada rakan.\nSemakan: Ayat yang sopan tetapi tidak menjawab respons masih perlu dibetulkan; bahasa sopan tidak menggantikan ketepatan konteks.\nBahan: Tiga pasangan dialog dan kad contoh salah guru.","aids_and_pak21_original":"BBM/ABM: Tiga pasangan dialog dan kad contoh salah guru.\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},{"phase_original":"Langkah 5\nPBD — Jawapan individu lengkap","execution_original":"Tindakan guru: Semak lembaran tiga ruang dan minta murid membaca satu pasangan pilihannya. Tandakan bentuk perintah serta kesepadanan maksud.\nJika jawapan masih meniru kad sepenuhnya, berikan satu respons sama tanpa kad dan minta murid menyebut perintahnya sendiri; rekod bantuan.\nTindakan murid: Serahkan tiga perintah yang dibina dan tunjuk tindakan yang sepadan pada setiap respons Hasan.\nBaca satu pasangan sebagai ayah dan Hasan; baiki struktur atau tanda baca selepas petunjuk guru.\nSemakan: PBD utama ialah menggunakan ayat perintah dalam dialog, bukan skor lakonan. Tiada TP automatik atau keputusan berdasarkan satu hasil pasangan sahaja.\nBahan: Lembaran individu dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Lembaran individu dan senarai semak.\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},{"phase_original":"Langkah 6\nPenutup — Arahan yang jelas dan sopan","execution_original":"Tindakan guru: Minta satu contoh perintah tentang memberikan daun kesum dan respons yang sesuai.\nRumusan urutan membaca respons, mengenal tindakan/objek dan membina perintah. Kaitkan dengan menjaga tanaman bersama keluarga.\nTindakan murid: Sebut satu perintah lengkap tanpa kad jika mampu.\nNyatakan sama ada kata tindakan atau objek yang masih memerlukan bantuan.\nSemakan: Catat unsur yang belum kukuh untuk intervensi, bukan menambah latihan umum yang tidak berkaitan dialog.\nBahan: BT48 dan kad tindakan.","aids_and_pak21_original":"BBM/ABM: BT48 dan kad tindakan.\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Susun perintah daripada respons berwarna","implementation_original":"Tugasan: Melengkapkan tiga perintah dengan tindakan dan objek ditandai, kemudian cuba satu ayat tanpa pilihan penuh.\nBahan: Respons Hasan dengan siram/petik/berikan digaris\nKad tolong/harap/sila serta objek yang sepadan\nRangka “Harap kamu dapat …” dan “Tolong … itu kepada jiran”\nBimbingan guru: Baca respons dan modelkan mencari tindakan melalui soalan buat apa. Beri dua pilihan objek, bukan terus ayat siap untuk disalin.\nSelepas pasangan pertama, tutup contoh dan kurangkan pilihan supaya murid memilih perintah bagi respons berikutnya.\nLangkah murid: Kenal pasti tindakan pada satu respons.\nPilih kata perintah dan objek lalu susun ayat.\nBaca perintah diikuti respons untuk menyemak maksud.\nTulis tiga ayat sendiri dan ulang satu tanpa melihat rangka penuh.\nHasil individu: Tiga pasangan dialog individu dengan tindakan/objek ditandai.\nKriteria: Ketiga-tiga perintah sepadan dan berbentuk arahan dengan bantuan direkod; jawapan separa tidak disamakan dengan objektif penuh.\nSusulan: Jika pelaku keliru, gunakan kad ayah meminta/Hasan melakukan sebelum melengkapkan dialog semula.","aids_and_pak21_original":"BBM/ABM: Respons Hasan dengan siram/petik/berikan digaris\nKad tolong/harap/sila serta objek yang sepadan\nRangka “Harap kamu dapat …” dan “Tolong … itu kepada jiran”\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},"pembina":{"label":"Langkah 1\nPembina — Bina ayat tanpa kad jawapan","implementation_original":"Tugasan: Menggunakan petunjuk respons untuk menulis tiga ayat perintah sendiri.\nBahan: BT48\nLembaran tiga ruang tanpa pilihan pelengkap\nSenarai semak kata perintah–tindakan–objek\nBimbingan guru: Minta murid membaca respons dahulu dan menjelaskan maklumat yang hendak digunakan.\nTanya adakah perintah itu boleh diikuti dengan respons buku tanpa mengubah tindakan; jangan memaksa satu skema ayat sahaja.\nLangkah murid: Gariskan kata tindakan dan objek pada setiap respons.\nTulis pelengkap yang sesuai bagi tolong siram, harap kamu dan ruang ayah terakhir.\nBaca kepada pasangan, dengar respons dan semak kesepadanan.\nBaiki struktur atau objek sendiri sebelum menyerahkan tiga ayat.\nHasil individu: Tiga perintah gramatis dan bacaan satu pasangan yang dapat difahami.\nKriteria: Tindakan menyiram, memetik dan memberikan dikekalkan, ayat tidak bertukar menjadi penyata dan kata perintah sesuai konteks.\nSusulan: Jika kukuh, cuba ungkap satu perintah dengan kata perintah lain tanpa mengubah tindakan; jika tidak, kembali kepada petunjuk respons.","aids_and_pak21_original":"BBM/ABM: BT48\nLembaran tiga ruang tanpa pilihan pelengkap\nSenarai semak kata perintah–tindakan–objek\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."},"pencabar":{"label":"Langkah 1\nPencabar — Pilihan kata perintah dan kesopanan","implementation_original":"Tugasan: Melengkapkan tiga perintah serta membandingkan dua ungkapan bagi satu permintaan tanpa mengubah maksud.\nBahan: BT48\nKad tolong/sila/harap\nKad perintah yang sengaja tidak sepadan respons\nBimbingan guru: Tanya perbezaan nuansa antara sila dan tolong dalam situasi ayah meminta bantuan. Terima penerangan mudah, bukan hafalan istilah.\nMinta murid menolak contoh ayat yang sopan tetapi salah tindakan dengan menunjukkan respons sebagai bukti.\nLangkah murid: Tulis tiga perintah yang menepati sasaran teras.\nPilih satu dan bina ungkapan alternatif yang masih gramatis.\nBandingkan kesopanan serta kesepadanan kedua-duanya apabila dibaca dengan respons.\nJelaskan satu ayat salah konteks dan baiki tindakan atau objeknya.\nHasil individu: Tiga jawapan teras serta satu perbandingan perintah bersebab.\nKriteria: Sasaran teras tepat dan perubahan kata perintah tidak merosakkan struktur atau maksud; bukan menambah arahan rawak.\nSusulan: Gunakan teknik yang sama pada satu permintaan awal buku sambil mengekalkan peranan penutur.","aids_and_pak21_original":"BBM/ABM: BT48\nKad tolong/sila/harap\nKad perintah yang sengaja tidak sepadan respons\nPAK-21: Rally Coach dialog: pembina membaca respons Hasan lalu mencadangkan perintah ayah, penyemak menilai tindakan dan objek; peranan bertukar bagi ruang berikutnya. Bacaan berperanan menguji sama ada dialog benar-benar bersambung."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan tiga ayat dalam dialog individu dan bacaan perintah–respons.","Evidens":"Tiga pelengkap ruang ayah, tindakan/objek sepadan dan penjelasan satu pilihan.","Kriteria Kejayaan":"Bentuk perintah, kesepadanan respons dan kegramatisan; bantuan dicatat."},"closure_original":"Tindakan guru: Minta satu contoh perintah tentang memberikan daun kesum dan respons yang sesuai.\nRumusan urutan membaca respons, mengenal tindakan/objek dan membina perintah. Kaitkan dengan menjaga tanaman bersama keluarga.\nTindakan murid: Sebut satu perintah lengkap tanpa kad jika mampu.\nNyatakan sama ada kata tindakan atau objek yang masih memerlukan bantuan.\nSemakan: Catat unsur yang belum kukuh untuk intervensi, bukan menambah latihan umum yang tidak berkaitan dialog.\nBahan: BT48 dan kad tindakan.","reflection_original":"____ / ____ murid melengkapkan tiga perintah; ____ masih menulis ayat penyata; ____ memerlukan pilihan objek. Bukti yang belum diperiksa: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M31-S5.docx","source_docx_sha256":"6a0271416e556be655d8ac7a1c52e3cc5159c73a996279bf5cdde7568bb5bde8","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":31,"session":5,"revision":"r2","title_original":"Harumnya Daun Kesum","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.1(iv)","sp_support_original":"—","objective_original":"Murid dapat menggunakan ayat perintah untuk melengkapkan dialog.","success_criteria_original":"Melengkapkan dua ayat perintah dalam dialog.; Menggunakan perkataan harap atau tolong dengan sesuai.","textbook_pages_original":"m/s 48","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru sebut, “Tolong buka buku.”\nGuru tanya perkataan yang digunakan untuk meminta bantuan.\nTindakan murid: Murid membuka buku.\nMurid menyebut perkataan tolong.\nSemakan: Beri contoh sekali lagi jika perlu.\nBahan: Buku teks halaman 48","BBM/ABM":"Buku teks halaman 48","PAK-21":"Lakonan dialog berpasangan sebagai ayah dan Hasan."},"six_phases_original":[{"phase_original":"Langkah 1\nDengar arahan","execution_original":"Tindakan guru: Guru sebut, “Tolong buka buku.”\nGuru tanya perkataan yang digunakan untuk meminta bantuan.\nTindakan murid: Murid membuka buku.\nMurid menyebut perkataan tolong.\nSemakan: Beri contoh sekali lagi jika perlu.\nBahan: Buku teks halaman 48","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 48\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."},{"phase_original":"Langkah 2\nBaca dialog","execution_original":"Tindakan guru: Guru baca dialog ayah dan Hasan.\nGuru tunjuk perkataan tolong, sila dan harap.\nTindakan murid: Murid ikut membaca dialog.\nMurid menyebut tiga perkataan tersebut.\nSemakan: Terangkan bahawa ayat perintah boleh digunakan untuk meminta seseorang melakukan sesuatu.\nBahan: Buku teks\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad perkataan\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."},{"phase_original":"Langkah 3\nLengkapkan bersama","execution_original":"Tindakan guru: Guru baca jawapan Hasan tentang menyiram pokok.\nGuru lengkapkan contoh: “Tolong siram pokok kesum itu setiap petang.”\nTindakan murid: Murid mengulang ayat contoh.\nMurid membaca jawapan Hasan tentang memetik daun kesum.\nSemakan: Pastikan murid memahami perbuatan siram dan petik.\nBahan: Buku teks\nRangka dialog","aids_and_pak21_original":"BBM/ABM: Buku teks\nRangka dialog\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri contoh permulaan “Harap kamu...” untuk ruang kedua.\nGuru bantu ruang akhir dengan “Tolong berikan...”\nTindakan murid: Murid melengkapkan ayat tentang memetik daun dan memberikan daun kepada jiran.\nMurid membaca dialog secara bergilir dengan pasangan.\nSemakan: Beri kad frasa kepada murid yang memerlukan bantuan.\nBahan: Kad ayat\nBuku teks","aids_and_pak21_original":"BBM/ABM: Kad ayat\nBuku teks\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."},{"phase_original":"Langkah 5\nTulis sendiri","execution_original":"Tindakan guru: Guru minta murid menulis dua ayat yang telah dilatih.\nGuru semak ayat mengikut jawapan Hasan.\nTindakan murid: Murid menulis “Harap kamu memetik daun kesum itu.”\nMurid menulis “Tolong berikan daun kesum itu kepada jiran.”\nSemakan: Terima ayat lain yang sesuai dengan dialog.\nBahan: Buku latihan\nBuku teks","aids_and_pak21_original":"BBM/ABM: Buku latihan\nBuku teks\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru pilih pasangan untuk membaca satu bahagian dialog.\nGuru ulang kegunaan tolong, sila dan harap.\nTindakan murid: Murid mendengar dialog rakan.\nMurid menyebut satu contoh permintaan yang sopan.\nSemakan: Betulkan permintaan yang kurang jelas secara lisan.\nBahan: Kad perkataan","aids_and_pak21_original":"BBM/ABM: Kad perkataan\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Melengkapkan ayat dengan frasa pilihan.\nBahan: Harap kamu ___.\nTolong berikan ___ kepada jiran.\nKad memetik daun kesum dan daun kesum\nBimbingan guru: Guru baca respons Hasan dahulu.\nGuru bantu memilih frasa yang sesuai.\nLangkah murid: Dengar bacaan guru.\nLetakkan frasa dalam ruang kosong.\nBaca dan tulis ayat yang lengkap.\nHasil individu: Dua ayat lengkap dengan bantuan.\nKriteria: Ayat sesuai dengan tindakan Hasan.\nSusulan: Ulang dialog secara lisan sebelum menulis.","aids_and_pak21_original":"BBM/ABM: Harap kamu ___.\nTolong berikan ___ kepada jiran.\nKad memetik daun kesum dan daun kesum\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Melengkapkan dua ayat perintah dalam dialog.\nBahan: Buku teks\nKad harap dan tolong\nBimbingan guru: Guru ingatkan murid membaca jawapan Hasan.\nGuru bantu ejaan apabila diminta.\nLangkah murid: Baca jawapan Hasan.\nCuba ayat dengan rakan.\nTulis dua ayat sendiri.\nHasil individu: Dua ayat perintah.\nKriteria: Perkataan perintah dan tindakan sesuai.\nSusulan: Baca semula ayat kepada pasangan.","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad harap dan tolong\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menggunakan sila dalam satu ayat perintah yang sopan.\nBahan: Kad sila\nGambar pokok kesum\nBimbingan guru: Guru tunjuk contoh “Sila masukkan tanah ke dalam botol itu.”\nGuru bantu murid memilih tindakan daripada dialog.\nLangkah murid: Pilih satu tindakan.\nBina ayat bermula dengan sila.\nGunakan ayat itu dalam lakonan pendek.\nHasil individu: Satu ayat lisan tambahan.\nKriteria: Ayat menyampaikan arahan yang jelas dan sopan.\nSusulan: Teruskan dialog jika murid mahu.","aids_and_pak21_original":"BBM/ABM: Kad sila\nGambar pokok kesum\nPAK-21: Lakonan dialog berpasangan sebagai ayah dan Hasan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan dua ayat dalam buku latihan.","Evidens":"Ayat perintah yang ditulis setiap murid.","Kriteria Kejayaan":"Dua ayat melengkapkan dialog dengan perkataan perintah yang sesuai."},"closure_original":"Tindakan guru: Guru pilih pasangan untuk membaca satu bahagian dialog.\nGuru ulang kegunaan tolong, sila dan harap.\nTindakan murid: Murid mendengar dialog rakan.\nMurid menyebut satu contoh permintaan yang sopan.\nSemakan: Betulkan permintaan yang kurang jelas secara lisan.\nBahan: Kad perkataan","reflection_original":"__ daripada __ murid dapat menggunakan ayat perintah dalam dialog. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M31-S5.docx","source_docx_sha256":"ff0851f9d92a580d9a304122e9957a88fcab1fe2a5476df7ea0dc72eefbec65f","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":31,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M32-S1","week_no":32,"session_no":1,"lesson_map":{"title":"Ternakan Ayam Hutan","sp":"1.2.2","page":49,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":32,"session":1,"revision":"r1","title_original":"Ternakan Ayam Hutan","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.2","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat memberikan empat respons lisan dalam dialog Ternakan Ayam Hutan, termasuk sekurang-kurangnya satu tafsiran beralasan tentang kaitan keistimewaan ayam dengan minat pembeli berdasarkan bahan.","success_criteria_original":"Empat respons meliputi pokok sebagai tempat tidur, makanan biji-bijian, ciri cantik dan alasan harga mahal yang munasabah.; Murid membezakan label yang dinyatakan dalam bahan daripada alasan yang disimpulkan; tidak menambah harga, status liar atau kelebihan kesihatan yang tidak diberikan.; Penjelasan jelas dan sepadan dengan pertanyaan Idris, dengan bantuan bahasa direkod.","textbook_pages_original":"m/s 49","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk empat label pada BT49 dan baca tidur di atas pokok serta biji-bijian. Tanya label mana menjawab soalan tentang makanan.\nBaca kotak info biji-bijian supaya murid memahami frasa sebelum menggunakannya dalam respons.\nTindakan murid: Padankan label makanan dengan soalan apa yang dimakan.\nSebut satu contoh biji-bijian daripada kotak info, bukan senarai makanan yang direka.\nSemakan: Jika murid tertukar ciri cantik dengan makanan, baca semula kata tanya apa makanan dan tunjuk kategori label.\nBahan: BT49 serta kad fakta.","BBM/ABM":"BT49 serta kad fakta.","PAK-21":"Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Empat petunjuk ayam hutan","execution_original":"Tindakan guru: Tunjuk empat label pada BT49 dan baca tidur di atas pokok serta biji-bijian. Tanya label mana menjawab soalan tentang makanan.\nBaca kotak info biji-bijian supaya murid memahami frasa sebelum menggunakannya dalam respons.\nTindakan murid: Padankan label makanan dengan soalan apa yang dimakan.\nSebut satu contoh biji-bijian daripada kotak info, bukan senarai makanan yang direka.\nSemakan: Jika murid tertukar ciri cantik dengan makanan, baca semula kata tanya apa makanan dan tunjuk kategori label.\nBahan: BT49 serta kad fakta.","aids_and_pak21_original":"BBM/ABM: BT49 serta kad fakta.\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},{"phase_original":"Langkah 2\nModel — Jawapan berasaskan label dan tafsiran","execution_original":"Tindakan guru: Baca dua giliran awal Idris–Hasan dan modelkan contoh respons guru “Ayam hutan suka kawasan banyak pokok kerana ayam itu tidur di atas pokok.”\nTunjuk label cantik dan dialog tentang penggemar. Bezakan fakta cantik daripada tafsiran “Keistimewaannya mungkin menarik minat penggemar”; jangan menyatakan harga sebenar atau jaminan sebab tunggal.\nTindakan murid: Gariskan petunjuk yang digunakan untuk menjawab setiap soalan pada salinan.\nCuba menjawab soalan makanan dengan ayat lengkap dan sebut bahagian bahan yang membantu.\nSemakan: Respons perlu menerangkan, bukan menyebut label sahaja. Perkataan mungkin/berdasarkan bahan membantu mengehadkan tafsiran tanpa memadam fakta.\nBahan: Dialog BT49 dan jalur Fakta–Tafsiran.","aids_and_pak21_original":"BBM/ABM: Dialog BT49 dan jalur Fakta–Tafsiran.\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},{"phase_original":"Langkah 3\nLatihan terbeza — Temu bual Idris dan Hasan","execution_original":"Tindakan guru: Gunakan tiga laluan bantuan di bawah. Semua murid berlatih empat respons, dengan sokongan berbeza untuk memilih fakta dan memberikan alasan.\nDengar pasangan, tanya “Ini label buku atau tafsiran kamu?” pada jawapan harga mahal. Jika alasan tentang sukar diternak tiada bukti, minta mereka kembali kepada cantik dan penggemar.\nTindakan murid: Bergilir bertanya serta menjawab empat soalan menggunakan bukti bahan.\nTukar watak dan perbaiki satu respons yang terlalu pendek atau melampaui maklumat.\nSemakan: Jangan anggap seorang penerang yang petah mewakili semua ahli. Catat respons setiap murid apabila didengar.\nBahan: Kad soalan, label, watak dan rangka alasan.","aids_and_pak21_original":"BBM/ABM: Kad soalan, label, watak dan rangka alasan.\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},{"phase_original":"Langkah 4\nSemak alasan — Boleh diketahui atau belum pasti?","execution_original":"Tindakan guru: Beri dua contoh guru: “Bahan menyebut ayam itu cantik” dan “Setiap ayam hutan berharga RM500”. Tanya yang mana disokong bahan.\nMinta murid menyusun jawapan harga mahal sebagai tafsiran yang berhati-hati, tanpa menambah fakta pasaran sebenar.\nTindakan murid: Nyatakan bukti atau ketiadaan bukti bagi dua dakwaan.\nUbah dakwaan harga kepada alasan munasabah yang berpaut ciri serta minat penggemar dalam dialog.\nSemakan: Tekankan perbezaan fakta label dengan inferens; tidak menilai ketepatan angka harga kerana angka tiada dalam bahan.\nBahan: Kad dakwaan rekaan guru dan BT49.","aids_and_pak21_original":"BBM/ABM: Kad dakwaan rekaan guru dan BT49.\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},{"phase_original":"Langkah 5\nPBD — Empat respons individu","execution_original":"Tindakan guru: Dengar empat respons ringkas daripada murid yang belum diperhatikan; gunakan juga catatan latihan bagi murid yang sudah didengar.\nTanda fakta tepat, respons sesuai soalan dan sekurang-kurangnya satu tafsiran beralasan. Murid belum sempat didengar ditanda susulan.\nTindakan murid: Jawab soalan Idris dengan kata sendiri tanpa pasangan membisikkan jawapan.\nTunjuk petunjuk apabila guru meminta bukti dan jelaskan satu tafsiran menggunakan kerana.\nSemakan: Jangan menjadikan hafalan dialog tepat sebagai satu-satunya ukuran. Respons dengan makna sama boleh diterima jika jelas dan berasas.\nBahan: Senarai semak lisan serta kad kata kunci jika perlu.","aids_and_pak21_original":"BBM/ABM: Senarai semak lisan serta kad kata kunci jika perlu.\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},{"phase_original":"Langkah 6\nPenutup — Fakta membantu alasan","execution_original":"Tindakan guru: Minta murid menyebut satu fakta label dan satu tafsiran yang berlainan.\nRumusan bahawa penerangan baik membezakan apa yang diketahui daripada apa yang disimpulkan.\nTindakan murid: Sebut makanan atau tempat tidur sebagai fakta, kemudian jelaskan satu kaitan yang munasabah.\nNyatakan soalan yang masih memerlukan rangka ayat.\nSemakan: Pilih intervensi berdasarkan kesukaran fakta atau alasan, bukan terus mengulangi semua dialog tanpa tujuan.\nBahan: BT49 dan jalur Fakta–Tafsiran.","aids_and_pak21_original":"BBM/ABM: BT49 dan jalur Fakta–Tafsiran.\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Label ke ayat lengkap","implementation_original":"Tugasan: Menjawab empat soalan dengan kad fakta dan rangka alasan yang dikurangkan secara bertahap.\nBahan: Empat label buku berasingan\nRangka “Ayam hutan makan …” dan “Ayam ini disukai kerana …”\nKad Fakta/Tafsiran\nBimbingan guru: Baca soalan dan minta murid memilih label sesuai sebelum membina ayat; tunjuk contoh satu respons sahaja.\nBagi soalan harga, bantu mengaitkan cantik dengan penggemar, kemudian tutup ayat model supaya murid cuba menjelaskan sendiri.\nLangkah murid: Padankan soalan dengan label.\nSebut ayat lengkap daripada label tersebut.\nTentukan respons mana memerlukan alasan dan tambah kerana dengan bantuan.\nTukar watak, jawab semula empat soalan dan cuba satu tanpa rangka.\nHasil individu: Empat respons lisan, termasuk tafsiran yang jelas ditandai.\nKriteria: Fakta tepat dan satu alasan berkaitan, dengan bantuan dicatat; jawapan dua soalan sahaja belum menepati sasaran penuh.\nSusulan: Jika kategori tertukar, latih makanan/ciri/tempat dahulu; jika alasan lemah, gunakan satu label dan satu penghubung sebelum kembali kepada dialog.","aids_and_pak21_original":"BBM/ABM: Empat label buku berasingan\nRangka “Ayam hutan makan …” dan “Ayam ini disukai kerana …”\nKad Fakta/Tafsiran\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},"pembina":{"label":"Langkah 1\nPembina — Fakta dipilih sendiri","implementation_original":"Tugasan: Melengkapkan dialog menggunakan empat petunjuk sumber tanpa pilihan jawapan penuh.\nBahan: BT49\nKad soalan Idris sahaja\nJalur kata kunci dan bukti\nBimbingan guru: Minta murid menunjuk petunjuk sebelum menerima respons, terutama pada penjelasan keistimewaan.\nTanya apakah batas alasan harga supaya murid tidak menganggap tafsiran sebagai angka atau hukum pasaran.\nLangkah murid: Baca bahan dan catat empat kata kunci.\nJawab soalan pasangan dengan ayat lengkap.\nBeri tafsiran untuk harga dengan kaitan cantik atau penggemar.\nTukar peranan dan baiki satu respons selepas diminta bukti.\nHasil individu: Empat respons kendiri dengan satu tafsiran beralasan.\nKriteria: Respons sepadan pertanyaan, fakta tepat dan tafsiran munasabah tanpa dakwaan luar sumber; adab perbualan dijaga.\nSusulan: Jika kukuh, nilai dakwaan harga rekaan; jika belum, kembali kepada label yang paling relevan dengan soalan.","aids_and_pak21_original":"BBM/ABM: BT49\nKad soalan Idris sahaja\nJalur kata kunci dan bukti\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."},"pencabar":{"label":"Langkah 1\nPencabar — Alasan yang mempunyai batas","implementation_original":"Tugasan: Menjelaskan empat respons dan menilai sama ada satu alasan tambahan mempunyai sokongan yang cukup.\nBahan: BT49\nKad dakwaan harga tetap atau sifat perubatan berlabel rekaan guru\nJalur Ada bukti/Belum cukup bukti\nBimbingan guru: Minta murid menolak dakwaan yang tidak dinyatakan tanpa membuat dakwaan baharu yang sama tidak berasas.\nTanya bagaimana jawapan boleh lebih berhati-hati tetapi masih menjawab soalan Idris dengan jelas.\nLangkah murid: Lengkapkan empat respons sasaran teras.\nPilih satu dakwaan guru dan cari bukti dalam bahan.\nJika tiada, nyatakan batas pengetahuan dengan sopan dan bina tafsiran yang lebih munasabah.\nTerangkan perbezaan dua jawapan kepada pasangan serta jawab satu pertanyaan susulan.\nHasil individu: Respons lengkap dan penilaian satu dakwaan berserta alasan.\nKriteria: Sasaran teras tercapai serta murid membezakan label, inferens dan maklumat luar; bukan panjang jawapan atau pengetahuan pasaran.\nSusulan: Amalkan struktur bukti–tafsiran pada soalan lain dengan mengekalkan maklumat label yang sebenar.","aids_and_pak21_original":"BBM/ABM: BT49\nKad dakwaan harga tetap atau sifat perubatan berlabel rekaan guru\nJalur Ada bukti/Belum cukup bukti\nPAK-21: Simulasi temu bual: penanya menggunakan soalan Idris, penerang menjadi Hasan; selepas empat soalan peranan ditukar. Rakan meminta alasan bagi tafsiran, bukan menerima semua jawapan sebagai fakta tercetak."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian empat respons dialog dan penjelasan alasan individu.","Evidens":"Respons tentang pokok, makanan, keistimewaan dan harga; satu alasan tersirat berasas.","Kriteria Kejayaan":"Fakta tepat, jawapan relevan dan tafsiran tidak melampaui sumber tanpa ditandai."},"closure_original":"Tindakan guru: Minta murid menyebut satu fakta label dan satu tafsiran yang berlainan.\nRumusan bahawa penerangan baik membezakan apa yang diketahui daripada apa yang disimpulkan.\nTindakan murid: Sebut makanan atau tempat tidur sebagai fakta, kemudian jelaskan satu kaitan yang munasabah.\nNyatakan soalan yang masih memerlukan rangka ayat.\nSemakan: Pilih intervensi berdasarkan kesukaran fakta atau alasan, bukan terus mengulangi semua dialog tanpa tujuan.\nBahan: BT49 dan jalur Fakta–Tafsiran.","reflection_original":"____ / ____ murid memberikan empat respons berasas; ____ memerlukan rangka alasan; ____ belum diperhatikan. Fakta atau tafsiran yang keliru: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M32-S1.docx","source_docx_sha256":"3100b8a6b565e1b956e6e1290867291461a5c548232683befa99bd179b93a977","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":32,"session":1,"revision":"r2","title_original":"Ternakan Ayam Hutan","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.2","sp_support_original":"—","objective_original":"Murid dapat menjelaskan maklumat tersurat dan tersirat tentang ayam hutan dengan ayat mudah.","success_criteria_original":"Menyebut makanan ayam hutan dengan betul.; Memberi satu sebab ayam hutan diminati penggemar.","textbook_pages_original":"m/s 49","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk ayam hutan pada BT49.\nGuru tanya, ‘Apakah makanan ayam?’\nTindakan murid: Murid lihat gambar ayam hutan.\nMurid sebut makanan ayam yang diketahui.\nSemakan: Guru dengar perkataan yang sudah dikenali murid.\nBahan: BT49.","BBM/ABM":"BT49.","PAK-21":"Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk ayam hutan pada BT49.\nGuru tanya, ‘Apakah makanan ayam?’\nTindakan murid: Murid lihat gambar ayam hutan.\nMurid sebut makanan ayam yang diketahui.\nSemakan: Guru dengar perkataan yang sudah dikenali murid.\nBahan: BT49.","aids_and_pak21_original":"BBM/ABM: BT49.\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca label tidur di atas pokok dan biji-bijian.\nGuru beri contoh: ‘Ayam hutan makan biji-bijian seperti jagung.’\nTindakan murid: Murid tunjuk label makanan.\nMurid ulang contoh jawapan bersama guru.\nSemakan: Murid mengaitkan biji-bijian dengan makanan ayam hutan.\nBahan: BT49 dan kad biji-bijian.","aids_and_pak21_original":"BBM/ABM: BT49 dan kad biji-bijian.\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru tanya, ‘Mengapa agaknya penggemar suka ayam hutan?’\nGuru beri contoh: ‘Mungkin kerana ayam hutan cantik.’\nTindakan murid: Murid lihat label cantik.\nMurid cuba memberi sebab dengan perkataan kerana.\nSemakan: Guru bantu murid menyambung sebab yang berkaitan dengan ayam hutan.\nBahan: BT49 dan rangka ‘Mungkin kerana …’.","aids_and_pak21_original":"BBM/ABM: BT49 dan rangka ‘Mungkin kerana …’.\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru beri soalan tentang makanan dan minat penggemar mengikut laluan bantuan.\nGuru dengar jawapan murid semasa pasangan bertukar watak.\nTindakan murid: Murid bertanya kepada pasangan sebagai Idris.\nMurid menjawab sebagai Hasan dengan bantuan kad jika perlu.\nSemakan: Guru perhatikan dua jawapan setiap murid semasa latihan.\nBahan: BT49, kad kata dan rangka ayat.","aids_and_pak21_original":"BBM/ABM: BT49, kad kata dan rangka ayat.\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru tanya dua soalan yang telah dilatih kepada murid yang belum didengar.\nGuru betulkan satu jawapan dengan contoh ayat pendek.\nTindakan murid: Murid memberi jawapan sendiri dengan bantuan jika perlu.\nMurid cuba menyebut semula jawapan yang dibetulkan.\nSemakan: Catat ketepatan makanan dan kesesuaian sebab serta bantuan yang digunakan.\nBahan: Kad kata dan senarai semak lisan.","aids_and_pak21_original":"BBM/ABM: Kad kata dan senarai semak lisan.\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tanya semula tempat ayam hutan tidur.\nGuru rumuskan makanan dan keistimewaan ayam hutan.\nTindakan murid: Murid menjawab bersama-sama.\nMurid sebut satu perkara yang dipelajari.\nSemakan: Guru kenal pasti murid yang masih memerlukan rangka jawapan.\nBahan: BT49.","aids_and_pak21_original":"BBM/ABM: BT49.\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Jawab bersama","implementation_original":"Tugasan: Menjawab soalan makanan dan minat penggemar bersama pasangan.\nBahan: BT49\nKad biji-bijian dan cantik\nRangka ‘Ayam hutan makan …’\nBimbingan guru: Guru padankan soalan makanan dengan kad biji-bijian.\nGuru bantu murid menyebut ‘Mungkin kerana ayam hutan cantik.’\nLangkah murid: Pilih kad yang sesuai.\nCuba jawapan bersama pasangan.\nJawab dua soalan guru dengan bantuan yang diperlukan.\nHasil individu: Dua jawapan lisan setiap murid.\nKriteria: Makanan betul dan sebab mudah sesuai.\nSusulan: Ulang soalan yang sukar dengan rangka ayat yang sama.","aids_and_pak21_original":"BBM/ABM: BT49\nKad biji-bijian dan cantik\nRangka ‘Ayam hutan makan …’\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},"pembina":{"label":"Langkah 1\nPembina — Pilih kata sendiri","implementation_original":"Tugasan: Menggunakan kata kunci untuk menjelaskan makanan dan sebab ayam hutan diminati.\nBahan: BT49\nBank kata biji-bijian, cantik dan penggemar\nBimbingan guru: Guru tunjuk tempat jawapan makanan pada halaman buku.\nGuru bantu dengan permulaan ‘Penggemar suka ayam ini kerana …’ jika perlu.\nLangkah murid: Pilih kata kunci bersama pasangan.\nBergilir bertanya dan menjawab.\nBerikan dua jawapan sendiri kepada guru.\nHasil individu: Dua jawapan lisan menggunakan kata yang dipilih.\nKriteria: Jawapan menjelaskan makanan dan satu sebab yang sesuai.\nSusulan: Baiki jawapan yang masih berupa satu perkataan dengan rangka ayat.","aids_and_pak21_original":"BBM/ABM: BT49\nBank kata biji-bijian, cantik dan penggemar\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."},"pencabar":{"label":"Langkah 1\nPencabar — Tambah satu contoh","implementation_original":"Tugasan: Menambah satu contoh biji-bijian pada jawapan makanan jika bersedia.\nBahan: BT49\nKotak info padi, gandum dan jagung\nBimbingan guru: Guru tunjuk contoh biji-bijian dalam kotak info.\nGuru beri permulaan ‘Ayam hutan makan biji-bijian seperti …’.\nLangkah murid: Latih dua jawapan bersama pasangan.\nPilih satu contoh biji-bijian daripada buku.\nSebut jawapan makanan dengan contoh pilihan.\nHasil individu: Dua jawapan lisan dengan satu contoh makanan.\nKriteria: Contoh yang dipilih sesuai dengan biji-bijian.\nSusulan: Gunakan contoh itu semula apabila pasangan bertanya tentang makanan.","aids_and_pak21_original":"BBM/ABM: BT49\nKotak info padi, gandum dan jagung\nPAK-21: Soal jawab berpasangan: murid menjadi Idris dan Hasan secara bergilir."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian lisan semasa latihan dan soal jawab individu.","Evidens":"Dua jawapan murid tentang makanan dan sebab ayam hutan diminati.","Kriteria Kejayaan":"Murid menyatakan makanan yang betul dan satu sebab yang sesuai."},"closure_original":"Tindakan guru: Guru tanya semula tempat ayam hutan tidur.\nGuru rumuskan makanan dan keistimewaan ayam hutan.\nTindakan murid: Murid menjawab bersama-sama.\nMurid sebut satu perkara yang dipelajari.\nSemakan: Guru kenal pasti murid yang masih memerlukan rangka jawapan.\nBahan: BT49.","reflection_original":"__ daripada __ murid dapat menjelaskan maklumat tentang ayam hutan. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M32-S1.docx","source_docx_sha256":"33fb2f3118e9adb8136e803ae7d5def5c896e81ab4ca2599e4dbc2d89888eb2a","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M32-S2","week_no":32,"session_no":2,"lesson_map":{"title":"Kolam Ikan dan Hasilnya","sp":"2.2.1","page":50,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":32,"session":2,"revision":"r1","title_original":"Kolam Ikan dan Hasilnya","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1(ii)(iii)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat mengenal pasti tiga pasangan isi tersurat dan isi tersirat daripada perenggan kedua hingga keempat Kolam Ikan dan Hasilnya serta menunjukkan ayat bukti bagi setiap pasangan.","success_criteria_original":"Tiga isi tersurat diambil daripada tindakan memilih sangkar besi, melepaskan benih atau memberi makan dan menjual ikan; maklumat tidak diubah.; Tafsiran munasabah berkaitan ayat bukti dan dibezakan daripada fakta yang benar-benar ditulis.; Murid menerangkan sebab padanan sekurang-kurangnya satu pasangan dengan kata sendiri; bantuan membaca dicatat.","textbook_pages_original":"m/s 50","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca tajuk dan ayat pertama. Tanya tempat sebenar Aidil serta bapanya menternak tilapia dalam cerita.\nTunjuk perkataan sangkar dan sungai untuk memperlihatkan pentingnya membaca isi, bukan membuat andaian berdasarkan tajuk.\nTindakan murid: Kenal pasti sangkar di sungai sebagai lokasi yang disebut.\nTunjuk frasa yang menyokong jawapan dan sebut satu maklumat lain daripada perenggan pertama.\nSemakan: Jika murid menjawab kolam semata-mata kerana tajuk, baca kembali ayat pertama dan bezakan tajuk dengan butiran cerita.\nBahan: BT50 dan jalur perenggan pertama.","BBM/ABM":"BT50 dan jalur perenggan pertama.","PAK-21":"Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Sungai atau kolam?","execution_original":"Tindakan guru: Baca tajuk dan ayat pertama. Tanya tempat sebenar Aidil serta bapanya menternak tilapia dalam cerita.\nTunjuk perkataan sangkar dan sungai untuk memperlihatkan pentingnya membaca isi, bukan membuat andaian berdasarkan tajuk.\nTindakan murid: Kenal pasti sangkar di sungai sebagai lokasi yang disebut.\nTunjuk frasa yang menyokong jawapan dan sebut satu maklumat lain daripada perenggan pertama.\nSemakan: Jika murid menjawab kolam semata-mata kerana tajuk, baca kembali ayat pertama dan bezakan tajuk dengan butiran cerita.\nBahan: BT50 dan jalur perenggan pertama.","aids_and_pak21_original":"BBM/ABM: BT50 dan jalur perenggan pertama.\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},{"phase_original":"Langkah 2\nModel — Fakta bertulis dan maksud disimpulkan","execution_original":"Tindakan guru: Tunjuk pasangan contoh buku: air bersih serta mengalir dan tafsiran bekalan oksigen serta pengeluaran bahan buangan.\nBaca perenggan kedua, pilih sangkar besi dan modelkan contoh tafsiran guru bahawa sangkar yang kukuh membantu menempatkan ikan. Nyatakan ini inferens munasabah, bukan ayat yang perlu dicari secara literal.\nTindakan murid: Gariskan isi tersurat dalam ayat dan letakkan pada lajur kiri.\nBezakan ayat petikan daripada penjelasan tujuan di lajur kanan; sebut hubungan dengan penghubung supaya atau kerana.\nSemakan: Jangan menuntut satu frasa inferens yang sama untuk semua murid jika alasan lain masih berasas. Tolak dakwaan jaminan keselamatan atau hasil jualan yang tidak dinyatakan.\nBahan: Jadual model dan perenggan kedua.","aids_and_pak21_original":"BBM/ABM: Jadual model dan perenggan kedua.\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},{"phase_original":"Langkah 3\nLatihan terbeza — Tiga pasangan berasaskan perenggan","execution_original":"Tindakan guru: Laksanakan laluan sokongan/teras/cabaran bagi perenggan kedua hingga keempat. Semua murid menyediakan tiga pasangan selepas contoh perenggan pertama.\nBimbing murid memisahkan fakta 500 ekor dan waktu pagi daripada alasan tentang perancangan atau penjagaan. Tanya “Apa yang ditulis?” dahulu sebelum “Apakah yang boleh disimpulkan?”.\nTindakan murid: Baca setiap perenggan, pilih fakta penting dan cadangkan isi tersirat yang relevan.\nBergilir menerangkan bukti dengan pasangan dan menulis tiga pasangan sendiri pada jadual.\nSemakan: Inferens yang memerlukan fakta luar, seperti suhu tertentu atau kadar tumbesaran, tidak diwajibkan. Murid boleh merujuk penjagaan teratur dan tujuan jualan berdasarkan cerita.\nBahan: BT50, jadual individu, kad fakta dan rangka alasan.","aids_and_pak21_original":"BBM/ABM: BT50, jadual individu, kad fakta dan rangka alasan.\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},{"phase_original":"Langkah 4\nSemak bukti — Betulkan padanan tersasar","execution_original":"Tindakan guru: Paparkan contoh guru fakta ikan dijual kepada peraih tetapi tafsirannya ikan dibekalkan kepada semua sekolah. Tanya adakah destinasi itu disokong.\nMinta murid membaiki satu padanan dengan alasan yang lebih munasabah, misalnya ternakan menghasilkan bekalan untuk dijual, tanpa mereka jumlah pendapatan.\nTindakan murid: Cari maklumat peraih pada perenggan akhir dan jelaskan mengapa kad sekolah tidak boleh dianggap fakta.\nSemak jadual rakan dan beri komen pada satu hubungan fakta–tafsiran, bukan sekadar ejaan.\nSemakan: Pastikan murid tidak menolak semua inferens kerana ayatnya tiada secara literal; inferens boleh diterima jika berasaskan bukti dan tidak bercanggah.\nBahan: Kad gangguan, perenggan akhir dan jadual.","aids_and_pak21_original":"BBM/ABM: Kad gangguan, perenggan akhir dan jadual.\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},{"phase_original":"Langkah 5\nPBD — Tiga pasangan individu","execution_original":"Tindakan guru: Semak jadual dan minta murid memilih satu pasangan untuk menerangkan ayat bukti serta alasannya.\nCatat isi tepat, tafsiran relevan dan bantuan; jika hanya contoh siap perenggan pertama disalin, minta satu pasangan baharu.\nTindakan murid: Tunjuk tiga fakta pilihan dan ayat asal yang berkaitan.\nJelaskan satu inferens dengan kata sendiri dan baiki jika maknanya melampaui bahan.\nSemakan: Sasaran tiga pasangan tidak diukur melalui bacaan kuat semata-mata. Pelbagai bentuk jawapan ringkas diterima asalkan hubungan jelas.\nBahan: Jadual individu dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Jadual individu dan senarai semak.\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},{"phase_original":"Langkah 6\nPenutup — Dua soalan pembaca teliti","execution_original":"Tindakan guru: Rumusan menggunakan soalan “Apa yang dinyatakan?” dan “Apakah maksud atau tujuan yang boleh disimpulkan?”.\nPilih satu fakta pemberian makanan setiap hari untuk murid menerangkan secara ringkas.\nTindakan murid: Sebut fakta dan satu tujuan penjagaan yang munasabah.\nNyatakan sama ada mereka masih sukar mencari ayat bukti atau membina alasan.\nSemakan: Gunakan maklumat itu untuk menentukan intervensi membaca atau inferens, bukan mengulang latihan sama tanpa diagnosis.\nBahan: BT50 dan dua kad soalan.","aids_and_pak21_original":"BBM/ABM: BT50 dan dua kad soalan.\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Fakta bergaris dan alasan pilihan","implementation_original":"Tugasan: Mengenal pasti tiga pasangan melalui petunjuk bacaan serta dua pilihan tafsiran yang jelas berbeza.\nBahan: Perenggan kedua hingga keempat dengan fakta bergaris\nKad sangkar besi/500 benih/makan setiap hari\nRangka “Ayat menyatakan …; ini membantu …”\nBimbingan guru: Baca satu fakta bersama murid dan tanya tujuan yang berkaitan, bukan terus memberi semua padanan.\nBagi pasangan berikutnya, tutup satu pilihan jawapan dan minta murid menyebut alasan sebelum mencatat.\nLangkah murid: Cari fakta bergaris dan baca dengan bantuan.\nPilih tafsiran yang sepadan lalu tolak pilihan tidak berkaitan.\nLengkapkan tiga baris jadual sendiri dengan frasa ringkas.\nTunjuk ayat bukti dan sebut satu pasangan tanpa membaca seluruh model guru.\nHasil individu: Tiga pasangan catatan individu dengan bukti ditandai.\nKriteria: Fakta tepat dan tafsiran berkaitan dengan bantuan direkod; jika dua pasangan sahaja, sasaran belum penuh dan satu pasangan dilatih semula.\nSusulan: Ulang fakta dahulu jika bacaan mengelirukan; kemudian gunakan satu kata tujuan supaya sebelum kembali kepada jadual.","aids_and_pak21_original":"BBM/ABM: Perenggan kedua hingga keempat dengan fakta bergaris\nKad sangkar besi/500 benih/makan setiap hari\nRangka “Ayat menyatakan …; ini membantu …”\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},"pembina":{"label":"Langkah 1\nPembina — Membaca dan menyimpulkan sendiri","implementation_original":"Tugasan: Memilih isi penting perenggan kedua hingga keempat dan menulis tiga tafsiran yang berpaut kepada fakta.\nBahan: BT50\nJadual dua lajur kosong selepas contoh buku\nKad semakan Apa bukti?/Apa tujuan?\nBimbingan guru: Tanya bahagian ayat yang menyokong tafsiran tanpa menyediakan senarai jawapan penuh.\nSemak maklumat tepat seperti jumlah benih dan peraih; pembetulan angka tidak menggantikan penjelasan maksud.\nLangkah murid: Baca perenggan dan gariskan fakta utama.\nCatat fakta serta satu inferens munasabah dalam jadual.\nMinta pasangan menilai hubungan dan tunjuk bukti.\nBaiki tafsiran yang terlalu jauh kemudian terangkan satu pasangan kepada guru.\nHasil individu: Tiga pasangan fakta–inferens dengan satu penjelasan kendiri.\nKriteria: Hubungan munasabah, isi tidak bercanggah dan ayat petikan dibezakan daripada inferens, bukan menyalin dua ayat fakta ke dua lajur.\nSusulan: Jika kukuh, uji dakwaan tanpa bukti; jika lemah, fokus satu perenggan sehingga fakta dan tujuan dapat dipisahkan.","aids_and_pak21_original":"BBM/ABM: BT50\nJadual dua lajur kosong selepas contoh buku\nKad semakan Apa bukti?/Apa tujuan?\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."},"pencabar":{"label":"Langkah 1\nPencabar — Inferens munasabah tanpa menambah fakta","implementation_original":"Tugasan: Membina tiga pasangan dan membandingkan dua tafsiran untuk menentukan yang lebih disokong.\nBahan: BT50\nKad tafsiran kukuh/lemah contoh guru\nJalur Bukti mencukupi/Perlu maklumat tambahan\nBimbingan guru: Tanya sama ada bahan membuktikan harga jualan atau destinasi selain peraih; murid perlu menyatakan batas maklumat.\nGalakkan perbandingan alasan, bukan menambah butiran teknikal ternakan yang tidak perlu untuk SP.\nLangkah murid: Lengkapkan tiga pasangan sasaran teras.\nPilih satu fakta dan bina dua kemungkinan tafsiran yang berbeza kekuatan.\nTentukan yang lebih munasabah dengan merujuk ayat sekitar.\nTerangkan tafsiran yang ditolak serta maklumat tambahan yang diperlukan untuk menyokongnya.\nHasil individu: Jadual tiga pasangan dan satu penilaian tafsiran berserta alasan.\nKriteria: Sasaran teras tepat serta murid membezakan inferens berasas daripada dakwaan luar; jawapan panjang tanpa bukti tidak diberi kelebihan.\nSusulan: Gunakan kaedah sama pada contoh perenggan pertama untuk memahami mengapa buku memberikan tafsiran tersebut.","aids_and_pak21_original":"BBM/ABM: BT50\nKad tafsiran kukuh/lemah contoh guru\nJalur Bukti mencukupi/Perlu maklumat tambahan\nPAK-21: Evidence Pair: pembaca mencari isi tersurat, pasangan menjelaskan tafsiran dan meminta bukti; peranan bergilir bagi perenggan berikutnya. Produk individu berupa tiga pasangan, bukan satu poster kumpulan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan jadual isi serta soal jawab bukti individu.","Evidens":"Tiga pasangan isi daripada perenggan kedua hingga keempat dan satu penjelasan bersebab.","Kriteria Kejayaan":"Fakta tepat, inferens relevan dan bukti boleh ditunjukkan; bantuan direkod."},"closure_original":"Tindakan guru: Rumusan menggunakan soalan “Apa yang dinyatakan?” dan “Apakah maksud atau tujuan yang boleh disimpulkan?”.\nPilih satu fakta pemberian makanan setiap hari untuk murid menerangkan secara ringkas.\nTindakan murid: Sebut fakta dan satu tujuan penjagaan yang munasabah.\nNyatakan sama ada mereka masih sukar mencari ayat bukti atau membina alasan.\nSemakan: Gunakan maklumat itu untuk menentukan intervensi membaca atau inferens, bukan mengulang latihan sama tanpa diagnosis.\nBahan: BT50 dan dua kad soalan.","reflection_original":"____ / ____ murid mengenal tiga pasangan isi; ____ memerlukan petunjuk ayat; ____ masih mencampurkan fakta dengan tafsiran. Pasangan yang perlu susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M32-S2.docx","source_docx_sha256":"d8bfce32ff9010596787eb7eda2d5241a203c503bc14e07e142a4400d795572b","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":32,"session":2,"revision":"r2","title_original":"Kolam Ikan dan Hasilnya","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1(ii)(iii)","sp_support_original":"—","objective_original":"Murid dapat mengenal pasti isi tersurat dan isi tersirat dalam teks tentang ternakan ikan.","success_criteria_original":"Menyatakan satu perkara yang dilakukan oleh Aidil.; Memberi satu sebab ikan diberi makan.","textbook_pages_original":"m/s 50","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Kolam Ikan dan Hasilnya pada BT50.\nGuru tanya, “Apakah makanan ikan?”\nTindakan murid: Murid sebut ikan yang dikenalinya.\nMurid kongsi jawapan tentang makanan ikan.\nSemakan: Guru dengar pengetahuan awal tentang ikan.\nBahan: BT50.","BBM/ABM":"BT50.","PAK-21":"Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk tajuk Kolam Ikan dan Hasilnya pada BT50.\nGuru tanya, “Apakah makanan ikan?”\nTindakan murid: Murid sebut ikan yang dikenalinya.\nMurid kongsi jawapan tentang makanan ikan.\nSemakan: Guru dengar pengetahuan awal tentang ikan.\nBahan: BT50.","aids_and_pak21_original":"BBM/ABM: BT50.\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca perenggan pertama dengan murid.\nGuru jelaskan contoh buku: air bersih dan mengalir membantu ikan mendapat oksigen.\nTindakan murid: Murid ikut bacaan guru.\nMurid tunjuk perkataan airnya bersih dalam teks.\nSemakan: Guru jelaskan oksigen sebagai udara yang diperlukan oleh ikan.\nBahan: BT50.","aids_and_pak21_original":"BBM/ABM: BT50.\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru baca perenggan tentang sangkar besi.\nGuru beri contoh jawapan: “Sangkar besi dipilih kerana kuat.”\nTindakan murid: Murid jawab soalan “Sangkar dibuat daripada apa?”\nMurid ulang sebab sangkar besi dipilih.\nSemakan: Guru bezakan isi tersurat melalui “Apa yang tertulis?” dan isi tersirat melalui “Mengapa agaknya?”.\nBahan: BT50 dan kad soalan.","aids_and_pak21_original":"BBM/ABM: BT50 dan kad soalan.\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru pilih perenggan akhir untuk latihan mengikut laluan bantuan.\nGuru tanya pasangan, “Mengapa Aidil memberi ikan makan?”\nTindakan murid: Murid baca perenggan akhir bersama pasangan.\nMurid bergilir menyebut perbuatan Aidil dan sebabnya.\nSemakan: Terima jawapan mudah seperti “Aidil memberi ikan makan” dan “Supaya ikan membesar”.\nBahan: BT50 dan bank kata.","aids_and_pak21_original":"BBM/ABM: BT50 dan bank kata.\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru minta murid menjawab dua soalan perenggan akhir dalam buku latihan.\nGuru semak jawapan dengan setiap murid yang memerlukan bantuan.\nTindakan murid: Murid tulis jawapan tentang perbuatan Aidil dan sebabnya.\nMurid baca jawapan kepada guru jika diminta.\nSemakan: Jawapan ringkas atau jawapan lisan dengan bantuan diterima untuk semakan kefahaman.\nBahan: Buku latihan, BT50 dan kad soalan.","aids_and_pak21_original":"BBM/ABM: Buku latihan, BT50 dan kad soalan.\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tanya, “Bagaimanakah Aidil membantu bapanya?”\nGuru rumuskan kepentingan memberi ikan makan.\nTindakan murid: Murid menjawab bersama-sama.\nMurid sebut satu perkara baharu tentang ternakan ikan.\nSemakan: Guru kenal pasti murid yang masih keliru tentang soalan mengapa.\nBahan: BT50.","aids_and_pak21_original":"BBM/ABM: BT50.\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Baca dan jawab bersama","implementation_original":"Tugasan: Mencari perbuatan Aidil dan sebab memberi ikan makan dalam perenggan akhir.\nBahan: BT50\nKad memberi makan dan membesar\nRangka “Supaya ikan …”\nBimbingan guru: Guru baca ayat tentang Aidil memberi ikan makan.\nGuru bantu pasangan melengkapkan jawapan menggunakan kad.\nLangkah murid: Ikut bacaan guru sambil menunjuk ayat.\nPilih kata yang menjawab soalan pasangan.\nBerikan dua jawapan dengan bantuan guru.\nHasil individu: Dua jawapan ringkas setiap murid.\nKriteria: Perbuatan betul dan sebab memberi makan sesuai.\nSusulan: Ulang bacaan ayat yang sama jika murid masih tersalah memilih kata.","aids_and_pak21_original":"BBM/ABM: BT50\nKad memberi makan dan membesar\nRangka “Supaya ikan …”\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},"pembina":{"label":"Langkah 1\nPembina — Baca dengan bank kata","implementation_original":"Tugasan: Membaca perenggan akhir untuk mendapatkan isi tersurat dan isi tersirat.\nBahan: BT50\nBank kata memberi makan dan membesar\nBuku latihan\nBimbingan guru: Guru ingatkan soalan apa mencari perkara yang tertulis.\nGuru bantu murid menggunakan supaya untuk menjawab soalan mengapa.\nLangkah murid: Baca perenggan bersama pasangan.\nBergilir menyebut perbuatan dan sebabnya.\nTulis dua jawapan sendiri dengan bank kata jika perlu.\nHasil individu: Dua jawapan tentang penjagaan ikan.\nKriteria: Jawapan tentang perbuatan Aidil dan sebabnya sesuai.\nSusulan: Baca semula ayat berkaitan bersama guru jika jawapan belum tepat.","aids_and_pak21_original":"BBM/ABM: BT50\nBank kata memberi makan dan membesar\nBuku latihan\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."},"pencabar":{"label":"Langkah 1\nPencabar — Cari satu isi lagi","implementation_original":"Tugasan: Mencari satu isi tersurat tambahan daripada perenggan akhir jika bersedia.\nBahan: BT50\nKad soalan “Kepada siapakah ikan dijual?”\nBimbingan guru: Guru tunjuk bahagian akhir perenggan.\nGuru jelaskan peraih ialah orang yang membeli hasil ternakan untuk dijual semula.\nLangkah murid: Selesaikan dua jawapan utama.\nCari perkataan peraih dalam teks.\nSebut satu isi tambahan kepada pasangan.\nHasil individu: Dua jawapan utama dan satu isi tentang jualan ikan.\nKriteria: Isi tambahan sepadan dengan teks.\nSusulan: Gunakan perkataan peraih semula dalam satu jawapan lisan ringkas.","aids_and_pak21_original":"BBM/ABM: BT50\nKad soalan “Kepada siapakah ikan dijual?”\nPAK-21: Baca berpasangan: murid membaca petikan pendek dan bergilir menjawab soalan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan dua jawapan individu dan pemerhatian semasa membaca.","Evidens":"Jawapan tentang perbuatan Aidil dan sebab memberi ikan makan.","Kriteria Kejayaan":"Murid mengenal pasti satu isi tersurat dan satu isi tersirat yang sesuai."},"closure_original":"Tindakan guru: Guru tanya, “Bagaimanakah Aidil membantu bapanya?”\nGuru rumuskan kepentingan memberi ikan makan.\nTindakan murid: Murid menjawab bersama-sama.\nMurid sebut satu perkara baharu tentang ternakan ikan.\nSemakan: Guru kenal pasti murid yang masih keliru tentang soalan mengapa.\nBahan: BT50.","reflection_original":"__ daripada __ murid dapat mengenal pasti isi tersurat dan isi tersirat. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M32-S2.docx","source_docx_sha256":"a93302db9465b2eaeebb2498289c2c24de7a9cb4028168343c1f5ac250ef3d39","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M32-S3","week_no":32,"session_no":3,"lesson_map":{"title":"Pelet Kambing","sp":"3.2.4","page":51,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":32,"session":3,"revision":"r1","title_original":"Pelet Kambing","sk_original":"3.2 Menulis perkataan, frasa, dan ayat yang bermakna","sp_original":"3.2.4(i)(ii)(iii)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat menulis sekurang-kurangnya tujuh daripada sembilan item imlak tentang Pelet Kambing dengan betul, merangkumi sekurang-kurangnya dua perkataan, dua frasa dan dua ayat.","success_criteria_original":"Imlak dinilai daripada hasil mendengar sebelum jawapan diperlihatkan; salinan pembetulan tidak menggantikan rekod pertama.; Ejaan perkataan/frasa, jarak antara perkataan dan huruf besar serta noktah bagi ayat disemak mengikut item.; Bantuan ulangan atau pemenggalan bacaan dicatat; tidak menganggap hasil salinan sebagai penguasaan imlak.","textbook_pages_original":"m/s 51","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca perkataan pelet dengan buku murid ditutup, minta mereka menyebut semula bunyinya sebelum memperlihatkan perkataan.\nJelaskan beza menyalin perkataan yang dilihat dengan menulis perkataan yang didengar; aktiviti hari ini ialah imlak.\nTindakan murid: Dengar, sebut dan cuba menulis satu perkataan percubaan yang tidak direkod sebagai PBD akhir.\nBandingkan dengan perkataan dipaparkan dan nyatakan satu bahagian bunyi yang perlu didengar teliti.\nSemakan: Jangan mencampurkan percubaan berpandu dengan markah akhir. Semak bahawa murid faham bila buku boleh dibuka dan ditutup.\nBahan: Kad pelet dan ruang percubaan.","BBM/ABM":"Kad pelet dan ruang percubaan.","PAK-21":"Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Dengar dahulu, bukan salin","execution_original":"Tindakan guru: Baca perkataan pelet dengan buku murid ditutup, minta mereka menyebut semula bunyinya sebelum memperlihatkan perkataan.\nJelaskan beza menyalin perkataan yang dilihat dengan menulis perkataan yang didengar; aktiviti hari ini ialah imlak.\nTindakan murid: Dengar, sebut dan cuba menulis satu perkataan percubaan yang tidak direkod sebagai PBD akhir.\nBandingkan dengan perkataan dipaparkan dan nyatakan satu bahagian bunyi yang perlu didengar teliti.\nSemakan: Jangan mencampurkan percubaan berpandu dengan markah akhir. Semak bahawa murid faham bila buku boleh dibuka dan ditutup.\nBahan: Kad pelet dan ruang percubaan.","aids_and_pak21_original":"BBM/ABM: Kad pelet dan ruang percubaan.\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},{"phase_original":"Langkah 2\nKenal bahasa dalam rutin datuk Komala","execution_original":"Tindakan guru: Baca petikan dan label kandang kambing serta kambing meragut rumput. Tunjuk perkataan, frasa dan ayat sebagai tiga bentuk berbeza.\nModelkan mendengar satu frasa, mengulang dalam hati dan menulis dengan jarak; bagi ayat, ingatkan huruf besar serta noktah tanpa mengeja semua perkataan.\nTindakan murid: Cari perkataan berkaitan kandang, pelet dan ladang pada buku.\nLatih menyebut frasa dengan jelas dan menandakan bilangan perkataan pada contoh sebelum menutup buku untuk percubaan.\nSemakan: Jika murid mencantum frasa, gunakan tepukan setiap perkataan sebagai bantuan latihan, bukan memberi jawapan bertulis pada imlak akhir.\nBahan: BT51, kad frasa dan model guru.","aids_and_pak21_original":"BBM/ABM: BT51, kad frasa dan model guru.\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},{"phase_original":"Langkah 3\nLatihan terbeza — Bunyi ke tulisan","execution_original":"Tindakan guru: Jalankan laluan bantuan di bawah menggunakan item latihan daripada petikan. Beri masa kumpulan sokongan untuk mendengar frasa pendek dan membetulkan jarak.\nBimbing kumpulan lain menyemak ejaan serta tanda baca setelah respons ditulis. Tarik balik kad suku kata sebelum pentaksiran bersama.\nTindakan murid: Berlatih mendengar dan menulis tanpa melihat ayat pada saat bacaan.\nSelepas guru membenarkan semakan, buka bahan, tandakan pembetulan dengan pen lain dan sebut semula item yang salah.\nSemakan: Latihan boleh dibantu tetapi tidak direkod sebagai markah tanpa bantuan. Semua murid bersedia untuk set sembilan item yang sama dengan bantuan diisytiharkan.\nBahan: Kad latihan, buku untuk semakan dan pen warna.","aids_and_pak21_original":"BBM/ABM: Kad latihan, buku untuk semakan dan pen warna.\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},{"phase_original":"Langkah 4\nImlak individu — Sembilan item","execution_original":"Tindakan guru: Minta buku ditutup. Baca setiap item sekali secara penuh, ulang sekali pada kadar sesuai, beri masa menulis dan ulang ayat penuh tanpa memecahkannya menjadi ejaan huruf.\nGunakan skrip tiga perkataan, tiga frasa dan tiga ayat yang ditetapkan. Catat jika seseorang menerima ulangan tambahan atau pemenggalan sebagai akomodasi.\nTindakan murid: Dengar setiap nombor, ulang dalam hati dan tulis jawapan sendiri.\nBagi ayat, semak huruf besar, jarak dan noktah sebelum bergerak ke nombor seterusnya; tidak meminta rakan mengeja.\nSemakan: Pemerhatian guru memastikan tiada paparan kunci jawapan. Jika item tidak sempat didengar, tandakan perlukan ulangan, bukan isi jawapan bagi pihak murid.\nBahan: Skrip guru dan lembaran sembilan ruang.","aids_and_pak21_original":"BBM/ABM: Skrip guru dan lembaran sembilan ruang.\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},{"phase_original":"Langkah 5\nPBD dan pembetulan berjejak","execution_original":"Tindakan guru: Paparkan kunci selepas semua respons pertama selesai. Nilai sembilan item dan liputan perkataan/frasa/ayat sebelum pembetulan.\nMinta murid mengekalkan jawapan asal, tulis pembetulan di bawah dengan pen lain dan catat corak kesalahan; guru menyemak markah kendiri.\nTindakan murid: Bandingkan setiap item, tandakan huruf atau jarak yang berubah dan baca pembetulan.\nPilih satu perkataan atau ayat yang sukar untuk diterangkan kepada guru: bunyi, jarak atau tanda baca.\nSemakan: Tujuh item tepat perlu juga meliputi sekurang-kurangnya dua setiap kategori. Markah selepas menyalin pembetulan tidak digunakan menggantikan respons asal.\nBahan: Kunci sembilan item dan pen dua warna.","aids_and_pak21_original":"BBM/ABM: Kunci sembilan item dan pen dua warna.\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},{"phase_original":"Langkah 6\nPenutup — Satu sasaran imlak berikutnya","execution_original":"Tindakan guru: Rumusan strategi dengar, ulang dalam hati, tulis dan semak. Pilih contoh kesalahan jarak atau noktah tanpa memalukan murid.\nNyatakan latihan susulan khusus bagi bunyi perkataan atau sempadan frasa berdasarkan lembaran sebenar.\nTindakan murid: Sebut satu strategi yang membantu dan satu item yang akan dilatih semula.\nSerahkan lembaran dengan respons asal serta pembetulan kekal kelihatan.\nSemakan: Refleksi menggunakan keputusan pertama dan bantuan sebenar, bukan semua pembetulan dianggap jawapan tepat asal.\nBahan: Lembaran imlak dan rekod guru.","aids_and_pak21_original":"BBM/ABM: Lembaran imlak dan rekod guru.\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Dengar pendek, sambung secara beransur","implementation_original":"Tugasan: Berlatih perkataan dan frasa daripada petikan dengan sokongan bunyi, kemudian mengikuti imlak bersama dengan bantuan ulangan direkod.\nBahan: Kad suku kata kandang dan matang untuk latihan sahaja\nKad pemisah perkataan bagi kandang kambing\nLembaran latihan sebelum set PBD\nBimbingan guru: Sebut frasa penuh kemudian pecahkan kepada perkataan semasa latihan. Minta murid mencuba sebelum memperlihatkan kad ejaan.\nTarik balik kad pada percubaan berikutnya; dalam PBD hanya ulangan tambahan diberi jika diperlukan dan dicatat.\nLangkah murid: Dengar satu item pendek dan sebut semula.\nTulis tanpa melihat kad lalu semak selepas dibenarkan.\nLatih jarak frasa dan cuba satu ayat dengan huruf besar serta noktah.\nIkuti sembilan item individu dan tandakan pembetulan kemudian, bukan semasa bacaan rakan.\nHasil individu: Lembaran imlak pertama serta pembetulan warna lain.\nKriteria: Sasaran tujuh item dan dua setiap kategori digunakan dengan jenis bantuan dinyatakan; pencapaian latihan berpandu tidak disamakan dengan imlak kendiri.\nSusulan: Ulang item yang bunyinya keliru secara pendek, kemudian imlak semula tanpa kad pada peluang berikutnya.","aids_and_pak21_original":"BBM/ABM: Kad suku kata kandang dan matang untuk latihan sahaja\nKad pemisah perkataan bagi kandang kambing\nLembaran latihan sebelum set PBD\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},"pembina":{"label":"Langkah 1\nPembina — Imlak dengan semakan kendiri","implementation_original":"Tugasan: Menulis perkataan, frasa dan ayat pada kadar bacaan biasa kelas serta menyemak bentuk tulisan selepas item selesai.\nBahan: BT51 untuk pralatihan\nLembaran sembilan item\nSenarai semak ejaan–jarak–noktah\nBimbingan guru: Modelkan cara menyemak tanpa meminta ejaan jawapan daripada rakan.\nBaca item secara konsisten kepada kelas dan catat ulangan tambahan jika diberikan kepada individu.\nLangkah murid: Baca petikan pralatihan untuk mengenal kosa kata.\nTutup buku dan dengar setiap item sepenuhnya sebelum menulis.\nSemak jarak frasa serta tanda baca ayat selepas bacaan.\nBandingkan dengan kunci selepas semua item dan catat satu corak kesalahan sendiri.\nHasil individu: Sembilan respons pertama dan pembetulan yang boleh dibezakan.\nKriteria: Sekurang-kurangnya tujuh item tepat dengan dua setiap kategori; kejujuran rekod serta bantuan dicatat tetapi tidak menambah markah ejaan.\nSusulan: Jika kukuh, latih ayat lain pada masa berikutnya; jika belum, fokus kategori paling lemah daripada lembaran.","aids_and_pak21_original":"BBM/ABM: BT51 untuk pralatihan\nLembaran sembilan item\nSenarai semak ejaan–jarak–noktah\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."},"pencabar":{"label":"Langkah 1\nPencabar — Mengawal ketepatan ayat panjang","implementation_original":"Tugasan: Mengikuti imlak yang sama secara kendiri dan menganalisis sebab satu pembetulan, bukan berlumba menulis paling pantas.\nBahan: Skrip kelas yang sama\nKad semakan tiga kategori\nRuang analisis pembetulan ringkas\nBimbingan guru: Minta murid menjelaskan bagaimana mereka mengingati urutan ayat tanpa melihat teks.\nSelepas PBD, berikan satu ayat tambahan daripada petikan sebagai latihan pilihan, bukan menggantikan item yang salah dalam penilaian.\nLangkah murid: Dengar dan tulis sembilan item bersama kelas.\nSemak ejaan, jarak serta tanda baca secara kendiri.\nBandingkan respons dengan kunci dan jelaskan satu peraturan atau strategi yang membantu.\nCuba ayat pilihan selepas penilaian, kemudian catat sama ada strategi itu berkesan.\nHasil individu: Lembaran PBD serta satu refleksi strategi atau latihan lanjutan berasingan.\nKriteria: Sasaran teras dicapai dan murid dapat menerangkan pembetulan; tambahan bukan markah bonus untuk menutup kekurangan kategori lain.\nSusulan: Gunakan strategi yang dikenal pasti pada imlak berikutnya dengan teks baharu yang masih sepadan tahap.","aids_and_pak21_original":"BBM/ABM: Skrip kelas yang sama\nKad semakan tiga kategori\nRuang analisis pembetulan ringkas\nPAK-21: Dengar–Tulis–Semak: pasangan membantu latihan sebutan dan semakan selepas respons pertama. Pentaksiran imlak dibuat individu dengan buku ditutup; pasangan tidak mengeja jawapan semasa guru membacakan item."}},"pbd_original":{"Kaedah Pentaksiran":"Imlak individu sembilan item dan semakan respons pertama.","Evidens":"Tiga perkataan, tiga frasa dan tiga ayat bertulis sebelum kunci dibuka; pembetulan disimpan berasingan.","Kriteria Kejayaan":"Tujuh daripada sembilan tepat, sekurang-kurangnya dua setiap kategori; bantuan ulangan direkod."},"closure_original":"Tindakan guru: Rumusan strategi dengar, ulang dalam hati, tulis dan semak. Pilih contoh kesalahan jarak atau noktah tanpa memalukan murid.\nNyatakan latihan susulan khusus bagi bunyi perkataan atau sempadan frasa berdasarkan lembaran sebenar.\nTindakan murid: Sebut satu strategi yang membantu dan satu item yang akan dilatih semula.\nSerahkan lembaran dengan respons asal serta pembetulan kekal kelihatan.\nSemakan: Refleksi menggunakan keputusan pertama dan bantuan sebenar, bukan semua pembetulan dianggap jawapan tepat asal.\nBahan: Lembaran imlak dan rekod guru.","reflection_original":"____ / ____ murid mencapai sasaran tujuh item dengan liputan kategori; ____ memerlukan ulangan; kesalahan paling kerap: ____. Respons yang perlu imlak semula: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M32-S3.docx","source_docx_sha256":"ef48ed5386fe90e94e0953ad6a553a7198e4ff2f05260674e04a7c45fd7bc902","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":32,"session":3,"revision":"r2","title_original":"Pelet Kambing","sk_original":"3.2 Menulis perkataan, frasa, dan ayat yang bermakna","sp_original":"3.2.4(i)(ii)(iii)","sp_support_original":"—","objective_original":"Murid dapat menulis berdasarkan bacaan guru dengan betul.","success_criteria_original":"Menulis perkataan pelet dan frasa kandang kambing yang didengar.; Menulis ayat “Kambing itu di dalam kandang.” yang didengar.","textbook_pages_original":"m/s 51","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Pelet Kambing pada BT51.\nGuru terangkan pelet ialah makanan kambing dalam petikan.\nTindakan murid: Murid sebut perkataan pelet.\nMurid tunjuk perkataan kambing dalam teks.\nSemakan: Guru dengar sebutan pelet dan kambing.\nBahan: BT51.","BBM/ABM":"BT51.","PAK-21":"Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk tajuk Pelet Kambing pada BT51.\nGuru terangkan pelet ialah makanan kambing dalam petikan.\nTindakan murid: Murid sebut perkataan pelet.\nMurid tunjuk perkataan kambing dalam teks.\nSemakan: Guru dengar sebutan pelet dan kambing.\nBahan: BT51.","aids_and_pak21_original":"BBM/ABM: BT51.\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru tunjuk cara mendengar dan mengulang perkataan pelet.\nGuru tulis pelet selepas menyebutnya.\nTindakan murid: Murid ikut sebutan pe-let.\nMurid sebut huruf dalam perkataan pelet.\nSemakan: Guru terangkan imlak bermaksud mendengar sebelum menulis.\nBahan: Papan tulis dan kad pelet.","aids_and_pak21_original":"BBM/ABM: Papan tulis dan kad pelet.\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru imlak frasa kandang kambing tanpa memaparkan jawapan.\nGuru tunjuk ejaan frasa selepas murid selesai menulis.\nTindakan murid: Murid dengar semula bacaan jika perlu.\nMurid tulis frasa dan semak bersama guru.\nSemakan: Guru bantu dengan sebutan perlahan bagi suku kata yang sukar.\nBahan: Skrip guru dan buku latihan.","aids_and_pak21_original":"BBM/ABM: Skrip guru dan buku latihan.\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},{"phase_original":"Langkah 4\nLatihan dengan bantuan","execution_original":"Tindakan guru: Guru imlak pelet, kandang kambing dan “Kambing itu di dalam kandang.” mengikut laluan bantuan.\nGuru paparkan contoh selepas semua item selesai ditulis.\nTindakan murid: Murid tulis tiga item yang didengar.\nMurid semak tulisan bersama pasangan menggunakan contoh.\nSemakan: Guru perhatikan ejaan yang perlu diulang tanpa menjadikan kelajuan sebagai ukuran.\nBahan: Skrip guru, buku latihan dan contoh semakan.","aids_and_pak21_original":"BBM/ABM: Skrip guru, buku latihan dan contoh semakan.\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru imlak semula tiga item dengan jeda yang cukup.\nGuru semak tulisan setiap murid.\nTindakan murid: Murid dengar dan tulis jawapan sendiri.\nMurid minta bacaan diulang jika perlu.\nSemakan: Bacaan ulang dan sebutan suku kata boleh diberi; jawapan bertulis digunakan selepas imlak untuk semakan.\nBahan: Skrip guru dan buku latihan.","aids_and_pak21_original":"BBM/ABM: Skrip guru dan buku latihan.\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru sebut semula perkataan yang paling sukar.\nGuru rumuskan langkah dengar, sebut dan tulis.\nTindakan murid: Murid ulang sebutan bersama-sama.\nMurid baiki satu ejaan berdasarkan contoh guru.\nSemakan: Guru pilih perkataan untuk latihan susulan.\nBahan: Papan tulis dan buku latihan.","aids_and_pak21_original":"BBM/ABM: Papan tulis dan buku latihan.\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Dengar perlahan-lahan","implementation_original":"Tugasan: Menulis tiga item imlak dengan sebutan perlahan dan bacaan berulang.\nBahan: BT51 untuk latihan awal\nSkrip imlak guru\nBuku latihan\nBimbingan guru: Guru latih sebutan pe-let dan kan-dang bersama pasangan.\nGuru baca ayat dalam bahagian pendek semasa imlak.\nLangkah murid: Sebut kata bersama pasangan sebelum imlak.\nDengar dan tulis setiap item dengan bantuan sebutan.\nSemak tulisan dengan contoh selepas imlak.\nHasil individu: Tulisan satu perkataan, satu frasa dan satu ayat.\nKriteria: Tulisan sepadan dengan item yang didengar.\nSusulan: Ulang imlak perkataan yang sukar dengan sebutan suku kata.","aids_and_pak21_original":"BBM/ABM: BT51 untuk latihan awal\nSkrip imlak guru\nBuku latihan\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},"pembina":{"label":"Langkah 1\nPembina — Dengar dan tulis","implementation_original":"Tugasan: Berlatih dengan bank kata sebelum menulis tiga item daripada bacaan guru.\nBahan: Bank kata pelet, kandang dan kambing untuk latihan awal\nSkrip guru\nBuku latihan\nBimbingan guru: Guru bantu pasangan membaca kata sebelum imlak.\nGuru ulang bacaan setiap item apabila murid memerlukannya.\nLangkah murid: Baca kata bersama pasangan sebelum imlak.\nDengar bacaan guru dan tulis sendiri.\nSemak tiga item menggunakan contoh selepas imlak.\nHasil individu: Tiga item tulisan daripada bacaan guru.\nKriteria: Perkataan, frasa dan ayat ditulis mengikut bacaan.\nSusulan: Latih semula satu item yang belum tepat dengan guru.","aids_and_pak21_original":"BBM/ABM: Bank kata pelet, kandang dan kambing untuk latihan awal\nSkrip guru\nBuku latihan\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."},"pencabar":{"label":"Langkah 1\nPencabar — Satu perkataan lagi","implementation_original":"Tugasan: Mencuba imlak satu perkataan tambahan daripada teks jika bersedia.\nBahan: BT51\nSkrip guru dengan perkataan rumput\nBuku latihan\nBimbingan guru: Guru sebut rumput selepas latihan utama selesai.\nGuru ulang sebutan jika murid memerlukannya.\nLangkah murid: Selesaikan tiga item imlak utama.\nDengar dan tulis perkataan rumput.\nSemak ejaan selepas guru menunjukkan contoh.\nHasil individu: Tulisan utama dan satu perkataan tambahan.\nKriteria: Perkataan tambahan ditulis berdasarkan bunyi yang didengar.\nSusulan: Sebut semula suku kata rum-put jika ejaan masih tertukar.","aids_and_pak21_original":"BBM/ABM: BT51\nSkrip guru dengan perkataan rumput\nBuku latihan\nPAK-21: Semak berpasangan: murid membandingkan tulisan dengan contoh selepas selesai mendengar dan menulis."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan latihan imlak individu.","Evidens":"Tulisan pelet, kandang kambing dan “Kambing itu di dalam kandang.”","Kriteria Kejayaan":"Tiga item tulisan sepadan dengan bacaan guru."},"closure_original":"Tindakan guru: Guru sebut semula perkataan yang paling sukar.\nGuru rumuskan langkah dengar, sebut dan tulis.\nTindakan murid: Murid ulang sebutan bersama-sama.\nMurid baiki satu ejaan berdasarkan contoh guru.\nSemakan: Guru pilih perkataan untuk latihan susulan.\nBahan: Papan tulis dan buku latihan.","reflection_original":"__ daripada __ murid dapat menulis item yang diimlakkan. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M32-S3.docx","source_docx_sha256":"954f8b4145a86f58fcb1cf6f5b7fd2436c1885d07889678fa925c9ee433d7054","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M32-S4","week_no":32,"session_no":4,"lesson_map":{"title":"Sang Lembu dan Sang Kerbau","sp":"4.3.2","page":52,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":32,"session":4,"revision":"r1","title_original":"Sang Lembu dan Sang Kerbau","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan mempersembahkannya secara Kreatif","sp_original":"4.3.2(ii)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat mempersembahkan cerita jenaka Sang Lembu dan Sang Kerbau mengikut tiga bahagian utama dengan suara dua watak yang dapat dibezakan serta pengakhiran yang munasabah berdasarkan cerita.","success_criteria_original":"Tiga bahagian ialah ejekan Sang Lembu, Sang Lembu sendiri membawa padi dan permohonan maaf; jalan cerita tidak bertukar kepada kejadian lain.; Suara watak menunjukkan perubahan sombong kepada malu serta respons Sang Kerbau yang menasihati.; Pengakhiran selepas “Sejak hari itu…” ditandai sebagai sambungan murid yang selaras dengan nilai cerita, bukan teks asal yang telah lengkap.","textbook_pages_original":"m/s 52","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca dakwaan Sang Lembu bahawa tuan tidak menyuruhnya bekerja kerana sayang akan dirinya. Tanya adakah dakwaan watak itu sudah terbukti.\nTunjukkan tajuk cerita jenaka dan jelaskan kelas akan memerhatikan perubahan situasi, bukan meniru ejekan terhadap rakan.\nTindakan murid: Nyatakan bahawa watak sedang membuat sangkaan dan sebut apa yang ingin diketahui seterusnya.\nCuba satu intonasi yakin untuk ujaran watak tanpa menjerit atau mengarah ejekan kepada rakan.\nSemakan: Semak batas adab sebelum latihan. Ketawa tidak menjadi satu-satunya ukuran cerita jenaka berjaya disampaikan.\nBahan: BT52 dan kad Sang Lembu.","BBM/ABM":"BT52 dan kad Sang Lembu.","PAK-21":"Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Sangkaan yang tersilap","execution_original":"Tindakan guru: Baca dakwaan Sang Lembu bahawa tuan tidak menyuruhnya bekerja kerana sayang akan dirinya. Tanya adakah dakwaan watak itu sudah terbukti.\nTunjukkan tajuk cerita jenaka dan jelaskan kelas akan memerhatikan perubahan situasi, bukan meniru ejekan terhadap rakan.\nTindakan murid: Nyatakan bahawa watak sedang membuat sangkaan dan sebut apa yang ingin diketahui seterusnya.\nCuba satu intonasi yakin untuk ujaran watak tanpa menjerit atau mengarah ejekan kepada rakan.\nSemakan: Semak batas adab sebelum latihan. Ketawa tidak menjadi satu-satunya ukuran cerita jenaka berjaya disampaikan.\nBahan: BT52 dan kad Sang Lembu.","aids_and_pak21_original":"BBM/ABM: BT52 dan kad Sang Lembu.\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},{"phase_original":"Langkah 2\nFahami tiga babak dan modelkan suara","execution_original":"Tindakan guru: Baca naratif serta dialog dan susun babak Sang Kerbau membajak, Sang Lembu membawa padi selepas menuai, kemudian permohonan maaf.\nModelkan satu ujaran Sang Lembu yang yakin dan satu ujaran malu selepas disedarkan; bandingkan dengan nasihat Sang Kerbau yang tenang.\nTindakan murid: Tunjuk peristiwa yang menyebabkan perubahan perasaan Sang Lembu.\nPadankan dialog kepada watak dan cuba menyebut dua suara yang berbeza dengan kata asal atau parafrasa yang sesuai.\nSemakan: Murid perlu memahami sebab malu, bukan melabel semua ujaran sebagai lucu. Penutur dialog disemak melalui teks.\nBahan: Kad babak dan jalur dialog.","aids_and_pak21_original":"BBM/ABM: Kad babak dan jalur dialog.\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},{"phase_original":"Langkah 3\nLatihan terbeza — Dua watak, satu perubahan","execution_original":"Tindakan guru: Gunakan laluan sokongan/teras/cabaran untuk menyiapkan rangka tiga bahagian dan sambungan “Sejak hari itu…”.\nDengar murid bergilir, berikan satu petunjuk intonasi atau urutan dan catat bantuan; jangan biarkan ahli yang kurang yakin hanya memegang kad.\nTindakan murid: Berlatih penceritaan pendek secara individu kepada pasangan, kemudian berlakon dua watak dengan giliran ditukar.\nCadangkan pengakhiran yang munasabah seperti saling membantu dan tidak mengejek lagi, serta labelkan sebagai sambungan sendiri.\nSemakan: Pengakhiran bukan fakta buku yang siap tercetak. Setiap murid mesti dapat menyampaikan rangka cerita, bukan hanya menghafal satu bunyi ketawa.\nBahan: BT52, kad babak, kad watak dan rangka sambungan.","aids_and_pak21_original":"BBM/ABM: BT52, kad babak, kad watak dan rangka sambungan.\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},{"phase_original":"Langkah 4\nPersembahan — Jenaka daripada situasi","execution_original":"Tindakan guru: Jalankan persembahan kelompok kecil secara bergilir. Guru mendengar murid terpilih dan penonton menggunakan senarai semak urutan, suara serta pengakhiran.\nTanya penonton mengapa keadaan akhir berbeza daripada sangkaan awal Sang Lembu; terima penjelasan ringkas berasas cerita.\nTindakan murid: Persembahkan tiga bahagian dengan perubahan suara watak.\nBeri satu komen khusus kepada pencerita, contohnya suara malu belum jelas pada permohonan maaf; tukar peranan sebagai penonton dan pembaca.\nSemakan: Jika jenaka berubah menjadi ejekan rakan, hentikan dan kembalikan fokus kepada watak serta situasi buku.\nBahan: Ruang persembahan dan kad komen.","aids_and_pak21_original":"BBM/ABM: Ruang persembahan dan kad komen.\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},{"phase_original":"Langkah 5\nPBD — Bahagian individu yang lengkap","execution_original":"Tindakan guru: Dengar semula murid yang belum diperhatikan atau belum menunjukkan perubahan suara; gunakan catatan latihan untuk yang sudah lengkap bukti.\nRekod tiga babak, dua suara dan pengakhiran munasabah. Persembahan kumpulan tidak terus dianggap penguasaan semua ahli.\nTindakan murid: Ceritakan tiga bahagian ringkas dengan kata sendiri atau bantuan kad urutan.\nJelaskan satu pilihan nada dan sebut pengakhiran sendiri yang tidak bercanggah dengan cerita.\nSemakan: Tanda belum diperhatikan jika belum didengar; tulisan pengakhiran bukan syarat utama kerana SP menekankan persembahan.\nBahan: Kad urutan jika perlu dan senarai semak guru.","aids_and_pak21_original":"BBM/ABM: Kad urutan jika perlu dan senarai semak guru.\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},{"phase_original":"Langkah 6\nPenutup — Kita sama-sama membantu","execution_original":"Tindakan guru: Baca nasihat Sang Kerbau “Kita sama sahaja” dan minta murid menyatakan kaitannya dengan perubahan Sang Lembu.\nRumusan bahawa jenaka boleh mengajar sikap rendah hati tanpa merendahkan orang lain.\nTindakan murid: Sebut satu ujaran maaf atau pengakhiran yang menunjukkan perubahan watak.\nNyatakan bantuan persembahan yang masih diperlukan untuk latihan seterusnya.\nSemakan: Gunakan respons untuk memilih latihan suara atau urutan secara khusus, bukan memaksa semua mengulang dialog yang sama.\nBahan: BT52 dan kad meminta maaf.","aids_and_pak21_original":"BBM/ABM: BT52 dan kad meminta maaf.\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Babak berikon dan dialog pendek","implementation_original":"Tugasan: Mempersembahkan tiga bahagian cerita dengan kad urutan dan dua ujaran yang jelas menunjukkan perubahan perasaan.\nBahan: Kad Ejekan–Membawa padi–Maaf\nIkon yakin/malu/tenang\nJalur “Sejak hari itu, mereka …” dengan kata bantu membantu/tidak mengejek\nBimbingan guru: Modelkan satu ujaran, minta murid memilih ikon suara dan cuba sendiri.\nTarik balik ayat model pada babak kedua tetapi kekalkan kata kunci supaya penceritaan tidak terhenti.\nLangkah murid: Susun tiga babak mengikut teks.\nSebut satu ayat bagi setiap babak dan tambah ujaran watak.\nPilih sambungan pengakhiran yang munasabah serta sebut ia cadangan sendiri.\nPersembahkan semula kepada pasangan dan guru tanpa suara rakan menggantikan respons.\nHasil individu: Penceritaan individu tiga babak dengan dua suara dan sambungan akhir.\nKriteria: Urutan serta intonasi sepadan dengan bantuan direkod; satu dialog sahaja belum cukup untuk objektif penuh.\nSusulan: Latih peralihan yakin kepada malu menggunakan dua ujaran pendek sebelum menyambungkannya kepada tiga babak.","aids_and_pak21_original":"BBM/ABM: Kad Ejekan–Membawa padi–Maaf\nIkon yakin/malu/tenang\nJalur “Sejak hari itu, mereka …” dengan kata bantu membantu/tidak mengejek\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},"pembina":{"label":"Langkah 1\nPembina — Teater bacaan dengan pengakhiran sendiri","implementation_original":"Tugasan: Menceritakan perubahan situasi serta mempersembahkan kedua-dua watak secara bergilir.\nBahan: BT52\nKad watak tanpa dialog siap\nSenarai semak urutan–suara–pengakhiran\nBimbingan guru: Tanya peristiwa yang mengubah sangkaan Sang Lembu dan minta murid menonjolkannya melalui intonasi.\nSemak pengakhiran supaya watak benar-benar belajar daripada kejadian, bukan cerita baharu tanpa kaitan.\nLangkah murid: Pilih dialog penting bagi awal, perubahan dan akhir.\nLatih naratif yang menghubungkan dialog serta dua suara berbeza.\nBina satu sambungan “Sejak hari itu…” dan beritahu pasangan bahawa itu ciptaan sendiri.\nPersembahkan, dengar komen rakan dan baiki satu bahagian sebelum PBD.\nHasil individu: Persembahan tiga bahagian lengkap dan pengakhiran berasas.\nKriteria: Suara serta urutan jelas, makna cerita kekal dan sambungan munasabah; hafalan tepat setiap perkataan bukan syarat.\nSusulan: Jika mantap, cuba persembahan lebih ringkas tanpa kehilangan konflik; jika belum, kembalikan kad peristiwa yang tertinggal.","aids_and_pak21_original":"BBM/ABM: BT52\nKad watak tanpa dialog siap\nSenarai semak urutan–suara–pengakhiran\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."},"pencabar":{"label":"Langkah 1\nPencabar — Menonjolkan ironi tanpa menghina","implementation_original":"Tugasan: Mempersembahkan cerita dengan jeda dan perubahan nada yang menunjukkan sangkaan awal menjadi terbalik pada akhir.\nBahan: Teks penuh\nKad penanda peralihan musim menuai\nKad komen penonton tentang bahagian yang difahami\nBimbingan guru: Tanya bagaimana jeda sebelum Sang Lembu membawa padi membantu penonton menyedari perubahan situasi.\nTekankan jenaka bukan mencipta gelaran kepada rakan atau berlebihan pada ungkapan yang menghina.\nLangkah murid: Rancang tiga babak dan titik perubahan intonasi.\nPersembahkan dengan perbezaan suara watak serta narator.\nUji dua pengakhiran yang sama-sama munasabah dan pilih yang paling menepati nilai cerita.\nTerangkan satu pilihan gaya kepada penonton dan perbaiki jika perubahan watak belum jelas.\nHasil individu: Persembahan penuh, pengakhiran terpilih dan alasan gaya ringkas.\nKriteria: Sasaran teras tercapai serta gaya menonjolkan makna jenaka dengan sopan; panjang dialog atau ketawa penonton bukan ukuran tunggal.\nSusulan: Latih satu versi tanpa props untuk memastikan makna tetap disampaikan melalui bahasa dan suara.","aids_and_pak21_original":"BBM/ABM: Teks penuh\nKad penanda peralihan musim menuai\nKad komen penonton tentang bahagian yang difahami\nPAK-21: Teater bacaan dengan giliran individu: pasangan berlatih kedua-dua watak dan bertukar; kelompok kecil mempersembahkan kepada rakan. Penonton menyatakan bahagian jenaka serta perubahan watak dengan alasan, bukan hanya ketawa."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian persembahan lisan individu sepanjang latihan dan giliran susulan.","Evidens":"Tiga babak, suara dua watak serta satu sambungan pengakhiran yang sepadan.","Kriteria Kejayaan":"Urutan tepat, suara dapat dibezakan dan pengakhiran munasabah; bantuan direkod tanpa TP automatik."},"closure_original":"Tindakan guru: Baca nasihat Sang Kerbau “Kita sama sahaja” dan minta murid menyatakan kaitannya dengan perubahan Sang Lembu.\nRumusan bahawa jenaka boleh mengajar sikap rendah hati tanpa merendahkan orang lain.\nTindakan murid: Sebut satu ujaran maaf atau pengakhiran yang menunjukkan perubahan watak.\nNyatakan bantuan persembahan yang masih diperlukan untuk latihan seterusnya.\nSemakan: Gunakan respons untuk memilih latihan suara atau urutan secara khusus, bukan memaksa semua mengulang dialog yang sama.\nBahan: BT52 dan kad meminta maaf.","reflection_original":"____ / ____ murid mempersembahkan tiga bahagian; ____ perlu latihan perubahan nada; ____ belum diperhatikan. Bantuan paling diperlukan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M32-S4.docx","source_docx_sha256":"eb3b03325b633dd63676eee6ff2e2459897f6f09537e09210eac79cd987d8dba","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":32,"session":4,"revision":"r2","title_original":"Sang Lembu dan Sang Kerbau","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan mempersembahkannya secara Kreatif","sp_original":"4.3.2(ii)","sp_support_original":"—","objective_original":"Murid dapat mempersembahkan cerita jenaka Sang Lembu dan Sang Kerbau dengan bahasa mudah.","success_criteria_original":"Menceritakan dua kejadian mengikut urutan.; Menggunakan suara atau mimik muka yang sesuai.","textbook_pages_original":"m/s 52","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk dua watak pada BT52.\nGuru tanya, “Siapakah watak dalam cerita ini?”\nTindakan murid: Murid sebut Sang Lembu dan Sang Kerbau.\nMurid tunjuk watak yang dipilih.\nSemakan: Guru pastikan murid mengenali dua watak.\nBahan: BT52 dan kad watak.","BBM/ABM":"BT52 dan kad watak.","PAK-21":"Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk dua watak pada BT52.\nGuru tanya, “Siapakah watak dalam cerita ini?”\nTindakan murid: Murid sebut Sang Lembu dan Sang Kerbau.\nMurid tunjuk watak yang dipilih.\nSemakan: Guru pastikan murid mengenali dua watak.\nBahan: BT52 dan kad watak.","aids_and_pak21_original":"BBM/ABM: BT52 dan kad watak.\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},{"phase_original":"Langkah 2\nGuru bercerita","execution_original":"Tindakan guru: Guru ceritakan Sang Kerbau membajak sawah dan Sang Lembu kemudian membawa padi.\nGuru baca ucapan lucu Sang Lembu dengan suara dan mimik muka yang sesuai.\nTindakan murid: Murid dengar cerita guru.\nMurid tiru muka malu Sang Lembu.\nSemakan: Guru tanya watak yang menunduk malu pada akhir cerita.\nBahan: BT52.","aids_and_pak21_original":"BBM/ABM: BT52.\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru susun kad membajak sawah, membawa padi dan malu.\nGuru beri contoh ringkas: “Sang Lembu malu. Dia berkata, Aku mohon maaf.”\nTindakan murid: Murid ceritakan kejadian mengikut kad bersama guru.\nMurid cuba suara Sang Lembu ketika meminta maaf.\nSemakan: Guru bantu dengan permulaan ayat jika murid terhenti.\nBahan: Kad kejadian dan BT52.","aids_and_pak21_original":"BBM/ABM: Kad kejadian dan BT52.\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru jalankan latihan cerita mengikut laluan bantuan.\nGuru dengar cerita setiap murid semasa pasangan bertukar giliran.\nTindakan murid: Murid ceritakan bahagian lucu kepada pasangan dalam dua atau tiga ayat.\nMurid menjadi pendengar apabila pasangan bercerita.\nSemakan: Guru semak urutan kejadian dan cara murid menyampaikan watak malu.\nBahan: BT52, kad kejadian dan kad watak.","aids_and_pak21_original":"BBM/ABM: BT52, kad kejadian dan kad watak.\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},{"phase_original":"Langkah 5\nPersembahan ringkas dan semak","execution_original":"Tindakan guru: Guru dengar murid yang belum diperhatikan bercerita kepada pasangan.\nGuru tunjuk satu cara menjadikan suara watak lebih jelas.\nTindakan murid: Murid persembahkan cerita pendek dengan bantuan kad jika perlu.\nMurid cuba semula satu ayat dengan suara yang sesuai.\nSemakan: Catatan latihan berpasangan turut digunakan sebagai bukti individu.\nBahan: Senarai semak lisan dan kad kejadian.","aids_and_pak21_original":"BBM/ABM: Senarai semak lisan dan kad kejadian.\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru cadangkan penutup: “Sejak hari itu, mereka saling membantu.”\nGuru rumuskan sikap rendah hati dalam cerita.\nTindakan murid: Murid sebut penutup cerita bersama-sama.\nMurid kongsi satu cara membantu rakan.\nSemakan: Guru kenal pasti murid yang masih memerlukan urutan kad.\nBahan: BT52.","aids_and_pak21_original":"BBM/ABM: BT52.\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Cerita dengan kad","implementation_original":"Tugasan: Mempersembahkan bahagian akhir cerita dengan model ayat pendek dan pasangan.\nBahan: BT52\nKad membajak sawah, membawa padi dan malu\nKad watak\nBimbingan guru: Guru ceritakan satu ayat bagi setiap kad.\nGuru bantu murid menyebut “Aku mohon maaf” dengan muka malu.\nLangkah murid: Susun kad bersama pasangan.\nCuba cerita pendek selepas contoh guru.\nBercerita mengikut kad dengan bantuan jika perlu.\nHasil individu: Cerita lisan dua atau tiga ayat setiap murid.\nKriteria: Dua kejadian diceritakan mengikut urutan.\nSusulan: Ulang cerita menggunakan dua kad dahulu jika murid masih keliru.","aids_and_pak21_original":"BBM/ABM: BT52\nKad membajak sawah, membawa padi dan malu\nKad watak\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},"pembina":{"label":"Langkah 1\nPembina — Cerita dengan kata kunci","implementation_original":"Tugasan: Menyampaikan cerita pendek menggunakan kata sendiri dan bank kata.\nBahan: BT52\nBank kata membajak, membawa padi, malu dan maaf\nBimbingan guru: Guru ingatkan Sang Kerbau bekerja dahulu sebelum Sang Lembu membawa padi.\nGuru bantu murid memilih ucapan maaf daripada cerita.\nLangkah murid: Latih urutan cerita bersama pasangan.\nCeritakan dua atau tiga ayat sendiri.\nGunakan suara watak ketika menyebut ucapan maaf.\nHasil individu: Cerita lisan ringkas dengan ucapan watak.\nKriteria: Urutan sesuai dan suara watak dapat didengar.\nSusulan: Baiki satu bahagian cerita yang masih terputus dengan bantuan kata kunci.","aids_and_pak21_original":"BBM/ABM: BT52\nBank kata membajak, membawa padi, malu dan maaf\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."},"pencabar":{"label":"Langkah 1\nPencabar — Hidupkan watak","implementation_original":"Tugasan: Mencuba satu mimik muka yang menjadikan bahagian lucu lebih menarik jika bersedia.\nBahan: BT52\nKad watak Sang Lembu\nBimbingan guru: Guru tunjuk perubahan daripada muka bangga kepada muka malu.\nGuru bantu murid memilih satu bahagian untuk gaya itu.\nLangkah murid: Latih cerita utama dengan pasangan.\nPilih bahagian Sang Lembu berasa malu.\nPersembahkan semula bahagian itu dengan mimik muka.\nHasil individu: Cerita pendek dengan satu gaya watak yang lebih jelas.\nKriteria: Gaya yang dipilih sesuai dengan kejadian cerita.\nSusulan: Gunakan gaya tersebut apabila bercerita sekali lagi kepada rakan.","aids_and_pak21_original":"BBM/ABM: BT52\nKad watak Sang Lembu\nPAK-21: Cerita berpasangan: murid bergilir bercerita dan menjadi pendengar."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian persembahan lisan individu semasa latihan dan cerita berpasangan.","Evidens":"Cerita pendek murid tentang kerja Sang Kerbau dan pengalaman Sang Lembu.","Kriteria Kejayaan":"Dua kejadian mengikut urutan dengan suara atau mimik muka yang sesuai."},"closure_original":"Tindakan guru: Guru cadangkan penutup: “Sejak hari itu, mereka saling membantu.”\nGuru rumuskan sikap rendah hati dalam cerita.\nTindakan murid: Murid sebut penutup cerita bersama-sama.\nMurid kongsi satu cara membantu rakan.\nSemakan: Guru kenal pasti murid yang masih memerlukan urutan kad.\nBahan: BT52.","reflection_original":"__ daripada __ murid dapat mempersembahkan cerita jenaka dengan bahasa mudah. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M32-S4.docx","source_docx_sha256":"691ce4c116ec62274b00e68c986ec7bb5d21082d030a054e4e3c8a43fec8322e","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":32,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M33-S1","week_no":33,"session_no":1,"lesson_map":{"title":"Pak Cik Isa Penternak Ayam","sp":"5.3.2","page":53,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":33,"session":1,"revision":"r1","title_original":"Pak Cik Isa Penternak Ayam","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (i)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid dapat melengkapkan sekurang-kurangnya tiga daripada empat ayat dasar tentang gerai Mak Cik Aminah dengan subjek dan predikat yang lengkap serta makna yang sesuai gambar BT53.","success_criteria_original":"Sekurang-kurangnya tiga ayat mempunyai subjek dan predikat yang sepadan konteks.; Ayat bukan cebisan frasa atau gabungan dua ayat; huruf besar dan noktah disemak.; Bantuan kad atau pertanyaan guru direkod berasingan daripada ketepatan jawapan.","textbook_pages_original":"m/s 53","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Paparkan 'Pak Cik Isa' sahaja dan tanya maklumat yang masih ingin diketahui tentang beliau.\nTambahkan 'penternak ayam'; bandingkan frasa nama dengan ayat yang menyampaikan maklumat lengkap.\nTindakan murid: Sebut siapa yang dinamakan dan cadangkan pertanyaan tentang pekerjaannya.\nBaca kedua-dua jalur bersama lalu tunjuk bahagian yang memberitahu pekerjaan.\nSemakan: Jika murid menyebut nama sahaja sebagai ayat lengkap, guru ulang soalan 'Pak Cik Isa bagaimana atau siapa?'\nBahan: Jalur Pak Cik Isa dan penternak ayam.","BBM/ABM":"Jalur Pak Cik Isa dan penternak ayam.","PAK-21":"Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: orang dan keterangannya","execution_original":"Tindakan guru: Paparkan 'Pak Cik Isa' sahaja dan tanya maklumat yang masih ingin diketahui tentang beliau.\nTambahkan 'penternak ayam'; bandingkan frasa nama dengan ayat yang menyampaikan maklumat lengkap.\nTindakan murid: Sebut siapa yang dinamakan dan cadangkan pertanyaan tentang pekerjaannya.\nBaca kedua-dua jalur bersama lalu tunjuk bahagian yang memberitahu pekerjaan.\nSemakan: Jika murid menyebut nama sahaja sebagai ayat lengkap, guru ulang soalan 'Pak Cik Isa bagaimana atau siapa?'\nBahan: Jalur Pak Cik Isa dan penternak ayam.","aids_and_pak21_original":"BBM/ABM: Jalur Pak Cik Isa dan penternak ayam.\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},{"phase_original":"Langkah 2\nPemodelan empat bentuk maklumat","execution_original":"Tindakan guru: Baca empat contoh bercetak; tandakan subjek biru dan predikat hijau tanpa mewajibkan istilah pola yang rumit.\nModelkan 'Ayam Pak Cik Isa / sangat lapar'; jelaskan bahawa maklumat sifat juga melengkapkan ayat dasar.\nTindakan murid: Tunjuk subjek bagi contoh memakai sarung tangan dan sebut predikatnya.\nBandingkan predikat pekerjaan, perbuatan, tempat dan sifat pada empat jalur tersebut.\nSemakan: Guru meminta murid membaca kedua-dua bahagian; jika predikat ditinggalkan, murid melengkapkan semula daripada teks.\nBahan: BT53, empat contoh bercetak dan pen warna.","aids_and_pak21_original":"BBM/ABM: BT53, empat contoh bercetak dan pen warna.\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},{"phase_original":"Langkah 3\nLatihan pasangan: padanan mesti bermakna","execution_original":"Tindakan guru: Campurkan empat pasangan jalur dan tunjuk kesilapan sengaja 'Makanan ayam memakai sarung tangan'.\nMinta pasangan membetulkan padanan dengan alasan berdasarkan cerita, bukan warna kad semata-mata.\nTindakan murid: Pasang semula empat ayat dan baca satu ayat kepada rakan.\nRakan bertanya siapa atau apa; pemilik menunjukkan subjek dan menerangkan mengapa predikat sesuai.\nSemakan: Padanan yang boleh dibaca tetapi tidak munasabah disemak semula dengan ayat sumber, bukan diterima kerana susunannya kemas.\nBahan: Jalur tanpa warna jawapan, BT53 dan papan mini.","aids_and_pak21_original":"BBM/ABM: Jalur tanpa warna jawapan, BT53 dan papan mini.\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},{"phase_original":"Langkah 4\nLatihan terbeza: bengkel ayat dasar","execution_original":"Tindakan guru: Jalankan tiga laluan serentak: mula dengan contoh Pak Cik Isa, kemudian pindahkan kemahiran kepada empat rangka Mak Cik Aminah dan pembeli.\nDampingi Peneroka menyebut subjek dan predikat; semak Pembina/Pencabar menunjukkan gerai atau telur sebagai bukti, tanpa mengandaikan identiti setiap figura.\nTindakan murid: Latih pola dengan jalur contoh, kemudian pilih pelengkap empat ayat pada gambar gerai.\nBaca ayat sendiri, tunjuk subjek/predikat dan semak makna; tidak menyalin semua ayat Pak Cik Isa sebagai jawapan ruang Mak Cik Aminah.\nSemakan: Guru menanda kehilangan subjek, kehilangan predikat atau ketidakpadanan makna sebelum mengurangkan bantuan.\nBahan: Bahan tiga laluan terperinci di bawah; lembaran setiap murid.","aids_and_pak21_original":"BBM/ABM: Bahan tiga laluan terperinci di bawah; lembaran setiap murid.\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},{"phase_original":"Langkah 5\nPBD individu: empat kad konteks","execution_original":"Tindakan guru: Berikan empat rangka Mak Cik Aminah dan pembeli yang sebenar dengan gambar BT53; murid melengkapkan tanpa ayat jawapan penuh.\nSemak menggunakan contoh guru Ini gerai Mak Cik Aminah; Mak Cik Aminah menyusun telur; Mak Cik Aminah menjual telur; Pembeli membeli telur. Terima ayat lain yang lengkap dan munasabah, bukan satu skema kaku.\nTindakan murid: Lengkapkan empat ayat gambar secara individu dan gariskan subjek serta predikat.\nTunjuk bukti gerai atau telur apabila diminta, baca ayat untuk memeriksa makna dan serahkan hasil sendiri.\nSemakan: Semak tiga daripada empat ayat lengkap serta munasabah; ejaan dicatat untuk susulan tanpa menggantikan fokus binaan ayat.\nBahan: Gambar gerai BT53, empat rangka asal dan lembaran pentaksiran.","aids_and_pak21_original":"BBM/ABM: Gambar gerai BT53, empat rangka asal dan lembaran pentaksiran.\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},{"phase_original":"Langkah 6\nPenutup: baiki satu cebisan","execution_original":"Tindakan guru: Paparkan 'Ayam Pak Cik Isa' dan minta murid melengkapkannya secara lisan.\nRumuskan fungsi subjek dan predikat; pilih kesalahan sebenar daripada semakan untuk latihan susulan tanpa menamakan murid.\nTindakan murid: Sebut pelengkap sifat yang sesuai berdasarkan teks.\nTandakan pada hasil sendiri bahagian yang perlu diperiksa apabila menulis ayat berikutnya.\nSemakan: Respons penutup membantu perancangan susulan; respons kelas tidak menggantikan empat ayat individu.\nBahan: Jalur cebisan dan hasil individu.","aids_and_pak21_original":"BBM/ABM: Jalur cebisan dan hasil individu.\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — sokongan subjek dan predikat","implementation_original":"Tugasan: Pasangkan maklumat ternakan ayam untuk membina empat ayat dasar dengan bantuan pertanyaan siapa dan bagaimana.\nBahan: Kad Pak Cik Isa, Beliau, Makanan ayam, Ayam Pak Cik Isa\nKad predikat sumber dan bingkai dua ruang\nKad gerai/telur dan empat rangka Mak Cik Aminah untuk pemindahan kemahiran\nBimbingan guru: Modelkan satu padanan sambil menunjuk dua bahagian ayat.\nAlihkan kad predikat selepas murid menerangkan satu padanan yang betul.\nLangkah murid: Pilih subjek dan sebut orang atau benda yang dimaksudkan.\nCari predikat yang sesuai, bukan sekadar sama warna.\nBaca ayat kepada guru untuk menguji kelengkapan makna.\nSelepas latihan empat contoh, lengkapkan empat rangka Mak Cik Aminah dengan kad gerai/telur sebagai bantuan, kemudian cuba satu tanpa kad.\nHasil individu: Empat ayat gerai Mak Cik Aminah/pembeli selepas latihan, dengan subjek-predikat dan bantuan atau pembetulan ditandai.\nKriteria: Tiga ayat lengkap menjadi sasaran; kejayaan dengan kad masih dicatat sebagai berbantu.\nSusulan: Jika predikat masih tertinggal, ulang soalan tentang pekerjaan, tempat atau sifat sebelum pentaksiran individu.","aids_and_pak21_original":"BBM/ABM: Kad Pak Cik Isa, Beliau, Makanan ayam, Ayam Pak Cik Isa\nKad predikat sumber dan bingkai dua ruang\nKad gerai/telur dan empat rangka Mak Cik Aminah untuk pemindahan kemahiran\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},"pembina":{"label":"Langkah 1\nPembina — bina daripada konteks","implementation_original":"Tugasan: Bina ayat daripada kata kunci Pak Cik Isa sebagai latihan, kemudian lengkapkan empat ayat dasar Mak Cik Aminah dan pembeli dengan maklumat gambar gerai.\nBahan: Empat kad konteks dan teks pengenalan Pak Cik Isa\nLembaran subjek/predikat kosong\nBimbingan guru: Tanya maklumat manakah yang sesuai dengan setiap subjek pilihan murid.\nMinta alasan jika pasangan menukar predikat, tanpa membekalkan ayat lengkap.\nLangkah murid: Baca pengenalan dan pilih maklumat yang benar-benar disebut.\nTulis subjek serta predikat untuk setiap kad konteks.\nTukar lembaran untuk rakan menunjukkan bahagian yang diragui.\nSelepas semakan pasangan, lengkapkan empat rangka gerai Mak Cik Aminah secara individu dan jelaskan satu pilihan predikat.\nHasil individu: Empat ayat gerai Mak Cik Aminah/pembeli selepas latihan, dengan subjek-predikat dan bantuan atau pembetulan ditandai.\nKriteria: Sekurang-kurangnya tiga ayat lengkap dan sesuai; alasan semakan menunjukkan kefahaman, bukan menyalin.\nSusulan: Jika padanan stabil, bina ayat setara menggunakan beliau tanpa mengubah orang yang dirujuk.","aids_and_pak21_original":"BBM/ABM: Empat kad konteks dan teks pengenalan Pak Cik Isa\nLembaran subjek/predikat kosong\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — uji kelengkapan dan makna","implementation_original":"Tugasan: Baiki empat ayat rosak adaptasi guru dengan membezakan bahagian yang hilang daripada maklumat yang tidak munasabah.\nBahan: Kad 'Beliau', 'Ayam Pak Cik Isa', 'Makanan ayam memakai sarung tangan', 'Pak Cik Isa di dalam mangkuk'\nBT53\nBimbingan guru: Minta murid menjelaskan jenis kesalahan sebelum menulis pembetulan.\nTanya sama ada ayat lengkap semestinya menepati cerita; minta bukti teks.\nLangkah murid: Tandakan kad yang hanya mempunyai satu bahagian ayat.\nKenal pasti dua kad lengkap tetapi tidak sesuai konteks.\nBina pembetulan yang mengekalkan maklumat petikan.\nJelaskan dua kesalahan model, kemudian lengkapkan empat rangka Mak Cik Aminah dengan ayat dasar yang berpaut pada gerai dan telur dalam gambar.\nHasil individu: Empat ayat gerai Mak Cik Aminah/pembeli selepas latihan, dengan subjek-predikat dan bantuan atau pembetulan ditandai.\nKriteria: Sekurang-kurangnya tiga pembetulan tepat serta dapat membezakan kelengkapan dengan kesesuaian makna.\nSusulan: Bina pasangan ayat contoh dan bukan contoh untuk intervensi rakan, tanpa mendakwa sebagai ayat buku.","aids_and_pak21_original":"BBM/ABM: Kad 'Beliau', 'Ayam Pak Cik Isa', 'Makanan ayam memakai sarung tangan', 'Pak Cik Isa di dalam mangkuk'\nBT53\nPAK-21: Fikir–Pasang–Semak: murid memasang ayat; pasangan menyoal siapa/apa dan keterangannya sebelum pemilik membetulkan ayat sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan bertulis empat ayat gambar Mak Cik Aminah dan pertanyaan subjek-predikat jika maksudnya tidak jelas.","Evidens":"Empat rangka gerai Mak Cik Aminah/pembeli dilengkapkan sendiri; latihan pasangan Pak Cik Isa berfungsi sebagai pemodelan sahaja.","Kriteria Kejayaan":"Sekurang-kurangnya tiga daripada empat ayat lengkap subjek-predikat dan tepat konteks."},"closure_original":"Tindakan guru: Paparkan 'Ayam Pak Cik Isa' dan minta murid melengkapkannya secara lisan.\nRumuskan fungsi subjek dan predikat; pilih kesalahan sebenar daripada semakan untuk latihan susulan tanpa menamakan murid.\nTindakan murid: Sebut pelengkap sifat yang sesuai berdasarkan teks.\nTandakan pada hasil sendiri bahagian yang perlu diperiksa apabila menulis ayat berikutnya.\nSemakan: Respons penutup membantu perancangan susulan; respons kelas tidak menggantikan empat ayat individu.\nBahan: Jalur cebisan dan hasil individu.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M33-S1.docx","source_docx_sha256":"fdea4bf6f140bb0fcb26c46141d2233cd343f983dcb741a74b032102ca21a567","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":33,"session":1,"revision":"r2","title_original":"Pak Cik Isa Penternak Ayam","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (i)","sp_support_original":"—","objective_original":"Murid dapat menggunakan ayat dasar yang sesuai dengan gambar gerai telur.","success_criteria_original":"Melengkapkan dua ayat tentang Mak Cik Aminah dan pembeli.; Menggunakan perkataan yang sesuai dengan gambar.","textbook_pages_original":"m/s 53","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Pak Cik Isa Penternak Ayam pada BT53.\nGuru tanya, “Apakah hasil ternakan ayam?”\nTindakan murid: Murid lihat gambar dalam buku.\nMurid sebut telur sebagai hasil ternakan ayam.\nSemakan: Guru pastikan murid mengenali perkataan telur.\nBahan: BT53.","BBM/ABM":"BT53.","PAK-21":"Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk tajuk Pak Cik Isa Penternak Ayam pada BT53.\nGuru tanya, “Apakah hasil ternakan ayam?”\nTindakan murid: Murid lihat gambar dalam buku.\nMurid sebut telur sebagai hasil ternakan ayam.\nSemakan: Guru pastikan murid mengenali perkataan telur.\nBahan: BT53.","aids_and_pak21_original":"BBM/ABM: BT53.\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca contoh “Pak Cik Isa penternak ayam.”\nGuru jelaskan ayat dasar sebagai ayat asas yang lengkap.\nTindakan murid: Murid ikut membaca contoh guru.\nMurid sebut orang yang diceritakan dalam ayat.\nSemakan: Guru bantu murid menyebut ayat lengkap, bukan nama orang sahaja.\nBahan: BT53.","aids_and_pak21_original":"BBM/ABM: BT53.\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru lengkapkan contoh “Ini gerai Mak Cik Aminah.”\nGuru tanya, “Mak Cik Aminah menyusun apa?”\nTindakan murid: Murid pilih perkataan gerai untuk ayat pertama.\nMurid sebut “Mak Cik Aminah menyusun telur.”\nSemakan: Guru padankan gerai dan telur dengan ayat serta gambar.\nBahan: BT53 dan kad gerai serta telur.","aids_and_pak21_original":"BBM/ABM: BT53 dan kad gerai serta telur.\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru beri rangka “Mak Cik Aminah …” dan “Pembeli …” mengikut laluan bantuan.\nGuru tunjuk frasa menjual telur dan membeli telur.\nTindakan murid: Murid bergilir melengkapkan ayat kepada pasangan.\nMurid membaca semula dua ayat yang dipilih.\nSemakan: Contoh jawapan: “Mak Cik Aminah menjual telur.” dan “Pembeli membeli telur.”\nBahan: BT53, rangka ayat dan kad frasa.","aids_and_pak21_original":"BBM/ABM: BT53, rangka ayat dan kad frasa.\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru minta murid menulis dua ayat yang dilatih.\nGuru semak padanan orang dengan perbuatan dalam ayat.\nTindakan murid: Murid tulis ayat sendiri dengan kad jika perlu.\nMurid baiki ayat berdasarkan tunjuk ajar guru.\nSemakan: Guru semak ayat lengkap dan makna yang sesuai dengan gerai telur.\nBahan: Buku latihan dan kad frasa.","aids_and_pak21_original":"BBM/ABM: Buku latihan dan kad frasa.\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru minta beberapa murid membaca satu ayat pilihan.\nGuru rumuskan kegunaan ayat dasar untuk menceritakan gambar.\nTindakan murid: Murid dengar ayat rakan.\nMurid sebut semula satu ayat bersama-sama.\nSemakan: Guru pilih murid yang memerlukan latihan menyambung ayat.\nBahan: BT53.","aids_and_pak21_original":"BBM/ABM: BT53.\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Padankan frasa","implementation_original":"Tugasan: Melengkapkan dua ayat gerai telur dengan pilihan frasa dan model guru.\nBahan: BT53\nKad menjual telur dan membeli telur\nRangka dua ayat\nBimbingan guru: Guru padankan Mak Cik Aminah dengan menjual telur.\nGuru sebut contoh bersama murid sebelum pasangan mencuba.\nLangkah murid: Lihat gambar gerai bersama pasangan.\nPilih frasa untuk setiap rangka ayat.\nTulis dua ayat dengan bantuan yang diperlukan.\nHasil individu: Dua ayat lengkap setiap murid.\nKriteria: Ayat menceritakan penjual dan pembeli dengan sesuai.\nSusulan: Latih satu ayat secara lisan dahulu jika murid masih keliru.","aids_and_pak21_original":"BBM/ABM: BT53\nKad menjual telur dan membeli telur\nRangka dua ayat\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},"pembina":{"label":"Langkah 1\nPembina — Lengkapkan ayat sendiri","implementation_original":"Tugasan: Menggunakan bank kata untuk membina dua ayat dasar tentang gerai telur.\nBahan: BT53\nBank kata Mak Cik Aminah, pembeli, menjual dan membeli\nBuku latihan\nBimbingan guru: Guru minta pasangan menyebut ayat sebelum menulis.\nGuru bantu melengkapkan bahagian ayat yang tertinggal.\nLangkah murid: Bincang padanan kata bersama pasangan.\nSebut dua ayat secara bergilir.\nTulis ayat sendiri dengan bank kata jika perlu.\nHasil individu: Dua ayat dasar tentang penjual dan pembeli.\nKriteria: Ayat lengkap dan sesuai dengan gambar.\nSusulan: Baca semula ayat bersama guru untuk membaiki bahagian yang belum lengkap.","aids_and_pak21_original":"BBM/ABM: BT53\nBank kata Mak Cik Aminah, pembeli, menjual dan membeli\nBuku latihan\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."},"pencabar":{"label":"Langkah 1\nPencabar — Satu ayat lagi","implementation_original":"Tugasan: Menambah satu ayat dasar tentang gerai telur jika bersedia.\nBahan: BT53\nKad gerai dan menyusun telur\nBuku latihan\nBimbingan guru: Guru tunjuk semula dua ayat awal dalam latihan buku.\nGuru bantu murid memilih satu perkara lain untuk diceritakan.\nLangkah murid: Selesaikan dua ayat utama.\nPilih ayat tentang gerai atau menyusun telur.\nTulis satu ayat tambahan dan bacakan kepada pasangan.\nHasil individu: Dua ayat utama dan satu ayat tambahan.\nKriteria: Ayat tambahan sesuai dengan bahan gerai telur.\nSusulan: Baca ayat tambahan dengan sebutan yang jelas kepada rakan.","aids_and_pak21_original":"BBM/ABM: BT53\nKad gerai dan menyusun telur\nBuku latihan\nPAK-21: Lengkapkan berpasangan: murid bergilir memilih frasa dan membaca ayat kepada rakan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan dua ayat individu dalam buku latihan.","Evidens":"Ayat tentang Mak Cik Aminah menjual telur dan pembeli membeli telur.","Kriteria Kejayaan":"Dua ayat dasar lengkap dan sesuai dengan gambar."},"closure_original":"Tindakan guru: Guru minta beberapa murid membaca satu ayat pilihan.\nGuru rumuskan kegunaan ayat dasar untuk menceritakan gambar.\nTindakan murid: Murid dengar ayat rakan.\nMurid sebut semula satu ayat bersama-sama.\nSemakan: Guru pilih murid yang memerlukan latihan menyambung ayat.\nBahan: BT53.","reflection_original":"__ daripada __ murid dapat menggunakan ayat dasar tentang gerai telur. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M33-S1.docx","source_docx_sha256":"1d70bfabf25c7535428d4fbfd82b2146bb767ac87dd55c9a95c3a9f67eba07a4","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M33-S2","week_no":33,"session_no":2,"lesson_map":{"title":"Ternakan Puyuh","sp":"5.3.2","page":54,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":33,"session":2,"revision":"r1","title_original":"Ternakan Puyuh","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (ii)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid membina secara individu sekurang-kurangnya tiga daripada empat ayat tunggal tentang ternakan puyuh yang mempunyai satu subjek dan satu predikat serta menepati maklumat sumber.","success_criteria_original":"Tiga ayat tepat struktur dan maklumat daripada empat konteks.; Keterangan masa atau tempat tidak disalah anggap sebagai subjek baharu.; Jenis bantuan dicatat; bercerita lancar sahaja bukan bukti penguasaan ayat tunggal.","textbook_pages_original":"m/s 54","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca ayat Encik Johari menghadiri seminar ternakan puyuh di Sarawak.\nTanya siapa yang diceritakan dan maklumat tentangnya sebelum memperkenalkan istilah ayat tunggal.\nTindakan murid: Sebut Encik Johari sebagai orang yang diceritakan.\nNyatakan seluruh predikat, termasuk keterangan di Sarawak, bukan kata kerja sahaja.\nSemakan: Jika murid memilih Sarawak sebagai subjek kedua, guru tanya sama ada Sarawak melakukan tindakan itu.\nBahan: BT54 dan satu jalur ayat seminar.","BBM/ABM":"BT54 dan satu jalur ayat seminar.","PAK-21":"Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: siapa melakukan apa?","execution_original":"Tindakan guru: Baca ayat Encik Johari menghadiri seminar ternakan puyuh di Sarawak.\nTanya siapa yang diceritakan dan maklumat tentangnya sebelum memperkenalkan istilah ayat tunggal.\nTindakan murid: Sebut Encik Johari sebagai orang yang diceritakan.\nNyatakan seluruh predikat, termasuk keterangan di Sarawak, bukan kata kerja sahaja.\nSemakan: Jika murid memilih Sarawak sebagai subjek kedua, guru tanya sama ada Sarawak melakukan tindakan itu.\nBahan: BT54 dan satu jalur ayat seminar.","aids_and_pak21_original":"BBM/ABM: BT54 dan satu jalur ayat seminar.\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},{"phase_original":"Langkah 2\nPemodelan: panjang bukan bilangan klausa","execution_original":"Tindakan guru: Modelkan 'Julaihi / mengutip telur puyuh setiap pagi' dengan dua warna.\nBandingkan dengan 'Beliau mendirikan reban di hujung kampung'; jelaskan satu subjek dan satu predikat walaupun ada keterangan.\nTindakan murid: Gariskan subjek pada jalur dan lingkungi keterangan masa atau tempat.\nSebut maklumat utama yang kekal apabila keterangan setiap pagi ditutup sementara.\nSemakan: Guru membetulkan anggapan setiap frasa tambahan membentuk ayat baharu; murid menunjukkan pasangan subjek-predikat.\nBahan: Dua jalur sumber, pen warna dan penutup kertas.","aids_and_pak21_original":"BBM/ABM: Dua jalur sumber, pen warna dan penutup kertas.\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},{"phase_original":"Langkah 3\nPencerita–Penyemak: rutin ternakan","execution_original":"Tindakan guru: Baca maklumat menjaga puyuh dan memasang lampu; jelaskan rujukan beliau kepada watak berdasarkan ayat sebelumnya, bukan nama figura yang dilabel gambar.\nMinta murid bercerita semula satu maklumat setiap ayat dan lengkapkan ruang Nenek berdasarkan gambar akhir yang menunjukkan wanita memasak dengan kuali.\nTindakan murid: Pencerita memilih maklumat dan menyebut satu ayat lengkap kepada pasangan.\nPenyemak menunjuk subjek-predikat, bertanya jika rujukan beliau kabur dan menukar peranan.\nSemakan: Jika maklumat dua tindakan digabungkan, murid memisahkannya kepada dua ayat tunggal untuk latihan ini.\nBahan: Jalur rutin daripada BT54 dan kad peranan.","aids_and_pak21_original":"BBM/ABM: Jalur rutin daripada BT54 dan kad peranan.\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},{"phase_original":"Langkah 4\nLatihan terbeza: ayat rutin puyuh","execution_original":"Tindakan guru: Jalankan tiga laluan serentak menggunakan teks sama; laluan ditentukan oleh semakan subjek-predikat tadi.\nBantu Peneroka memilih subjek, kemudian semak alasan Pembina dan pembaikan Pencabar tanpa menulis jawapan mereka.\nTindakan murid: Laksanakan empat langkah laluan dan simpan hasil atas nama sendiri.\nTerangkan satu ayat kepada pasangan serta betulkan sendiri setelah menerima soalan, bukan menyalin jawapan rakan.\nSemakan: Guru menanda sama ada kesilapan berpunca daripada maklumat sumber, subjek hilang atau gabungan tindakan.\nBahan: Kad dan lembaran tiga laluan di bawah.","aids_and_pak21_original":"BBM/ABM: Kad dan lembaran tiga laluan di bawah.\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},{"phase_original":"Langkah 5\nPBD: empat ayat rutin individu","execution_original":"Tindakan guru: Berikan empat kad konteks lampu, telur, daging dan Nenek; murid membina ayat tunggal berpandukan teks/gambar tanpa ayat jawapan penuh.\nContoh guru: Julaihi mengutip telur puyuh setiap pagi; Encik Johari menjual daging puyuh di pasar; Nenek memasak. Isi kuali tidak dipastikan, maka jangan mewajibkan menggoreng daging puyuh.\nTindakan murid: Tulis empat ayat tentang lampu, telur, daging dan Nenek memasak, kemudian ceritakan semula rutin mengikut bahan.\nTandakan subjek/predikat dan serahkan hasil individu sebelum semakan kelas.\nSemakan: Tiga ayat tepat memenuhi sasaran; ayat dengan keterangan panjang diterima jika strukturnya kekal tunggal.\nBahan: Kad pentaksiran empat konteks, lembaran dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Kad pentaksiran empat konteks, lembaran dan senarai semak.\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},{"phase_original":"Langkah 6\nPenutup: pertahankan satu ayat","execution_original":"Tindakan guru: Paparkan ayat panjang tentang mengutip telur dan tanya sebab ayat itu tunggal.\nRumuskan bahawa bilangan subjek-predikat, bukan bilangan perkataan, membantu semakan.\nTindakan murid: Tunjuk satu subjek dan satu predikat pada ayat tersebut.\nNyatakan pembaikan yang diperlukan pada ayat sendiri tanpa mengumumkan markah rakan.\nSemakan: Guru pilih susulan struktur atau ketepatan maklumat berdasarkan hasil individu, bukan kelancaran bercerita.\nBahan: Ayat contoh dan hasil murid.","aids_and_pak21_original":"BBM/ABM: Ayat contoh dan hasil murid.\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — bingkai satu maklumat","implementation_original":"Tugasan: Bina empat ayat tentang lampu, telur, daging dan Nenek dengan bingkai siapa serta maklumat tentangnya.\nBahan: Kad Encik Johari, Julaihi dan beliau\nFrasa tindakan sumber, bingkai dua ruang dan kad masa/tempat\nKad Nenek dan memasak; gambar akhir dengan kuali sebagai bukti\nBimbingan guru: Modelkan padanan Encik Johari dengan mendirikan reban di hujung kampung.\nTutup satu frasa selepas murid dapat menerangkan siapa yang melakukan tindakan.\nLangkah murid: Pilih subjek dengan merujuk ayat sebelum dalam teks.\nPasangkan satu tindakan yang sesuai dengan orang itu.\nTambahkan masa atau tempat tanpa menambah tindakan baharu.\nBaca dan tulis empat ayat, kemudian tandakan dua bahagiannya.\nHasil individu: Empat ayat berbingkai dengan subjek-predikat ditanda.\nKriteria: Tiga ayat tepat menjadi sasaran; penggunaan frasa bantuan direkod dan bukan penguasaan kendiri.\nSusulan: Alihkan bingkai apabila subjek stabil; jika masih kabur, gunakan nama dahulu sebelum beliau.","aids_and_pak21_original":"BBM/ABM: Kad Encik Johari, Julaihi dan beliau\nFrasa tindakan sumber, bingkai dua ruang dan kad masa/tempat\nKad Nenek dan memasak; gambar akhir dengan kuali sebagai bukti\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},"pembina":{"label":"Langkah 1\nPembina — susun maklumat sendiri","implementation_original":"Tugasan: Ceritakan rutin ternakan dalam empat ayat tunggal daripada kata kunci tanpa menyalin seluruh ayat buku.\nBahan: Kad lampu, telur, daging dan Nenek; rujuk teks serta gambar akhir untuk memilih predikat\nBT54 untuk semakan fakta; lembaran empat ruang\nBimbingan guru: Tanya sama ada setiap ayat hanya menyampaikan satu pasangan subjek-predikat.\nMinta murid menunjukkan bukti apabila masa atau tempat yang digunakan diragui.\nLangkah murid: Pilih tiga maklumat rutin daripada teks dan satu maklumat Nenek memasak daripada gambar untuk melengkapkan empat ayat.\nBina satu ayat dan tandakan subjek serta predikatnya.\nBaca kepada rakan yang menyemak rujukan nama atau beliau.\nBetulkan maklumat dan salin versi akhir sendiri tanpa bantuan rakan.\nHasil individu: Empat ayat rutin dengan jejak satu semakan pasangan.\nKriteria: Sekurang-kurangnya tiga ayat tunggal betul struktur serta tepat maklumat teks.\nSusulan: Jika tepat, tambah keterangan sesuai dan buktikan ayat masih tunggal.","aids_and_pak21_original":"BBM/ABM: Kad lampu, telur, daging dan Nenek; rujuk teks serta gambar akhir untuk memilih predikat\nBT54 untuk semakan fakta; lembaran empat ruang\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."},"pencabar":{"label":"Langkah 1\nPencabar — asing dan jelaskan","implementation_original":"Tugasan: Baiki ayat gabungan adaptasi guru, kemudian jelaskan mengapa ayat berketerangan panjang masih boleh menjadi ayat tunggal.\nBahan: Kad 'Julaihi mengutip telur puyuh dan Encik Johari menjual daging puyuh di pasar'\nKad ayat seminar dan ayat mendirikan reban\nBimbingan guru: Minta murid mencari tindakan dan subjek sebelum memisahkan gabungan.\nTanya maklumat mana yang hilang jika ayat dipendekkan secara berlebihan.\nLangkah murid: Pisahkan ayat gabungan kepada dua ayat lengkap.\nTandakan struktur kedua-dua ayat hasil pemisahan.\nBina dua lagi ayat berketerangan berdasarkan teks.\nJelaskan kepada pasangan perbezaan keterangan dengan gabungan dua ayat.\nHasil individu: Empat ayat tunggal dan satu alasan struktur secara lisan.\nKriteria: Tiga ayat tepat serta alasan menyebut satu subjek-predikat, bukan sekadar ayat pendek.\nSusulan: Uji alasan pada ayat lain dan baiki rujukan kata ganti yang kabur.","aids_and_pak21_original":"BBM/ABM: Kad 'Julaihi mengutip telur puyuh dan Encik Johari menjual daging puyuh di pasar'\nKad ayat seminar dan ayat mendirikan reban\nPAK-21: Pencerita–Penyemak: seorang menyebut satu ayat, rakan menunjukkan subjek dan predikat; peranan bertukar selepas setiap ayat."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan empat ayat bertulis individu; penjelasan lisan hanya mengesahkan struktur yang dimaksudkan.","Evidens":"Empat ayat tentang lampu, telur, daging dan Nenek dengan tanda subjek-predikat serta bacaan cerita ringkas.","Kriteria Kejayaan":"Tiga daripada empat ayat tunggal tepat struktur dan maklumat sumber."},"closure_original":"Tindakan guru: Paparkan ayat panjang tentang mengutip telur dan tanya sebab ayat itu tunggal.\nRumuskan bahawa bilangan subjek-predikat, bukan bilangan perkataan, membantu semakan.\nTindakan murid: Tunjuk satu subjek dan satu predikat pada ayat tersebut.\nNyatakan pembaikan yang diperlukan pada ayat sendiri tanpa mengumumkan markah rakan.\nSemakan: Guru pilih susulan struktur atau ketepatan maklumat berdasarkan hasil individu, bukan kelancaran bercerita.\nBahan: Ayat contoh dan hasil murid.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M33-S2.docx","source_docx_sha256":"c4b39232518afdb154f268cb9cb662a43051a2d4d5e346b4be8c56f9335ced3b","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":33,"session":2,"revision":"r2","title_original":"Ternakan Puyuh","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (ii)","sp_support_original":"—","objective_original":"Murid dapat menggunakan ayat tunggal untuk bercerita tentang ternakan puyuh.","success_criteria_original":"Melengkapkan ayat “Nenek memasak.”; Menyebut satu lagi ayat tunggal tentang ternakan puyuh.","textbook_pages_original":"m/s 54","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Ternakan Puyuh pada BT54.\nGuru tanya, “Apakah haiwan dalam cerita ini?”\nTindakan murid: Murid lihat gambar puyuh.\nMurid sebut nama haiwan tersebut.\nSemakan: Guru bantu sebutan puyuh jika perlu.\nBahan: BT54.","BBM/ABM":"BT54.","PAK-21":"Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk tajuk Ternakan Puyuh pada BT54.\nGuru tanya, “Apakah haiwan dalam cerita ini?”\nTindakan murid: Murid lihat gambar puyuh.\nMurid sebut nama haiwan tersebut.\nSemakan: Guru bantu sebutan puyuh jika perlu.\nBahan: BT54.","aids_and_pak21_original":"BBM/ABM: BT54.\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca “Julaihi mengutip telur puyuh setiap pagi.”\nGuru bantu murid mengenali ayat tunggal dengan soalan 'Siapa?' dan 'Buat apa?'.\nTindakan murid: Murid sebut Julaihi sebagai orang dalam ayat.\nMurid sebut perbuatan mengutip telur puyuh.\nSemakan: Guru padankan orang dengan satu cerita tentangnya.\nBahan: BT54 dan kad Julaihi.","aids_and_pak21_original":"BBM/ABM: BT54 dan kad Julaihi.\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru tunjuk rangka “Nenek …” pada gambar akhir.\nGuru beri contoh “Nenek memasak.”\nTindakan murid: Murid sebut perbuatan memasak.\nMurid baca ayat lengkap bersama guru.\nSemakan: Guru bantu murid menyambung Nenek dengan memasak.\nBahan: BT54, kad Nenek dan kad memasak.","aids_and_pak21_original":"BBM/ABM: BT54, kad Nenek dan kad memasak.\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru pilih ayat Julaihi dan Nenek untuk latihan mengikut laluan bantuan.\nGuru dengar pasangan bercerita secara bergilir.\nTindakan murid: Murid pilih kata daripada bank kata.\nMurid sebut dua ayat pendek kepada pasangan.\nSemakan: Contoh: “Julaihi mengutip telur puyuh.” dan “Nenek memasak.”\nBahan: BT54 dan bank kata.","aids_and_pak21_original":"BBM/ABM: BT54 dan bank kata.\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru dengar dua ayat murid yang belum diperhatikan.\nGuru bantu membaiki satu ayat yang belum lengkap.\nTindakan murid: Murid bercerita sendiri dengan bantuan kad jika perlu.\nMurid sebut semula ayat yang dibantu guru.\nSemakan: Guru semak ayat lengkap dan perbuatan yang sesuai dengan bahan.\nBahan: Senarai semak lisan dan kad kata.","aids_and_pak21_original":"BBM/ABM: Senarai semak lisan dan kad kata.\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru minta beberapa murid menyebut ayat pilihan.\nGuru rumuskan ayat tunggal melalui contoh Julaihi.\nTindakan murid: Murid dengar ayat rakan.\nMurid ulang satu ayat bersama-sama.\nSemakan: Guru kenal pasti murid yang memerlukan bantuan menyambung nama dengan perbuatan.\nBahan: BT54.","aids_and_pak21_original":"BBM/ABM: BT54.\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Nama dan perbuatan","implementation_original":"Tugasan: Menyebut dua ayat tunggal dengan kad nama, gambar dan model guru.\nBahan: BT54\nKad Julaihi dan Nenek\nKad mengutip telur puyuh dan memasak\nBimbingan guru: Guru padankan Nenek dengan memasak.\nGuru sebut ayat Julaihi bersama murid sebelum latihan pasangan.\nLangkah murid: Pilih kad nama bersama pasangan.\nPadankan kad dengan perbuatan yang sesuai.\nSebut dua ayat kepada guru dengan bantuan.\nHasil individu: Dua ayat tunggal secara lisan setiap murid.\nKriteria: Nama dan perbuatan dipadankan dengan betul.\nSusulan: Ulang rangka “Nenek …” jika murid masih menyebut perbuatan sahaja.","aids_and_pak21_original":"BBM/ABM: BT54\nKad Julaihi dan Nenek\nKad mengutip telur puyuh dan memasak\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},"pembina":{"label":"Langkah 1\nPembina — Cerita dengan bank kata","implementation_original":"Tugasan: Menggunakan bank kata untuk bercerita tentang Julaihi dan Nenek.\nBahan: BT54\nBank kata Julaihi, Nenek, mengutip telur puyuh dan memasak\nBimbingan guru: Guru ingatkan murid menyebut orang sebelum perbuatannya.\nGuru bantu murid menyusun kata jika ayat terputus.\nLangkah murid: Pilih kata bersama pasangan.\nLatih dua ayat secara bergilir.\nSebut dua ayat sendiri dengan bank kata jika perlu.\nHasil individu: Cerita lisan dua ayat tunggal.\nKriteria: Dua ayat lengkap dan sesuai dengan bahan.\nSusulan: Baiki satu ayat yang belum lengkap bersama guru sebelum mengulang cerita.","aids_and_pak21_original":"BBM/ABM: BT54\nBank kata Julaihi, Nenek, mengutip telur puyuh dan memasak\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."},"pencabar":{"label":"Langkah 1\nPencabar — Ceritakan Encik Johari","implementation_original":"Tugasan: Menambah satu ayat tunggal tentang Encik Johari jika bersedia.\nBahan: BT54\nKad menjual daging puyuh\nBimbingan guru: Guru tunjuk ayat tentang Encik Johari di pasar.\nGuru bantu murid memilih kata yang diperlukan untuk ayat tambahan.\nLangkah murid: Latih dua ayat utama dengan pasangan.\nCari perbuatan Encik Johari dalam teks.\nSebut satu ayat tambahan seperti “Encik Johari menjual daging puyuh.”\nHasil individu: Dua ayat utama dan satu ayat tambahan secara lisan.\nKriteria: Ayat tambahan sesuai dengan teks.\nSusulan: Ulang ayat tambahan kepada rakan dengan sebutan yang jelas.","aids_and_pak21_original":"BBM/ABM: BT54\nKad menjual daging puyuh\nPAK-21: Cerita berpasangan: murid bergilir menyebut ayat tentang gambar puyuh dan Nenek."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian lisan semasa cerita berpasangan dan semakan individu.","Evidens":"Ayat “Nenek memasak” dan satu ayat tentang ternakan puyuh.","Kriteria Kejayaan":"Dua ayat tunggal lengkap dan sesuai dengan bahan."},"closure_original":"Tindakan guru: Guru minta beberapa murid menyebut ayat pilihan.\nGuru rumuskan ayat tunggal melalui contoh Julaihi.\nTindakan murid: Murid dengar ayat rakan.\nMurid ulang satu ayat bersama-sama.\nSemakan: Guru kenal pasti murid yang memerlukan bantuan menyambung nama dengan perbuatan.\nBahan: BT54.","reflection_original":"__ daripada __ murid dapat menggunakan ayat tunggal tentang ternakan puyuh. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M33-S2.docx","source_docx_sha256":"b05e6586476db8c2e99bbbbdee9777024d8c596a392e329f76d16056e7a678bb","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M33-S3","week_no":33,"session_no":3,"lesson_map":{"title":"Tokoh Penternakan","sp":"1.1.3","page":55,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":33,"session":3,"revision":"r1","title_original":"Tokoh Penternakan","sk_original":"1.1 Mendengar dan memberikan respons","sp_original":"1.1.3 (i)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid memberikan secara individu sekurang-kurangnya dua daripada tiga respons lisan terhadap soalan bercapah tentang ayam kampung organik, setiap satunya mengandungi tafsiran atau pilihan serta satu alasan relevan berasaskan maklumat yang didengar.","success_criteria_original":"Dua respons menjawab kehendak soalan, bukan mengulang soalan.; Setiap respons menghubungkan pendapat dengan satu maklumat bahan.; Respons berbeza diterima jika beralasan; bantuan dan belum diperhatikan dicatat.","textbook_pages_original":"m/s 55","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Sebut nama Dr. Mohamad Zainol dan baca pengenalan tokoh tanpa meminta murid menyalin.\nTanya siapa tokoh itu dan jelaskan bahawa soalan seterusnya memerlukan pendapat beralasan.\nTindakan murid: Dengar pengenalan dan sebut bidang penternakan tokoh.\nBezakan pertanyaan siapa dengan pertanyaan mengapa melalui dua contoh guru.\nSemakan: Jika istilah organik menghalang pemahaman, guru gunakan keterangan buku tanpa menambah dakwaan produk.\nBahan: Pengenalan BT55 dan kad nama tokoh.","BBM/ABM":"Pengenalan BT55 dan kad nama tokoh.","PAK-21":"Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: dengar untuk mengetahui tokoh","execution_original":"Tindakan guru: Sebut nama Dr. Mohamad Zainol dan baca pengenalan tokoh tanpa meminta murid menyalin.\nTanya siapa tokoh itu dan jelaskan bahawa soalan seterusnya memerlukan pendapat beralasan.\nTindakan murid: Dengar pengenalan dan sebut bidang penternakan tokoh.\nBezakan pertanyaan siapa dengan pertanyaan mengapa melalui dua contoh guru.\nSemakan: Jika istilah organik menghalang pemahaman, guru gunakan keterangan buku tanpa menambah dakwaan produk.\nBahan: Pengenalan BT55 dan kad nama tokoh.","aids_and_pak21_original":"BBM/ABM: Pengenalan BT55 dan kad nama tokoh.\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},{"phase_original":"Langkah 2\nDengar dialog dan model tafsiran","execution_original":"Tindakan guru: Baca dialog dua kali dengan fakta permintaan tinggi, bebas bahan kimia serta pasaran hotel dan kedai makan.\nModelkan adaptasi: 'Saya memilih ternakan ini kerana permintaannya tinggi'; tunjuk pilihan dan alasan, bukan jawapan hafalan.\nTindakan murid: Pada bacaan pertama, dengar tanpa mencelah; pada bacaan kedua, tunjuk kad fakta yang disebut.\nSebut maklumat yang menyokong pilihan guru dan cadangkan alasan lain daripada dialog.\nSemakan: Guru membezakan fakta 'pasarannya hotel' daripada tafsiran 'saya memilih hotel'; kedua-duanya tidak disamakan.\nBahan: Skrip dialog dan tiga kad fakta.","aids_and_pak21_original":"BBM/ABM: Skrip dialog dan tiga kad fakta.\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},{"phase_original":"Langkah 3\nSimulasi Hasan–Elis dengan soalan lanjut","execution_original":"Tindakan guru: Modelkan pertanyaan buku tentang keistimewaan, pasaran dan kesihatan; gunakan pertanyaan fakta sebagai jambatan sahaja.\nTanya lanjut 'Mengapa kamu berpendapat begitu?' dan terima lebih daripada satu respons yang munasabah.\nTindakan murid: Hasan bertanya, Elis menjawab dengan pendapat serta alasan, kemudian bertukar peranan.\nPendengar menyebut semula alasan rakan sebelum menyatakan persetujuan atau pilihan berlainan.\nSemakan: Jika murid sekadar menyebut hotel, guru tanya sebab memilihnya; jangan membekalkan seluruh jawapan.\nBahan: Kad peranan dan tiga kad fakta sumber.","aids_and_pak21_original":"BBM/ABM: Kad peranan dan tiga kad fakta sumber.\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},{"phase_original":"Langkah 4\nLatihan terbeza: klinik respons beralasan","execution_original":"Tindakan guru: Laksanakan tiga laluan serentak; bimbing Peneroka mendengar semula soalan dan biarkan pasangan lain berlatih bergilir.\nMula mendengar respons individu merentas laluan menggunakan tiga soalan pentaksiran; catat bantuan serta respons yang belum sempat diperhatikan.\nTindakan murid: Jalankan langkah laluan dan berlatih menyampaikan alasan, bukan membaca jawapan lengkap.\nApabila dipanggil, dengar soalan guru dan jawab sendiri sementara pasangan meneruskan latihan.\nSemakan: Respons latihan dengan bingkai direkod berbantu; kesimpulan mesti bersandar pada respons individu yang benar-benar didengar.\nBahan: Bahan laluan dan senarai giliran pemerhatian.","aids_and_pak21_original":"BBM/ABM: Bahan laluan dan senarai giliran pemerhatian.\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},{"phase_original":"Langkah 5\nPBD lisan: dengar, pilih dan jelaskan","execution_original":"Tindakan guru: Teruskan giliran individu: mengapa memilih ternakan ini, tempat pasaran pilihan dan pendapat tentang kesihatan berdasarkan bahan.\nTerima alasan setara; bagi soalan kesihatan, model semakan guru ialah 'Bahan menyebut bebas bahan kimia, maka saya memahami sebab orang memilihnya', bukan jaminan kesihatan.\nTindakan murid: Dengar tiga soalan yang disampaikan guru tanpa skrip jawapan dan berikan respons sendiri.\nMinta soalan diulang jika perlu; murid menunggu berlatih mendengar, bukan membisikkan jawapan.\nSemakan: Sasaran dua respons beralasan; individu belum didengar dijadualkan susulan, bukan diberi keputusan daripada simulasi kumpulan.\nBahan: Kad tiga soalan guru dan rekod respons individu.","aids_and_pak21_original":"BBM/ABM: Kad tiga soalan guru dan rekod respons individu.\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},{"phase_original":"Langkah 6\nPenutup: fakta dan pendapat","execution_original":"Tindakan guru: Sebut satu fakta pasaran dan satu cadangan; minta murid membezakan kedua-duanya.\nRumuskan cara respons: dengar kehendak soalan, nyatakan pendapat, kemudian sokong dengan maklumat.\nTindakan murid: Nyatakan yang mana fakta dan yang mana pilihan seseorang.\nSebut satu ungkapan sopan untuk meminta penjelasan daripada rakan.\nSemakan: Jawapan serentak hanya pengukuhan; guru kekalkan rekod individu yang belum lengkap.\nBahan: Kad fakta dan cadangan guru.","aids_and_pak21_original":"BBM/ABM: Kad fakta dan cadangan guru.\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — bingkai pendapat dan sebab","implementation_original":"Tugasan: Jawab tiga soalan yang didengar dengan memilih fakta sokongan sebelum menyampaikan pendapat sendiri secara lisan.\nBahan: Kad permintaan tinggi, bebas bahan kimia, hotel/kedai makan\nBingkai 'Saya memilih… kerana…'\nBimbingan guru: Ulang soalan dengan jeda dan minta murid menyebut apa yang ditanya.\nModelkan satu respons, kemudian tutup bingkai apabila murid mula menghubungkan pilihan dengan sebab.\nLangkah murid: Dengar soalan sampai habis sebelum mengambil kad fakta.\nPilih maklumat yang berkaitan dengan soalan tersebut.\nSebut pendapat dan alasan kepada pasangan tanpa menyalin skrip.\nJawab semula selepas kad ditutup dan terima pertanyaan lanjut.\nHasil individu: Tiga percubaan respons lisan individu dengan nota bantuan guru.\nKriteria: Dua respons relevan beralasan ialah sasaran; respons menggunakan bingkai dicatat berbantu.\nSusulan: Jika hanya menyebut fakta, ulang pertanyaan mengapa dan tarik balik pilihan kad secara beransur.","aids_and_pak21_original":"BBM/ABM: Kad permintaan tinggi, bebas bahan kimia, hotel/kedai makan\nBingkai 'Saya memilih… kerana…'\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},"pembina":{"label":"Langkah 1\nPembina — simulasi dengan alasan kendiri","implementation_original":"Tugasan: Tafsir tiga soalan tentang pilihan penternakan, tempat pemasaran dan pendapat kesihatan menggunakan maklumat dialog tanpa skrip jawapan.\nBahan: Kad soalan penemu bual\nTiga kata kunci sumber dan kad peranan bergilir\nBimbingan guru: Tanya fakta mana yang menyokong alasan murid apabila hubungannya kabur.\nMinta penemu bual merumuskan alasan rakan sebelum menyoal lanjut.\nLangkah murid: Dengar soalan daripada pasangan tanpa menyampuk.\nBerikan pendapat dengan satu alasan yang berkaitan.\nDengar rumusan rakan dan betulkan jika maksud tersalah faham.\nBertukar peranan lalu jawab satu soalan yang disusun semula.\nHasil individu: Respons individu serta rumusan alasan pasangan secara lisan.\nKriteria: Sekurang-kurangnya dua respons relevan mempunyai alasan sumber, bukan fakta yang disebut tanpa hubungan.\nSusulan: Jika mantap, pertimbangkan pilihan pasaran lain dalam bahan dan jelaskan perbezaan alasan.","aids_and_pak21_original":"BBM/ABM: Kad soalan penemu bual\nTiga kata kunci sumber dan kad peranan bergilir\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."},"pencabar":{"label":"Langkah 1\nPencabar — pertimbang pilihan dan batas dakwaan","implementation_original":"Tugasan: Pertahankan pilihan pasaran dan nilai kenyataan 'Ayam organik pasti menjadikan semua orang sihat' berdasarkan maklumat yang didengar.\nBahan: Kad hotel/kedai makan\nKad dakwaan adaptasi guru dan tiga fakta buku\nBimbingan guru: Tanya sama ada perkataan pasti dan semua dinyatakan dalam dialog.\nMinta murid membezakan alasan munasabah dengan jaminan yang melampaui bahan.\nLangkah murid: Dengar soalan dan pilih satu saluran pasaran.\nJelaskan alasan serta kemungkinan pilihan rakan yang berbeza.\nSemak dakwaan melampau dengan menyebut batas maklumat sumber.\nJawab soalan susulan menggunakan ungkapan pendapat, bukan kepastian tanpa bukti.\nHasil individu: Tiga respons lisan dengan satu penjelasan batas dakwaan.\nKriteria: Dua respons beralasan relevan dan dapat menolak jaminan yang tidak terdapat dalam bahan.\nSusulan: Latih soalan lanjut yang menguji alasan tanpa memperlekeh pilihan pasangan.","aids_and_pak21_original":"BBM/ABM: Kad hotel/kedai makan\nKad dakwaan adaptasi guru dan tiga fakta buku\nPAK-21: Simulasi penemu bual–pemberi respons: pendengar merumuskan alasan rakan sebelum bertanya lanjut dan bertukar peranan."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian respons lisan individu terhadap tiga soalan guru sejak latihan terbeza.","Evidens":"Catatan inti pendapat dan alasan sebenar setiap murid; skrip bertulis bukan bukti respons mendengar.","Kriteria Kejayaan":"Dua daripada tiga respons mengandungi tafsiran/pilihan dan satu alasan relevan."},"closure_original":"Tindakan guru: Sebut satu fakta pasaran dan satu cadangan; minta murid membezakan kedua-duanya.\nRumuskan cara respons: dengar kehendak soalan, nyatakan pendapat, kemudian sokong dengan maklumat.\nTindakan murid: Nyatakan yang mana fakta dan yang mana pilihan seseorang.\nSebut satu ungkapan sopan untuk meminta penjelasan daripada rakan.\nSemakan: Jawapan serentak hanya pengukuhan; guru kekalkan rekod individu yang belum lengkap.\nBahan: Kad fakta dan cadangan guru.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M33-S3.docx","source_docx_sha256":"671456abdab63f018bdefefef3dbcdcc557043e6ec7ae655bc172611860e9b22","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":33,"session":3,"revision":"r2","title_original":"Tokoh Penternakan","sk_original":"1.1 Mendengar dan memberikan respons","sp_original":"1.1.3 (i)","sp_support_original":"—","objective_original":"Murid dapat menjawab soalan tentang penternakan ayam dengan jawapan yang sesuai.","success_criteria_original":"Memberi dua jawapan yang sesuai selepas mendengar soalan.; Memberi satu sebab mudah bagi pilihan tempat menjual ayam.","textbook_pages_original":"m/s 55","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru baca tajuk Tokoh Penternakan pada BT55.\nGuru perkenalkan Dr. Mohamad Zainol sebagai penternak ayam kampung organik dalam buku.\nTindakan murid: Murid dengar penerangan guru.\nMurid sebut jenis ayam yang diternak.\nSemakan: Guru bantu sebutan ayam kampung organik.\nBahan: BT55.","BBM/ABM":"BT55.","PAK-21":"Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru baca tajuk Tokoh Penternakan pada BT55.\nGuru perkenalkan Dr. Mohamad Zainol sebagai penternak ayam kampung organik dalam buku.\nTindakan murid: Murid dengar penerangan guru.\nMurid sebut jenis ayam yang diternak.\nSemakan: Guru bantu sebutan ayam kampung organik.\nBahan: BT55.","aids_and_pak21_original":"BBM/ABM: BT55.\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca dialog Hasan dan Elis dengan jelas.\nGuru jelaskan permintaannya tinggi bermaksud ramai orang mahu membeli ayam itu.\nTindakan murid: Murid dengar dialog guru.\nMurid sebut hotel atau kedai makan sebagai tempat jualan.\nSemakan: Guru ulang maklumat bebas daripada bahan kimia seperti yang disebut dalam buku.\nBahan: BT55 dan kad tempat jualan.","aids_and_pak21_original":"BBM/ABM: BT55 dan kad tempat jualan.\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru tanya, “Mengapa orang mungkin memilih ayam ini?”\nGuru beri contoh: “Mungkin mereka mahu menjaga kesihatan.”\nTindakan murid: Murid dengar soalan hingga selesai.\nMurid cuba jawapan pendek dengan bantuan guru.\nSemakan: Guru terima jawapan mudah yang sesuai dengan maklumat ayam dalam buku.\nBahan: BT55 dan kad soalan.","aids_and_pak21_original":"BBM/ABM: BT55 dan kad soalan.\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru tambah soalan, “Mengapa kamu memilih hotel atau kedai makan untuk menjual ayam?”\nGuru bantu pasangan dengan contoh “Saya memilih hotel kerana hotel menyediakan makanan.”\nTindakan murid: Murid bergilir bertanya dua soalan sebagai Hasan.\nMurid menjawab sebagai Elis mengikut laluan bantuan.\nSemakan: Dua soalan meliputi sebab orang memilih ayam dan pilihan tempat jualan.\nBahan: Kad soalan, kad tempat dan rangka ayat.","aids_and_pak21_original":"BBM/ABM: Kad soalan, kad tempat dan rangka ayat.\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru dengar dua jawapan murid yang belum diperhatikan semasa latihan.\nGuru beri awal ayat apabila murid sukar menyebut sebab.\nTindakan murid: Murid jawab dengan pilihan sendiri.\nMurid sebut semula sebab dengan bantuan jika perlu.\nSemakan: Pilihan hotel atau kedai makan diterima apabila sebabnya mudah dan sesuai.\nBahan: Kad tempat, rangka ayat dan catatan guru.","aids_and_pak21_original":"BBM/ABM: Kad tempat, rangka ayat dan catatan guru.\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru minta beberapa murid berkongsi pilihan tempat jualan.\nGuru rumuskan bahawa jawapan boleh berbeza mengikut pilihan.\nTindakan murid: Murid dengar pilihan rakan.\nMurid ucap terima kasih selepas soal jawab.\nSemakan: Guru kenal pasti murid yang memerlukan latihan menjawab mengapa.\nBahan: BT55.","aids_and_pak21_original":"BBM/ABM: BT55.\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Dengar dan pilih","implementation_original":"Tugasan: Menjawab dua soalan dengan pilihan tempat dan contoh sebab yang pendek.\nBahan: BT55\nKad hotel dan kedai makan\nRangka “Saya memilih … kerana …”\nBimbingan guru: Guru baca soalan perlahan-lahan kepada pasangan.\nGuru bantu melengkapkan sebab seperti tempat itu menyediakan makanan.\nLangkah murid: Dengar soalan bersama pasangan.\nPilih kad tempat yang disukai.\nSebut dua jawapan dengan model guru jika perlu.\nHasil individu: Dua respons lisan setiap murid.\nKriteria: Jawapan sesuai dengan soalan dan pilihan tempat.\nSusulan: Ulang satu soalan mengapa dengan rangka kerana jika murid masih terhenti.","aids_and_pak21_original":"BBM/ABM: BT55\nKad hotel dan kedai makan\nRangka “Saya memilih … kerana …”\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},"pembina":{"label":"Langkah 1\nPembina — Jawab dengan kata sendiri","implementation_original":"Tugasan: Memberi respons tentang pilihan ayam dan tempat jualan menggunakan bank kata.\nBahan: BT55\nBank kata kesihatan, hotel, kedai makan dan makanan\nBimbingan guru: Guru beri masa murid berbincang sebelum menjawab.\nGuru bantu menyambung sebab menggunakan kerana apabila diperlukan.\nLangkah murid: Dengar dua soalan daripada pasangan.\nLatih jawapan menggunakan kata pilihan.\nBerikan dua respons sendiri kepada guru.\nHasil individu: Dua respons lisan dengan satu sebab pilihan tempat.\nKriteria: Respons menjawab soalan yang didengar.\nSusulan: Baiki sebab yang belum jelas bersama guru menggunakan contoh tempat makan.","aids_and_pak21_original":"BBM/ABM: BT55\nBank kata kesihatan, hotel, kedai makan dan makanan\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."},"pencabar":{"label":"Langkah 1\nPencabar — Satu sebab lagi","implementation_original":"Tugasan: Mencuba satu sebab tambahan bagi pilihan tempat jualan jika bersedia.\nBahan: BT55\nKad hotel dan kedai makan\nBimbingan guru: Guru tanya perkara yang berlaku di tempat pilihan murid.\nGuru bantu murid menyebut sebab tambahan dalam satu ayat pendek.\nLangkah murid: Selesaikan dua respons utama.\nFikirkan satu sebab lain bersama pasangan.\nSebut sebab tambahan kepada guru.\nHasil individu: Dua respons utama dan satu sebab tambahan.\nKriteria: Sebab tambahan berkaitan dengan tempat jualan yang dipilih.\nSusulan: Gunakan sebab yang paling mudah difahami apabila menjawab soalan semula.","aids_and_pak21_original":"BBM/ABM: BT55\nKad hotel dan kedai makan\nPAK-21: Temu bual berpasangan: murid menjadi Hasan dan Elis secara bergilir."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian lisan selepas murid mendengar soalan guru atau pasangan.","Evidens":"Dua respons tentang pilihan ayam dan tempat menjual ayam.","Kriteria Kejayaan":"Respons sesuai dengan soalan serta satu sebab pilihan tempat dapat diberikan."},"closure_original":"Tindakan guru: Guru minta beberapa murid berkongsi pilihan tempat jualan.\nGuru rumuskan bahawa jawapan boleh berbeza mengikut pilihan.\nTindakan murid: Murid dengar pilihan rakan.\nMurid ucap terima kasih selepas soal jawab.\nSemakan: Guru kenal pasti murid yang memerlukan latihan menjawab mengapa.\nBahan: BT55.","reflection_original":"__ daripada __ murid dapat memberi respons terhadap soalan bercapah. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M33-S3.docx","source_docx_sha256":"4a7b2a8964ee6a3ca30435fc19ab2d907037a6c2cbc3e932793009ea75e33bfc","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M33-S4","week_no":33,"session_no":4,"lesson_map":{"title":"Rumput Napier","sp":"2.2.1","page":56,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":33,"session":4,"revision":"r1","title_original":"Rumput Napier","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1 (iv) (v)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid mengenal pasti secara individu satu idea utama dan satu idea sampingan yang menyokongnya bagi sekurang-kurangnya tiga daripada empat perenggan kedua hingga kelima dalam teks Rumput Napier.","success_criteria_original":"Tiga pasangan idea utama–sampingan tepat daripada empat perenggan.; Idea utama merangkumi perkara pokok; idea sampingan memberikan bukti atau penerangan khusus.; Petikan kekal terbuka; kelancaran dan intonasi bacaan bukan kriteria utama.","textbook_pages_original":"m/s 56","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca perenggan pertama dan tanya perkara yang ingin dilakukan oleh ayah Kok Bun.\nBezakan keinginan mengusahakan tanah dengan butiran lokasi tanah di hujung kampung.\nTindakan murid: Tunjuk ayat tentang tanah terbiar dan keinginan ayah.\nSebut perkara pokok kemudian satu butiran yang menerangkannya.\nSemakan: Jika murid memilih lokasi sahaja sebagai idea utama, tanya sama ada lokasi menjelaskan keseluruhan masalah ayah.\nBahan: BT56, perenggan pertama.","BBM/ABM":"BT56, perenggan pertama.","PAK-21":"Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: cerita pokok atau butiran?","execution_original":"Tindakan guru: Baca perenggan pertama dan tanya perkara yang ingin dilakukan oleh ayah Kok Bun.\nBezakan keinginan mengusahakan tanah dengan butiran lokasi tanah di hujung kampung.\nTindakan murid: Tunjuk ayat tentang tanah terbiar dan keinginan ayah.\nSebut perkara pokok kemudian satu butiran yang menerangkannya.\nSemakan: Jika murid memilih lokasi sahaja sebagai idea utama, tanya sama ada lokasi menjelaskan keseluruhan masalah ayah.\nBahan: BT56, perenggan pertama.","aids_and_pak21_original":"BBM/ABM: BT56, perenggan pertama.\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},{"phase_original":"Langkah 2\nPemodelan hubungan utama–sampingan","execution_original":"Tindakan guru: Modelkan perenggan kedua: idea utama 'Kok Bun memberikan idea kepada ayahnya'; sampingan 'Idea itu bernas dan bapanya bersetuju'.\nTunjuk bahawa jawapan boleh diparafrasa tetapi mesti disokong ayat; jangan mengajar ayat pertama sentiasa jawapan utama.\nTindakan murid: Gariskan ayat sokongan untuk contoh guru dan padankan dengan jadual dua ruang.\nBandingkan 'Idea itu bernas' dengan idea utama; jelaskan yang mana memerlukan konteks tambahan.\nSemakan: Murid perlu menerangkan hubungan butiran dengan perkara pokok, bukan memilih berdasarkan kedudukan ayat sahaja.\nBahan: Perenggan kedua, jadual contoh dan pen penanda.","aids_and_pak21_original":"BBM/ABM: Perenggan kedua, jadual contoh dan pen penanda.\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},{"phase_original":"Langkah 3\nPasangan: buktikan idea perenggan ketiga","execution_original":"Tindakan guru: Edarkan kad 'Napier sesuai untuk ternakan', 'air banyak' dan 'tekstur lembut'; minta murid menyusun hubungan.\nTanya mengapa kambing, lembu dan ayam belanda ialah contoh ternakan, bukan tiga idea utama berlainan.\nTindakan murid: Baca senyap perenggan ketiga dan pilih satu idea yang merangkumi isi.\nRakan meminta bukti; pemilik menunjukkan ayat tentang air atau tekstur dan menjelaskan hubungannya.\nSemakan: Model semakan guru: utama Napier sesuai untuk ternakan; sampingan mengandungi banyak air atau bertekstur lembut.\nBahan: Perenggan ketiga dan tiga kad idea.","aids_and_pak21_original":"BBM/ABM: Perenggan ketiga dan tiga kad idea.\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},{"phase_original":"Langkah 4\nLatihan terbeza: peta idea empat perenggan","execution_original":"Tindakan guru: Jalankan tiga laluan serentak meliputi perenggan kedua hingga kelima; bantuan berbeza tetapi sasaran hubungan idea sama.\nSemak alasan setiap kumpulan: perenggan keempat tentang hasil/pendapatan keluarga, kelima tentang kerjasama mengusahakan Napier.\nTindakan murid: Gunakan langkah laluan untuk menghasilkan jadual atau peta hubungan milik sendiri.\nSemak pilihan dengan petikan dan ubah jawapan jika butiran tidak menyokong idea utama.\nSemakan: Guru mengesan jawapan angka sahaja atau idea terlalu umum seperti 'rumput'; minta rangkuman yang lebih bermakna.\nBahan: Petikan bernombor, kad pilihan dan jadual tiga laluan.","aids_and_pak21_original":"BBM/ABM: Petikan bernombor, kad pilihan dan jadual tiga laluan.\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},{"phase_original":"Langkah 5\nPBD individu: empat pasangan idea","execution_original":"Tindakan guru: Berikan jadual kosong perenggan 2–5; petikan dibenarkan tetapi kad jawapan dan bantuan rakan ditutup.\nSemak model adaptasi: hasil Napier/pendapatan sehingga RM2300.00 sebulan; kerjasama penduduk/tiada lagi tanah terbiar. Terima rumusan setara yang terbukti.\nTindakan murid: Tulis satu idea utama dan satu sampingan bagi setiap perenggan.\nTandakan ayat bukti pada petikan dan serahkan jadual individu.\nSemakan: Satu pasangan dikira tepat hanya jika kedua-dua idea betul serta berkaitan; sasaran tiga pasangan, bukan enam fakta rawak.\nBahan: Jadual empat baris dan BT56.","aids_and_pak21_original":"BBM/ABM: Jadual empat baris dan BT56.\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},{"phase_original":"Langkah 6\nPenutup: butiran mesti menyokong","execution_original":"Tindakan guru: Tanya mengapa '30 hari' sahaja tidak menerangkan keseluruhan perenggan keempat.\nRumuskan beza perkara pokok dengan penerangan; pilih pasangan idea yang perlu dibimbing semula.\nTindakan murid: Sebut perkara yang diterangkan oleh butiran masa menuai itu.\nNyatakan satu soalan semakan sendiri: 'Butiran ini menerangkan idea mana?'\nSemakan: Respons penutup digunakan untuk intervensi; sebutan nombor dan kelancaran membaca tidak diberi skor objektif ini.\nBahan: Kad 30 hari dan jadual individu.","aids_and_pak21_original":"BBM/ABM: Kad 30 hari dan jadual individu.\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — padanan idea dengan bukti","implementation_original":"Tugasan: Pilih idea utama dan padankan satu butiran bagi setiap perenggan menggunakan pilihan terhad yang masih memerlukan alasan.\nBahan: Perenggan 2–5 dipisahkan\nDua kad calon utama setiap perenggan dan kad butiran air, pendapatan, persetujuan, kerjasama\nBimbingan guru: Modelkan cara menolak kad yang hanya menyebut satu butiran kecil.\nBacakan frasa sukar jika perlu, kemudian minta murid sendiri menentukan hubungan idea.\nLangkah murid: Baca satu perenggan dan sebut perkara yang paling banyak diterangkan.\nBandingkan dua calon idea utama sebelum memilih.\nLetakkan butiran di bawah pilihan dan tunjuk ayat buktinya.\nTulis empat pasangan dalam jadual dengan bantuan kad dikurangkan.\nHasil individu: Jadual empat pasangan idea berserta tanda bukti.\nKriteria: Tiga pasangan tepat ialah sasaran; pilihan kad dan bacaan bantuan dicatat.\nSusulan: Jika keliru, uji satu butiran dengan dua idea utama sebelum mencuba semula.","aids_and_pak21_original":"BBM/ABM: Perenggan 2–5 dipisahkan\nDua kad calon utama setiap perenggan dan kad butiran air, pendapatan, persetujuan, kerjasama\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},"pembina":{"label":"Langkah 1\nPembina — rangkum dan sahkan","implementation_original":"Tugasan: Kenal pasti sendiri perkara pokok dan satu butiran sokongan bagi perenggan kedua hingga kelima tanpa kad jawapan.\nBahan: Petikan lengkap bernombor\nJadual utama/sampingan/bukti serta pen dua warna\nBimbingan guru: Tanya sama ada rumusan murid merangkumi isi, bukan sekadar mengulang tajuk.\nMinta rakan menyoal hubungan apabila butiran dipilih daripada perenggan berlainan.\nLangkah murid: Baca setiap perenggan dan tandakan perkataan yang berulang maknanya.\nTulis satu rumusan utama menggunakan kata sendiri atau frasa teks.\nPilih butiran yang menjelaskan rumusan dan catat bukti.\nTukar jadual untuk disoal rakan lalu baiki jawapan sendiri.\nHasil individu: Empat pasangan idea dengan bukti perenggan yang dapat dijejaki.\nKriteria: Sekurang-kurangnya tiga pasangan tepat serta hubungan sokongan dapat diterangkan.\nSusulan: Jika mantap, bandingkan dua rumusan munasabah dan pilih yang lebih merangkumi isi.","aids_and_pak21_original":"BBM/ABM: Petikan lengkap bernombor\nJadual utama/sampingan/bukti serta pen dua warna\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — nilai rumusan yang bersaing","implementation_original":"Tugasan: Uji calon idea utama yang terlalu sempit, terlalu umum atau munasabah sebelum membina peta idea empat perenggan.\nBahan: Kad 'RM2300.00', 'Rumput', 'Tanaman Napier menghasilkan pendapatan keluarga'\nBT56 dan peta hubungan kosong\nBimbingan guru: Minta murid menolak calon dengan alasan liputan isi, bukan kerana ayatnya pendek.\nTanya sama ada kerjasama penduduk atau pendapatan keluarga lebih sesuai untuk perenggan terakhir.\nLangkah murid: Baca semula perenggan dan bandingkan calon rumusan.\nNyatakan sebab menolak angka atau tajuk umum sebagai rumusan.\nTulis idea utama dan satu sampingan untuk setiap perenggan.\nPertahankan satu pilihan apabila pasangan menawarkan rumusan alternatif.\nHasil individu: Peta empat pasangan idea dan dua alasan penolakan calon.\nKriteria: Tiga pasangan tepat serta alasan menunjukkan hubungan dan liputan isi.\nSusulan: Perhalus rumusan tanpa menambah fakta pertanian yang tidak dinyatakan dalam teks.","aids_and_pak21_original":"BBM/ABM: Kad 'RM2300.00', 'Rumput', 'Tanaman Napier menghasilkan pendapatan keluarga'\nBT56 dan peta hubungan kosong\nPAK-21: Fikir–Padan–Buktikan: pasangan memilih idea, menunjukkan ayat sokongan dan bertukar peranan sebagai penyoal; setiap murid menulis jadual sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan jadual individu dengan petikan terbuka; penjelasan hubungan jika diperlukan.","Evidens":"Empat pasangan utama–sampingan perenggan 2–5 dan tanda bukti teks.","Kriteria Kejayaan":"Sekurang-kurangnya tiga pasangan tepat serta saling berkaitan."},"closure_original":"Tindakan guru: Tanya mengapa '30 hari' sahaja tidak menerangkan keseluruhan perenggan keempat.\nRumuskan beza perkara pokok dengan penerangan; pilih pasangan idea yang perlu dibimbing semula.\nTindakan murid: Sebut perkara yang diterangkan oleh butiran masa menuai itu.\nNyatakan satu soalan semakan sendiri: 'Butiran ini menerangkan idea mana?'\nSemakan: Respons penutup digunakan untuk intervensi; sebutan nombor dan kelancaran membaca tidak diberi skor objektif ini.\nBahan: Kad 30 hari dan jadual individu.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M33-S4.docx","source_docx_sha256":"a8e297845448d10a6f87bc75aaf55ae365ba81a5d63572bc654bfa32f87d109a","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":33,"session":4,"revision":"r2","title_original":"Rumput Napier","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1 (iv) (v)","sp_support_original":"—","objective_original":"Murid dapat mengenal pasti idea utama dan idea sampingan dalam teks Rumput Napier.","success_criteria_original":"Menyatakan satu idea utama bagi perenggan pilihan.; Menyatakan satu idea sampingan yang berkaitan.","textbook_pages_original":"m/s 56","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Rumput Napier pada BT56.\nGuru tanya, “Haiwan apakah yang makan rumput?”\nTindakan murid: Murid sebut kambing atau lembu.\nMurid dengar penerangan ringkas tentang rumput Napier.\nSemakan: Guru kaitkan rumput Napier dengan makanan ternakan.\nBahan: BT56.","BBM/ABM":"BT56.","PAK-21":"Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk tajuk Rumput Napier pada BT56.\nGuru tanya, “Haiwan apakah yang makan rumput?”\nTindakan murid: Murid sebut kambing atau lembu.\nMurid dengar penerangan ringkas tentang rumput Napier.\nSemakan: Guru kaitkan rumput Napier dengan makanan ternakan.\nBahan: BT56.","aids_and_pak21_original":"BBM/ABM: BT56.\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca perenggan kedua tentang idea Kok Bun.\nGuru tunjuk idea utama “Kok Bun memberikan idea kepada ayahnya” dan idea sampingan “Ayahnya bersetuju”.\nTindakan murid: Murid ikut bacaan guru.\nMurid sebut dua idea contoh bersama-sama.\nSemakan: Guru jelaskan idea utama sebagai perkara utama dan idea sampingan sebagai maklumat tambahan.\nBahan: BT56 dan dua kad idea.","aids_and_pak21_original":"BBM/ABM: BT56 dan dua kad idea.\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru baca perenggan ketiga tentang menanam rumput Napier.\nGuru tanya, “Apakah perkara utama yang mereka lakukan?”\nTindakan murid: Murid tunjuk ayat “Mereka menanam rumput Napier.”\nMurid baca ayat itu bersama guru.\nSemakan: Guru bantu murid mengenal pasti menanam rumput Napier sebagai perkara utama.\nBahan: BT56.","aids_and_pak21_original":"BBM/ABM: BT56.\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru tanya, “Rumput Napier sesuai untuk apa?”\nGuru bantu pasangan memilih idea mengikut laluan bantuan.\nTindakan murid: Murid baca semula perenggan ketiga bersama pasangan.\nMurid sebut perkara utama dan satu maklumat tambahan secara bergilir.\nSemakan: Contoh maklumat tambahan: rumput Napier sesuai untuk makanan ternakan.\nBahan: BT56, bank kata dan dua kad idea.","aids_and_pak21_original":"BBM/ABM: BT56, bank kata dan dua kad idea.\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru beri ruang Perkara utama dan Maklumat tambahan dalam buku latihan.\nGuru semak dua jawapan setiap murid.\nTindakan murid: Murid tulis jawapan sendiri dengan bank kata jika perlu.\nMurid baca jawapan kepada guru apabila diminta.\nSemakan: Guru terima jawapan ringkas yang menyampaikan idea perenggan dengan betul.\nBahan: Buku latihan dan BT56.","aids_and_pak21_original":"BBM/ABM: Buku latihan dan BT56.\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tanya semula perkara utama perenggan yang dibaca.\nGuru rumuskan beza perkara utama dengan maklumat tambahan.\nTindakan murid: Murid jawab bersama-sama.\nMurid sebut satu maklumat tentang rumput Napier.\nSemakan: Guru kenal pasti murid yang masih menukar dua jenis idea.\nBahan: Dua kad idea dan BT56.","aids_and_pak21_original":"BBM/ABM: Dua kad idea dan BT56.\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Pilih dua idea","implementation_original":"Tugasan: Memadankan idea perenggan ketiga dengan kad perkara utama dan maklumat tambahan.\nBahan: BT56\nKad menanam rumput Napier dan makanan ternakan\nDua kad idea\nBimbingan guru: Guru baca dua ayat awal perenggan ketiga kepada pasangan.\nGuru padankan menanam rumput Napier dengan perkara utama.\nLangkah murid: Ikut bacaan bersama guru.\nLetakkan kad makanan ternakan pada maklumat tambahan.\nSebut dua idea dengan bantuan sebelum menulis jawapan.\nHasil individu: Dua jawapan ringkas setiap murid.\nKriteria: Perkara utama dan maklumat tambahan dipadankan dengan betul.\nSusulan: Ulang padanan dua kad bersama guru jika murid masih keliru.","aids_and_pak21_original":"BBM/ABM: BT56\nKad menanam rumput Napier dan makanan ternakan\nDua kad idea\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},"pembina":{"label":"Langkah 1\nPembina — Cari idea bersama rakan","implementation_original":"Tugasan: Membaca perenggan ketiga untuk memilih idea utama dan idea sampingan.\nBahan: BT56\nBank kata menanam, rumput Napier dan ternakan\nBuku latihan\nBimbingan guru: Guru tanya perkara utama yang dilakukan oleh keluarga Kok Bun.\nGuru bantu murid mencari ayat tentang kegunaan rumput.\nLangkah murid: Baca perenggan bersama pasangan.\nBergilir menyebut dua idea pilihan.\nTulis idea sendiri dengan bank kata jika perlu.\nHasil individu: Satu idea utama dan satu idea sampingan.\nKriteria: Dua idea berkaitan dengan perenggan yang dibaca.\nSusulan: Baca semula ayat berkaitan bersama guru jika jawapan terlalu umum.","aids_and_pak21_original":"BBM/ABM: BT56\nBank kata menanam, rumput Napier dan ternakan\nBuku latihan\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."},"pencabar":{"label":"Langkah 1\nPencabar — Satu maklumat lagi","implementation_original":"Tugasan: Mencari satu idea sampingan tambahan daripada perenggan yang sama jika bersedia.\nBahan: BT56\nKad air banyak dan lembut\nBimbingan guru: Guru tunjuk ayat tentang sebab ternakan menggemari rumput Napier.\nGuru bantu murid memilih satu ciri rumput sebagai maklumat tambahan.\nLangkah murid: Selesaikan dua idea utama latihan.\nBaca ayat tentang ciri rumput bersama pasangan.\nSebut satu idea sampingan tambahan.\nHasil individu: Dua jawapan utama dan satu maklumat tambahan.\nKriteria: Idea tambahan sesuai dengan perenggan ketiga.\nSusulan: Kongsi idea itu dengan pasangan menggunakan satu ayat pendek.","aids_and_pak21_original":"BBM/ABM: BT56\nKad air banyak dan lembut\nPAK-21: Baca berpasangan: murid mencari perkara utama dan maklumat tambahan dalam satu perenggan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan dua jawapan individu dan pemerhatian semasa membaca.","Evidens":"Idea utama dan idea sampingan daripada perenggan ketiga.","Kriteria Kejayaan":"Murid mengenal pasti perkara utama dan satu maklumat tambahan yang berkaitan."},"closure_original":"Tindakan guru: Guru tanya semula perkara utama perenggan yang dibaca.\nGuru rumuskan beza perkara utama dengan maklumat tambahan.\nTindakan murid: Murid jawab bersama-sama.\nMurid sebut satu maklumat tentang rumput Napier.\nSemakan: Guru kenal pasti murid yang masih menukar dua jenis idea.\nBahan: Dua kad idea dan BT56.","reflection_original":"__ daripada __ murid dapat mengenal pasti idea utama dan idea sampingan. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M33-S4.docx","source_docx_sha256":"6d0a6963816d0a2b9ca6d29c078c847c73e74812ebcdac428614f2f7fc3013d7","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M33-S5","week_no":33,"session_no":5,"lesson_map":{"title":"Bahan Buangan yang Berharga","sp":"3.3.1","page":57,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":33,"session":5,"revision":"r1","title_original":"Bahan Buangan yang Berharga","sk_original":"3.3 Menghasilkan penulisan","sp_original":"3.3.1 (i)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid melengkapkan secara individu sebuah cerita separa terkawal tentang Julaihi dan ayahnya dengan sekurang-kurangnya empat daripada lima bahagian isi tepat serta urutan peristiwa yang munasabah.","success_criteria_original":"Empat daripada lima ruang bergambar lengkap dengan isi yang sesuai.; Cerita mengekalkan Julaihi dan ayahnya, proses menghasilkan rotan bulu ayam serta urutan yang diberi.; Ayat dibaca bersama sambungan asal supaya jawapan tidak menjadi senarai berasingan; bantuan bank frasa direkod.","textbook_pages_original":"m/s 57","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca pengenalan tentang bulu ayam dibuang di pasar dan cadangan sumber pendapatan sampingan.\nTanya siapa watak dan apakah masalah atau peluang yang mereka lihat.\nTindakan murid: Nyatakan Julaihi dan ayahnya sebagai watak.\nHubungkan bahan terbuang dengan cadangan mereka berdasarkan ayat yang didengar.\nSemakan: Terima fakta pengenalan; hubungkan gambar bulu yang dikumpulkan kepada peluang pendapatan tanpa mereka harga jualan.\nBahan: Dua ayat pengenalan BT57.","BBM/ABM":"Dua ayat pengenalan BT57.","PAK-21":"Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: bahan terbuang, idea pendapatan","execution_original":"Tindakan guru: Baca pengenalan tentang bulu ayam dibuang di pasar dan cadangan sumber pendapatan sampingan.\nTanya siapa watak dan apakah masalah atau peluang yang mereka lihat.\nTindakan murid: Nyatakan Julaihi dan ayahnya sebagai watak.\nHubungkan bahan terbuang dengan cadangan mereka berdasarkan ayat yang didengar.\nSemakan: Terima fakta pengenalan; hubungkan gambar bulu yang dikumpulkan kepada peluang pendapatan tanpa mereka harga jualan.\nBahan: Dua ayat pengenalan BT57.","aids_and_pak21_original":"BBM/ABM: Dua ayat pengenalan BT57.\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},{"phase_original":"Langkah 2\nPemodelan cerita separa terkawal","execution_original":"Tindakan guru: Tunjuk kelima-lima ruang asal dan gambar petunjuk. Modelkan membaca ayat sebelum dan selepas ruang pertama sebelum memilih bulu ayam sebagai pelengkap.\nBaca penanda Selepas itu, Setelah kering dan Setelah siap. Tanya mengapa menjemur perlu berlaku sebelum memilih bulu yang cantik; jangan memisahkan jawapan daripada aliran cerita.\nTindakan murid: Baca bahagian kerangka yang sudah diberi dan kenal pasti ruang yang perlu dilengkapkan.\nTandakan penanda setelah kering dan setelah siap pada teks, kemudian jelaskan urutannya.\nSemakan: Contoh guru diberi bagi satu ruang sahaja; murid melengkapkan ruang lain daripada gambar dan konteks tanpa menyalin semua jawapan.\nBahan: BT57, kerangka asal dan pen penanda.","aids_and_pak21_original":"BBM/ABM: BT57, kerangka asal dan pen penanda.\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},{"phase_original":"Langkah 3\nLatihan pasangan: uji kesinambungan","execution_original":"Tindakan guru: Sediakan jalur mengumpulkan bulu, meletakkan dalam bakul, menjemur, melekatkan pada rotan dan menggunakan alat untuk membersihkan meja.\nMinta pasangan menyusun jalur mengikut teks serta gambar, kemudian jelaskan peranan penanda masa sebelum menulis.\nTindakan murid: Susun jalur menjadi urutan cerita lalu baca kepada pasangan.\nTanya bahagian mana memerlukan sambungan supaya pembaca memahami perubahan daripada bahan kepada hasil.\nSemakan: Jika hasil siap diletakkan sebelum penjemuran atau pemilihan bahan, murid menggunakan penanda setelah kering dan setelah siap serta gambar untuk membetulkan urutan.\nBahan: Empat jalur peristiwa teks dan kerangka naratif.","aids_and_pak21_original":"BBM/ABM: Empat jalur peristiwa teks dan kerangka naratif.\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},{"phase_original":"Langkah 4\nLatihan terbeza: bengkel melengkapkan cerita","execution_original":"Tindakan guru: Jalankan tiga laluan serentak menggunakan lima ruang bergambar asal; bank frasa hanya untuk murid yang memerlukan sokongan.\nSemak kesinambungan ayat setiap murid dan tanya gambar mana membantu pilihan kata; tarik balik bank frasa selepas murid mula memberi alasan.\nTindakan murid: Lengkapkan kerangka mengikut empat langkah laluan dengan tulisan sendiri.\nBacakan draf kepada pasangan, terima pertanyaan urutan dan baiki tanpa menyalin cerita rakan.\nSemakan: Guru membezakan isi salah, urutan terbalik dan kesalahan ejaan; fokus utama kekal penghasilan naratif.\nBahan: Kerangka, kad sokongan dan jalur semakan tiga laluan.","aids_and_pak21_original":"BBM/ABM: Kerangka, kad sokongan dan jalur semakan tiga laluan.\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},{"phase_original":"Langkah 5\nPBD individu: cerita lengkap, bukan senarai","execution_original":"Tindakan guru: Berikan kerangka asal tanpa jawapan pasangan; murid melengkapkan lima ruang sebagai cerita bersambung, bukan senarai kata sahaja.\nContoh semakan guru: bulu ayam, bakul, menjemur, rotan dan membersihkan meja. Terima frasa setara yang sesuai; jangan mewajibkan bahan bakul atau habuk yang tidak jelas pada gambar.\nTindakan murid: Lengkapkan lima bahagian dan baca semula bersama ayat sebelum serta selepas ruang dalam kerangka asal.\nSemak urutan, rujukan watak dan noktah sebelum menyerahkan tulisan sendiri.\nSemakan: Sekurang-kurangnya empat ruang tepat serta urutan munasabah memenuhi sasaran; ejaan dan penghubung turut diperbaik tanpa mengubah fokus naratif.\nBahan: Kerangka lima ruang asal BT57, gambar petunjuk dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Kerangka lima ruang asal BT57, gambar petunjuk dan senarai semak.\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},{"phase_original":"Langkah 6\nPenutup: satu pembaikan cerita","execution_original":"Tindakan guru: Tunjuk contoh dua peristiwa terbalik daripada jalur guru dan minta pembetulan.\nRumuskan bahawa cerita memerlukan urutan serta isi, bukan lima jawapan yang terpisah.\nTindakan murid: Sebut urutan yang munasabah dan sebabnya.\nTandakan satu bahagian tulisan sendiri yang perlu diperiksa semula bersama guru.\nSemakan: Semakan akhir membezakan murid yang tahu fakta dengan murid yang dapat menghubungkannya dalam cerita.\nBahan: Jalur urutan dan hasil individu.","aids_and_pak21_original":"BBM/ABM: Jalur urutan dan hasil individu.\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — kerangka dan bank frasa","implementation_original":"Tugasan: Lengkapkan lima ruang cerita asal menggunakan gambar, ayat pengapit dan bank frasa yang dikurangkan secara beransur-ansur.\nBahan: Kerangka asal dengan pembukaan dan penutup sedia ada\nBank contoh bulu ayam/bakul/menjemur/rotan/membersihkan meja serta gambar buku\nBimbingan guru: Modelkan membaca ayat sebelum dan selepas ruang sebelum memilih frasa.\nTutup satu kad apabila murid dapat menjelaskan hubungannya dengan cerita.\nLangkah murid: Baca pembukaan dan sebut watak yang perlu dikekalkan.\nPilih frasa bagi ruang dengan merujuk konteks ayat.\nBaca sambungan kepada guru untuk menguji makna dan urutan.\nTulis cerita lengkap lalu cuba satu ruang tanpa bank frasa.\nHasil individu: Cerita asal BT57 yang telah dilengkapkan lima ruang, bukan senarai lima perkataan terpisah.\nKriteria: Empat isi tepat dan urutan munasabah menjadi sasaran; bantuan frasa dicatat.\nSusulan: Jika masih menjadi senarai, baca setiap jawapan bersama ayat pengapit sebelum menulis semula.","aids_and_pak21_original":"BBM/ABM: Kerangka asal dengan pembukaan dan penutup sedia ada\nBank contoh bulu ayam/bakul/menjemur/rotan/membersihkan meja serta gambar buku\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},"pembina":{"label":"Langkah 1\nPembina — kata kunci kepada sambungan","implementation_original":"Tugasan: Hasilkan sambungan naratif dalam kerangka asal dengan kata kunci serta gambar, bukan memilih jawapan lengkap daripada bank frasa.\nBahan: Kerangka asal BT57 tanpa bank jawapan\nKad nombor lima gambar dan kata penanda urutan\nBimbingan guru: Tanya ayat manakah membuktikan isi jika murid menambah maklumat baharu.\nMinta pasangan menyoal urutan dan rujukan mereka tanpa menentukan jawapan untuk pemilik.\nLangkah murid: Baca seluruh kerangka asal dan teliti lima gambar sebelum mengisi mana-mana ruang.\nBina frasa atau sambungan ayat berdasarkan kata kunci.\nBaca cerita kepada pasangan dan tandakan sambungan yang janggal.\nBaiki urutan serta rujukan watak dan tulis versi akhir sendiri.\nHasil individu: Cerita lengkap dengan satu pembaikan kesinambungan ditandakan.\nKriteria: Empat daripada lima isi tepat serta cerita dapat diikuti tanpa lompatan urutan.\nSusulan: Jika mantap, variasikan penanda masa tanpa mengubah peristiwa sumber.","aids_and_pak21_original":"BBM/ABM: Kerangka asal BT57 tanpa bank jawapan\nKad nombor lima gambar dan kata penanda urutan\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — menyunting urutan dalam kerangka","implementation_original":"Tugasan: Nilai susunan peristiwa yang sengaja diganggu sebelum melengkapkan cerita separa terkawal dengan sambungan sendiri berasaskan sumber.\nBahan: Jalur menyangkut hasil diletakkan sebelum memilih bahan\nKerangka asal BT57 dengan pembukaan, penutup dan lima ruang isi tetap\nBimbingan guru: Minta murid menjelaskan mengapa sesuatu peristiwa perlu mendahului peristiwa lain.\nHadkan peluasan kepada kata penghubung dan kelancaran ayat; butiran alat atau kegunaan perlu sepadan gambar, bukan rekaan cerita bebas.\nLangkah murid: Baca jalur dan kesan hubungan masa yang terbalik.\nSusun semula dengan merujuk setelah kering dan setelah siap.\nLengkapkan lima ruang dalam cerita menggunakan ungkapan sendiri.\nPertahankan satu pembaikan dan semak bahawa semua isi dapat dijejaki.\nHasil individu: Cerita asal yang dilengkapkan lima ruang dengan catatan ringkas sebab pembaikan urutan.\nKriteria: Empat isi tepat, urutan munasabah dan alasan merujuk penanda masa serta gambar yang telah diperiksa.\nSusulan: Perhalus penghubung supaya cerita lancar tanpa mengubah fakta atau menjadi karangan bebas.","aids_and_pak21_original":"BBM/ABM: Jalur menyangkut hasil diletakkan sebelum memilih bahan\nKerangka asal BT57 dengan pembukaan, penutup dan lima ruang isi tetap\nPAK-21: Pencerita–Penyemak urutan: murid menceritakan draf kepada rakan yang menyoal apa berlaku dahulu; pemilik menulis pembaikan sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan naratif bertulis individu, bukan skor padanan frasa sahaja.","Evidens":"Cerita asal dengan lima ruang bergambar dilengkapkan, jejak pembetulan dan bantuan bank frasa dinyatakan.","Kriteria Kejayaan":"Sekurang-kurangnya empat isi tepat dan urutan peristiwa munasabah."},"closure_original":"Tindakan guru: Tunjuk contoh dua peristiwa terbalik daripada jalur guru dan minta pembetulan.\nRumuskan bahawa cerita memerlukan urutan serta isi, bukan lima jawapan yang terpisah.\nTindakan murid: Sebut urutan yang munasabah dan sebabnya.\nTandakan satu bahagian tulisan sendiri yang perlu diperiksa semula bersama guru.\nSemakan: Semakan akhir membezakan murid yang tahu fakta dengan murid yang dapat menghubungkannya dalam cerita.\nBahan: Jalur urutan dan hasil individu.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M33-S5.docx","source_docx_sha256":"18e2d51744ba567cb0c1709c5579397ec6b52f6a1703eedd69eac7e67b1c7c78","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":33,"session":5,"revision":"r2","title_original":"Bahan Buangan yang Berharga","sk_original":"3.3 Menghasilkan penulisan","sp_original":"3.3.1 (i)","sp_support_original":"—","objective_original":"Murid dapat melengkapkan cerita pendek berdasarkan gambar bulu ayam dengan bantuan kata.","success_criteria_original":"Melengkapkan tiga ruang cerita dengan kata yang sesuai.; Membaca cerita pendek mengikut urutan.","textbook_pages_original":"m/s 57","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Bahan Buangan yang Berharga pada BT57.\nGuru tanya, “Apakah bahan yang dikumpulkan oleh Julaihi dan ayahnya?”\nTindakan murid: Murid lihat gambar bulu ayam.\nMurid sebut bulu ayam.\nSemakan: Guru kaitkan bulu ayam dengan alat membersihkan meja.\nBahan: BT57.","BBM/ABM":"BT57.","PAK-21":"Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk tajuk Bahan Buangan yang Berharga pada BT57.\nGuru tanya, “Apakah bahan yang dikumpulkan oleh Julaihi dan ayahnya?”\nTindakan murid: Murid lihat gambar bulu ayam.\nMurid sebut bulu ayam.\nSemakan: Guru kaitkan bulu ayam dengan alat membersihkan meja.\nBahan: BT57.","aids_and_pak21_original":"BBM/ABM: BT57.\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca pembukaan cerita Julaihi dan ayahnya.\nGuru lengkapkan contoh “Julaihi dan ayahnya mengumpulkan bulu ayam.”\nTindakan murid: Murid ikut bacaan guru.\nMurid tunjuk gambar bagi perkataan bulu ayam.\nSemakan: Guru tunjuk cara menggunakan gambar untuk memilih kata.\nBahan: BT57 dan bank kata.","aids_and_pak21_original":"BBM/ABM: BT57 dan bank kata.\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru bimbing ayat “Bulu ayam itu dimasukkan ke dalam bakul.”\nGuru baca bahagian akhir menggunakan kata rotan dan membersihkan meja.\nTindakan murid: Murid padankan gambar bakul dengan perkataannya.\nMurid sebut rotan dan membersihkan meja mengikut gambar.\nSemakan: Guru membantu murid memahami keseluruhan cerita sebelum menulis bahagian pendek.\nBahan: BT57 dan bank kata.","aids_and_pak21_original":"BBM/ABM: BT57 dan bank kata.\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru beri rangka tiga ayat awal dengan ruang bulu ayam, bakul dan menjemur.\nGuru bantu pasangan melengkapkan cerita mengikut laluan bantuan.\nTindakan murid: Murid pilih tiga kata berdasarkan gambar.\nMurid baca tiga ayat yang lengkap kepada pasangan.\nSemakan: Ayat ketiga ialah “Selepas itu, mereka menjemur bulu ayam itu.”\nBahan: Rangka cerita dan bank kata.","aids_and_pak21_original":"BBM/ABM: Rangka cerita dan bank kata.\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru minta murid melengkapkan tiga ayat sebagai satu cerita pendek.\nGuru semak pilihan kata dalam cerita murid.\nTindakan murid: Murid tulis cerita dengan bantuan bank kata jika perlu.\nMurid baiki satu kata berdasarkan semakan guru.\nSemakan: Semak tiga ruang dalam ayat yang bersambung, bukan senarai kata sahaja.\nBahan: Buku latihan, rangka cerita dan bank kata.","aids_and_pak21_original":"BBM/ABM: Buku latihan, rangka cerita dan bank kata.\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru ajak murid membaca cerita pendek bersama-sama.\nGuru rumuskan kegunaan bulu ayam sebagai alat membersihkan meja.\nTindakan murid: Murid baca cerita mengikut urutan.\nMurid sebut satu bahan yang boleh digunakan semula.\nSemakan: Guru kenal pasti kata yang perlu dilatih semula.\nBahan: BT57 dan cerita murid.","aids_and_pak21_original":"BBM/ABM: BT57 dan cerita murid.\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Gambar kepada cerita","implementation_original":"Tugasan: Melengkapkan tiga ayat awal cerita dengan gambar dan pilihan kata.\nBahan: BT57\nKad bulu ayam, bakul dan menjemur\nRangka cerita tiga ayat\nBimbingan guru: Guru baca rangka sambil menunjuk gambar.\nGuru lengkapkan ayat pertama bersama pasangan sebagai contoh.\nLangkah murid: Padankan tiga kad dengan gambar.\nSebut ayat lengkap bersama pasangan.\nIsi ruang cerita sendiri dengan bantuan jika perlu.\nHasil individu: Cerita pendek tiga ayat yang dilengkapkan.\nKriteria: Kata yang dipilih sesuai dengan gambar dan ayat.\nSusulan: Ulang padanan gambar menjemur dengan kata jika murid masih keliru.","aids_and_pak21_original":"BBM/ABM: BT57\nKad bulu ayam, bakul dan menjemur\nRangka cerita tiga ayat\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},"pembina":{"label":"Langkah 1\nPembina — Lengkapkan cerita sendiri","implementation_original":"Tugasan: Menggunakan bank kata untuk melengkapkan cerita tiga ayat tentang bulu ayam.\nBahan: BT57\nBank kata bulu ayam, bakul dan menjemur\nBuku latihan\nBimbingan guru: Guru minta pasangan membaca ayat sebelum memilih kata.\nGuru bantu murid menyambung cerita menggunakan Selepas itu.\nLangkah murid: Lihat gambar mengikut urutan bersama pasangan.\nLatih cerita pendek secara lisan.\nLengkapkan tiga ayat sendiri dengan bank kata jika perlu.\nHasil individu: Satu cerita pendek tiga ayat.\nKriteria: Tiga ruang diisi dengan kata yang sesuai.\nSusulan: Baca semula ayat bersama guru jika pilihan kata belum sesuai.","aids_and_pak21_original":"BBM/ABM: BT57\nBank kata bulu ayam, bakul dan menjemur\nBuku latihan\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."},"pencabar":{"label":"Langkah 1\nPencabar — Sambung satu ayat","implementation_original":"Tugasan: Menambah satu ayat daripada bahagian akhir cerita jika bersedia.\nBahan: BT57\nKad rotan\nRangka “Bapa Julaihi melekatkan bulu ayam itu pada batang …”\nBimbingan guru: Guru tunjuk gambar batang rotan pada cerita.\nGuru bantu murid membaca rangka ayat tambahan.\nLangkah murid: Selesaikan tiga ayat utama.\nPilih kata rotan untuk rangka tambahan.\nTulis ayat itu sebagai sambungan cerita.\nHasil individu: Cerita pendek dengan satu ayat sambungan.\nKriteria: Ayat tambahan bersambung dengan kegiatan menghasilkan alat bulu ayam.\nSusulan: Baca cerita yang disambung kepada pasangan mengikut urutan.","aids_and_pak21_original":"BBM/ABM: BT57\nKad rotan\nRangka “Bapa Julaihi melekatkan bulu ayam itu pada batang …”\nPAK-21: Baca berpasangan: murid memilih kata mengikut gambar dan membaca cerita yang dilengkapkan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan cerita pendek individu dalam buku latihan.","Evidens":"Tiga ayat dengan ruang bulu ayam, bakul dan menjemur yang dilengkapkan.","Kriteria Kejayaan":"Tiga kata sesuai melengkapkan cerita mengikut urutan gambar."},"closure_original":"Tindakan guru: Guru ajak murid membaca cerita pendek bersama-sama.\nGuru rumuskan kegunaan bulu ayam sebagai alat membersihkan meja.\nTindakan murid: Murid baca cerita mengikut urutan.\nMurid sebut satu bahan yang boleh digunakan semula.\nSemakan: Guru kenal pasti kata yang perlu dilatih semula.\nBahan: BT57 dan cerita murid.","reflection_original":"__ daripada __ murid dapat melengkapkan cerita pendek berdasarkan gambar. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M33-S5.docx","source_docx_sha256":"9b512a5cd1a0db70ff08ff10d1cc5e97155fb9331d4343e43a0b7a4821043fdc","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":33,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M34-S1","week_no":34,"session_no":1,"lesson_map":{"title":"Menternak Kerbau","sp":"5.3.2","page":58,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":34,"session":1,"revision":"r1","title_original":"Menternak Kerbau","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (iii)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid membina secara individu sekurang-kurangnya tiga daripada empat ayat majmuk yang menggabungkan maklumat pasangan ayat Menternak Kerbau dengan penghubung sesuai serta mengekalkan maksud asal.","success_criteria_original":"Tiga gabungan lengkap daripada empat pasangan ayat sumber.; Maklumat kedua-dua ayat asal dikekalkan tanpa pengulangan subjek yang mengganggu.; Penghubung dipilih mengikut hubungan makna; bantuan direkod berasingan.","textbook_pages_original":"m/s 58","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca dua ayat pekerja memakai sarung tangan dan tangannya tidak cedera.\nTanya hubungan pemakaian sarung tangan dengan keadaan tangan sebelum menunjukkan ayat gabungan buku.\nTindakan murid: Nyatakan dua maklumat yang perlu kekal dalam ayat gabungan.\nSebut tujuan memakai sarung tangan berdasarkan pasangan ayat.\nSemakan: Jika murid menyebut tindakan sahaja, guru tunjuk semula maklumat tangan tidak cedera.\nBahan: Pasangan sarung tangan dan ayat contoh BT58.","BBM/ABM":"Pasangan sarung tangan dan ayat contoh BT58.","PAK-21":"Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: dua maklumat berkaitan","execution_original":"Tindakan guru: Baca dua ayat pekerja memakai sarung tangan dan tangannya tidak cedera.\nTanya hubungan pemakaian sarung tangan dengan keadaan tangan sebelum menunjukkan ayat gabungan buku.\nTindakan murid: Nyatakan dua maklumat yang perlu kekal dalam ayat gabungan.\nSebut tujuan memakai sarung tangan berdasarkan pasangan ayat.\nSemakan: Jika murid menyebut tindakan sahaja, guru tunjuk semula maklumat tangan tidak cedera.\nBahan: Pasangan sarung tangan dan ayat contoh BT58.","aids_and_pak21_original":"BBM/ABM: Pasangan sarung tangan dan ayat contoh BT58.\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},{"phase_original":"Langkah 2\nPemodelan penghubung dan pengguguran","execution_original":"Tindakan guru: Tandakan 'Pekerja itu memakai sarung tangan supaya tangannya tidak cedera'; jelaskan tujuan dan rujukan tangannya.\nModel adaptasi 'Pekerja itu menukul tiang pagar dengan menggunakan penukul'; kekalkan tindakan menggunakan, bukan menganggap setiap frasa dengan sebagai ayat majmuk.\nTindakan murid: Tunjuk dua maklumat asal pada ayat gabungan dan sebut penghubungnya.\nBandingkan ayat lengkap dengan versi yang kehilangan menggunakan; jelaskan maklumat yang berkurang.\nSemakan: Guru menilai penggabungan maklumat dan struktur, bukan kewujudan perkataan dengan semata-mata.\nBahan: Jalur dua pasangan pertama dan kad supaya/dengan.","aids_and_pak21_original":"BBM/ABM: Jalur dua pasangan pertama dan kad supaya/dengan.\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},{"phase_original":"Langkah 3\nLatihan bersama: uji urutan kerbau","execution_original":"Tindakan guru: Paparkan pasangan mengumpulkan kerbau dan menariknya ke kandang; minta pilihan lalu atau kerana.\nModel semakan: 'Bapa Hasan mengumpulkan kerbau lalu menarik kerbau tersebut ke dalam kandang'; tanya perkara yang berlaku dahulu.\nTindakan murid: Cantum jalur menggunakan lalu dan baca kepada pasangan.\nTunjuk maklumat kedua-dua ayat serta sebab pengulangan Bapa Hasan boleh dikurangkan.\nSemakan: Jika maklumat ke dalam kandang hilang, murid merujuk pasangan asal sebelum membaiki.\nBahan: Jalur kerbau, kad lalu/kerana dan papan mini.","aids_and_pak21_original":"BBM/ABM: Jalur kerbau, kad lalu/kerana dan papan mini.\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},{"phase_original":"Langkah 4\nLatihan terbeza: penghubung bermakna","execution_original":"Tindakan guru: Jalankan tiga laluan serentak dengan empat pasangan sumber sama; sokongan berbeza pada pilihan dan alasan.\nDampingi padanan Peneroka, kemudian semak alasan Pembina dan pertukaran makna Pencabar tanpa membekalkan seluruh ayat.\nTindakan murid: Ikut langkah laluan untuk menggabungkan pasangan ayat pada lembaran sendiri.\nSemak satu ayat rakan dengan menunjukkan maklumat yang hilang atau hubungan yang berubah.\nSemakan: Guru merekod salah penghubung, maklumat tertinggal atau pengulangan; pembaikan ditulis oleh pemilik hasil.\nBahan: Jalur, kad dan lembaran tiga laluan.","aids_and_pak21_original":"BBM/ABM: Jalur, kad dan lembaran tiga laluan.\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},{"phase_original":"Langkah 5\nPBD individu: empat gabungan","execution_original":"Tindakan guru: Berikan empat pasangan ayat ujian dengan kata panduan buku tetapi tanpa model gabungan.\nModel semakan guru termasuk 'Bapa Hasan berjumpa peraih untuk menjual kerbau' dan 'Bapa Hasan ke bank kerana hendak menyimpan wang'; terima bentuk setara yang tepat.\nTindakan murid: Tulis empat ayat majmuk dan lingkungi penghubung masing-masing.\nSemak dua maklumat asal masih hadir sebelum menyerahkan lembaran individu.\nSemakan: Sekurang-kurangnya tiga gabungan tepat memenuhi sasaran; menyalin satu ayat asal sahaja tidak dikira gabungan.\nBahan: Empat pasangan ujian dan senarai semak individu.","aids_and_pak21_original":"BBM/ABM: Empat pasangan ujian dan senarai semak individu.\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},{"phase_original":"Langkah 6\nPenutup: penghubung mengubah hubungan","execution_original":"Tindakan guru: Tanya hubungan yang dinyatakan oleh supaya, lalu dan kerana pada contoh hari ini.\nPilih satu gabungan yang kehilangan maklumat untuk dibetulkan bersama tanpa menamakan murid.\nTindakan murid: Padankan tujuan, urutan dan sebab dengan contoh sumber.\nSebut satu langkah semakan sebelum menggabungkan dua ayat.\nSemakan: Guru merancang susulan berdasarkan jenis kesalahan, bukan jumlah kata hubung yang dihafal.\nBahan: Kad penghubung dan satu contoh pembaikan.","aids_and_pak21_original":"BBM/ABM: Kad penghubung dan satu contoh pembaikan.\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — jalur dua maklumat","implementation_original":"Tugasan: Gabungkan empat pasangan ayat menggunakan jalur berwarna dan penghubung buku yang sudah dipadankan kepada setiap konteks.\nBahan: Pasangan menukul, kerbau, peraih dan bank\nKad dengan, lalu, untuk, kerana serta penanda subjek berulang\nBimbingan guru: Modelkan cara mengekalkan dua maklumat sambil menutup subjek berulang.\nTanya hubungan mudah seperti selepas itu atau sebab apa sebelum mengurangkan warna bantuan.\nLangkah murid: Baca kedua-dua ayat dan sebut maklumat masing-masing.\nLetakkan penghubung di antara jalur yang sesuai.\nTutup pengulangan yang boleh digugurkan dan baca semula.\nTulis empat gabungan serta semak bahawa maksud asal kekal.\nHasil individu: Empat ayat gabungan dengan penghubung dilingkungi.\nKriteria: Tiga gabungan tepat ialah sasaran; padanan penghubung yang dibekalkan dicatat berbantu.\nSusulan: Jika maklumat hilang, buka semula dua jalur; selepas stabil, beri pilihan dua penghubung.","aids_and_pak21_original":"BBM/ABM: Pasangan menukul, kerbau, peraih dan bank\nKad dengan, lalu, untuk, kerana serta penanda subjek berulang\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},"pembina":{"label":"Langkah 1\nPembina — pilih berdasarkan hubungan","implementation_original":"Tugasan: Gabungkan pasangan ayat tanpa warna bantuan dan jelaskan hubungan makna sebelum memilih penghubung daripada bank kata.\nBahan: Empat pasangan ayat sumber tanpa penandaan\nBank lima penghubung termasuk supaya dan lembaran kosong\nBimbingan guru: Tanya perkara yang menghubungkan dua ayat apabila pilihan penghubung diragui.\nMinta murid membaca ayat asal semula untuk mengesan maklumat tertinggal.\nLangkah murid: Kenal pasti pelaku dan maklumat dalam setiap pasangan.\nPilih penghubung dengan menyebut hubungan tujuan, urutan, cara atau sebab.\nTulis ayat gabungan tanpa pengulangan subjek yang tidak perlu.\nTukar hasil untuk semakan makna dan baiki sendiri.\nHasil individu: Empat gabungan dan catatan hubungan ringkas di sebelahnya.\nKriteria: Tiga ayat tepat penggabungan serta makna; alasan tidak sekadar mengikut kedudukan kad.\nSusulan: Jika mantap, uji satu penghubung alternatif dan jelaskan sama ada maksud berubah.","aids_and_pak21_original":"BBM/ABM: Empat pasangan ayat sumber tanpa penandaan\nBank lima penghubung termasuk supaya dan lembaran kosong\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."},"pencabar":{"label":"Langkah 1\nPencabar — nilai gabungan yang mengelirukan","implementation_original":"Tugasan: Bandingkan gabungan betul dengan versi yang menukar hubungan atau menggugurkan maklumat penting, kemudian hasilkan pembetulan beralasan.\nBahan: Kad 'Bapa Hasan mengumpulkan kerbau kerana menarik kerbau ke kandang'\nKad menukul tanpa maklumat menggunakan penukul dan empat pasangan asal\nBimbingan guru: Tanya sama ada hubungan sebab dalam kad disokong pasangan sumber.\nMinta murid membezakan ayat yang boleh dibaca dengan gabungan yang benar-benar mengekalkan maklumat.\nLangkah murid: Bandingkan setiap kad dengan dua ayat asal.\nTandakan penghubung bermasalah atau maklumat yang hilang.\nTulis empat gabungan tepat menggunakan penghubung sumber.\nPertahankan dua pembaikan dengan menerangkan hubungan sebelum dan selepasnya.\nHasil individu: Empat ayat dan dua alasan pembaikan makna.\nKriteria: Tiga gabungan tepat serta alasan mengenal pasti perubahan hubungan atau kehilangan maklumat.\nSusulan: Cipta satu kad semakan rakan tanpa memperkenalkan fakta gambar yang belum disahkan.","aids_and_pak21_original":"BBM/ABM: Kad 'Bapa Hasan mengumpulkan kerbau kerana menarik kerbau ke kandang'\nKad menukul tanpa maklumat menggunakan penukul dan empat pasangan asal\nPAK-21: Cantum–Uji Makna: pasangan menggabungkan jalur, rakan menyemak dua maklumat asal dan menyoal fungsi penghubung sebelum bertukar peranan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan empat ayat gabungan bertulis individu.","Evidens":"Empat gabungan pasangan menukul, kerbau, peraih dan bank.","Kriteria Kejayaan":"Tiga gabungan mengekalkan maklumat asal dengan penghubung dan struktur sesuai."},"closure_original":"Tindakan guru: Tanya hubungan yang dinyatakan oleh supaya, lalu dan kerana pada contoh hari ini.\nPilih satu gabungan yang kehilangan maklumat untuk dibetulkan bersama tanpa menamakan murid.\nTindakan murid: Padankan tujuan, urutan dan sebab dengan contoh sumber.\nSebut satu langkah semakan sebelum menggabungkan dua ayat.\nSemakan: Guru merancang susulan berdasarkan jenis kesalahan, bukan jumlah kata hubung yang dihafal.\nBahan: Kad penghubung dan satu contoh pembaikan.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M34-S1.docx","source_docx_sha256":"2fb5a0883fe23dbac86c2bdeae97231cbd1d01e7b4eab7b6c38ac7fea164885e","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":34,"session":1,"revision":"r2","title_original":"Menternak Kerbau","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (iii)","sp_support_original":"—","objective_original":"Murid dapat membina ayat majmuk tentang kegiatan menternak kerbau dengan bantuan kata hubung.","success_criteria_original":"Membina dua ayat majmuk menggunakan lalu dan untuk.; Mengekalkan maksud ayat asal.","textbook_pages_original":"m/s 58","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Menternak Kerbau pada BT58.\nGuru baca ayat tentang pekerja memakai sarung tangan.\nTindakan murid: Murid sebut sarung tangan.\nMurid kongsi kegunaan sarung tangan secara ringkas.\nSemakan: Guru kaitkan sarung tangan dengan menjaga tangan.\nBahan: BT58.","BBM/ABM":"BT58.","PAK-21":"Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi","execution_original":"Tindakan guru: Guru tunjuk tajuk Menternak Kerbau pada BT58.\nGuru baca ayat tentang pekerja memakai sarung tangan.\nTindakan murid: Murid sebut sarung tangan.\nMurid kongsi kegunaan sarung tangan secara ringkas.\nSemakan: Guru kaitkan sarung tangan dengan menjaga tangan.\nBahan: BT58.","aids_and_pak21_original":"BBM/ABM: BT58.\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},{"phase_original":"Langkah 2\nGuru tunjuk contoh","execution_original":"Tindakan guru: Guru baca dua ayat awal tentang pekerja dan tangannya.\nGuru baca contoh “Pekerja itu memakai sarung tangan supaya tangannya tidak cedera.”\nTindakan murid: Murid dengar gabungan ayat.\nMurid tunjuk kata supaya dalam contoh.\nSemakan: Guru terangkan kata hubung membantu menyambung ayat.\nBahan: BT58.","aids_and_pak21_original":"BBM/ABM: BT58.\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru baca pasangan ayat bapa Hasan mengumpulkan kerbau dan menariknya ke kandang.\nGuru modelkan “Bapa Hasan mengumpulkan kerbau lalu menarik kerbau tersebut ke dalam kandang.”\nTindakan murid: Murid letakkan kad lalu antara dua bahagian ayat.\nMurid baca ayat majmuk bersama guru.\nSemakan: Guru bantu murid menyebut tindakan mengumpulkan dahulu sebelum menarik kerbau.\nBahan: BT58, kad lalu dan jalur ayat.","aids_and_pak21_original":"BBM/ABM: BT58, kad lalu dan jalur ayat.\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},{"phase_original":"Langkah 4\nLatihan berpasangan","execution_original":"Tindakan guru: Guru beri pasangan ayat tentang berjumpa peraih dan menjual kerbau.\nGuru bantu murid menggunakan untuk mengikut laluan bantuan.\nTindakan murid: Murid susun “Bapa Hasan berjumpa peraih untuk menjual kerbau.”\nMurid bergilir membaca ayat lalu dan ayat untuk.\nSemakan: Guru semak kata hubung sesuai dengan urutan atau tujuan.\nBahan: Jalur ayat, kad lalu dan untuk.","aids_and_pak21_original":"BBM/ABM: Jalur ayat, kad lalu dan untuk.\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},{"phase_original":"Langkah 5\nCuba sendiri dan semak","execution_original":"Tindakan guru: Guru minta murid menulis dua ayat majmuk yang dilatih.\nGuru semak gabungan ayat dalam buku latihan.\nTindakan murid: Murid tulis dua ayat dengan bantuan kad jika perlu.\nMurid baca semula ayat yang dibetulkan bersama guru.\nSemakan: Guru semak maksud tentang mengurus dan menjual kerbau dikekalkan.\nBahan: Buku latihan, BT58 dan kad kata hubung.","aids_and_pak21_original":"BBM/ABM: Buku latihan, BT58 dan kad kata hubung.\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tunjuk kad lalu dan untuk.\nGuru rumuskan contoh ayat majmuk hari ini.\nTindakan murid: Murid sebut dua kata hubung.\nMurid baca satu ayat pilihan bersama-sama.\nSemakan: Guru kenal pasti kata hubung yang masih memerlukan latihan.\nBahan: Kad lalu dan untuk.","aids_and_pak21_original":"BBM/ABM: Kad lalu dan untuk.\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Susun ayat bersama","implementation_original":"Tugasan: Menggabungkan dua pasangan ayat dengan jalur ayat dan model guru.\nBahan: BT58\nJalur ayat mengumpulkan kerbau dan berjumpa peraih\nKad lalu dan untuk\nBimbingan guru: Guru susun ayat lalu bersama pasangan.\nGuru beri rangka “Bapa Hasan berjumpa peraih untuk …”.\nLangkah murid: Baca jalur ayat bersama guru.\nLetakkan kad kata hubung yang sesuai.\nTulis dua ayat dengan bantuan pasangan dan guru.\nHasil individu: Dua ayat majmuk setiap murid.\nKriteria: Gabungan ayat sesuai dengan kegiatan dalam buku.\nSusulan: Ulang satu pasangan ayat dahulu jika murid masih tertukar kata hubung.","aids_and_pak21_original":"BBM/ABM: BT58\nJalur ayat mengumpulkan kerbau dan berjumpa peraih\nKad lalu dan untuk\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},"pembina":{"label":"Langkah 1\nPembina — Pilih kata hubung","implementation_original":"Tugasan: Membina dua ayat majmuk menggunakan bank kata lalu dan untuk.\nBahan: BT58\nBank kata lalu dan untuk\nBuku latihan\nBimbingan guru: Guru minta pasangan membaca maksud dua ayat sebelum menyambungnya.\nGuru bantu murid mengekalkan kedua-dua perbuatan dalam ayat gabungan.\nLangkah murid: Bincang kata hubung bersama pasangan.\nSebut dua ayat majmuk secara bergilir.\nTulis ayat sendiri dengan bank kata jika perlu.\nHasil individu: Dua ayat majmuk tentang bapa Hasan.\nKriteria: Kata hubung sesuai dan maksud asal kekal.\nSusulan: Baiki satu gabungan yang belum lancar dengan jalur ayat guru.","aids_and_pak21_original":"BBM/ABM: BT58\nBank kata lalu dan untuk\nBuku latihan\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."},"pencabar":{"label":"Langkah 1\nPencabar — Satu gabungan lagi","implementation_original":"Tugasan: Mencuba satu ayat majmuk tambahan dengan kerana jika bersedia.\nBahan: BT58\nPasangan ayat bapa Hasan ke bank\nKad kerana\nBimbingan guru: Guru baca dua ayat tentang bapa Hasan hendak menyimpan wang.\nGuru beri awal ayat “Bapa Hasan ke bank kerana …”.\nLangkah murid: Selesaikan dua ayat utama.\nSambung rangka ayat bersama pasangan.\nTulis satu ayat tambahan tentang menyimpan wang.\nHasil individu: Dua ayat utama dan satu ayat menggunakan kerana.\nKriteria: Ayat tambahan menyatakan sebab ke bank dengan sesuai.\nSusulan: Baca ayat itu semula dengan kata hubung yang jelas.","aids_and_pak21_original":"BBM/ABM: BT58\nPasangan ayat bapa Hasan ke bank\nKad kerana\nPAK-21: Gabung berpasangan: murid menyambung pasangan ayat dengan kad kata hubung."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan dua ayat majmuk individu.","Evidens":"Ayat bapa Hasan mengumpulkan kerbau lalu menariknya dan berjumpa peraih untuk menjual kerbau.","Kriteria Kejayaan":"Dua ayat menggunakan kata hubung yang sesuai tanpa mengubah maksud asal."},"closure_original":"Tindakan guru: Guru tunjuk kad lalu dan untuk.\nGuru rumuskan contoh ayat majmuk hari ini.\nTindakan murid: Murid sebut dua kata hubung.\nMurid baca satu ayat pilihan bersama-sama.\nSemakan: Guru kenal pasti kata hubung yang masih memerlukan latihan.\nBahan: Kad lalu dan untuk.","reflection_original":"__ daripada __ murid dapat membina ayat majmuk tentang menternak kerbau. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M34-S1.docx","source_docx_sha256":"6886deef6c7d1e3f6e9c5b0c619494b6200c7633546e80f56f07ed1a0d7daa14","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M34-S2","week_no":34,"session_no":2,"lesson_map":{"title":"Tapak Semaian Pak Long","sp":"5.1.2","page":59,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":34,"session":2,"revision":"r1","title_original":"Tapak Semaian Pak Long","sk_original":"5.1 Memahami fungsi dan menggunakan golongan kata mengikut konteks","sp_original":"5.1.2 (i)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid menggunakan kata kerja aktif transitif dalam sekurang-kurangnya empat daripada lima ayat individu tentang tapak semaian dengan objek yang dinyatakan jelas serta sesuai makna.","success_criteria_original":"Empat ayat mempunyai pelaku, kata kerja sasaran dan objek sesuai.; Objek menjawab apa yang dikenai tindakan; keterangan tempat tidak menggantikannya.; Bantuan bahan dan rangka ayat dicatat berasingan daripada ketepatan.","textbook_pages_original":"m/s 59","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca contoh Hasan memasukkan tanah ke dalam beg plastik dan tunjuk kad tanah.\nTanya 'Memasukkan apa?' kemudian 'Ke mana?' untuk membezakan objek dengan keterangan.\nTindakan murid: Sebut tanah sebagai benda yang dimasukkan.\nSebut beg plastik sebagai arah/tempat dan tunjuk bahawa kedua-duanya mempunyai fungsi berbeza.\nSemakan: Jika murid memilih beg plastik sebagai objek langsung, guru kembali kepada soalan memasukkan apa.\nBahan: Contoh bercetak BT59 dan kad tanah/beg plastik.","BBM/ABM":"Contoh bercetak BT59 dan kad tanah/beg plastik.","PAK-21":"Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: tindakan mesti mengenai sesuatu","execution_original":"Tindakan guru: Baca contoh Hasan memasukkan tanah ke dalam beg plastik dan tunjuk kad tanah.\nTanya 'Memasukkan apa?' kemudian 'Ke mana?' untuk membezakan objek dengan keterangan.\nTindakan murid: Sebut tanah sebagai benda yang dimasukkan.\nSebut beg plastik sebagai arah/tempat dan tunjuk bahawa kedua-duanya mempunyai fungsi berbeza.\nSemakan: Jika murid memilih beg plastik sebagai objek langsung, guru kembali kepada soalan memasukkan apa.\nBahan: Contoh bercetak BT59 dan kad tanah/beg plastik.","aids_and_pak21_original":"BBM/ABM: Contoh bercetak BT59 dan kad tanah/beg plastik.\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},{"phase_original":"Langkah 2\nPemodelan kata kerja dan objek","execution_original":"Tindakan guru: Letakkan Hasan/memasukkan/tanah/ke dalam beg plastik dalam empat ruang; lingkungi kata kerja dan gariskan objek.\nTunjuk gambar3 dan modelkan contoh guru Lelaki itu menyusun beg semaian; bandingkan dengan Hasan menyusun di meja yang tidak menyatakan objek.\nTindakan murid: Tunjuk pasangan memasukkan tanah dan menyusun bekas semaian.\nBaiki ayat yang hanya mempunyai tempat dengan menamakan benda dalam demonstrasi.\nSemakan: Guru menegaskan imbuhan sahaja tidak cukup; kata kerja transitif dalam ayat perlu disertai objek yang munasabah.\nBahan: Jalur empat ruang, bekas kosong dan dua kad ayat.","aids_and_pak21_original":"BBM/ABM: Jalur empat ruang, bekas kosong dan dua kad ayat.\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},{"phase_original":"Langkah 3\nLima gambar semaian: cari objek yang tepat","execution_original":"Tindakan guru: Tunjuk gambar2–6 dan minta murid memadankan kata menyemai, menyusun, mengasingkan, memilih dan menjual dengan objek pada gambar.\nContoh guru: menyemai benih, menyusun beg semaian, mengasingkan baja bunga daripada baja pokok, memilih pokok berpasu, menjual pokok berpasu. Nama setiap figura tidak dilabel; gunakan pelaku umum jika perlu.\nTindakan murid: Pilih kata kerja dan tunjuk objek pada gambar sebelum membina ayat.\nPasangan menyoal objek dan keterangan, kemudian bertukar peranan untuk gambar lain.\nSemakan: Mengasingkan pada gambar4 ialah dua jenis baja yang berlabel, bukan anak pokok rosak/baik yang direka. Biji benih pada gambar2 tidak jelas spesiesnya.\nBahan: BT59 gambar2–6 dan kad kata kerja/objek.","aids_and_pak21_original":"BBM/ABM: BT59 gambar2–6 dan kad kata kerja/objek.\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},{"phase_original":"Langkah 4\nLatihan terbeza: bengkel ayat berobjek","execution_original":"Tindakan guru: Jalankan tiga laluan serentak menggunakan lima kata kerja selepas contoh memasukkan; bantuan dipilih daripada bukti latihan tadi.\nDampingi Peneroka menamakan objek, kemudian semak padanan Pembina dan alasan pembaikan Pencabar.\nTindakan murid: Bina ayat mengikut langkah laluan dan tandakan kata kerja serta objek pada hasil sendiri.\nSemak satu ayat rakan dengan soalan apa; pemilik membaiki objek hilang atau tidak sesuai.\nSemakan: Catat sama ada objek tiada, objek tidak munasabah atau keterangan disangka objek sebelum mengurangkan bantuan.\nBahan: Kad lima kata kerja, gambar2–6 BT59 dan lembaran laluan.","aids_and_pak21_original":"BBM/ABM: Kad lima kata kerja, gambar2–6 BT59 dan lembaran laluan.\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},{"phase_original":"Langkah 5\nPBD individu: lima kata kerja berobjek","execution_original":"Tindakan guru: Berikan lima kata kerja gambar2–6 dan minta satu ayat bagi setiap gambar dengan pelaku serta objek.\nTerima pelaku umum seperti wanita itu, penjual itu atau budak lelaki itu apabila nama tiada label. Contoh objek mesti sepadan gambar, bukan jawapan rambang tapak semaian.\nTindakan murid: Tulis lima ayat dengan pelaku dan objek yang jelas.\nLingkungi kata kerja, gariskan objek dan serahkan lembaran tanpa pembetulan pasangan.\nSemakan: Empat ayat lengkap kata kerja-objek memenuhi sasaran; jawapan satu perkataan tidak membuktikan penggunaan dalam ayat.\nBahan: Kad lima kata kerja dan lembaran pentaksiran.","aids_and_pak21_original":"BBM/ABM: Kad lima kata kerja dan lembaran pentaksiran.\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},{"phase_original":"Langkah 6\nPenutup: objek atau keterangan?","execution_original":"Tindakan guru: Paparkan 'Pak Long menjual di tapak semaian' dan minta satu pembaikan.\nRumuskan semakan pelaku, tindakan dan objek sebelum keterangan tambahan.\nTindakan murid: Tambahkan objek sesuai dan jelaskan benda yang dijual.\nNyatakan satu pasangan kata kerja-objek yang dapat digunakan semula.\nSemakan: Guru memilih intervensi objek hilang atau padanan makna berdasarkan lima ayat individu.\nBahan: Ayat rosak adaptasi dan hasil individu.","aids_and_pak21_original":"BBM/ABM: Ayat rosak adaptasi dan hasil individu.\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — padanan tindakan dengan benda","implementation_original":"Tugasan: Bina lima ayat menggunakan bingkai pelaku–kata kerja–objek dengan gambar2–6 yang boleh ditunjuk semasa menyebut.\nBahan: Kad pelaku Hasan/lelaki/wanita/penjual\nLima kata kerja dan objek gambar: benih, beg semaian, baja bunga/pokok, pokok berpasu\nBimbingan guru: Modelkan pertanyaan menyemai apa sambil menunjuk biji benih.\nTutup kad objek selepas murid menamakannya supaya ayat berikutnya tidak bergantung sepenuhnya pada padanan.\nLangkah murid: Pilih pelaku dan satu tindakan daripada kad buku.\nTunjuk benda dalam gambar yang menerima tindakan, khususnya bungkusan baja bunga dan baja pokok.\nSebut ayat lengkap kepada guru lalu uji dengan soalan apa.\nTulis lima ayat dan gariskan objek masing-masing.\nHasil individu: Lima ayat berbingkai dengan objek ditandakan.\nKriteria: Empat ayat berobjek tepat menjadi sasaran; bantuan kad direkod secara jelas.\nSusulan: Jika tempat menggantikan objek, asingkan kad benda daripada kad lokasi sebelum mencuba semula.","aids_and_pak21_original":"BBM/ABM: Kad pelaku Hasan/lelaki/wanita/penjual\nLima kata kerja dan objek gambar: benih, beg semaian, baja bunga/pokok, pokok berpasu\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},"pembina":{"label":"Langkah 1\nPembina — bina daripada gambar","implementation_original":"Tugasan: Gunakan lima kata kerja untuk menerangkan gambar2–6 dengan ayat sendiri tanpa bank padanan objek yang siap.\nBahan: Kad menyemai, menyusun, mengasingkan, memilih, menjual\nGambar2–6 BT59 dan lembaran kosong\nBimbingan guru: Tanya sama ada pembaca dapat mengetahui benda yang dikenai tindakan.\nMinta rakan membezakan objek daripada keterangan apabila ayat mengandungi tempat.\nLangkah murid: Perhatikan setiap gambar dan pilih objek yang benar-benar sesuai tindakan, bukan sekadar benda yang biasa di tapak semaian.\nTulis ayat dengan nama pelaku yang jelas.\nTambahkan keterangan hanya selepas objek sudah lengkap.\nTukar hasil, uji dengan soalan apa dan baiki ayat sendiri.\nHasil individu: Lima ayat kendiri dengan kata kerja dan objek ditanda.\nKriteria: Sekurang-kurangnya empat ayat tepat struktur serta padanan makna dalam konteks semaian.\nSusulan: Jika mantap, jelaskan mengapa frasa tempat tidak dapat menggantikan objek pada satu ayat pilihan.","aids_and_pak21_original":"BBM/ABM: Kad menyemai, menyusun, mengasingkan, memilih, menjual\nGambar2–6 BT59 dan lembaran kosong\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."},"pencabar":{"label":"Langkah 1\nPencabar — baiki struktur dan padanan","implementation_original":"Tugasan: Nilai ayat yang kehilangan objek atau mempunyai objek tidak sesuai, kemudian hasilkan lima ayat semaian dengan alasan pembaikan.\nBahan: Kad 'Hasan menyusun di tapak semaian' dan 'Hasan menyemai bekas plastik'\nLima kata kerja sumber dan kad objek yang dipadankan dengan gambar2–6\nBimbingan guru: Tanya sama ada kesalahan berpunca daripada ruang objek kosong atau pemilihan benda.\nMinta murid membuktikan pembaikan melalui soalan apa dan makna tindakan.\nLangkah murid: Tandakan kata kerja dan calon objek pada kad rosak.\nBezakan objek tiada dengan objek yang tidak munasabah.\nTulis pembetulan dan lengkapkan lima ayat menggunakan kata kerja sasaran.\nJelaskan dua pembaikan struktur kepada pasangan kemudian semak lima objek jawapan dengan gambar asal.\nHasil individu: Lima ayat serta dua alasan pembaikan struktur atau makna.\nKriteria: Empat ayat berobjek tepat dan sepadan gambar; murid menjelaskan sama ada pembetulan melibatkan objek hilang atau padanan makna yang salah.\nSusulan: Bina satu contoh berobjek serta berketerangan untuk menguji kefahaman rakan.","aids_and_pak21_original":"BBM/ABM: Kad 'Hasan menyusun di tapak semaian' dan 'Hasan menyemai bekas plastik'\nLima kata kerja sumber dan kad objek yang dipadankan dengan gambar2–6\nPAK-21: Pemerhati–Penyemak objek: seorang membina ayat daripada gambar, rakan bertanya melakukan apa kepada apa; bertukar peranan selepas satu gambar. Bahan tambahan ialah sokongan, bukan pengganti gambar buku."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan bertulis lima ayat individu menggunakan kata kerja sasaran.","Evidens":"Lima ayat dengan tanda kata kerja dan objek; demonstrasi kumpulan bukan bukti semua ahli.","Kriteria Kejayaan":"Empat daripada lima ayat mempunyai pelaku, kata kerja dan objek yang sesuai."},"closure_original":"Tindakan guru: Paparkan 'Pak Long menjual di tapak semaian' dan minta satu pembaikan.\nRumuskan semakan pelaku, tindakan dan objek sebelum keterangan tambahan.\nTindakan murid: Tambahkan objek sesuai dan jelaskan benda yang dijual.\nNyatakan satu pasangan kata kerja-objek yang dapat digunakan semula.\nSemakan: Guru memilih intervensi objek hilang atau padanan makna berdasarkan lima ayat individu.\nBahan: Ayat rosak adaptasi dan hasil individu.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M34-S2.docx","source_docx_sha256":"2f3d5c1cc927456645d5010bab9e6b4b2a8d49fbb5a230d9a530209b5386877e","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":34,"session":2,"revision":"r2","title_original":"Tapak Semaian Pak Long","sk_original":"5.1 Memahami fungsi dan menggunakan golongan kata mengikut konteks","sp_original":"5.1.2 (i)","sp_support_original":"—","objective_original":"Murid dapat membina ayat mudah menggunakan kata kerja aktif transitif.","success_criteria_original":"Membina dua ayat berdasarkan gambar.; Menyatakan benda yang menerima perbuatan dalam ayat.","textbook_pages_original":"m/s 59","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk gambar Hasan membantu Pak Long.\nGuru tanya, “Apakah yang Hasan masukkan ke dalam beg plastik?”\nTindakan murid: Murid melihat gambar pertama.\nMurid menyebut tanah.\nSemakan: Bantu murid menamakan benda dalam gambar.\nBahan: Buku teks halaman 59","BBM/ABM":"Buku teks halaman 59","PAK-21":"Bina ayat berpasangan menggunakan kad perkataan."},"six_phases_original":[{"phase_original":"Langkah 1\nLihat tapak semaian","execution_original":"Tindakan guru: Guru tunjuk gambar Hasan membantu Pak Long.\nGuru tanya, “Apakah yang Hasan masukkan ke dalam beg plastik?”\nTindakan murid: Murid melihat gambar pertama.\nMurid menyebut tanah.\nSemakan: Bantu murid menamakan benda dalam gambar.\nBahan: Buku teks halaman 59","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 59\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."},{"phase_original":"Langkah 2\nDengar ayat contoh","execution_original":"Tindakan guru: Guru baca “Hasan memasukkan tanah ke dalam beg plastik.”\nGuru tunjuk memasukkan sebagai perbuatan dan tanah sebagai bendanya.\nTindakan murid: Murid mengulang ayat.\nMurid menyebut perbuatan dan benda yang dimasukkan.\nSemakan: Gunakan soalan mudah “Masukkan apa?”\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."},{"phase_original":"Langkah 3\nBina bersama","execution_original":"Tindakan guru: Guru tunjuk gambar beg semaian dan bungkusan baja.\nGuru beri contoh “Lelaki itu menyusun beg semaian.”\nTindakan murid: Murid mengulang ayat contoh.\nMurid melengkapkan “Lelaki itu mengasingkan baja bunga daripada baja pokok.”\nSemakan: Baca label baja bunga dan baja pokok bersama murid.\nBahan: Buku teks\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad perkataan\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri kad menyusun dan mengasingkan.\nGuru bantu pasangan memilih benda yang sesuai.\nTindakan murid: Murid menyusun kad menjadi ayat.\nMurid bergilir-gilir menyebut ayat lengkap.\nSemakan: Tanya “Susun apa?” jika ayat belum lengkap.\nBahan: Kad ayat","aids_and_pak21_original":"BBM/ABM: Kad ayat\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."},{"phase_original":"Langkah 5\nTulis sendiri","execution_original":"Tindakan guru: Guru minta murid menulis dua ayat yang telah dilatih.\nGuru semak kata kerja dan benda dalam ayat.\nTindakan murid: Murid menulis ayat tentang beg semaian dan baja.\nMurid membetulkan ayat dengan bantuan guru.\nSemakan: Kad dan buku boleh dirujuk.\nBahan: Buku latihan\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Buku latihan\nKad perkataan\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tunjuk gambar memilih dan menjual pokok berpasu.\nGuru beri contoh “Wanita itu memilih pokok berpasu.”\nTindakan murid: Murid mengulang contoh ayat.\nMurid menyebut satu kata kerja yang dipelajari.\nSemakan: Kukuhkan ayat yang menyatakan perbuatan dan bendanya.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Melengkapkan ayat dengan pilihan benda.\nBahan: Lelaki itu menyusun ___.\nKad beg semaian dan baja\nBimbingan guru: Guru tunjuk gambar yang sepadan.\nGuru baca ayat sambil menunjuk kad.\nLangkah murid: Pilih kad benda.\nLengkapkan ayat bersama guru.\nBaca dan tulis ayat lengkap.\nHasil individu: Ayat lengkap dengan bantuan.\nKriteria: Ayat menyebut perbuatan dan benda yang sesuai.\nSusulan: Ulang soalan “Susun apa?” menggunakan gambar.","aids_and_pak21_original":"BBM/ABM: Lelaki itu menyusun ___.\nKad beg semaian dan baja\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Membina ayat menggunakan menyusun dan mengasingkan.\nBahan: Gambar buku\nKad kata kerja dan benda\nBimbingan guru: Guru beri contoh ayat menyusun.\nGuru bantu membaca label pada bungkusan baja.\nLangkah murid: Pilih kata berdasarkan gambar.\nCuba dua ayat dengan rakan.\nTulis sendiri dua ayat.\nHasil individu: Dua ayat dalam buku latihan.\nKriteria: Ayat sesuai dengan gambar.\nSusulan: Tambah benda yang tertinggal dalam ayat.","aids_and_pak21_original":"BBM/ABM: Gambar buku\nKad kata kerja dan benda\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Membina satu ayat menggunakan memilih atau menjual.\nBahan: Gambar pokok berpasu\nBimbingan guru: Guru tunjuk gambar kelima atau keenam.\nGuru tanya “Memilih apa?” atau “Menjual apa?”\nLangkah murid: Pilih satu gambar.\nSebut ayat lengkap.\nTulis ayat jika sudah bersedia.\nHasil individu: Satu ayat tambahan.\nKriteria: Kata kerja digunakan dengan benda yang sesuai.\nSusulan: Kongsi ayat kepada rakan tanpa menambah tugasan panjang.","aids_and_pak21_original":"BBM/ABM: Gambar pokok berpasu\nPAK-21: Bina ayat berpasangan menggunakan kad perkataan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan ayat dalam buku latihan.","Evidens":"Dua ayat setiap murid.","Kriteria Kejayaan":"Dua ayat menggunakan kata kerja dan benda yang sesuai."},"closure_original":"Tindakan guru: Guru tunjuk gambar memilih dan menjual pokok berpasu.\nGuru beri contoh “Wanita itu memilih pokok berpasu.”\nTindakan murid: Murid mengulang contoh ayat.\nMurid menyebut satu kata kerja yang dipelajari.\nSemakan: Kukuhkan ayat yang menyatakan perbuatan dan bendanya.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat membina ayat menggunakan kata kerja aktif transitif. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M34-S2.docx","source_docx_sha256":"bf5a4037414b23c76d88d2286653ed4bec493ffbe8d68494e61e5f1d54f52136","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M34-S3","week_no":34,"session_no":3,"lesson_map":{"title":"Kolam Ikan Sepat","sp":"5.3.2","page":60,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":34,"session":3,"revision":"r1","title_original":"Kolam Ikan Sepat","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (ii) (iii)","sp_support_original":"—","objective_original":"Pada akhir pembelajaran, murid dapat membina empat ayat bagi gambar3–6 Kolam Ikan Sepat dengan sekurang-kurangnya tiga ayat tepat dan meliputi sekurang-kurangnya satu ayat tunggal serta satu ayat majmuk yang disokong hubungan maklumat.","success_criteria_original":"Tiga daripada empat ayat tepat, meliputi kedua-dua binaan.; Ayat tunggal mengandungi satu klausa; ayat majmuk menunjukkan penggabungan klausa yang bermakna.; Kehadiran dan sahaja bukan bukti mencukupi; bantuan dan penjelasan murid direkod.","textbook_pages_original":"m/s 60","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca 'Kok Bun melepaskan ikan sepat ke dalam kolam' daripada buku.\nTanya siapa dan apakah maklumat tentangnya; tandakan sempadan subjek-predikat.\nTindakan murid: Nyatakan Kok Bun sebagai subjek dan tindakan lengkap sebagai predikat.\nTerangkan bahawa ke dalam kolam ialah keterangan dalam ayat, bukan tindakan kedua.\nSemakan: Jika murid memisahkan keterangan sebagai ayat baharu, guru minta subjek serta predikat yang dapat berdiri sendiri.\nBahan: Ayat pertama BT60 dan pen warna.","BBM/ABM":"Ayat pertama BT60 dan pen warna.","PAK-21":"Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: satu perbuatan di kolam","execution_original":"Tindakan guru: Baca 'Kok Bun melepaskan ikan sepat ke dalam kolam' daripada buku.\nTanya siapa dan apakah maklumat tentangnya; tandakan sempadan subjek-predikat.\nTindakan murid: Nyatakan Kok Bun sebagai subjek dan tindakan lengkap sebagai predikat.\nTerangkan bahawa ke dalam kolam ialah keterangan dalam ayat, bukan tindakan kedua.\nSemakan: Jika murid memisahkan keterangan sebagai ayat baharu, guru minta subjek serta predikat yang dapat berdiri sendiri.\nBahan: Ayat pertama BT60 dan pen warna.","aids_and_pak21_original":"BBM/ABM: Ayat pertama BT60 dan pen warna.\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},{"phase_original":"Langkah 2\nPemodelan: binaan, bukan kata penanda sahaja","execution_original":"Tindakan guru: Baca ayat kedua tentang Kok Bun dan ayahnya menabur makanan; tanya unsur yang dihubungkan oleh dan tanpa memaksa label daripada satu perkataan.\nModel adaptasi jelas: 'Kok Bun melepaskan ikan sepat dan ayahnya menabur makanan ikan'; tunjuk dua klausa dengan pelaku serta tindakan berbeza.\nTindakan murid: Lingkungi dua nama dalam ayat sumber dan jelaskan tindakan yang dikongsi.\nPisahkan model guru kepada dua ayat asal untuk membuktikan penggabungan klausa.\nSemakan: Jangan ajar semua ayat berdan automatik majmuk; ayat sumber dengan gabungan nama digunakan untuk perbincangan, bukan item skor binaan yang kabur.\nBahan: Dua ayat buku dan model gabungan guru.","aids_and_pak21_original":"BBM/ABM: Dua ayat buku dan model gabungan guru.\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},{"phase_original":"Langkah 3\nEmpat gambar sambungan: tindakan dan tujuan","execution_original":"Tindakan guru: Tunjuk gambar3–6. Model contoh guru “Kok Bun memotong rumput di tepi kolam” dan “Kok Bun menangguk ikan lalu memasukkannya ke dalam bekas.” Bezakan ayat lengkap tunggal dengan dua tindakan berturutan.\nBagi gambar5, terima huraian yang jelas tentang kotak/troli tanpa memastikan transaksi jualan. Bagi gambar6, rujuk pemberian wang serta bank untuk contoh “Kok Bun memberikan wang kepada wanita itu untuk disimpan di bank.”\nTindakan murid: Tunjuk objek atau tindakan gambar yang menyokong satu ayat sebelum memilih penghubung.\nBaca contoh, nyatakan satu atau dua maklumat yang dihubungkan, kemudian cuba membina ayat sendiri bagi gambar seterusnya.\nSemakan: Murid tidak menambah membakar atau menggoreng ikan kerana tiada gambar demikian. Nama wanita dan transaksi jualan yang tidak dilabel tidak dijadikan jawapan wajib.\nBahan: BT60 gambar3–6, kad lalu/untuk dan jalur contoh guru.","aids_and_pak21_original":"BBM/ABM: BT60 gambar3–6, kad lalu/untuk dan jalur contoh guru.\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},{"phase_original":"Langkah 4\nLatihan terbeza: bengkel dua binaan","execution_original":"Tindakan guru: Jalankan tiga laluan pada gambar3–6, dengan sekurang-kurangnya satu ayat tunggal dan satu majmuk dalam empat jawapan.\nSemak Peneroka melalui jalur pelaku/tindakan, Pembina melalui ayat sendiri dan Pencabar melalui alasan penghubung serta batas butiran gambar.\nTindakan murid: Laksanakan langkah laluan dan tandakan binaan pada ayat sendiri.\nMinta rakan menunjukkan klausa atau maklumat asal, kemudian baiki struktur tanpa menukar konteks kolam.\nSemakan: Guru mengesan gabungan frasa yang dilabel majmuk tanpa alasan serta ayat tunggal yang tercantum dua tindakan.\nBahan: Jalur dan lembaran tiga laluan.","aids_and_pak21_original":"BBM/ABM: Jalur dan lembaran tiga laluan.\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},{"phase_original":"Langkah 5\nPBD individu: empat ayat gambar3–6","execution_original":"Tindakan guru: Berikan empat ruang jawapan3–6 dengan gambar asal; murid membina ayat tanpa model penuh atau jawapan pasangan.\nSemak tindakan memotong rumput, menangguk lalu meletakkan ikan, huraian kotak/troli yang munasabah, dan tujuan menyimpan wang. Gambar5 boleh menerima ayat berhati-hati tentang kotak, bukan wajib menyatakan menjual.\nTindakan murid: Tulis empat ayat mengikut gambar3–6 dan nomborkan jawapan.\nTunjuk ayat tunggal dan ayat majmuk, kemudian jelaskan dua maklumat bagi gabungan yang dipilih.\nSemakan: Tiga daripada empat ayat tepat memenuhi sasaran jika kedua-dua bentuk turut diwakili. Jangan menghukum variasi pelaku umum apabila nama pada gambar tidak dilabel.\nBahan: BT60 gambar3–6 dan lembaran individu.","aids_and_pak21_original":"BBM/ABM: BT60 gambar3–6 dan lembaran individu.\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},{"phase_original":"Langkah 6\nPenutup: buktikan dengan ayat asal","execution_original":"Tindakan guru: Tanya bagaimana membuktikan bahawa model gabungan ialah ayat majmuk.\nRumuskan bahawa sesi ini meneliti binaan ayat kolam; urutan enam kata gambar akan menjadi tugas berbeza dalam pengayaan BT62.\nTindakan murid: Sebut dua ayat asal bagi satu model majmuk.\nNyatakan satu semakan selain mencari perkataan dan.\nSemakan: Gunakan alasan struktur untuk merancang susulan, bukan hafalan istilah sahaja.\nBahan: Model gabungan dan hasil individu.","aids_and_pak21_original":"BBM/ABM: Model gabungan dan hasil individu.\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — satu atau dua maklumat klausa","implementation_original":"Tugasan: Bina empat ayat gambar3–6 dengan jalur pelaku dan tindakan; gabungkan sekurang-kurangnya satu pasangan tindakan yang sesuai menggunakan lalu atau untuk.\nBahan: Jalur memotong rumput, menangguk ikan, memasukkan ke dalam bekas, kotak/troli dan wang/bank\nGambar3–6 BT60 serta kad lalu/untuk\nBimbingan guru: Modelkan satu pasangan subjek-predikat sebelum menambah klausa kedua.\nTutup warna bantuan apabila murid dapat menunjukkan dua ayat asal secara lisan.\nLangkah murid: Tunjuk pelaku dan tindakan pada setiap gambar3–6.\nPasang satu ayat tunggal yang lengkap sebelum mencantum dua tindakan.\nGunakan lalu pada menangguk/memasukkan atau untuk pada tujuan menyimpan wang dan baca semula makna.\nTulis empat ayat bernombor, tunjuk kedua-dua bentuk serta cuba satu tanpa kad jawapan.\nHasil individu: Empat ayat gambar3–6 dengan sekurang-kurangnya satu tunggal dan satu majmuk, bantuan ditandai.\nKriteria: Tiga ayat tepat termasuk satu setiap binaan menjadi sasaran; jalur bantuan dicatat.\nSusulan: Jika masih menghitung perkataan, kembali kepada soalan siapa dan melakukan apa sebelum mencantum.","aids_and_pak21_original":"BBM/ABM: Jalur memotong rumput, menangguk ikan, memasukkan ke dalam bekas, kotak/troli dan wang/bank\nGambar3–6 BT60 serta kad lalu/untuk\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},"pembina":{"label":"Langkah 1\nPembina — bina dan buktikan","implementation_original":"Tugasan: Bina empat ayat gambar3–6 daripada pemerhatian sendiri dan uji hubungan maklumat bagi ayat majmuk.\nBahan: BT60 gambar3–6\nKad lalu/untuk dan lembaran empat ruang\nBimbingan guru: Minta murid menyebut hubungan dua klausa sebelum memilih penghubung.\nTanya dua ayat asal apabila binaan majmuk yang ditulis tidak jelas.\nLangkah murid: Pilih satu fakta yang jelas daripada setiap gambar.\nBina empat ayat dengan kedua-dua bentuk diwakili, tanpa memaksa semua menjadi panjang.\nTandakan maklumat yang dihubungkan dan baca kepada pasangan untuk diuji.\nBaiki pelaku atau penghubung yang kabur, khususnya kotak/troli dan tujuan bank.\nHasil individu: Empat ayat gambar3–6 dan bukti hubungan pada ayat majmuk.\nKriteria: Tiga ayat tepat meliputi kedua-dua binaan serta alasan penggabungan dapat diterangkan.\nSusulan: Jika mantap, ubah penghubung satu model dan jelaskan perubahan hubungan tanpa mereka gambar.","aids_and_pak21_original":"BBM/ABM: BT60 gambar3–6\nKad lalu/untuk dan lembaran empat ruang\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."},"pencabar":{"label":"Langkah 1\nPencabar — menilai bukti penggabungan","implementation_original":"Tugasan: Bina empat ayat gambar3–6 dan nilai sama ada dakwaan tentang jualan ikan atau identiti wanita disokong gambar sebelum memilih ungkapan yang tepat.\nBahan: Gambar3–6 BT60\nKad dakwaan guru “Kok Bun menjual ikan dengan harga RM50” untuk diuji, bukan fakta buku\nBimbingan guru: Tanya unsur yang dihubungkan dan kemungkinan ayat asal, bukan meminta label daripada penanda sahaja.\nMinta murid menghasilkan model tidak kabur untuk tujuan pentaksiran.\nLangkah murid: Bina empat ayat dengan kedua-dua binaan yang jelas.\nPisahkan satu ayat majmuk kepada dua maklumat asal untuk membuktikan hubungan.\nUji kad dakwaan harga dan jelaskan bahagian yang tidak disokong gambar.\nPerhalus ayat tentang kotak/troli atau wang/bank agar tidak menambah fakta yang tidak ditunjukkan.\nHasil individu: Empat ayat dan satu penilaian dakwaan berasaskan bukti gambar.\nKriteria: Tiga ayat tepat meliputi kedua-dua binaan dan bukti klausa munasabah.\nSusulan: Perhalus model supaya pelaku, tindakan dan hubungan tidak menimbulkan kekaburan semasa semakan.","aids_and_pak21_original":"BBM/ABM: Gambar3–6 BT60\nKad dakwaan guru “Kok Bun menjual ikan dengan harga RM50” untuk diuji, bukan fakta buku\nPAK-21: Jurutera ayat–Penguji klausa: pemilik membina ayat, rakan meminta ayat asal yang digabungkan; pemilik membuktikan binaan sebelum bertukar peranan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan empat ayat individu dan pertanyaan bukti klausa apabila diperlukan.","Evidens":"Empat jawapan gambar3–6, kedua-dua binaan diwakili dan alasan hubungan pada satu ayat majmuk.","Kriteria Kejayaan":"Tiga ayat tepat termasuk sekurang-kurangnya satu tunggal dan satu majmuk."},"closure_original":"Tindakan guru: Tanya bagaimana membuktikan bahawa model gabungan ialah ayat majmuk.\nRumuskan bahawa sesi ini meneliti binaan ayat kolam; urutan enam kata gambar akan menjadi tugas berbeza dalam pengayaan BT62.\nTindakan murid: Sebut dua ayat asal bagi satu model majmuk.\nNyatakan satu semakan selain mencari perkataan dan.\nSemakan: Gunakan alasan struktur untuk merancang susulan, bukan hafalan istilah sahaja.\nBahan: Model gabungan dan hasil individu.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M34-S3.docx","source_docx_sha256":"c750e71bf1cd0e207e5cb027e1f06c828a05c9f73ad37daa9ea7fbbc04d19f45","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":34,"session":3,"revision":"r2","title_original":"Kolam Ikan Sepat","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2 (ii) (iii)","sp_support_original":"—","objective_original":"Murid dapat membina ayat tunggal dan ayat majmuk berdasarkan gambar.","success_criteria_original":"Membina satu ayat tunggal tentang kegiatan di kolam.; Membina satu ayat majmuk dengan kata hubung lalu.","textbook_pages_original":"m/s 60","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk gambar kolam ikan.\nGuru tanya, “Apakah yang Kok Bun bela?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut ikan sepat.\nSemakan: Bantu sebutan ikan sepat.\nBahan: Buku teks halaman 60","BBM/ABM":"Buku teks halaman 60","PAK-21":"Susun ayat berpasangan berdasarkan gambar kolam ikan."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali kolam ikan","execution_original":"Tindakan guru: Guru tunjuk gambar kolam ikan.\nGuru tanya, “Apakah yang Kok Bun bela?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut ikan sepat.\nSemakan: Bantu sebutan ikan sepat.\nBahan: Buku teks halaman 60","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 60\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."},{"phase_original":"Langkah 2\nBaca contoh","execution_original":"Tindakan guru: Guru baca ayat pertama tentang melepaskan ikan ke dalam kolam.\nGuru tunjuk contoh ayat tunggal “Kok Bun memotong rumput di tepi kolam.”\nTindakan murid: Murid mengikuti bacaan.\nMurid menunjukkan gambar yang sesuai dengan ayat.\nSemakan: Terangkan ayat tunggal melalui contoh yang pendek.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."},{"phase_original":"Langkah 3\nGabung ayat bersama","execution_original":"Tindakan guru: Guru baca “Kok Bun menangguk ikan. Kok Bun memasukkan ikan ke dalam bekas.”\nGuru gabungkan: “Kok Bun menangguk ikan lalu memasukkannya ke dalam bekas.”\nTindakan murid: Murid mengulang kedua-dua perbuatan.\nMurid menyebut ayat gabungan bersama guru.\nSemakan: Jelaskan lalu bermaksud perbuatan yang dilakukan selepas itu.\nBahan: Kad perbuatan\nKad lalu","aids_and_pak21_original":"BBM/ABM: Kad perbuatan\nKad lalu\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."},{"phase_original":"Langkah 4\nLatihan pasangan","execution_original":"Tindakan guru: Guru beri kad perbuatan kepada pasangan.\nGuru bantu murid menyusun tindakan sebelum dan selepas.\nTindakan murid: Murid menyusun kad menangguk ikan dan memasukkan ikan ke dalam bekas.\nMurid menyebut satu ayat tunggal dan satu ayat majmuk kepada rakan.\nSemakan: Tunjuk gambar semula jika urutan tertukar.\nBahan: Buku teks\nKad ayat","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad ayat\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."},{"phase_original":"Langkah 5\nTulis sendiri","execution_original":"Tindakan guru: Guru minta murid menulis dua ayat yang dilatih.\nGuru semak ayat memotong rumput dan ayat menggunakan lalu.\nTindakan murid: Murid menulis satu ayat tunggal.\nMurid menulis satu ayat majmuk dengan bantuan kad jika perlu.\nSemakan: Semak kedua-dua jenis ayat tanpa meminta huraian istilah yang panjang.\nBahan: Buku latihan\nKad lalu","aids_and_pak21_original":"BBM/ABM: Buku latihan\nKad lalu\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru ajak kelas membaca ayat yang telah lengkap.\nGuru tanya perkataan yang digunakan untuk menyambung ayat.\nTindakan murid: Murid membaca ayat bersama-sama.\nMurid menyebut lalu.\nSemakan: Ulang contoh ayat gabungan jika perlu.\nBahan: Ayat di papan putih","aids_and_pak21_original":"BBM/ABM: Ayat di papan putih\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Melengkapkan dua rangka ayat dengan kad.\nBahan: Kok Bun memotong ___.\nKok Bun menangguk ikan lalu ___.\nKad rumput dan memasukkannya ke dalam bekas\nBimbingan guru: Guru baca rangka ayat.\nGuru tunjuk gambar bagi setiap tindakan.\nLangkah murid: Pilih kad.\nBaca ayat bersama guru.\nTulis ayat lengkap dengan bantuan.\nHasil individu: Dua ayat berpandu.\nKriteria: Ayat sesuai dengan gambar.\nSusulan: Ulang perbuatan pertama dan kedua secara lisan.","aids_and_pak21_original":"BBM/ABM: Kok Bun memotong ___.\nKok Bun menangguk ikan lalu ___.\nKad rumput dan memasukkannya ke dalam bekas\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Membina dua jenis ayat daripada gambar.\nBahan: Buku teks\nKad kata kerja dan lalu\nBimbingan guru: Guru beri contoh ayat tunggal.\nGuru bantu murid menggabungkan dua perbuatan.\nLangkah murid: Lihat gambar memotong rumput.\nSebut ayat tunggal dan ayat gabungan.\nTulis kedua-dua ayat sendiri.\nHasil individu: Satu ayat tunggal dan satu ayat majmuk.\nKriteria: Ayat lengkap dan kata lalu digunakan dengan sesuai.\nSusulan: Baca semula ayat untuk menyemak urutan.","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad kata kerja dan lalu\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Membina satu ayat gabungan menggunakan dan.\nBahan: Gambar awal kolam\nKad dan\nBimbingan guru: Guru beri contoh permulaan “Kok Bun melepaskan ikan...”\nGuru bantu menyambung dengan perbuatan ayah menabur makanan.\nLangkah murid: Pilih dua perbuatan.\nGabungkan menggunakan dan.\nSebut ayat kepada rakan.\nHasil individu: Satu ayat majmuk lisan.\nKriteria: Dua maklumat disambung dengan jelas.\nSusulan: Murid boleh menulis ayat jika mahu.","aids_and_pak21_original":"BBM/ABM: Gambar awal kolam\nKad dan\nPAK-21: Susun ayat berpasangan berdasarkan gambar kolam ikan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan hasil tulisan.","Evidens":"Dua ayat berdasarkan gambar.","Kriteria Kejayaan":"Satu ayat tunggal dan satu ayat majmuk sesuai dengan gambar."},"closure_original":"Tindakan guru: Guru ajak kelas membaca ayat yang telah lengkap.\nGuru tanya perkataan yang digunakan untuk menyambung ayat.\nTindakan murid: Murid membaca ayat bersama-sama.\nMurid menyebut lalu.\nSemakan: Ulang contoh ayat gabungan jika perlu.\nBahan: Ayat di papan putih","reflection_original":"__ daripada __ murid dapat membina ayat tunggal dan ayat majmuk berdasarkan gambar. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M34-S3.docx","source_docx_sha256":"458f02613d542d63e69f470fd20c462d5b72d6f96025c0ef39d51043df3262ff","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M34-S4","week_no":34,"session_no":4,"lesson_map":{"title":"Pengayaan","sp":"5.3.2","page":62,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":34,"session":4,"revision":"r1","title_original":"Pengayaan","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2(ii)(iii)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat membina enam ayat mengikut urutan enam gambar Pengayaan tentang itik Pak Abu, dengan sekurang-kurangnya dua ayat tunggal dan dua ayat majmuk yang sesuai konteks.","success_criteria_original":"Keenam-enam kata panduan membela, menyudu, bertelur, berenang, mengutip dan menjual digunakan mengikut nombor gambar.; Sekurang-kurangnya dua ayat tunggal dan dua ayat majmuk dapat dikenal pasti serta dijelaskan; ayat bukan cebisan frasa.; Maklumat pelaku dan objek disemak pada gambar sebenar; cadangan penggunaan hasil jualan dibezakan daripada fakta gambar.","textbook_pages_original":"m/s 62","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk tajuk Pengayaan dan baca arahan membina ayat tunggal serta majmuk mengikut nombor gambar.\nCampurkan kad kata dan minta murid mencari nombor asal, bukan meneka urutan hanya berdasarkan kebiasaan ternakan.\nTindakan murid: Susun kata panduan mengikut gambar 1 hingga 6.\nSebut kata yang merujuk perbuatan itik dan yang perlu dilihat pelakunya dalam gambar sebelum membina ayat.\nSemakan: Buku ini meletakkan Pengayaan pada BT62 dalam M34S4. Jangan melabelnya sebagai M30S4 atau menambah sesi yang tidak wujud.\nBahan: BT62 dan enam kad bernombor.","BBM/ABM":"BT62 dan enam kad bernombor.","PAK-21":"Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Enam kata menjadi urutan","execution_original":"Tindakan guru: Tunjuk tajuk Pengayaan dan baca arahan membina ayat tunggal serta majmuk mengikut nombor gambar.\nCampurkan kad kata dan minta murid mencari nombor asal, bukan meneka urutan hanya berdasarkan kebiasaan ternakan.\nTindakan murid: Susun kata panduan mengikut gambar 1 hingga 6.\nSebut kata yang merujuk perbuatan itik dan yang perlu dilihat pelakunya dalam gambar sebelum membina ayat.\nSemakan: Buku ini meletakkan Pengayaan pada BT62 dalam M34S4. Jangan melabelnya sebagai M30S4 atau menambah sesi yang tidak wujud.\nBahan: BT62 dan enam kad bernombor.","aids_and_pak21_original":"BBM/ABM: BT62 dan enam kad bernombor.\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},{"phase_original":"Langkah 2\nModel — Satu ayat, kemudian hubungan maklumat","execution_original":"Tindakan guru: Baca pembukaan tentang Hasan dan ayahnya bersiar-siar serta frasa Pak Abu membela. Modelkan contoh ayat guru “Pak Abu membela itik.” berdasarkan konteks teks.\nBandingkan contoh tunggal itu dengan contoh adaptasi “Pak Abu membela itik supaya memperoleh hasil jualan telur.” Jelaskan tujuan ini cadangan munasabah daripada konteks hasil jualan, bukan petikan lengkap buku; pelengkap lain mesti disemak konteks.\nTindakan murid: Kenal pasti subjek serta predikat dalam ayat tunggal.\nTunjuk dua maklumat yang dihubungkan dalam ayat majmuk dan sebut fungsi supaya sebagai tujuan.\nSemakan: Tidak menganggap semua ayat yang mempunyai perkataan dan semestinya dua klausa; semak maksud dan binaan yang digabungkan.\nBahan: Jalur pembukaan, contoh guru dan kad penghubung.","aids_and_pak21_original":"BBM/ABM: Jalur pembukaan, contoh guru dan kad penghubung.\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},{"phase_original":"Langkah 3\nLatihan terbeza — Enam gambar, enam ayat","execution_original":"Tindakan guru: Jalankan tiga laluan di bawah untuk membina ayat mengikut nombor. Semua menghasilkan enam ayat, dengan bantuan pelaku–tindakan–objek yang berbeza.\nMinta murid membezakan pelaku: itik menyudu/bertelur/berenang, perempuan mengutip/menjual, Pak Abu membela mengikut konteks teks. Semak objek makanan dalam bekas, telur dan tempat sungai; jangan menukar nombor5–6 menjadi Pak Abu sendiri tanpa bukti.\nTindakan murid: Bergilir menerangkan satu gambar dan membina ayat; gunakan kata panduan pada nombor yang sepadan.\nPilih sekurang-kurangnya dua tempat untuk ayat majmuk dan dua untuk ayat tunggal, kemudian baca urutan kepada pasangan.\nSemakan: Enam frasa seperti “itik berenang” tanpa pertimbangan ayat lengkap serta hubungan belum mencukupi. Guru menyemak sambungan makna dan batas bukti gambar.\nBahan: BT62, enam ruang ayat, kad penghubung dan rangka laluan.","aids_and_pak21_original":"BBM/ABM: BT62, enam ruang ayat, kad penghubung dan rangka laluan.\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},{"phase_original":"Langkah 4\nPBD penulisan — Urutan individu","execution_original":"Tindakan guru: Minta murid menulis semula enam ayat pilihan sendiri selepas pembukaan, bukan menyalin senarai kumpulan.\nSemak bentuk tunggal/majmuk dengan menanyakan dua maklumat yang dihubungkan. Minta pembetulan jika kata ganti atau pelaku berubah tanpa penjelasan.\nTindakan murid: Tulis enam ayat mengikut nombor dan gariskan penghubung.\nLabelkan sekurang-kurangnya dua ayat tunggal dan dua majmuk; tunjuk kepada guru bahagian yang disambungkan.\nSemakan: Kualiti diperiksa melalui binaan dan konteks, bukan bilangan penghubung sahaja. Butiran gambar yang belum pasti tidak dipaksa menjadi jawapan tunggal.\nBahan: Lembaran individu dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Lembaran individu dan senarai semak.\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},{"phase_original":"Langkah 5\nCadangan hasil jualan — Fakta atau idea?","execution_original":"Tindakan guru: Baca soalan akhir buku tentang apa yang boleh dibuat Pak Abu dengan wang jualan telur. Nyatakan jawapan merupakan cadangan, bukan peristiwa tambahan yang mesti dimasukkan sebagai fakta.\nMinta satu ayat cadangan bersebab dan semak sama ada murid boleh membezakan tujuan dengan perbuatan gambar.\nTindakan murid: Cadangkan penggunaan wang secara munasabah, misalnya membeli keperluan penjagaan itik, dengan menyatakan “Saya mencadangkan …”.\nSemak enam ayat rakan dan perbaiki satu ayat yang belum jelas bentuk atau urutannya.\nSemakan: Cadangan tambahan tidak menggantikan enam ayat utama. Tiada pengiraan pendapatan atau harga rekaan diperlukan.\nBahan: Soalan akhir BT62 dan hasil enam ayat.","aids_and_pak21_original":"BBM/ABM: Soalan akhir BT62 dan hasil enam ayat.\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},{"phase_original":"Langkah 6\nPenutup — Bahasa menyusun usaha penternak","execution_original":"Tindakan guru: Pilih satu ayat tunggal serta satu majmuk daripada hasil untuk dibaca tanpa menamakan penulis.\nRumusan peranan urutan nombor, kata panduan dan penghubung dalam membina cerita yang dapat diikuti.\nTindakan murid: Sebut beza bentuk dua ayat serta kata panduan yang digunakan.\nSerahkan enam ayat dan nyatakan nombor gambar yang masih memerlukan bantuan semakan.\nSemakan: Refleksi berasaskan bukti enam ayat dan bantuan sebenar, bukan dianggap lengkap kerana semua kad telah disusun.\nBahan: Kad kata panduan dan hasil murid.","aids_and_pak21_original":"BBM/ABM: Kad kata panduan dan hasil murid.\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Rangka pelaku–tindakan–maklumat","implementation_original":"Tugasan: Membina enam ayat dengan kad bernombor dan rangka subjek/predikat, sambil cuba dua cantuman maklumat yang disemak bersama guru.\nBahan: Enam kata panduan bernombor\nRangka “Pak Abu …” atau “Itik itu …” dipilih selepas melihat gambar\nKad dan/lalu/supaya dengan contoh fungsi\nBimbingan guru: Tanya siapa melakukan tindakan pada gambar sebelum murid memilih subjek. Modelkan satu ayat sahaja dan minta murid membina ayat berikutnya.\nUntuk ayat majmuk, asingkan dua maklumat pada dua jalur dan cantum selepas murid dapat menyebut kedua-duanya.\nLangkah murid: Tunjuk gambar bernombor dan pilih pelaku yang sesuai.\nBina ayat lengkap menggunakan kata panduan.\nCantum dua maklumat pada dua ayat pilihan dengan penghubung yang munasabah.\nTulis enam ayat individu dan label dua tunggal serta dua majmuk dengan bantuan.\nHasil individu: Enam ayat mengikut urutan dengan bentuk sasaran dan bantuan ditandai.\nKriteria: Enam ayat lengkap serta liputan bentuk dipenuhi; jika hanya padanan kad selesai, objektif penulisan belum dicapai.\nSusulan: Ulang satu ayat yang kehilangan subjek atau maklumat kedua menggunakan jalur, kemudian tulis tanpa rangka.","aids_and_pak21_original":"BBM/ABM: Enam kata panduan bernombor\nRangka “Pak Abu …” atau “Itik itu …” dipilih selepas melihat gambar\nKad dan/lalu/supaya dengan contoh fungsi\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},"pembina":{"label":"Langkah 1\nPembina — Ayat daripada gambar dan kata panduan","implementation_original":"Tugasan: Menghasilkan enam ayat tanpa ayat jawapan penuh, kemudian menguji kelancaran cerita selepas pembukaan buku.\nBahan: BT62\nEnam ruang kosong bernombor\nKad semakan subjek–predikat–hubungan\nBimbingan guru: Minta bukti bagi pelaku dan objek yang dipilih serta semak makna kata menyudu.\nTanya dua maklumat dalam setiap ayat majmuk supaya penghubung tidak digunakan sekadar hiasan.\nLangkah murid: Teliti gambar mengikut nombor dan catat kata kunci pelaku/objek.\nBina enam ayat dengan sekurang-kurangnya dua tunggal dan dua majmuk.\nBaca sambungan selepas pembukaan kepada pasangan.\nBaiki ayat yang melompat urutan atau mengandungi rujukan kabur sebelum menyerah hasil.\nHasil individu: Enam ayat individu membentuk sambungan yang tersusun dan sepadan gambar.\nKriteria: Bentuk ayat tepat, kata panduan semua digunakan dan hubungan maklumat munasabah; tidak perlu sama dengan ayat model guru.\nSusulan: Jika kukuh, bandingkan penggunaan dan/lalu pada satu ayat; jika tidak, asingkan klausa sebelum mencantum semula.","aids_and_pak21_original":"BBM/ABM: BT62\nEnam ruang kosong bernombor\nKad semakan subjek–predikat–hubungan\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."},"pencabar":{"label":"Langkah 1\nPencabar — Menilai hubungan dan pilihan ayat","implementation_original":"Tugasan: Membina enam ayat dan menerangkan satu pilihan penghubung serta satu cadangan berasaskan konteks jualan telur.\nBahan: BT62\nKad penghubung alternatif\nJalur Fakta gambar/Cadangan saya\nBimbingan guru: Tanya sama ada penghubung menunjukkan tambahan, urutan atau tujuan dan minta contoh daripada hasil murid.\nBimbing murid menandai cadangan penggunaan wang sebagai idea, bukan peristiwa yang semestinya berlaku dalam gambar.\nLangkah murid: Siapkan enam ayat dengan sasaran bentuk teras.\nPilih satu majmuk dan bandingkan penghubung alternatif.\nTentukan versi yang lebih jelas dan jelaskan sebab kepada pasangan.\nBina satu ayat cadangan hasil jualan bersebab tanpa menambah angka harga atau fakta yang tiada.\nHasil individu: Enam ayat lengkap, alasan pilihan penghubung dan satu cadangan berlabel.\nKriteria: Sasaran teras tercapai serta alasan menjelaskan makna; lebih banyak penghubung atau ayat panjang tidak semestinya lebih baik.\nSusulan: Semak sama ada cadangan boleh dinyatakan dengan ayat tunggal dan majmuk tanpa mengubah maksud asal.","aids_and_pak21_original":"BBM/ABM: BT62\nKad penghubung alternatif\nJalur Fakta gambar/Cadangan saya\nPAK-21: Urutan cerita berpasangan: seorang menjadi pemerhati gambar, seorang pembina ayat; peranan bertukar pada nombor berikutnya. Semak rakan menguji hubungan dua klausa dan susunan, bukan mengulang pengelasan ayat tanpa membina cerita."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan enam ayat individu dan penerangan satu pilihan bentuk ayat.","Evidens":"Enam ayat mengikut nombor dengan dua tunggal serta dua majmuk, kata panduan dan penghubung ditandai.","Kriteria Kejayaan":"Ayat lengkap, konteks gambar, urutan dan hubungan maklumat tepat; bantuan direkod."},"closure_original":"Tindakan guru: Pilih satu ayat tunggal serta satu majmuk daripada hasil untuk dibaca tanpa menamakan penulis.\nRumusan peranan urutan nombor, kata panduan dan penghubung dalam membina cerita yang dapat diikuti.\nTindakan murid: Sebut beza bentuk dua ayat serta kata panduan yang digunakan.\nSerahkan enam ayat dan nyatakan nombor gambar yang masih memerlukan bantuan semakan.\nSemakan: Refleksi berasaskan bukti enam ayat dan bantuan sebenar, bukan dianggap lengkap kerana semua kad telah disusun.\nBahan: Kad kata panduan dan hasil murid.","reflection_original":"____ / ____ murid menulis enam ayat dengan bentuk sasaran; ____ memerlukan rangka; butiran gambar atau penghubung yang perlu susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M34-S4.docx","source_docx_sha256":"398d0359a32f9cd97f8a989d5cf4e366f345b1c3cf4b43ebcac91eda9bc21637","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":34,"session":4,"revision":"r2","title_original":"Pengayaan","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2(ii)(iii)","sp_support_original":"—","objective_original":"Murid dapat membina ayat tunggal dan ayat majmuk tentang gambar ternakan itik.","success_criteria_original":"Membina satu ayat tunggal tentang mengutip telur.; Membina satu ayat majmuk tentang menjual telur.","textbook_pages_original":"m/s 62","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk enam gambar dalam buku.\nGuru tanya, “Haiwan apakah yang kamu lihat?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut itik dan telur.\nSemakan: Bantu murid menamakan haiwan.\nBahan: Buku teks halaman 62","BBM/ABM":"Buku teks halaman 62","PAK-21":"Bercerita dan membina ayat secara berpasangan mengikut gambar."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali ternakan itik","execution_original":"Tindakan guru: Guru tunjuk enam gambar dalam buku.\nGuru tanya, “Haiwan apakah yang kamu lihat?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut itik dan telur.\nSemakan: Bantu murid menamakan haiwan.\nBahan: Buku teks halaman 62","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 62\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."},{"phase_original":"Langkah 2\nBaca contoh awal","execution_original":"Tindakan guru: Guru baca pembukaan tentang Hasan dan ayahnya.\nGuru contohkan “Pak Abu membela itik. Itik menyudu makanan. Itik bertelur.”\nTindakan murid: Murid mengikuti bacaan.\nMurid menunjukkan gambar pertama hingga ketiga.\nSemakan: Terangkan menyudu sebagai cara itik mengambil makanan dengan paruh.\nBahan: Buku teks\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad perkataan\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."},{"phase_original":"Langkah 3\nCuba bersama","execution_original":"Tindakan guru: Guru bimbing ayat “Itik berenang di sungai.”\nGuru tunjuk contoh “Wanita itu mengutip telur.”\nTindakan murid: Murid mengulang ayat mengikut gambar keempat dan kelima.\nMurid menyebut perbuatan dalam gambar keenam.\nSemakan: Pastikan murid membezakan mengutip dengan menjual.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."},{"phase_original":"Langkah 4\nBina dengan rakan","execution_original":"Tindakan guru: Guru beri contoh “Wanita itu menjual telur untuk mendapatkan wang.”\nGuru bantu pasangan menggunakan kata untuk.\nTindakan murid: Murid bergilir menyebut ayat mengutip telur.\nMurid menyebut ayat menjual telur bersama pasangan.\nSemakan: Beri kad frasa jika murid terlupa sambungan ayat.\nBahan: Kad untuk mendapatkan wang","aids_and_pak21_original":"BBM/ABM: Kad untuk mendapatkan wang\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."},{"phase_original":"Langkah 5\nTulis sendiri","execution_original":"Tindakan guru: Guru minta murid menulis ayat bagi gambar kelima dan keenam.\nGuru semak ayat tunggal dan ayat majmuk murid.\nTindakan murid: Murid menulis ayat tentang mengutip telur.\nMurid menulis ayat tentang menjual telur untuk mendapatkan wang.\nSemakan: Buku dan rangka ayat boleh dirujuk.\nBahan: Buku latihan\nRangka ayat","aids_and_pak21_original":"BBM/ABM: Buku latihan\nRangka ayat\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru baca semula ayat mengikut enam gambar.\nGuru tanya cadangan menggunakan wang jualan telur.\nTindakan murid: Murid mengikuti cerita daripada gambar.\nMurid memberi cadangan mudah jika bersedia.\nSemakan: Terima cadangan seperti membeli makanan itik.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Melengkapkan ayat mengutip dan menjual telur.\nBahan: Wanita itu mengutip ___.\nWanita itu menjual telur untuk ___.\nKad telur dan mendapatkan wang\nBimbingan guru: Guru tunjuk gambar satu demi satu.\nGuru baca rangka ayat bersama murid.\nLangkah murid: Pilih kad jawapan.\nSebut ayat lengkap.\nTulis ayat dengan bantuan.\nHasil individu: Dua ayat berpandu.\nKriteria: Perbuatan sepadan dengan gambar.\nSusulan: Ulang ayat lisan jika murid belum bersedia menulis.","aids_and_pak21_original":"BBM/ABM: Wanita itu mengutip ___.\nWanita itu menjual telur untuk ___.\nKad telur dan mendapatkan wang\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Membina dua jenis ayat tentang telur itik.\nBahan: Buku teks\nKad mengutip, menjual dan untuk\nBimbingan guru: Guru semak pilihan kata kerja.\nGuru bantu sambungan ayat tentang tujuan menjual.\nLangkah murid: Lihat dua gambar akhir.\nCuba ayat dengan rakan.\nTulis sendiri dua ayat.\nHasil individu: Satu ayat tunggal dan satu ayat majmuk.\nKriteria: Ayat lengkap dan sesuai dengan gambar.\nSusulan: Baca semula ayat kepada guru.","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad mengutip, menjual dan untuk\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menggabungkan dua perbuatan itik menggunakan dan.\nBahan: Gambar menyudu makanan dan berenang\nKad dan\nBimbingan guru: Guru bantu memilih dua perbuatan.\nGuru beri awal ayat “Itik menyudu makanan...”\nLangkah murid: Sebut dua ayat pendek.\nGabungkan ayat menggunakan dan.\nSampaikan kepada rakan.\nHasil individu: Satu ayat gabungan lisan.\nKriteria: Maklumat daripada kedua-dua gambar disampaikan dengan jelas.\nSusulan: Tulis ayat tambahan jika murid mahu.","aids_and_pak21_original":"BBM/ABM: Gambar menyudu makanan dan berenang\nKad dan\nPAK-21: Bercerita dan membina ayat secara berpasangan mengikut gambar."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan dua ayat dalam buku latihan.","Evidens":"Ayat tentang gambar mengutip dan menjual telur.","Kriteria Kejayaan":"Murid membina satu ayat tunggal dan satu ayat majmuk yang sesuai."},"closure_original":"Tindakan guru: Guru baca semula ayat mengikut enam gambar.\nGuru tanya cadangan menggunakan wang jualan telur.\nTindakan murid: Murid mengikuti cerita daripada gambar.\nMurid memberi cadangan mudah jika bersedia.\nSemakan: Terima cadangan seperti membeli makanan itik.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat membina ayat berdasarkan gambar ternakan itik. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M34-S4.docx","source_docx_sha256":"7f16d518688c5df2df955fdedd89446779de209e4e0c662d3d1bc9f4dd05401c","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":34,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M35-S1","week_no":35,"session_no":1,"lesson_map":{"title":"Cerita Dino","sp":"1.1.1","page":64,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":35,"session":1,"revision":"r1","title_original":"Cerita Dino","sk_original":"1.1 Mendengar dan memberikan respons","sp_original":"1.1.1","sp_support_original":"—","objective_original":"Selepas mendengar Cerita Dino, setiap murid mengecam dan mengulang sekurang-kurangnya dua daripada tiga ayat majmuk sasaran dengan kedua-dua maklumat, kata hubung dan sebutan yang jelas tanpa membaca teks.","success_criteria_original":"Mengecam dua ayat majmuk, membezakannya daripada ayat tunggal pengalih.; Mengulang dua ayat lengkap dengan kata hubung serta maksud asal.; Bantuan dicatat; tiada TP automatik.","textbook_pages_original":"m/s 64","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca Nama saya Dino, kemudian minta dua murid mengulang tanpa melihat buku.\nBaca ayat anak bongsu tetapi tidak manja; tanya Adakah Dino manja? Modelkan jawapan Tidak, Dino tidak manja.\nTindakan murid: Letakkan buku tertutup dan dengar kedua-dua bacaan guru.\nUlang ayat pendek, kemudian jawab tentang sifat Dino berdasarkan perkara yang didengar.\nSemakan: Jika menjawab manja, ulang tetapi saya tidak manja dan semak semula.\nBahan: Skrip Cerita Dino BT64 dan kad telinga.","BBM/ABM":"Skrip Cerita Dino BT64 dan kad telinga.","PAK-21":"Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: kenali suara Dino","execution_original":"Tindakan guru: Baca Nama saya Dino, kemudian minta dua murid mengulang tanpa melihat buku.\nBaca ayat anak bongsu tetapi tidak manja; tanya Adakah Dino manja? Modelkan jawapan Tidak, Dino tidak manja.\nTindakan murid: Letakkan buku tertutup dan dengar kedua-dua bacaan guru.\nUlang ayat pendek, kemudian jawab tentang sifat Dino berdasarkan perkara yang didengar.\nSemakan: Jika menjawab manja, ulang tetapi saya tidak manja dan semak semula.\nBahan: Skrip Cerita Dino BT64 dan kad telinga.","aids_and_pak21_original":"BBM/ABM: Skrip Cerita Dino BT64 dan kad telinga.\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},{"phase_original":"Langkah 2\nPemodelan: dengar dua maklumat","execution_original":"Tindakan guru: Baca cerita, kemudian ulang tiga ayat sasaran dengan jeda semula jadi, bukan memotong setiap perkataan.\nPaparkan kad tetapi, supaya, kerana selepas bacaan; jelaskan belajar bersungguh-sungguh bertujuan berjaya, manakala mengemas katil mempunyai sebab tidak menyusahkan ibu.\nTindakan murid: Angkat kad dua maklumat apabila mendengar ayat sasaran.\nUlang setiap ayat bersama guru dan sebut hubungan maknanya, misalnya kerana menerangkan sebab.\nSemakan: Jika kata hubung hilang, modelkan semula ayat lengkap.\nBahan: BT64, kad kata hubung dan kad dua maklumat.","aids_and_pak21_original":"BBM/ABM: BT64, kad kata hubung dan kad dua maklumat.\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},{"phase_original":"Langkah 3\nLatihan pasangan: gema yang tepat","execution_original":"Tindakan guru: Baca ayat mengemas katil dan ayat pengalih Nama saya Dino dalam susunan berselang.\nTanya Apakah sebab Dino mengemas katil? Terima Tidak mahu menyusahkan ibu, kemudian minta ayat asal diulang penuh.\nTindakan murid: Pendengar memilih kad satu atau dua maklumat sebelum mengulang ayat sasaran.\nPenyemak menyebut bahagian tertinggal tanpa mengejek; tukar peranan bagi ayat belajar bersungguh-sungguh.\nSemakan: Betulkan pengguguran sendiri atau kata hubung sebelum latihan kendiri.\nBahan: Kad satu/dua maklumat dan skrip tiga ayat.","aids_and_pak21_original":"BBM/ABM: Kad satu/dua maklumat dan skrip tiga ayat.\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},{"phase_original":"Langkah 4\nBengkel pendengaran terbeza","execution_original":"Tindakan guru: Jalankan tiga laluan pada ayat anak bongsu tetapi tidak manja, belajar supaya berjaya dan mengemas katil kerana tidak mahu menyusahkan ibu; murid mendengar sebelum mengulang, bukan menyalin teks.\nPeneroka menggunakan dua penanda makna dan kad penghubung, Pembina hanya kad satu/dua maklumat, Pencabar membandingkan pengguguran perkataan tidak. Tarik balik petunjuk sebelum respons individu.\nTindakan murid: Ikuti langkah laluan masing-masing menggunakan ayat Dino yang sama.\nLatih ulangan penuh dan beri isyarat sedia apabila boleh mengulang tanpa panduan bertulis.\nSemakan: Jika murid mengulang bunyi tetapi mengubah sifat Dino, semak perkataan tidak; jika maksud difahami tetapi ayat tertinggal, ulang seluruh rangsangan dan catat bantuan ingatan.\nBahan: Kad kata hubung latihan, BT64 dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Kad kata hubung latihan, BT64 dan senarai semak.\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},{"phase_original":"Langkah 5\nPBD: giliran suara individu","execution_original":"Tindakan guru: Panggil murid bergilir dalam kelompok kecil; baca tiga ayat sasaran bersama ayat pengalih, tanpa kad teks.\nMinta setiap murid mengecam kemudian mengulang; beri satu rangsangan semula jika perlu dan rekod bantuan tersebut.\nTindakan murid: Dengar rangsangan dan nyatakan ayat yang membawa maklumat gabungan.\nUlang ayat sasaran seorang diri; murid menunggu menyemak cerita secara senyap tanpa membisikkan jawapan.\nSemakan: Semak maklumat, kata hubung dan kejelasan; giliran belum diuji ditanda belum diperhatikan.\nBahan: Skrip bacaan terkawal dan senarai semak nama.","aids_and_pak21_original":"BBM/ABM: Skrip bacaan terkawal dan senarai semak nama.\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},{"phase_original":"Langkah 6\nPenutup: sebab dalam satu ayat","execution_original":"Tindakan guru: Baca semula ayat mengemas katil dan minta seorang murid mengulang sebagai rumusan.\nTanya Apakah yang hilang jika kerana dibuang? Jelaskan bahawa hubungan sebab menjadi kurang jelas.\nTindakan murid: Ulang satu ayat pilihan secara bergilir dengan pasangan.\nNyatakan sama ada masih memerlukan bacaan perlahan atau sudah bersedia tanpa kad.\nSemakan: Tentukan latihan susulan tanpa menggantikan rekod individu.\nBahan: Kad kerana dan catatan bantuan guru.","aids_and_pak21_original":"BBM/ABM: Kad kerana dan catatan bantuan guru.\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — gema bersegmen","implementation_original":"Tugasan: Dengar ayat anak bongsu dan mengemas katil secara bersegmen sebelum mengulang penuh tanpa membaca.\nBahan: Kad tetapi dan kerana\nDua penanda kosong bagi dua bahagian makna\nBimbingan guru: Baca Saya anak bongsu dalam keluarga, kemudian tetapi saya tidak manja; tunjuk penanda mengikut bahagian.\nCantumkan bacaan dan simpan kad sebelum giliran akhir supaya murid bergantung pada pendengaran.\nLangkah murid: Dengar satu bahagian tanpa bercakap serentak.\nUlang bahagian itu dengan sebutan jelas.\nDengar ayat penuh dan sentuh penanda apabila maklumat kedua bermula.\nUlang ayat penuh tanpa kad dan jelaskan bahawa Dino tidak manja.\nHasil individu: Dua respons lisan individu dengan rekod bantuan segmen atau ulangan.\nKriteria: Dua ayat tepat memenuhi objektif; satu ayat tepat ialah kemajuan sokongan, belum pencapaian penuh.\nSusulan: Jika kata hubung hilang, ulang bahagian makna; jika stabil, cuba ayat supaya tanpa penanda.","aids_and_pak21_original":"BBM/ABM: Kad tetapi dan kerana\nDua penanda kosong bagi dua bahagian makna\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},"pembina":{"label":"Langkah 1\nPembina — dengar, semak, ulang","implementation_original":"Tugasan: Bezakan tiga ayat majmuk Dino daripada ayat tunggal pengalih dan ulang secara lisan; semakan rakan untuk latihan sahaja.\nBahan: Kad satu/dua maklumat\nTiga rangsangan lisan daripada BT64\nBimbingan guru: Bacakan ayat dalam susunan berlainan dan tanyakan tujuan belajar bersungguh-sungguh.\nHentikan isyarat tangan selepas percubaan pertama dan minta pasangan tidak membantu giliran akhir.\nLangkah murid: Dengar rangsangan sehingga selesai.\nPilih kad berdasarkan bilangan maklumat yang digabungkan.\nUlang ayat kepada pasangan tanpa membuka buku.\nTerima semakan kata hubung, kemudian ulang sendiri di hadapan guru.\nHasil individu: Ulangan individu bagi tiga ayat sasaran dan pilihan ayat majmuk.\nKriteria: Sekurang-kurangnya dua ayat dikecam dan diulang lengkap dengan maksud serta kata hubung asal.\nSusulan: Jika tujuan/sebab tertukar, bandingkan supaya/kerana; jika tepat, cuba tanpa kad.","aids_and_pak21_original":"BBM/ABM: Kad satu/dua maklumat\nTiga rangsangan lisan daripada BT64\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."},"pencabar":{"label":"Langkah 1\nPencabar — kesan ulangan yang tersasar","implementation_original":"Tugasan: Ulang ayat sumber, kemudian kesan pengguguran tidak dalam contoh salah guru dan pulihkan maksud; contoh itu bukan teks buku.\nBahan: Skrip asal Cerita Dino\nCatatan guru bagi pengguguran perkataan tidak\nBimbingan guru: Sebut versi latihan dan tanya Adakah maksudnya masih sama dengan cerita Dino?\nBacakan semula versi asal sekali, kemudian hentikan semua petunjuk ketika murid mengulang.\nLangkah murid: Dengar dan ulang ayat sumber dahulu.\nBandingkan versi asal dengan ulangan latihan guru.\nSebut perkataan yang hilang serta perubahan sifat Dino.\nPulihkan ayat lengkap dan ulang ayat tujuan atau sebab secara individu.\nHasil individu: Respons lisan ayat sumber serta pembetulan makna secara berasingan.\nKriteria: Objektif dua daripada tiga ayat tetap digunakan; penerangan perubahan makna ialah bukti perluasan, bukan syarat tambahan semua murid.\nSusulan: Jika penerangan baik tetapi ulangan tersasar, latih semula pendengaran ayat penuh.","aids_and_pak21_original":"BBM/ABM: Skrip asal Cerita Dino\nCatatan guru bagi pengguguran perkataan tidak\nPAK-21: Dengar–Ulang Berpasangan: pendengar mengulang bacaan guru, penyemak menyebut bahagian tertinggal; tukar peranan sebelum giliran individu tanpa bantuan."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian dan pentaksiran lisan individu selepas rangsangan bacaan guru.","Evidens":"Catatan respons bagi tiga ayat majmuk Dino; jawapan berkumpulan tidak dianggap bukti individu.","Kriteria Kejayaan":"Sekurang-kurangnya dua daripada tiga ayat dikecam dan diulang lengkap, kata hubung tepat, maksud kekal dan sebutan jelas tanpa membaca."},"closure_original":"Tindakan guru: Baca semula ayat mengemas katil dan minta seorang murid mengulang sebagai rumusan.\nTanya Apakah yang hilang jika kerana dibuang? Jelaskan bahawa hubungan sebab menjadi kurang jelas.\nTindakan murid: Ulang satu ayat pilihan secara bergilir dengan pasangan.\nNyatakan sama ada masih memerlukan bacaan perlahan atau sudah bersedia tanpa kad.\nSemakan: Tentukan latihan susulan tanpa menggantikan rekod individu.\nBahan: Kad kerana dan catatan bantuan guru.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan yang diberi: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M35-S1.docx","source_docx_sha256":"8c71731953c1b62416092203600b758571120f928b9fd93eef767929b6ac50e3","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":35,"session":1,"revision":"r2","title_original":"Cerita Dino","sk_original":"1.1 Mendengar dan memberikan respons","sp_original":"1.1.1","sp_support_original":"—","objective_original":"Murid dapat menyebut semula ayat majmuk yang didengar dalam cerita Dino.","success_criteria_original":"Menyebut semula dua ayat majmuk dengan bantuan jika perlu.; Mengekalkan kata hubung dalam ayat yang disebut.","textbook_pages_original":"m/s 64","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca pengenalan Dino pada BT64.\nTanya: Adakah Dino anak yang manja?\nTindakan murid: Dengar bacaan guru.\nJawab soalan dengan ayat pendek.\nSemakan: Murid menyebut Dino tidak manja.\nBahan: BT64.","BBM/ABM":"BT64.","PAK-21":"Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali Dino","execution_original":"Tindakan guru: Baca pengenalan Dino pada BT64.\nTanya: Adakah Dino anak yang manja?\nTindakan murid: Dengar bacaan guru.\nJawab soalan dengan ayat pendek.\nSemakan: Murid menyebut Dino tidak manja.\nBahan: BT64.","aids_and_pak21_original":"BBM/ABM: BT64.\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},{"phase_original":"Langkah 2\nGuru contohkan, kelas cuba","execution_original":"Tindakan guru: Baca perlahan: Saya anak bongsu dalam keluarga tetapi saya tidak manja.\nBaca: Setiap pagi, saya mengemas katil sendiri kerana tidak mahu menyusahkan ibu.\nTindakan murid: Ulang ayat pertama bersama guru.\nUlang ayat kedua bersama guru.\nSemakan: Guru ulang bahagian ayat yang kurang jelas.\nBahan: BT64; kad tetapi dan kerana.","aids_and_pak21_original":"BBM/ABM: BT64; kad tetapi dan kerana.\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},{"phase_original":"Langkah 3\nDengar bersama pasangan","execution_original":"Tindakan guru: Baca dua ayat sasaran sekali lagi.\nBantu pasangan menyambung bahagian selepas tetapi.\nTindakan murid: Sebut satu ayat kepada pasangan.\nTukar giliran untuk ayat seterusnya.\nSemakan: Guru dengar giliran individu semasa bergerak antara pasangan.\nBahan: Bacaan guru; kad kata hubung.","aids_and_pak21_original":"BBM/ABM: Bacaan guru; kad kata hubung.\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},{"phase_original":"Langkah 4\nCuba ikut bantuan yang sesuai","execution_original":"Tindakan guru: Jalankan latihan mengikut tiga pilihan bantuan di bawah.\nBaca semula ayat apabila murid memerlukannya.\nTindakan murid: Dengar ayat pilihan yang dibaca guru.\nCuba menyebutnya sendiri dengan bantuan yang sesuai.\nSemakan: Setiap murid mendapat giliran, bukan jawapan serentak sahaja.\nBahan: BT64; kad kata hubung.","aids_and_pak21_original":"BBM/ABM: BT64; kad kata hubung.\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},{"phase_original":"Langkah 5\nSemakan kecil","execution_original":"Tindakan guru: Dengar murid yang belum sempat diperhatikan menyebut dua ayat.\nCatat bantuan yang digunakan setiap murid.\nTindakan murid: Sebut semula ayat selepas mendengar bacaan guru.\nCuba semula bahagian yang dibetulkan.\nSemakan: Dua ulangan ayat menjadi bukti kecil individu.\nBahan: Senarai semak lisan; bacaan guru.","aids_and_pak21_original":"BBM/ABM: Senarai semak lisan; bacaan guru.\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Ulang ayat tentang mengemas katil.\nTanya: Apakah kerja rumah yang kamu boleh bantu?\nTindakan murid: Sebut ayat itu bersama-sama.\nKongsi satu kerja rumah yang mudah.\nSemakan: Guru ingatkan murid membantu keluarga.\nBahan: BT64.","aids_and_pak21_original":"BBM/ABM: BT64.\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bimbing bersama","implementation_original":"Tugasan: Dengar dan ulang dua ayat Dino sedikit demi sedikit.\nBahan: Bacaan guru BT64\nKad tetapi dan kerana\nBimbingan guru: Baca satu bahagian ayat dengan perlahan.\nSebut bersama murid apabila mereka terhenti.\nLangkah murid: Dengar bahagian pertama.\nUlang bahagian kedua bersama guru.\nCantumkan ayat dengan bantuan suara guru.\nHasil individu: Dua ayat yang diulang secara lisan.\nKriteria: Murid menyebut ayat dengan kata hubung, walaupun masih dibantu.\nSusulan: Ulang ayat yang sama pada pertemuan ringkas berikutnya.","aids_and_pak21_original":"BBM/ABM: Bacaan guru BT64\nKad tetapi dan kerana\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},"pembina":{"label":"Langkah 1\nPembina — Cuba dengan pasangan","implementation_original":"Tugasan: Ulang dua ayat Dino selepas latihan berpasangan.\nBahan: Bacaan guru BT64\nKad kata hubung\nBimbingan guru: Baca ayat penuh untuk pasangan.\nIngatkan perkataan yang tertinggal dengan sebutan perlahan.\nLangkah murid: Dengar ayat guru.\nLatih ulangan dengan pasangan.\nSebut dua ayat pada giliran sendiri.\nHasil individu: Ulangan lisan dua ayat sumber.\nKriteria: Kata tetapi dan kerana kekal dalam ayat yang disebut.\nSusulan: Kekalkan kad dan bacaan semula sehingga murid selesa.","aids_and_pak21_original":"BBM/ABM: Bacaan guru BT64\nKad kata hubung\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."},"pencabar":{"label":"Langkah 1\nPencabar — Sebut lebih jelas","implementation_original":"Tugasan: Sebut dua ayat yang sama dengan suara lebih jelas.\nBahan: Bacaan guru BT64\nKad kata hubung jika perlu\nBimbingan guru: Contohkan jeda pendek selepas keluarga.\nBantu murid memperlahankan sebutan.\nLangkah murid: Dengar contoh sebutan guru.\nPilih satu ayat untuk dilatih.\nUlang ayat itu dengan sebutan lebih jelas.\nHasil individu: Ulangan lisan ayat sumber yang lebih lancar.\nKriteria: Maksud ayat kekal semasa sebutan diperbaik.\nSusulan: Beri peluang membantu pasangan jika murid mahu.","aids_and_pak21_original":"BBM/ABM: Bacaan guru BT64\nKad kata hubung jika perlu\nPAK-21: Dengar dan ulang berpasangan: murid membantu pasangan menyebut ayat yang didengar."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian lisan individu semasa latihan dan semakan kecil.","Evidens":"Ulangan dua ayat selepas bacaan guru.","Kriteria Kejayaan":"Murid menyebut semula dua ayat majmuk dengan kata hubung yang sesuai."},"closure_original":"Tindakan guru: Ulang ayat tentang mengemas katil.\nTanya: Apakah kerja rumah yang kamu boleh bantu?\nTindakan murid: Sebut ayat itu bersama-sama.\nKongsi satu kerja rumah yang mudah.\nSemakan: Guru ingatkan murid membantu keluarga.\nBahan: BT64.","reflection_original":"__ daripada __ murid dapat menyebut semula ayat majmuk yang didengar. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M35-S1.docx","source_docx_sha256":"ae9c6139ecb0e6c3fbc13167083da63197ecf98d1a60f300a1237e81dba99275","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M35-S2","week_no":35,"session_no":2,"lesson_map":{"title":"Gigih demi Kejayaan","sp":"2.2.1","page":65,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":35,"session":2,"revision":"r1","title_original":"Gigih demi Kejayaan","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1","sp_support_original":"—","objective_original":"Selepas membaca catatan Gigih demi Kejayaan, setiap murid menyatakan satu idea keseluruhan yang menghubungkan kegigihan dengan kejayaan, serta menyokongnya dengan dua maklumat tepat daripada catatan.","success_criteria_original":"Idea merangkumi usaha dan hasil, bukan hanya kemenangan pingat.; Dua bukti daripada bahagian berlainan catatan menyokong rumusan.; Respons individu dan bantuan direkod tanpa TP automatik.","textbook_pages_original":"m/s 65","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjukkan jalur gagal mendapat pingat dan pingat emas; tanya Apakah yang mungkin menghubungkannya?\nTerima jangkaan latihan, kemudian arahkan murid menyemak jangkaan dalam catatan, bukan menganggapnya fakta.\nTindakan murid: Baca dua jalur dan berikan satu jangkaan secara ringkas.\nBuka BT65 untuk mencari bukti yang mengesahkan atau menolak jangkaan.\nSemakan: Bezakan jangkaan daripada maklumat bertulis sebelum bacaan.\nBahan: BT65 dan dua jalur hasil pertandingan.","BBM/ABM":"BT65 dan dua jalur hasil pertandingan.","PAK-21":"Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: gagal bukan pengakhiran","execution_original":"Tindakan guru: Tunjukkan jalur gagal mendapat pingat dan pingat emas; tanya Apakah yang mungkin menghubungkannya?\nTerima jangkaan latihan, kemudian arahkan murid menyemak jangkaan dalam catatan, bukan menganggapnya fakta.\nTindakan murid: Baca dua jalur dan berikan satu jangkaan secara ringkas.\nBuka BT65 untuk mencari bukti yang mengesahkan atau menolak jangkaan.\nSemakan: Bezakan jangkaan daripada maklumat bertulis sebelum bacaan.\nBahan: BT65 dan dua jalur hasil pertandingan.","aids_and_pak21_original":"BBM/ABM: BT65 dan dua jalur hasil pertandingan.\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},{"phase_original":"Langkah 2\nBacaan: jejak usaha dalam diari","execution_original":"Tindakan guru: Bimbing bacaan lima butiran catatan; jelaskan 15 November ialah tarikh dalam bahan, bukan tarikh pengajaran.\nTanya Siapa melatih penulis dan bila? Model jawapan Ibu melatihnya setiap petang.\nTindakan murid: Baca catatan senyap, kemudian secara bergilir dalam pasangan.\nTandakan kegagalan dahulu, latihan, kemenangan 80 meter dan azam tahun hadapan dengan penanda kertas.\nSemakan: Betulkan dakwaan sudah menjadi johan daerah; perkara itu masih azam.\nBahan: BT65 dan penanda kertas.","aids_and_pak21_original":"BBM/ABM: BT65 dan penanda kertas.\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},{"phase_original":"Langkah 3\nPemodelan: butiran atau keseluruhan","execution_original":"Tindakan guru: Bandingkan Penulis mendapat pingat emas dengan Kegigihan berusaha dengan sokongan ibu membawa kejayaan.\nTanya Rumusan manakah merangkumi kegagalan dan latihan juga? Tunjukkan hubungan bukti dengan idea, bukan panjang ayat.\nTindakan murid: Kelaskan dua jawapan sebagai butiran kecil atau idea menyeluruh.\nPadankan jalur latihan setiap petang dengan rumusan kegigihan dan terangkan padanan kepada pasangan.\nSemakan: Jika memilih berdasarkan ayat panjang, minta murid menunjukkan bahagian teks yang diliputi.\nBahan: Kad dua rumusan guru dan empat jalur peristiwa.","aids_and_pak21_original":"BBM/ABM: Kad dua rumusan guru dan empat jalur peristiwa.\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},{"phase_original":"Langkah 4\nLatihan terbeza: rumusan berjejak bukti","execution_original":"Tindakan guru: Jalankan tiga laluan menggunakan hubungan gagal tahun lepas, latihan ibu setiap petang dan pingat emas; semua murid membina satu idea keseluruhan serta dua bukti berbeza.\nPeneroka menyusun jalur usaha–hasil; Pembina memilih bukti terus daripada catatan; Pencabar menilai rumusan pingat sahaja. Tanya bahagian teks yang tidak diliputi jika jawapan hanya menyebut kemenangan.\nTindakan murid: Lengkapkan langkah laluan dan hasilkan rumusan sendiri.\nMinta pasangan menunjukkan jika bukti berulang, kemudian semak semula teks.\nSemakan: Semak dua bukti datang daripada butiran berlainan dan hubungan dengan rumusan jelas. Azam menjadi johan daerah tidak boleh ditulis sebagai kejayaan yang telah berlaku.\nBahan: BT65, jalur sokongan dan slip idea–bukti.","aids_and_pak21_original":"BBM/ABM: BT65, jalur sokongan dan slip idea–bukti.\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},{"phase_original":"Langkah 5\nPBD: idea keseluruhan individu","execution_original":"Tindakan guru: Berikan slip baharu; minta satu idea keseluruhan dan dua bukti tanpa jawapan pasangan.\nDengar penerangan individu yang memerlukan respons lisan; tanya Bukti ini menunjukkan usaha atau hasil? tanpa membekalkan jawapan.\nTindakan murid: Baca semula BT65 dan tulis rumusan serta dua bukti pada slip sendiri.\nTerangkan hubungan satu bukti dengan idea apabila disoal guru.\nSemakan: Nilai kefahaman bacaan, bukan panjang karangan atau kemerduan bacaan.\nBahan: BT65, slip baharu dan senarai semak nama.","aids_and_pak21_original":"BBM/ABM: BT65, slip baharu dan senarai semak nama.\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},{"phase_original":"Langkah 6\nPenutup: lengkapkan hubungan","execution_original":"Tindakan guru: Minta rumusan tanpa menyebut semua peristiwa satu persatu.\nTegaskan idea usaha gigih membawa kejayaan; terima ungkapan setara yang disokong teks.\nTindakan murid: Kongsi satu rumusan dan tunjuk bukti latihan ibu.\nNyatakan pembaikan yang dibuat daripada jawapan awal.\nSemakan: Asingkan murid yang masih menyebut tajuk sahaja untuk bimbingan susulan.\nBahan: Slip awal dan slip individu.","aids_and_pak21_original":"BBM/ABM: Slip awal dan slip individu.\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — sambungkan usaha dengan hasil","implementation_original":"Tugasan: Baca catatan mengikut bahagian kecil dan bina idea keseluruhan menggunakan pasangan usaha–hasil. Murid tetap merumus seluruh bahan, bukan sekadar memadankan gambar pingat atau menyalin tajuk.\nBahan: Jalur latihan ibu setiap petang dan kemenangan 80 meter\nRangka Usaha yang gigih ...\nBimbingan guru: Baca bersama bahagian kegagalan dan latihan, lalu tanyakan perubahan yang berlaku.\nTutup pilihan rumusan selepas murid mengenal hubungan dan minta ungkapan sendiri.\nLangkah murid: Baca bahagian kegagalan dan nyatakan tindakan seterusnya.\nLetakkan jalur latihan sebelum jalur kemenangan.\nLengkapkan rumusan usaha membawa kejayaan secara lisan.\nNyatakan dua bukti sambil menunjuk ayat, kemudian catat pada slip.\nHasil individu: Slip individu idea keseluruhan dengan dua bukti, dibantu bacaan jika perlu.\nKriteria: Satu idea merangkumi usaha–hasil dan dua bukti tepat; satu bukti sahaja belum memenuhi objektif.\nSusulan: Jika hanya menyebut menang, baca semula latihan ibu; kurangkan rangka apabila hubungan sudah jelas.","aids_and_pak21_original":"BBM/ABM: Jalur latihan ibu setiap petang dan kemenangan 80 meter\nRangka Usaha yang gigih ...\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},"pembina":{"label":"Langkah 1\nPembina — tapis butiran untuk rumusan","implementation_original":"Tugasan: Baca seluruh catatan dan pilih maklumat yang benar-benar menyokong idea kegigihan. Murid membezakan rumusan menyeluruh daripada satu butiran menarik serta tidak menganggap azam sebagai kejayaan yang sudah berlaku.\nBahan: BT65 tanpa tanda jawapan\nSlip idea dan dua ruang bukti\nBimbingan guru: Tanya Sama ada rumusanmu masih sesuai dengan bahagian gagal tahun lepas.\nBenarkan semakan pasangan sekali, kemudian minta hasil individu tanpa arahan isi.\nLangkah murid: Baca seluruh catatan sebelum memilih idea.\nTulis satu ayat rumusan usaha dan kejayaan.\nPilih dua bukti berlainan, misalnya latihan setiap petang dan pingat emas.\nJelaskan kaitan bukti kepada pasangan lalu baiki slip sendiri.\nHasil individu: Rumusan individu dan dua petikan atau parafrasa tepat.\nKriteria: Idea bukan tajuk sahaja; kedua-dua bukti menyokong hubungan yang dinyatakan.\nSusulan: Jika bukti tidak berkaitan, tukar bukti setelah membaca; jika kukuh, bandingkan dengan rumusan alternatif.","aids_and_pak21_original":"BBM/ABM: BT65 tanpa tanda jawapan\nSlip idea dan dua ruang bukti\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — uji keluasan rumusan","implementation_original":"Tugasan: Bandingkan rumusan Penulis gembira mendapat pingat dengan Sokongan ibu dan kegigihan membantu penulis menuju kejayaan. Pilih yang lebih menyeluruh, kemudian hasilkan rumusan sendiri tanpa mendakwa penulis sudah menjadi johan daerah.\nBahan: Dua kad rumusan guru\nBT65 dan slip bukti\nBimbingan guru: Tanya bahagian catatan yang tidak diliputi rumusan pingat sahaja.\nSingkirkan kad contoh sebelum murid menulis rumusan akhir dengan bahasanya sendiri.\nLangkah murid: Baca kedua-dua rumusan dan seluruh catatan.\nTandakan bukti yang diliputi setiap rumusan.\nPilih rumusan lebih menyeluruh dan jelaskan kekurangan pilihan lain.\nTulis idea sendiri dengan dua bukti serta bezakan azam daripada hasil.\nHasil individu: Slip individu idea–bukti dan penerangan perbandingan ringkas.\nKriteria: Objektif utama tetap satu idea dan dua bukti; perbandingan menjadi perluasan penaakulan.\nSusulan: Jika rumusan terlalu umum seperti semua orang mesti baik, kembalikan murid kepada hubungan usaha, sokongan dan kejayaan dalam teks.","aids_and_pak21_original":"BBM/ABM: Dua kad rumusan guru\nBT65 dan slip bukti\nPAK-21: Fikir–Pasang–Kongsi: setiap murid menulis rumusan awal, pasangan meminta bukti daripada teks, kemudian masing-masing membaiki jawapan sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Respons bertulis atau lisan individu selepas membaca bahan.","Evidens":"Slip satu idea keseluruhan dan dua bukti; penerangan lisan dicatat jika tulisan dibantu.","Kriteria Kejayaan":"Idea menghubungkan kegigihan dengan kejayaan dan disokong dua maklumat tepat daripada catatan."},"closure_original":"Tindakan guru: Minta rumusan tanpa menyebut semua peristiwa satu persatu.\nTegaskan idea usaha gigih membawa kejayaan; terima ungkapan setara yang disokong teks.\nTindakan murid: Kongsi satu rumusan dan tunjuk bukti latihan ibu.\nNyatakan pembaikan yang dibuat daripada jawapan awal.\nSemakan: Asingkan murid yang masih menyebut tajuk sahaja untuk bimbingan susulan.\nBahan: Slip awal dan slip individu.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M35-S2.docx","source_docx_sha256":"b6ef36db2895c84668cb11c59976c8800491f71c796c6d63e251a3b6c54d0d41","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":35,"session":2,"revision":"r2","title_original":"Gigih demi Kejayaan","sk_original":"2.2 Membaca, memahami, dan menaakul bahan grafik dan bukan grafik","sp_original":"2.2.1","sp_support_original":"—","objective_original":"Murid dapat menyatakan idea keseluruhan catatan Gigih demi Kejayaan selepas membacanya.","success_criteria_original":"Membaca catatan pendek dengan bimbingan.; Menyatakan satu idea keseluruhan dengan ayat mudah.","textbook_pages_original":"m/s 65","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk tajuk Gigih demi Kejayaan pada BT65.\nTanya: Apakah maksud gigih?\nTindakan murid: Baca tajuk bersama-sama.\nCuba jawab dengan perkataan berusaha.\nSemakan: Guru terangkan gigih sebagai terus berusaha.\nBahan: BT65; kad usaha.","BBM/ABM":"BT65; kad usaha.","PAK-21":"Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali catatan","execution_original":"Tindakan guru: Tunjuk tajuk Gigih demi Kejayaan pada BT65.\nTanya: Apakah maksud gigih?\nTindakan murid: Baca tajuk bersama-sama.\nCuba jawab dengan perkataan berusaha.\nSemakan: Guru terangkan gigih sebagai terus berusaha.\nBahan: BT65; kad usaha.","aids_and_pak21_original":"BBM/ABM: BT65; kad usaha.\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},{"phase_original":"Langkah 2\nGuru tunjuk cara membaca","execution_original":"Tindakan guru: Baca catatan tentang pingat emas dan kegagalan tahun lepas.\nBaca baki catatan tentang latihan ibu dan azam murid.\nTindakan murid: Ikut bacaan guru secara perlahan.\nTunjuk ayat Usaha yang gigih akan membawa kejayaan.\nSemakan: Bantu bacaan perkataan meluangkan dan meningkatkan.\nBahan: BT65.","aids_and_pak21_original":"BBM/ABM: BT65.\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},{"phase_original":"Langkah 3\nCari maksud bersama","execution_original":"Tindakan guru: Tanya: Siapakah yang melatih penulis setiap petang?\nContohkan idea keseluruhan: Usaha gigih membawa kejayaan.\nTindakan murid: Baca semula bahagian latihan dengan pasangan.\nSebut idea keseluruhan bersama guru.\nSemakan: Murid faham catatan ini tentang usaha untuk berjaya.\nBahan: BT65; kad latihan dan kejayaan.","aids_and_pak21_original":"BBM/ABM: BT65; kad latihan dan kejayaan.\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},{"phase_original":"Langkah 4\nLatihan mengikut bantuan","execution_original":"Tindakan guru: Gunakan tiga pilihan bantuan di bawah semasa bacaan pasangan.\nBantu murid melengkapkan frasa Catatan ini tentang....\nTindakan murid: Baca semula catatan dengan bantuan yang sesuai.\nCuba menyatakan maksud seluruh catatan pada giliran sendiri.\nSemakan: Terima ayat mudah seperti Kita perlu berusaha untuk berjaya.\nBahan: BT65; kad pilihan idea; kad kata.","aids_and_pak21_original":"BBM/ABM: BT65; kad pilihan idea; kad kata.\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},{"phase_original":"Langkah 5\nSemakan kecil individu","execution_original":"Tindakan guru: Tanya murid yang belum diperhatikan: Apakah cerita utama catatan ini?\nCatat jawapan dan bantuan membaca.\nTindakan murid: Beri satu jawapan ringkas sendiri.\nBaiki jawapan selepas mendengar contoh guru.\nSemakan: Jawapan menyebut usaha untuk berjaya, bukan pingat sahaja.\nBahan: Senarai semak; BT65.","aids_and_pak21_original":"BBM/ABM: Senarai semak; BT65.\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Baca semula ayat tentang usaha gigih.\nAjak murid menyebut pesanan catatan.\nTindakan murid: Ikut bacaan guru.\nSebut pesanan dengan ayat sendiri.\nSemakan: Rumusan dibuat secara santai, bukan ujian tambahan.\nBahan: BT65.","aids_and_pak21_original":"BBM/ABM: BT65.\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Baca dengan guru","implementation_original":"Tugasan: Baca catatan bersama guru sebelum memilih maksudnya.\nBahan: BT65\nKad Usaha membawa kejayaan dan kad Bercuti bersama keluarga\nBimbingan guru: Baca satu catatan pada satu masa.\nTerangkan pingat ialah hadiah kemenangan.\nLangkah murid: Ikut bacaan guru.\nPilih kad yang sesuai dengan seluruh catatan.\nSebut pilihan sebagai satu ayat dengan bantuan.\nHasil individu: Satu jawapan lisan tentang idea keseluruhan.\nKriteria: Murid memilih dan menyebut maksud usaha membawa kejayaan.\nSusulan: Baca semula bahagian latihan jika murid masih keliru.","aids_and_pak21_original":"BBM/ABM: BT65\nKad Usaha membawa kejayaan dan kad Bercuti bersama keluarga\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},"pembina":{"label":"Langkah 1\nPembina — Baca dengan pasangan","implementation_original":"Tugasan: Baca bergilir dan nyatakan maksud seluruh catatan.\nBahan: BT65\nKad usaha, latihan dan kejayaan\nBimbingan guru: Bantu pasangan membaca perkataan sukar.\nTanya Catatan ini tentang apa? selepas bacaan.\nLangkah murid: Baca catatan bergilir dengan pasangan.\nPilih kata yang membantu jawapan.\nSebut satu idea keseluruhan pada giliran sendiri.\nHasil individu: Satu ayat lisan seperti Usaha gigih membawa kejayaan.\nKriteria: Jawapan menyatakan usaha untuk berjaya.\nSusulan: Gunakan kad kata lagi jika jawapan belum jelas.","aids_and_pak21_original":"BBM/ABM: BT65\nKad usaha, latihan dan kejayaan\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."},"pencabar":{"label":"Langkah 1\nPencabar — Sebut dengan lebih jelas","implementation_original":"Tugasan: Baiki satu ayat idea keseluruhan supaya mudah difahami.\nBahan: BT65\nKad usaha dan kejayaan jika perlu\nBimbingan guru: Dengar rumusan ringkas murid.\nCadangkan kata usaha jika jawapan hanya tentang pingat.\nLangkah murid: Baca semula catatan pilihan.\nSebut idea keseluruhan dengan ayat sendiri.\nCuba semula ayat itu dengan lebih jelas.\nHasil individu: Satu rumusan lisan yang ringkas.\nKriteria: Maksud usaha membawa kejayaan kekal dalam jawapan.\nSusulan: Terima rumusan yang sudah jelas tanpa menambah tugasan.","aids_and_pak21_original":"BBM/ABM: BT65\nKad usaha dan kejayaan jika perlu\nPAK-21: Baca berpasangan: murid membaca catatan bergilir sebelum berkongsi maksudnya."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian bacaan dan satu respons lisan individu semasa latihan.","Evidens":"Jawapan murid tentang idea keseluruhan catatan BT65.","Kriteria Kejayaan":"Murid menyatakan usaha untuk mencapai kejayaan dengan ayat mudah."},"closure_original":"Tindakan guru: Baca semula ayat tentang usaha gigih.\nAjak murid menyebut pesanan catatan.\nTindakan murid: Ikut bacaan guru.\nSebut pesanan dengan ayat sendiri.\nSemakan: Rumusan dibuat secara santai, bukan ujian tambahan.\nBahan: BT65.","reflection_original":"__ daripada __ murid dapat menyatakan idea keseluruhan catatan. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M35-S2.docx","source_docx_sha256":"259d3afcd9c2a3d260e892e183a6d2915a66730d2f65af119cce18ccc19911c3","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M35-S3","week_no":35,"session_no":3,"lesson_map":{"title":"Elis yang Jujur","sp":"3.2.3","page":66,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":35,"session":3,"revision":"r1","title_original":"Elis yang Jujur","sk_original":"3.2 Menulis perkataan, frasa, dan ayat yang bermakna","sp_original":"3.2.3","sp_support_original":"—","objective_original":"Selepas membaca Elis yang Jujur, setiap murid menyusun dan mencatat enam baris maklumat dalam jadual Perkara–Wang Masuk–Wang Keluar dengan sekurang-kurangnya lima baris tepat dari segi perkara, amaun dan lajur.","success_criteria_original":"Catatan memadankan perkara dengan amaun literal sumber.; Wang pemberian ibu berada dalam Wang Masuk; pembelian dan baki mengikut susunan jadual buku.; Sekurang-kurangnya lima daripada enam baris lengkap dan tepat; bantuan direkod.","textbook_pages_original":"m/s 66","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Paparkan kad Wang pemberian ibu dan Buku latihan; tanya Yang manakah menunjukkan wang diterima?\nTunjuk RM10.00 dalam teks dan modelkan jawapan Wang pemberian ibu ialah wang masuk.\nTindakan murid: Baca kedua-dua kad perkara dan pilih kad wang diterima.\nJejak ayat ibu memberi Elis RM10.00 dalam BT66.\nSemakan: Jika semua amaun dianggap belanja, bezakan pemberian dengan membeli melalui kata kerja sumber.\nBahan: BT66 dan dua kad perkara.","BBM/ABM":"BT66 dan dua kad perkara.","PAK-21":"Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: wang diterima atau dibelanjakan","execution_original":"Tindakan guru: Paparkan kad Wang pemberian ibu dan Buku latihan; tanya Yang manakah menunjukkan wang diterima?\nTunjuk RM10.00 dalam teks dan modelkan jawapan Wang pemberian ibu ialah wang masuk.\nTindakan murid: Baca kedua-dua kad perkara dan pilih kad wang diterima.\nJejak ayat ibu memberi Elis RM10.00 dalam BT66.\nSemakan: Jika semua amaun dianggap belanja, bezakan pemberian dengan membeli melalui kata kerja sumber.\nBahan: BT66 dan dua kad perkara.","aids_and_pak21_original":"BBM/ABM: BT66 dan dua kad perkara.\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},{"phase_original":"Langkah 2\nBacaan: padankan perkara dan amaun","execution_original":"Tindakan guru: Bimbing murid membaca cerita serta jadual, termasuk RM3.50 biskut dan RM2.20 susu coklat.\nTanya Berapakah catatan bagi dua buah buku? Tegaskan RM1.20 mengikut sumber, bukan harga seunit untuk didarab.\nTindakan murid: Tandakan nama barang dalam cerita dan tunjuk amaun sepadan dalam jadual.\nSebut padanan pensel RM1.00 serta kenal pasti baki yang dihulurkan kepada ibu.\nSemakan: Bezakan jumlah bersama biskut dan susu RM5.70 daripada catatan berasingan kedua-duanya.\nBahan: BT66 dan penjejak baris.","aids_and_pak21_original":"BBM/ABM: BT66 dan penjejak baris.\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},{"phase_original":"Langkah 3\nPemodelan: satu baris satu maklumat","execution_original":"Tindakan guru: Isi baris pemberian ibu: RM10.00 pada Wang Masuk dan tanda sengkang pada Wang Keluar.\nModelkan baris biskut; tanya Mengapa RM3.50 bukan di lajur masuk? Jawapan: Elis membayar untuk membelinya.\nTindakan murid: Tunjuk lajur dan baris sebelum mencatat padanan contoh.\nTerangkan fungsi sengkang sebagai tiada catatan wang dalam lajur berkenaan.\nSemakan: Alihkan penjejak jika murid tersasar baris; jangan menganggap amaun betul sahaja sudah mencukupi.\nBahan: Jadual contoh guru dan pembaris.","aids_and_pak21_original":"BBM/ABM: Jadual contoh guru dan pembaris.\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},{"phase_original":"Langkah 4\nLatihan terbeza: susun rekod Elis","execution_original":"Tindakan guru: Jalankan tiga laluan catatan: Peneroka menggunakan pembaris dan warna lajur; Pembina menggabungkan maklumat cerita dengan jadual; Pencabar membetulkan jadual contoh yang meletakkan wang ibu pada lajur salah.\nMinta murid menunjukkan bukti amaun buku RM1.20 dan pensel RM1.00. Tarik balik kad padanan apabila murid merujuk sendiri; jangan menggandakan harga kerana kuantiti dua barang.\nTindakan murid: Lengkapkan jadual mengikut langkah laluan tanpa menukar nilai wang.\nSemak silang satu baris dengan pasangan dan baiki catatan sendiri.\nSemakan: Periksa perkara, amaun dan lajur serentak; jangan menilai berdasarkan jumlah pengiraan sahaja.\nBahan: Kad perkara–amaun, BT66 dan jadual latihan.","aids_and_pak21_original":"BBM/ABM: Kad perkara–amaun, BT66 dan jadual latihan.\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},{"phase_original":"Langkah 5\nPBD: jadual individu enam baris","execution_original":"Tindakan guru: Edarkan jadual baharu dengan tajuk Perkara–Wang Masuk–Wang Keluar sahaja. Benarkan BT66, tetapi tiada jawapan pasangan; murid mencatat enam baris sendiri.\nSemak baris ibu, buku, pensel, biskut, susu dan baki dengan sumber. Tanya makna Baki RM2.10, jelaskan ia wang dipulangkan bukan barang yang dibeli; jumlah disemak berasingan daripada enam baris sasaran.\nTindakan murid: Tulis nama perkara, kuantiti barang dan amaun pada baris sesuai.\nSemak keenam-enam baris dengan sumber dan serahkan jadual bernama.\nSemakan: Skor enam baris sasaran; baris Jumlah disemak sebagai semakan sumber, bukan ujian matematik.\nBahan: Jadual individu kosong dan BT66.","aids_and_pak21_original":"BBM/ABM: Jadual individu kosong dan BT66.\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},{"phase_original":"Langkah 6\nPenutup: rekod yang boleh dipercayai","execution_original":"Tindakan guru: Tanya Mengapa nama perkara perlu ada bersama wang? Modelkan supaya pembaca tahu wang digunakan untuk apa.\nTegaskan baki bukan pembelian dan amaun sumber mesti kekal.\nTindakan murid: Baca satu baris lengkap kepada pasangan.\nNyatakan satu semakan yang membantu mengelakkan kesilapan lajur.\nSemakan: Catat murid yang masih menulis amaun tanpa perkara untuk latihan baris berpandu.\nBahan: Jadual hasil murid dan catatan guru.","aids_and_pak21_original":"BBM/ABM: Jadual hasil murid dan catatan guru.\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — penjejak baris dan lajur","implementation_original":"Tugasan: Susun kad perkara–amaun sebelum mencatat jadual Elis; bantuan memandu baris dan lajur, bukan menggantikan catatan dengan tampalan.\nBahan: Kad Buku latihan (2 buah)–RM1.20 dan Pensel (2 batang)–RM1.00\nJadual berwarna lajur dan pembaris\nBimbingan guru: Modelkan satu padanan dengan menunjuk bukti teks serta kedudukan lajur.\nAlihkan kad contoh selepas dua baris supaya murid mencari sendiri dalam buku.\nLangkah murid: Baca nama perkara pada satu kad.\nCari amaun yang sepadan dalam BT66.\nLetakkan pembaris pada baris sasaran dan pilih lajur.\nTulis padanan lengkap, kemudian semak kembali dengan sumber.\nHasil individu: Jadual individu enam baris dengan bantuan lajur dicatat.\nKriteria: Lima baris tepat memenuhi objektif; padanan lisan tanpa catatan belum mencukupi.\nSusulan: Jika baris tersasar, kekalkan pembaris; jika tepat, gunakan jadual tanpa warna.","aids_and_pak21_original":"BBM/ABM: Kad Buku latihan (2 buah)–RM1.20 dan Pensel (2 batang)–RM1.00\nJadual berwarna lajur dan pembaris\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},"pembina":{"label":"Langkah 1\nPembina — catatan daripada dua bentuk bahan","implementation_original":"Tugasan: Gabungkan nama barang daripada cerita dengan amaun terperinci dalam jadual sumber. Jangan gandakan harga buku atau pensel kerana catatan bukan harga seunit.\nBahan: BT66 dengan cerita dan jadual\nJadual kosong tanpa warna\nBimbingan guru: Tanya sumber manakah memberikan harga biskut secara berasingan.\nBenarkan pasangan menunjukkan bukti sahaja, kemudian hentikan semakan sebelum catatan individu.\nLangkah murid: Baca cerita dan senaraikan perkara secara lisan.\nRujuk jadual untuk amaun setiap perkara.\nCatat enam baris mengikut lajur dan kuantiti sumber.\nBaca semula setiap padanan sambil menyemak sengkang serta kedudukan baki.\nHasil individu: Jadual individu dengan enam baris dan Jumlah seperti sumber.\nKriteria: Sekurang-kurangnya lima baris tepat pada perkara, amaun serta lajur.\nSusulan: Jika RM5.70 diulang pada kedua-dua barang, kembali kepada baris biskut dan susu; jika tepat, lakukan audit catatan.","aids_and_pak21_original":"BBM/ABM: BT66 dengan cerita dan jadual\nJadual kosong tanpa warna\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — audit sebelum mencatat semula","implementation_original":"Tugasan: Audit jadual salah guru: RM10.00 diletakkan dalam Wang Keluar dan buku dicatat RM2.40. Betulkan melalui bukti sumber; ini latihan rekaan, bukan teks buku.\nBahan: Jadual audit guru dua kesalahan\nBT66 dan jadual bersih\nBimbingan guru: Minta murid membuktikan pembetulan melalui lajur dan amaun dalam BT66.\nTarik balik jadual salah sebelum murid menulis semula agar tidak menyalin kesilapan.\nLangkah murid: Bandingkan lajur wang ibu dengan sumber.\nBandingkan amaun buku tanpa membuat andaian harga seunit.\nTerangkan pembetulan kepada pasangan dengan menunjuk bukti.\nCatat jadual individu enam baris serta jelaskan baki ialah wang dipulangkan.\nHasil individu: Jadual bersih individu dan dua alasan pembetulan lisan.\nKriteria: Objektif lima daripada enam baris tetap digunakan; alasan audit ialah perluasan.\nSusulan: Jika alasan bergantung pada tekaan pengiraan, arahkan semula kepada nilai literal sumber sebelum audit lain.","aids_and_pak21_original":"BBM/ABM: Jadual audit guru dua kesalahan\nBT66 dan jadual bersih\nPAK-21: Semak Silang Jadual: pasangan menunjukkan bukti padanan tanpa menulis pada hasil rakan; murid membetulkan catatan sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan hasil catatan jadual individu.","Evidens":"Jadual enam baris bernama: pemberian ibu, buku, pensel, biskut, susu coklat dan baki.","Kriteria Kejayaan":"Sekurang-kurangnya lima baris tepat serentak pada perkara, amaun dan lajur; kemahiran utama ialah mencatat maklumat."},"closure_original":"Tindakan guru: Tanya Mengapa nama perkara perlu ada bersama wang? Modelkan supaya pembaca tahu wang digunakan untuk apa.\nTegaskan baki bukan pembelian dan amaun sumber mesti kekal.\nTindakan murid: Baca satu baris lengkap kepada pasangan.\nNyatakan satu semakan yang membantu mengelakkan kesilapan lajur.\nSemakan: Catat murid yang masih menulis amaun tanpa perkara untuk latihan baris berpandu.\nBahan: Jadual hasil murid dan catatan guru.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M35-S3.docx","source_docx_sha256":"d1650edf21f3fd90321a3858d4a6902997bbf7f55e3a5139dd00134088a2e558","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":35,"session":3,"revision":"r2","title_original":"Elis yang Jujur","sk_original":"3.2 Menulis perkataan, frasa, dan ayat yang bermakna","sp_original":"3.2.3","sp_support_original":"—","objective_original":"Murid dapat menyusun dan mencatat maklumat pembelian Elis dalam jadual mudah.","success_criteria_original":"Memadankan nama barang dengan harga yang diberi.; Mencatat dua nama barang pada baris yang sesuai.","textbook_pages_original":"m/s 66","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca perenggan Elis ke pasar raya dengan ibunya.\nTanya: Apakah yang Elis beli di bahagian alat tulis?\nTindakan murid: Dengar cerita Elis.\nSebut buku latihan atau pensel.\nSemakan: Guru tunjuk perkataan dalam cerita jika murid perlukan bantuan.\nBahan: BT66.","BBM/ABM":"BT66.","PAK-21":"Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali pembelian Elis","execution_original":"Tindakan guru: Baca perenggan Elis ke pasar raya dengan ibunya.\nTanya: Apakah yang Elis beli di bahagian alat tulis?\nTindakan murid: Dengar cerita Elis.\nSebut buku latihan atau pensel.\nSemakan: Guru tunjuk perkataan dalam cerita jika murid perlukan bantuan.\nBahan: BT66.","aids_and_pak21_original":"BBM/ABM: BT66.\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},{"phase_original":"Langkah 2\nGuru tunjuk cara mencatat","execution_original":"Tindakan guru: Tunjuk lajur Perkara, Wang Masuk dan Wang Keluar.\nContohkan catatan Buku latihan (2 buah) pada baris RM1.20.\nTindakan murid: Tunjuk harga RM1.20 dalam jadual.\nBaca catatan contoh bersama guru.\nSemakan: Harga telah diberi; murid tidak perlu mengira.\nBahan: BT66; jadual guru.","aids_and_pak21_original":"BBM/ABM: BT66; jadual guru.\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},{"phase_original":"Langkah 3\nPadan bersama pasangan","execution_original":"Tindakan guru: Baca ayat dua batang pensel berharga RM1.00.\nTunjuk baris RM2.20 untuk susu coklat dalam jadual.\nTindakan murid: Letak kad pensel pada baris RM1.00.\nLetak kad susu coklat pada baris RM2.20.\nSemakan: Semak padanan nama barang dengan baris harga, bukan pengiraan.\nBahan: BT66; kad barang; jadual harga.","aids_and_pak21_original":"BBM/ABM: BT66; kad barang; jadual harga.\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},{"phase_original":"Langkah 4\nCatatan sendiri dengan bantuan","execution_original":"Tindakan guru: Gunakan tiga pilihan bantuan di bawah untuk latihan jadual.\nBantu murid mengeja nama barang apabila diminta.\nTindakan murid: Rujuk padanan barang dan harga.\nTulis dua nama barang pada jadual sendiri.\nSemakan: Pensel dan susu coklat dicatat pada baris yang betul.\nBahan: Jadual individu; BT66; kad perkataan.","aids_and_pak21_original":"BBM/ABM: Jadual individu; BT66; kad perkataan.\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},{"phase_original":"Langkah 5\nSemakan kecil","execution_original":"Tindakan guru: Semak dua catatan pada setiap jadual murid.\nTunjuk baris yang perlu dibetulkan.\nTindakan murid: Baca satu catatan sendiri kepada guru.\nBaiki catatan dengan merujuk kad barang.\nSemakan: Catatan jelas dan diletakkan pada baris harga yang diberi.\nBahan: Jadual murid; senarai semak.","aids_and_pak21_original":"BBM/ABM: Jadual murid; senarai semak.\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Tunjuk semula jadual lengkap BT66.\nTanya: Apakah yang Elis pulangkan kepada ibu?\nTindakan murid: Sebut satu barang yang telah dicatat.\nJawab baki wang.\nSemakan: Guru kaitkan catatan yang teliti dengan sikap jujur.\nBahan: BT66.","aids_and_pak21_original":"BBM/ABM: BT66.\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Padan dengan guru","implementation_original":"Tugasan: Lengkapkan dua baris nama barang dengan kad pilihan.\nBahan: Jadual harga siap dicetak\nKad pensel dan susu coklat\nBT66\nBimbingan guru: Baca nama pada setiap kad.\nTunjuk baris harga yang sepadan satu demi satu.\nLangkah murid: Pilih kad pensel untuk RM1.00.\nPilih kad susu coklat untuk RM2.20.\nTulis nama barang dengan merujuk kad.\nHasil individu: Dua catatan nama barang dalam jadual.\nKriteria: Nama barang berada pada baris yang sesuai dengan bantuan.\nSusulan: Ulang padanan satu baris jika murid masih tersalah tempat.","aids_and_pak21_original":"BBM/ABM: Jadual harga siap dicetak\nKad pensel dan susu coklat\nBT66\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},"pembina":{"label":"Langkah 1\nPembina — Semak dengan pasangan","implementation_original":"Tugasan: Padankan barang dengan pasangan sebelum mencatat sendiri.\nBahan: BT66\nJadual harga\nKad nama barang\nBimbingan guru: Ingatkan murid melihat harga yang telah diberi.\nBantu ejaan tanpa menambah latihan mengira.\nLangkah murid: Cari pensel dan susu coklat dalam bahan.\nSemak padanan harga dengan pasangan.\nCatat kedua-dua nama pada jadual sendiri.\nHasil individu: Jadual individu dengan dua ruang Perkara diisi.\nKriteria: Pensel pada RM1.00 dan susu coklat pada RM2.20.\nSusulan: Beri kad ejaan semula jika tulisan nama belum lengkap.","aids_and_pak21_original":"BBM/ABM: BT66\nJadual harga\nKad nama barang\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."},"pencabar":{"label":"Langkah 1\nPencabar — Tambah satu catatan","implementation_original":"Tugasan: Jika bersedia, catat satu lagi barang menggunakan harga yang sudah diberi.\nBahan: BT66\nJadual tambahan satu baris Biskut\nKad RM3.50\nBimbingan guru: Tunjuk catatan Biskut (1 bungkus) dalam BT66.\nIngatkan murid menggunakan harga bercetak sahaja.\nLangkah murid: Siapkan dua catatan utama.\nBaca baris biskut pada BT66.\nCatat Biskut (1 bungkus) pada baris RM3.50.\nHasil individu: Jadual dengan satu catatan tambahan pilihan.\nKriteria: Maklumat biskut dipindahkan ke baris yang sesuai.\nSusulan: Hentikan tambahan apabila masa latihan tamat.","aids_and_pak21_original":"BBM/ABM: BT66\nJadual tambahan satu baris Biskut\nKad RM3.50\nPAK-21: Padan berpasangan: murid membantu pasangan mencari nama barang untuk baris harga yang diberi."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan jadual individu semasa murid menulis.","Evidens":"Dua catatan nama barang pada jadual harga yang diberi.","Kriteria Kejayaan":"Murid mencatat pensel dan susu coklat pada baris yang betul."},"closure_original":"Tindakan guru: Tunjuk semula jadual lengkap BT66.\nTanya: Apakah yang Elis pulangkan kepada ibu?\nTindakan murid: Sebut satu barang yang telah dicatat.\nJawab baki wang.\nSemakan: Guru kaitkan catatan yang teliti dengan sikap jujur.\nBahan: BT66.","reflection_original":"__ daripada __ murid dapat mencatat maklumat pembelian dalam jadual. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M35-S3.docx","source_docx_sha256":"b8832d426ee55dee0b9f614c8095ef80627fecd86c4dc857f48d77de8c7e4c49","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M35-S4","week_no":35,"session_no":4,"lesson_map":{"title":"Pesan Ibu Ayah","sp":"4.3.3","page":67,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":35,"session":4,"revision":"r1","title_original":"Pesan Ibu Ayah","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan kesantunan bahasa serta mempersembahkannya secara kreatif","sp_original":"4.3.3","sp_support_original":"—","objective_original":"Setiap murid mempersembahkan dua rangkap awal Pesan Ibu Ayah mengikut irama Tanya Sama Pokok dengan sekurang-kurangnya enam daripada lapan baris jelas dan tepat, kesinambungan irama serta satu gerak santun yang sesuai dengan lirik.","success_criteria_original":"Menyanyi, bukan hanya membaca atau menyebut lirik berirama.; Sekurang-kurangnya enam baris jelas dan tepat sambil mengekalkan aliran lagu.; Satu gerak sesuai dan santun; bantuan permulaan dicatat.","textbook_pages_original":"m/s 67","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca Tanya pada ibu, Apa sikap baik dan tanya Apakah jawapan lirik?\nTunjuk Sikap yang ikhlas, kemudian nyanyikan frasa itu untuk membezakan bacaan daripada nyanyian.\nTindakan murid: Cari jawapan ikhlas pada paparan lirik.\nDengar dua cara persembahan dan nyatakan yang mempunyai melodi.\nSemakan: Ulang model melodi jika murid sekadar bersuara kuat tanpa menyanyi.\nBahan: BT67 dan paparan rangkap ibu.","BBM/ABM":"BT67 dan paparan rangkap ibu.","PAK-21":"Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: pesan melalui lagu","execution_original":"Tindakan guru: Baca Tanya pada ibu, Apa sikap baik dan tanya Apakah jawapan lirik?\nTunjuk Sikap yang ikhlas, kemudian nyanyikan frasa itu untuk membezakan bacaan daripada nyanyian.\nTindakan murid: Cari jawapan ikhlas pada paparan lirik.\nDengar dua cara persembahan dan nyatakan yang mempunyai melodi.\nSemakan: Ulang model melodi jika murid sekadar bersuara kuat tanpa menyanyi.\nBahan: BT67 dan paparan rangkap ibu.","aids_and_pak21_original":"BBM/ABM: BT67 dan paparan rangkap ibu.\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},{"phase_original":"Langkah 2\nPemodelan: melodi Tanya Sama Pokok","execution_original":"Tindakan guru: Nyanyikan dua rangkap awal mengikut irama buku, menunjuk baris semasa dinyanyikan.\nModelkan sebutan ikhlas dan siapa; tunjuk tangan terbuka pada Pada semua tanpa gerak berlebihan.\nTindakan murid: Ikut jejak lirik dan dengar tempat frasa berakhir.\nTiru satu baris kemudian satu rangkap, sambil mencuba gerak yang dicontohkan.\nSemakan: Jika murid mendahului melodi, hentikan pada hujung frasa dan mulakan semula dengan isyarat tangan.\nBahan: Lirik BT67 dan demonstrasi suara guru, tanpa QR/audio.","aids_and_pak21_original":"BBM/ABM: Lirik BT67 dan demonstrasi suara guru, tanpa QR/audio.\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},{"phase_original":"Langkah 3\nLatihan bersahut: tanya dan jawab","execution_original":"Tindakan guru: Bahagikan pasangan kepada penanya dan penjawab untuk Tanya pada ayah serta Nanti jawab ayah.\nTanya Adakah jawapan Pada semua kedengaran jelas? Modelkan semula jika suku kata tertelan.\nTindakan murid: Nyanyikan bahagian masing-masing, kemudian tukar peranan.\nBerikan maklum balas satu baris yang jelas dan satu sebutan yang perlu diulang.\nSemakan: Pastikan kedua-dua murid menyanyi; pendengar tetap bukan bukti menguasai persembahan.\nBahan: Kad peranan dan lirik dua rangkap.","aids_and_pak21_original":"BBM/ABM: Kad peranan dan lirik dua rangkap.\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},{"phase_original":"Langkah 4\nBengkel terbeza: suara dan gerak","execution_original":"Tindakan guru: Jalankan laluan gema satu baris untuk Peneroka, sambungan tanya–jawab untuk Pembina dan tafsiran gerak pada ikhlas/semua untuk Pencabar. Semua kembali kepada dua rangkap awal sebagai sasaran individu.\nKurangkan suara model kepada nada mula apabila murid stabil. Jika gerak tangan mengganggu nafas atau menyembunyikan perkataan ikhlas, kecilkan gerak dahulu, kemudian sambung semula dengan melodi.\nTindakan murid: Latih nyanyian mengikut langkah laluan masing-masing.\nGabungkan sekurang-kurangnya satu gerak dengan lirik tanpa mengganggu aliran lagu.\nSemakan: Jika gerak menyebabkan nyanyian terhenti, ringkaskan gerak dahulu, bukan menggugurkan nyanyian.\nBahan: BT67, kad mula dan ruang persembahan setempat.","aids_and_pak21_original":"BBM/ABM: BT67, kad mula dan ruang persembahan setempat.\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},{"phase_original":"Langkah 5\nPBD: persembahan yang dapat didengar","execution_original":"Tindakan guru: Panggil murid bergilir menyanyikan dua rangkap awal; pasangan lain tidak menyanyi bersama.\nCatat baris tepat, kesinambungan irama dan gerak; beri nada mula jika perlu serta rekodkan bantuan.\nTindakan murid: Nyanyikan rangkap Tanya pada ibu dan Tanya pada ayah secara individu dengan lirik tersedia.\nLakukan gerak pilihan dan tunggu maklum balas tanpa membandingkan suara dengan rakan.\nSemakan: Nilai persembahan lagu, bukan hafalan tanpa buku; tandakan belum diperhatikan jika giliran belum selesai.\nBahan: Paparan lirik dan senarai semak individu.","aids_and_pak21_original":"BBM/ABM: Paparan lirik dan senarai semak individu.\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},{"phase_original":"Langkah 6\nPenutup: pesan yang diingat","execution_original":"Tindakan guru: Pimpin nyanyian bersama rangkap Dengar pesan ibu dan Ibu serta ayah.\nTanya Gerak mana membantu maksud pesan? Kaitkan pilihan dengan kesantunan persembahan.\nTindakan murid: Nyanyikan dua rangkap penutup bersama dengan gerak sederhana.\nNyatakan satu bahagian nyanyian yang mahu dibaiki.\nSemakan: Catat keperluan sebutan atau melodi secara berasingan untuk susulan.\nBahan: BT67 dengan keseluruhan lirik.","aids_and_pak21_original":"BBM/ABM: BT67 dengan keseluruhan lirik.\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — gema frasa bermelodi","implementation_original":"Tugasan: Bina persembahan dua rangkap awal melalui gema satu baris sebelum menyambung rangkap. Murid dibantu melodi dan penjejak lirik, tetapi giliran akhir tetap nyanyian individu, bukan sekadar mengikut suara kumpulan.\nBahan: Lirik berjarak dengan perkataan ikhlas ditandakan\nKad mula dan tangan penjejak guru\nBimbingan guru: Nyanyikan Tanya pada ibu, berhenti dan beri ruang murid menggemakan frasa.\nKurangkan suara model kepada nada mula sahaja selepas murid berjaya menyambung baris.\nLangkah murid: Dengar melodi satu baris sambil menjejak lirik.\nNyanyikan semula tanpa suara guru menindih.\nCantumkan baris menjadi rangkap ibu dan rangkap ayah.\nTambah tangan terbuka pada Pada semua dan persembahkan sendiri.\nHasil individu: Persembahan individu dua rangkap dengan jenis bantuan dicatat.\nKriteria: Enam baris tepat, aliran lagu dan satu gerak memenuhi objektif; gema berterusan masih memerlukan sokongan.\nSusulan: Jika frasa terputus, ulang sambungan dua baris; jika lancar, hilangkan penjejak guru.","aids_and_pak21_original":"BBM/ABM: Lirik berjarak dengan perkataan ikhlas ditandakan\nKad mula dan tangan penjejak guru\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},"pembina":{"label":"Langkah 1\nPembina — sambung tanya dengan jawapan","implementation_original":"Tugasan: Latih hubungan musikal antara bahagian pertanyaan dengan jawapan sebelum menyanyikan kedua-dua rangkap sendiri. Rakan menyemak sebutan dan kesinambungan sahaja, bukan mengambil alih bahagian yang belum dikuasai penyanyi.\nBahan: Paparan dua rangkap BT67\nKad semakan jelas–bersambung–santun\nBimbingan guru: Tunjukkan cara menarik nafas pada hujung frasa tanpa menambah perkataan.\nHentikan isyarat rentak setelah pasangan boleh menyambung tanya dan jawab.\nLangkah murid: Nyanyikan bahagian tanya ketika pasangan mendengar.\nTukar bahagian dan semak sebutan ikhlas serta siapa.\nNyanyikan keseluruhan dua rangkap tanpa bantuan suara pasangan.\nPilih gerak santun, ulang persembahan dan terima satu maklum balas.\nHasil individu: Nyanyian individu dua rangkap dengan gerak pilihan.\nKriteria: Sekurang-kurangnya enam baris tepat dan jelas, irama bersambung serta gerak sepadan maksud.\nSusulan: Jika lirik tepat tetapi melodi bertukar menjadi bacaan, dengar semula model frasa; jika stabil, perluaskan ekspresi.","aids_and_pak21_original":"BBM/ABM: Paparan dua rangkap BT67\nKad semakan jelas–bersambung–santun\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — tafsir pesan melalui gerak","implementation_original":"Tugasan: Persembahkan dua rangkap awal dengan gerak yang membezakan pertanyaan dan jawapan, kemudian cuba rangkap Dengar pesan ibu sebagai perluasan. Keindahan datang daripada kesesuaian ekspresi, bukan gerakan besar atau nyanyian paling kuat.\nBahan: BT67 seluruh lirik\nKad petunjuk tanya, ikhlas dan semua\nBimbingan guru: Tanya mengapa tangan terbuka lebih sesuai untuk semua daripada menunjuk seorang rakan.\nSimpan kad petunjuk sebelum persembahan supaya pilihan ekspresi datang daripada murid.\nLangkah murid: Baca maksud dua rangkap awal dan pilih gerak.\nNyanyikan dengan melodi buku serta sebutan jelas.\nSemak sama ada gerak mengganggu nafas atau aliran lagu.\nPersembahkan sendiri, kemudian cuba rangkap pesan dengan ekspresi sesuai.\nHasil individu: Persembahan individu dan alasan ringkas bagi satu gerak.\nKriteria: Rubrik utama sama; rangkap tambahan serta alasan gerak ialah perluasan, bukan syarat semua murid.\nSusulan: Jika ekspresi menenggelamkan lirik, kecilkan gerak dan utamakan baris yang jelas dahulu.","aids_and_pak21_original":"BBM/ABM: BT67 seluruh lirik\nKad petunjuk tanya, ikhlas dan semua\nPAK-21: Nyanyian Bersahut: pasangan bergilir menyanyikan tanya–jawab dan menyemak sebutan, kemudian setiap murid menyanyikan kedua-duanya sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian persembahan nyanyian individu dengan lirik tersedia.","Evidens":"Catatan dua rangkap awal bagi setiap murid, bukan markah persembahan kumpulan.","Kriteria Kejayaan":"Enam daripada lapan baris tepat dan jelas, kesinambungan irama Tanya Sama Pokok dan satu gerak santun."},"closure_original":"Tindakan guru: Pimpin nyanyian bersama rangkap Dengar pesan ibu dan Ibu serta ayah.\nTanya Gerak mana membantu maksud pesan? Kaitkan pilihan dengan kesantunan persembahan.\nTindakan murid: Nyanyikan dua rangkap penutup bersama dengan gerak sederhana.\nNyatakan satu bahagian nyanyian yang mahu dibaiki.\nSemakan: Catat keperluan sebutan atau melodi secara berasingan untuk susulan.\nBahan: BT67 dengan keseluruhan lirik.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M35-S4.docx","source_docx_sha256":"76ce7e116857ea77f821d3bebc0fb9b4f20df47f3e82675e1c3649c3d9f37bfd","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":35,"session":4,"revision":"r2","title_original":"Pesan Ibu Ayah","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan kesantunan bahasa serta mempersembahkannya secara kreatif","sp_original":"4.3.3","sp_support_original":"—","objective_original":"Murid dapat mempersembahkan lagu Pesan Ibu Ayah dengan sebutan yang jelas.","success_criteria_original":"Menyanyikan satu rangkap dengan bantuan jika perlu.; Menyebut perkataan dalam rangkap dengan jelas.","textbook_pages_original":"m/s 67","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca tajuk Pesan Ibu Ayah.\nTanya: Apakah pesan ibu atau ayah di rumah?\nTindakan murid: Sebut tajuk lagu.\nKongsi satu pesan yang mudah.\nSemakan: Terima contoh seperti belajar rajin dan bercakap baik.\nBahan: BT67.","BBM/ABM":"BT67.","PAK-21":"Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},"six_phases_original":[{"phase_original":"Langkah 1\nDengar pesan","execution_original":"Tindakan guru: Baca tajuk Pesan Ibu Ayah.\nTanya: Apakah pesan ibu atau ayah di rumah?\nTindakan murid: Sebut tajuk lagu.\nKongsi satu pesan yang mudah.\nSemakan: Terima contoh seperti belajar rajin dan bercakap baik.\nBahan: BT67.","aids_and_pak21_original":"BBM/ABM: BT67.\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},{"phase_original":"Langkah 2\nGuru menyanyi, kelas ikut","execution_original":"Tindakan guru: Nyanyikan rangkap Dengar pesan ibu / Patuh kata ayah / Amalkan selalu / Sikap terpuji.\nGunakan irama Tanya Sama Pokok yang dinyatakan pada BT67.\nTindakan murid: Dengar contoh nyanyian guru.\nIkut nyanyian satu baris demi satu baris.\nSemakan: Bantu sebutan perkataan terpuji.\nBahan: BT67; suara guru; kad lirik.","aids_and_pak21_original":"BBM/ABM: BT67; suara guru; kad lirik.\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},{"phase_original":"Langkah 3\nNyanyi bersahut","execution_original":"Tindakan guru: Mulakan baris Dengar pesan ibu untuk disambut kelas.\nTunjuk gerak tangan mendengar sebagai contoh mudah.\nTindakan murid: Nyanyi bersahut dengan pasangan.\nCuba satu gerak tangan sambil menyanyi.\nSemakan: Guru dengar suara murid secara bergilir semasa latihan.\nBahan: Kad lirik; suara guru.","aids_and_pak21_original":"BBM/ABM: Kad lirik; suara guru.\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},{"phase_original":"Langkah 4\nLatihan dengan bantuan pilihan","execution_original":"Tindakan guru: Gunakan tiga pilihan bantuan di bawah untuk rangkap yang sama.\nBantu murid memulakan nyanyian pada giliran sendiri.\nTindakan murid: Latih rangkap bersama pasangan.\nNyanyi satu rangkap sendiri dengan bantuan jika perlu.\nSemakan: Murid menyanyi, bukan membaca lirik sahaja.\nBahan: BT67; kad lirik.","aids_and_pak21_original":"BBM/ABM: BT67; kad lirik.\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},{"phase_original":"Langkah 5\nSemakan persembahan kecil","execution_original":"Tindakan guru: Dengar satu rangkap daripada murid yang belum diperhatikan.\nBeri contoh sebutan bagi perkataan yang kurang jelas.\nTindakan murid: Nyanyi di tempat duduk pada giliran sendiri.\nUlang baris yang mahu diperbaik.\nSemakan: Semakan dibuat sepanjang latihan, bukan semua murid pada penutup.\nBahan: Kad lirik; senarai semak.","aids_and_pak21_original":"BBM/ABM: Kad lirik; senarai semak.\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},{"phase_original":"Langkah 6\nNyanyi bersama","execution_original":"Tindakan guru: Pimpin kelas menyanyikan rangkap pilihan.\nIngatkan satu pesan supaya berbuat baik.\nTindakan murid: Nyanyi bersama-sama.\nUcap terima kasih kepada pasangan.\nSemakan: Murid menutup aktiviti dengan sopan.\nBahan: BT67.","aids_and_pak21_original":"BBM/ABM: BT67.\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Nyanyi bersama guru","implementation_original":"Tugasan: Nyanyikan rangkap Dengar pesan ibu dengan bantuan suara guru.\nBahan: Kad lirik empat baris\nSuara guru\nBimbingan guru: Nyanyikan satu baris dengan perlahan.\nTerus menyanyi bersama jika murid belum yakin.\nLangkah murid: Dengar satu baris.\nIkut nyanyian guru.\nNyanyikan rangkap pada giliran sendiri dengan bantuan.\nHasil individu: Nyanyian lisan satu rangkap pendek.\nKriteria: Murid menyanyikan perkataan rangkap walaupun dibantu.\nSusulan: Ulang dua baris pertama sebelum menyambung baris seterusnya.","aids_and_pak21_original":"BBM/ABM: Kad lirik empat baris\nSuara guru\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},"pembina":{"label":"Langkah 1\nPembina — Latih dengan pasangan","implementation_original":"Tugasan: Nyanyikan rangkap yang sama selepas latihan bersahut.\nBahan: BT67\nKad lirik rangkap pilihan\nBimbingan guru: Beri nada permulaan dengan suara sendiri.\nTunjuk baris lirik apabila murid terlupa.\nLangkah murid: Nyanyi dua baris dengan pasangan.\nTukar giliran untuk dua baris berikutnya.\nNyanyi seluruh rangkap pada giliran sendiri.\nHasil individu: Persembahan satu rangkap di tempat duduk.\nKriteria: Lirik rangkap kedengaran jelas semasa nyanyian.\nSusulan: Kekalkan kad lirik dan bantuan nada jika diperlukan.","aids_and_pak21_original":"BBM/ABM: BT67\nKad lirik rangkap pilihan\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."},"pencabar":{"label":"Langkah 1\nPencabar — Tambah gerak mudah","implementation_original":"Tugasan: Jika mahu, tambah satu gerak yang sesuai pada rangkap yang sama.\nBahan: BT67\nKad lirik\nBimbingan guru: Contohkan tangan dekat telinga pada Dengar pesan ibu.\nBantu murid mengekalkan nyanyian semasa bergerak.\nLangkah murid: Nyanyi rangkap yang telah dilatih.\nPilih satu gerak tangan yang sopan.\nUlang rangkap dengan gerak pilihan.\nHasil individu: Satu rangkap dengan satu gerak mudah.\nKriteria: Nyanyian kekal jelas; gerak ialah pilihan tambahan.\nSusulan: Kembali kepada nyanyian sahaja jika gerak mengganggu.","aids_and_pak21_original":"BBM/ABM: BT67\nKad lirik\nPAK-21: Nyanyi bersahut: pasangan menyanyikan baris lagu secara bergilir."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian nyanyian individu semasa latihan dan persembahan kecil.","Evidens":"Nyanyian satu rangkap Pesan Ibu Ayah oleh setiap murid.","Kriteria Kejayaan":"Murid menyanyikan satu rangkap dengan sebutan yang boleh didengar jelas."},"closure_original":"Tindakan guru: Pimpin kelas menyanyikan rangkap pilihan.\nIngatkan satu pesan supaya berbuat baik.\nTindakan murid: Nyanyi bersama-sama.\nUcap terima kasih kepada pasangan.\nSemakan: Murid menutup aktiviti dengan sopan.\nBahan: BT67.","reflection_original":"__ daripada __ murid dapat mempersembahkan satu rangkap lagu. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M35-S4.docx","source_docx_sha256":"77badfa353a061dcf7f5d00f9d9a0d2c3053c560d48c67bee9aaed5fa416578e","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M35-S5","week_no":35,"session_no":5,"lesson_map":{"title":"Sehari dalam Kehidupan Elis","sp":"5.2.2","page":68,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":35,"session":5,"revision":"r1","title_original":"Sehari dalam Kehidupan Elis","sk_original":"5.2 Memahami dan menggunakan pembentukan kata mengikut konteks","sp_original":"5.2.2","sp_support_original":"—","objective_original":"Setiap murid menulis satu perenggan sekurang-kurangnya tiga ayat berkaitan tentang rutin petang–malam Elis, menggunakan sekurang-kurangnya tiga kata majmuk BT68 dengan makna dan konteks tepat.","success_criteria_original":"Perenggan menceritakan rutin, bukan senarai kata atau ayat terpisah.; Tiga kata majmuk digunakan tepat tanpa memisahkan pasangan maknanya.; Urutan petang–malam jelas; bantuan rangka dicatat.","textbook_pages_original":"m/s 68","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Paparkan kad jam loceng dan baju seragam; tanya Yang manakah dipakai Elis?\nTunjuk jawapan baju seragam dalam teks pagi dan kaitkan dengan rutin yang tersusun.\nTindakan murid: Baca kedua-dua kad sebagai pasangan kata lengkap.\nPilih baju seragam dan nyatakan kegunaan jam loceng berdasarkan teks.\nSemakan: Jika hanya menyebut baju, minta pasangan kata lengkap yang menentukan jenisnya.\nBahan: BT68 dan dua kad kata majmuk.","BBM/ABM":"BT68 dan dua kad kata majmuk.","PAK-21":"Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: pasangan kata membawa makna","execution_original":"Tindakan guru: Paparkan kad jam loceng dan baju seragam; tanya Yang manakah dipakai Elis?\nTunjuk jawapan baju seragam dalam teks pagi dan kaitkan dengan rutin yang tersusun.\nTindakan murid: Baca kedua-dua kad sebagai pasangan kata lengkap.\nPilih baju seragam dan nyatakan kegunaan jam loceng berdasarkan teks.\nSemakan: Jika hanya menyebut baju, minta pasangan kata lengkap yang menentukan jenisnya.\nBahan: BT68 dan dua kad kata majmuk.","aids_and_pak21_original":"BBM/ABM: BT68 dan dua kad kata majmuk.\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},{"phase_original":"Langkah 2\nPenerokaan: kata untuk petang dan malam","execution_original":"Tindakan guru: Bimbing bacaan teks pagi serta butiran petang dan malam, tanpa menghuraikan gambar yang belum diperiksa.\nTanya Di manakah Elis berehat? Model jawapan Di ruang tamu; padankan kerja sekolah dengan tindakan menyiapkan sebagai contoh guru.\nTindakan murid: Kenal pasti pasangan kata ruang tamu, buku cerita, kerja sekolah dan jadual waktu.\nPadankan pasangan itu dengan tindakan sesuai, misalnya membaca buku cerita.\nSemakan: Betulkan padanan tidak munasabah seperti memakai jadual waktu dengan membincangkan maksudnya.\nBahan: BT68, kad kata dan jalur petang–malam.","aids_and_pak21_original":"BBM/ABM: BT68, kad kata dan jalur petang–malam.\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},{"phase_original":"Langkah 3\nPemodelan: daripada butiran kepada perenggan","execution_original":"Tindakan guru: Tulis contoh guru: Pada waktu petang, Elis berehat di ruang tamu. Dia membaca buku cerita. Pada waktu malam, Elis menyiapkan kerja sekolah.\nBandingkan contoh itu dengan senarai ruang tamu, buku cerita, kerja sekolah; tanya yang manakah menceritakan kegiatan Elis?\nTindakan murid: Garis pasangan kata majmuk dalam contoh perenggan.\nJelaskan bahawa ayat mempunyai tindakan dan saling berkaitan, manakala senarai hanya menamakan kata.\nSemakan: Semak ayat lengkap dan hubungan masa, bukan jumlah kata majmuk sahaja.\nBahan: Contoh perenggan guru dan senarai pembanding.","aids_and_pak21_original":"BBM/ABM: Contoh perenggan guru dan senarai pembanding.\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},{"phase_original":"Langkah 4\nLatihan terbeza: sambung rutin Elis","execution_original":"Tindakan guru: Jalankan tiga laluan menulis perenggan menggunakan butiran petang–malam sama.\nTanya Apakah tindakan yang sesuai dengan jadual waktu? Terima menyemak jadual waktu; tarik balik rangka secara berperingkat.\nTindakan murid: Rancang urutan dan bina perenggan mengikut langkah laluan.\nBaca kepada pasangan, dengar satu semakan kata dan baiki tulisan sendiri.\nSemakan: Jika hasil masih senarai, minta murid menyebut siapa melakukan apa sebelum menulis semula.\nBahan: Kad kata, jalur masa dan kertas latihan.","aids_and_pak21_original":"BBM/ABM: Kad kata, jalur masa dan kertas latihan.\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},{"phase_original":"Langkah 5\nPBD: perenggan individu yang berkaitan","execution_original":"Tindakan guru: Tutup contoh perenggan guru dan benarkan BT68 serta kad kata tanpa ayat jawapan. Minta tiga ayat atau lebih tentang rutin petang–malam Elis yang berkaitan dalam satu perenggan.\nSemak sekurang-kurangnya tiga kata majmuk bergaris. Tanya satu tindakan yang sesuai dengan kerja sekolah atau jadual waktu untuk memastikan murid memahami penggunaannya, bukan menyisipkan kata tanpa makna.\nTindakan murid: Tulis rutin petang hingga malam Elis dalam satu perenggan.\nGaris sekurang-kurangnya tiga kata majmuk dan baca semula untuk memastikan konteks tepat.\nSemakan: Nilai penggunaan kata dalam perenggan, bukan jumlah pasangan yang digaris sahaja.\nBahan: BT68, kad kata dan kertas individu bernama.","aids_and_pak21_original":"BBM/ABM: BT68, kad kata dan kertas individu bernama.\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},{"phase_original":"Langkah 6\nPenutup: makna kekal dalam ayat","execution_original":"Tindakan guru: Minta satu contoh penggunaan buku cerita dan kerja sekolah yang tepat.\nTegaskan kata majmuk perlu menjalankan fungsi dalam cerita, bukan disisipkan tanpa makna.\nTindakan murid: Baca satu ayat daripada perenggan sendiri.\nNyatakan satu pembaikan yang menjadikan rutin lebih jelas.\nSemakan: Simpan contoh salah konteks untuk bimbingan, tanpa memalukan penulisnya.\nBahan: Perenggan individu dan catatan guru.","aids_and_pak21_original":"BBM/ABM: Perenggan individu dan catatan guru.\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — rangka tindakan dan masa","implementation_original":"Tugasan: Bina perenggan petang–malam dengan rangka masa dan kata majmuk. Bantuan memandu siapa, tindakan serta tempat; hasil mesti ayat lengkap, bukan isian perkataan.\nBahan: Kad ruang tamu, buku cerita dan kerja sekolah\nRangka Pada waktu petang, Elis ...; Dia ...; Pada waktu malam, Elis ...\nBimbingan guru: Modelkan secara lisan berehat di ruang tamu dan tanyakan tindakan untuk buku cerita.\nTutup contoh ayat selepas perancangan, tinggalkan kad kata serta penanda masa sahaja.\nLangkah murid: Pilih kad kata untuk kegiatan petang dan malam.\nSebut ayat lengkap bagi setiap kad kepada guru.\nTulis tiga ayat bersambung sebagai satu perenggan.\nBaca semula dan garis tiga pasangan kata yang digunakan.\nHasil individu: Perenggan individu dengan jenis rangka bantuan dicatat.\nKriteria: Tiga ayat berkaitan dan tiga kata majmuk tepat memenuhi objektif; senarai belum mencukupi.\nSusulan: Jika tindakan hilang, latih ayat lisan dahulu; jika stabil, kurangkan rangka masa.","aids_and_pak21_original":"BBM/ABM: Kad ruang tamu, buku cerita dan kerja sekolah\nRangka Pada waktu petang, Elis ...; Dia ...; Pada waktu malam, Elis ...\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},"pembina":{"label":"Langkah 1\nPembina — perenggan kendiri berurutan","implementation_original":"Tugasan: Kembangkan butiran petang–malam menjadi perenggan dengan kata majmuk sumber. Pilih urutan tindakan munasabah dan kekalkan Elis sebagai watak tanpa menyalin model.\nBahan: BT68 dengan butiran petang–malam\nKad ruang tamu, buku cerita, kerja sekolah dan jadual waktu\nBimbingan guru: Tanya kegiatan manakah berlaku di ruang tamu dan apakah tujuan jadual waktu.\nBerikan semakan pertanyaan sahaja selepas draf pertama; jangan menyusun ayat akhir untuk murid.\nLangkah murid: Pilih sekurang-kurangnya tiga pasangan kata yang difahami.\nRancang tindakan petang kemudian tindakan malam secara lisan.\nTulis satu perenggan dengan ayat lengkap yang berkaitan.\nBaca kepada pasangan, baiki satu penggunaan kata dan serahkan hasil sendiri.\nHasil individu: Perenggan individu dengan kata majmuk digaris.\nKriteria: Tiga kata majmuk bermakna dalam sekurang-kurangnya tiga ayat berkaitan, bukan senarai.\nSusulan: Jika urutan melompat, susun semula ayat; jika tepat, tambah hubungan tujuan yang sesuai.","aids_and_pak21_original":"BBM/ABM: BT68 dengan butiran petang–malam\nKad ruang tamu, buku cerita, kerja sekolah dan jadual waktu\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."},"pencabar":{"label":"Langkah 1\nPencabar — hubungan kegiatan dan tujuan","implementation_original":"Tugasan: Hubungkan rutin Elis dengan persediaan sekolah melalui jadual waktu, misalnya menyemaknya untuk menyediakan buku. Sambungan ini rekaan munasabah, bukan fakta gambar.\nBahan: Empat kad kata petang–malam\nKad soalan Apakah tujuannya?\nBimbingan guru: Tanya bagaimana menyemak jadual waktu membantu Elis bersedia tanpa mencipta waktu khusus.\nSimpan contoh hubungan tujuan selepas perbincangan supaya ayat akhir milik murid.\nLangkah murid: Pilih kegiatan petang dan malam berdasarkan butiran teks.\nRancang satu hubungan tujuan yang sesuai.\nTulis perenggan dengan kata majmuk lengkap dan ayat saling berkait.\nSemak sama ada setiap kata membawa makna, kemudian baca perenggan sendiri.\nHasil individu: Perenggan individu dengan hubungan tujuan serta penggunaan kata yang tepat.\nKriteria: Objektif tiga ayat dan tiga kata tetap digunakan; hubungan tujuan ialah perluasan mutu.\nSusulan: Jika ayat panjang mengaburkan maksud, pecahkan ayat sambil mengekalkan kata majmuk dan kesinambungan.","aids_and_pak21_original":"BBM/ABM: Empat kad kata petang–malam\nKad soalan Apakah tujuannya?\nPAK-21: Bina–Baca–Baiki: murid merancang bersama pasangan, membaca perenggan sendiri dan menerima semakan satu kata; rakan tidak menulis bagi pihaknya."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan perenggan bertulis individu dan penjelasan penggunaan kata jika perlu.","Evidens":"Satu perenggan petang–malam bernama dengan kata majmuk digaris.","Kriteria Kejayaan":"Sekurang-kurangnya tiga ayat berkaitan dan tiga kata majmuk tepat makna serta konteks; senarai tidak memenuhi objektif."},"closure_original":"Tindakan guru: Minta satu contoh penggunaan buku cerita dan kerja sekolah yang tepat.\nTegaskan kata majmuk perlu menjalankan fungsi dalam cerita, bukan disisipkan tanpa makna.\nTindakan murid: Baca satu ayat daripada perenggan sendiri.\nNyatakan satu pembaikan yang menjadikan rutin lebih jelas.\nSemakan: Simpan contoh salah konteks untuk bimbingan, tanpa memalukan penulisnya.\nBahan: Perenggan individu dan catatan guru.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M35-S5.docx","source_docx_sha256":"63934a68a8400ba596aae7a1e776b292677de63aac8f26b48a848f9ed3cab7b9","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":35,"session":5,"revision":"r2","title_original":"Sehari dalam Kehidupan Elis","sk_original":"5.2 Memahami dan menggunakan pembentukan kata mengikut konteks","sp_original":"5.2.2","sp_support_original":"—","objective_original":"Murid dapat menggunakan kata majmuk dalam perenggan pendek tentang kegiatan Elis.","success_criteria_original":"Mengenal pasti dua kata majmuk dalam bahan.; Menggunakan ruang tamu dan buku cerita dalam perenggan dua ayat.","textbook_pages_original":"m/s 68","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca ayat tentang jam loceng dan baju seragam pada BT68.\nTanya: Apakah yang Elis pakai ke sekolah?\nTindakan murid: Ikut bacaan guru.\nSebut baju seragam.\nSemakan: Guru kenalkan baju seragam sebagai satu kata majmuk.\nBahan: BT68.","BBM/ABM":"BT68.","PAK-21":"Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nKegiatan Elis","execution_original":"Tindakan guru: Baca ayat tentang jam loceng dan baju seragam pada BT68.\nTanya: Apakah yang Elis pakai ke sekolah?\nTindakan murid: Ikut bacaan guru.\nSebut baju seragam.\nSemakan: Guru kenalkan baju seragam sebagai satu kata majmuk.\nBahan: BT68.","aids_and_pak21_original":"BBM/ABM: BT68.\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},{"phase_original":"Langkah 2\nGuru contohkan perenggan","execution_original":"Tindakan guru: Tunjuk kata ruang tamu dan buku cerita pada bahagian petang.\nTulis contoh: Pada waktu petang, Elis berehat di ruang tamu. Dia membaca buku cerita.\nTindakan murid: Baca dua kata majmuk bersama guru.\nBaca contoh perenggan dua ayat.\nSemakan: Guru jelaskan dua ayat ini bercerita tentang kegiatan Elis pada waktu petang.\nBahan: BT68; papan tulis; kad kata.","aids_and_pak21_original":"BBM/ABM: BT68; papan tulis; kad kata.\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},{"phase_original":"Langkah 3\nCuba ayat dengan pasangan","execution_original":"Tindakan guru: Beri permulaan ayat Elis berehat di....\nBantu pasangan menyambung Dia membaca....\nTindakan murid: Pilih kad ruang tamu untuk ayat pertama.\nSebut ayat kedua menggunakan buku cerita.\nSemakan: Dengar penggunaan kata majmuk dalam ayat, bukan senarai kata sahaja.\nBahan: Kad ruang tamu dan buku cerita; contoh guru.","aids_and_pak21_original":"BBM/ABM: Kad ruang tamu dan buku cerita; contoh guru.\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},{"phase_original":"Langkah 4\nTulis perenggan pendek","execution_original":"Tindakan guru: Jalankan tiga pilihan bantuan di bawah dalam masa yang sama.\nBantu murid menyambung dua ayat dalam satu perenggan.\nTindakan murid: Latih dua ayat dengan bantuan pilihan.\nTulis perenggan sendiri dengan merujuk kad atau contoh.\nSemakan: Perenggan ringkas kekal tentang kegiatan petang Elis.\nBahan: Buku tulis; kad kata; contoh perenggan.","aids_and_pak21_original":"BBM/ABM: Buku tulis; kad kata; contoh perenggan.\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},{"phase_original":"Langkah 5\nSemak hasil sendiri","execution_original":"Tindakan guru: Semak dua kata majmuk dalam perenggan setiap murid.\nTunjuk satu ayat yang perlu dilengkapkan.\nTindakan murid: Tunjuk kata majmuk yang digunakan.\nBaiki ayat dengan bantuan guru.\nSemakan: Ruang tamu dan buku cerita digunakan mengikut maksudnya.\nBahan: Buku tulis; BT68.","aids_and_pak21_original":"BBM/ABM: Buku tulis; BT68.\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Ajak kelas membaca satu perenggan contoh.\nTunjuk kata kerja sekolah pada bahagian malam.\nTindakan murid: Baca perenggan bersama-sama.\nSebut satu kata majmuk yang dipelajari.\nSemakan: Guru rumuskan kegunaan kata majmuk dalam cerita harian.\nBahan: BT68; contoh perenggan.","aids_and_pak21_original":"BBM/ABM: BT68; contoh perenggan.\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Isi bersama guru","implementation_original":"Tugasan: Lengkapkan dua ayat pendek menjadi satu perenggan.\nBahan: Kad ruang tamu dan buku cerita\nRangka Elis berehat di ___. Dia membaca ___.\nBimbingan guru: Baca rangka ayat sambil menunjukkan kad pilihan.\nBantu ejaan apabila murid menulis.\nLangkah murid: Pilih ruang tamu untuk ayat pertama.\nPilih buku cerita untuk ayat kedua.\nLengkapkan perenggan dengan bantuan guru.\nHasil individu: Satu perenggan dua ayat dalam buku tulis.\nKriteria: Dua kata majmuk digunakan pada tempat yang sesuai.\nSusulan: Ulang satu ayat dengan kad pilihan jika murid keliru.","aids_and_pak21_original":"BBM/ABM: Kad ruang tamu dan buku cerita\nRangka Elis berehat di ___. Dia membaca ___.\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},"pembina":{"label":"Langkah 1\nPembina — Cuba selepas pasangan","implementation_original":"Tugasan: Tulis dua ayat berkaitan tentang kegiatan petang Elis.\nBahan: BT68\nKad ruang tamu dan buku cerita\nBuku tulis\nBimbingan guru: Dengar ayat yang dilatih oleh pasangan.\nTawarkan permulaan ayat apabila diperlukan.\nLangkah murid: Sebut ayat pertama kepada pasangan.\nSambung ayat kedua tentang membaca.\nTulis kedua-dua ayat sebagai satu perenggan.\nHasil individu: Perenggan pendek tentang Elis pada waktu petang.\nKriteria: Kata ruang tamu dan buku cerita digunakan dengan betul.\nSusulan: Baiki satu ayat sahaja dahulu jika murid belum lancar.","aids_and_pak21_original":"BBM/ABM: BT68\nKad ruang tamu dan buku cerita\nBuku tulis\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — Tambah satu ayat pilihan","implementation_original":"Tugasan: Jika mahu, tambah satu ayat tentang kegiatan malam Elis.\nBahan: BT68\nKad kerja sekolah\nPerenggan sendiri\nBimbingan guru: Tunjuk butiran kerja sekolah pada BT68.\nContohkan permulaan Pada waktu malam,....\nLangkah murid: Baca semula perenggan sendiri.\nSebut satu ayat menggunakan kerja sekolah.\nTambah ayat itu pada perenggan jika bersedia.\nHasil individu: Perenggan dengan satu ayat tambahan pilihan.\nKriteria: Kata kerja sekolah digunakan dalam ayat yang sesuai.\nSusulan: Terima dua ayat asal jika masa atau bantuan masih diperlukan.","aids_and_pak21_original":"BBM/ABM: BT68\nKad kerja sekolah\nPerenggan sendiri\nPAK-21: Bina bersama pasangan: murid menyebut ayat tentang Elis sebelum menulis sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan perenggan individu semasa murid menulis.","Evidens":"Perenggan dua ayat tentang kegiatan Elis.","Kriteria Kejayaan":"Dua kata majmuk digunakan mengikut konteks dalam ayat yang berkaitan."},"closure_original":"Tindakan guru: Ajak kelas membaca satu perenggan contoh.\nTunjuk kata kerja sekolah pada bahagian malam.\nTindakan murid: Baca perenggan bersama-sama.\nSebut satu kata majmuk yang dipelajari.\nSemakan: Guru rumuskan kegunaan kata majmuk dalam cerita harian.\nBahan: BT68; contoh perenggan.","reflection_original":"__ daripada __ murid dapat menggunakan kata majmuk dalam perenggan pendek. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M35-S5.docx","source_docx_sha256":"13b090b4a43da063e42158d1d3fb30b52fe913c04ac5d27f3cc739a5f27c68c1","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":35,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M36-S1","week_no":36,"session_no":1,"lesson_map":{"title":"Minta Maaf, Cikgu","sp":"1.2.1","page":69,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":36,"session":1,"revision":"r1","title_original":"Minta Maaf, Cikgu","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.1","sp_support_original":"—","objective_original":"Setiap murid dapat menjelaskan situasi permohonan maaf Kok Bun kepada Cikgu Maria dengan menyebut peristiwa kerosakan cermin kereta, satu tindakan susulan yang relevan serta sapaan dan ungkapan maaf yang santun dalam giliran individu.","success_criteria_original":"Penerangan menyebut kerosakan cermin kereta yang ditunjukkan, bukan hanya mengatakan maaf.; Satu tindakan susulan selamat atau janji berhati-hati dikemukakan sebagai cadangan, bukan fakta buku yang telah berlaku.; Sapaan cikgu dan maaf digunakan dengan nada sopan; bantuan dicatat tanpa TP automatik.","textbook_pages_original":"m/s 69","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Sebut Saya minta maaf tanpa konteks; tanya Adakah pendengar tahu apa yang berlaku?\nTunjuk gambar ingatan Kok Bun pada BT69. Tanya apa yang betul-betul dapat dilihat: kereta bercermin retak/pecah dan bola, tanpa mendakwa siapa menendang pada detik kejadian.\nTindakan murid: Nyatakan maklumat yang belum diketahui daripada ungkapan maaf sahaja.\nTunjuk kerosakan cermin dan bola pada gambar, kemudian bezakan pemerhatian itu daripada tekaan tentang pemilik kereta.\nSemakan: Jika murid menambah identiti pemilik atau cara cermin pecah yang tidak jelas, kembali kepada gambar dan tandakan butiran itu sebagai andaian, bukan bukti.\nBahan: Gambar ingatan Kok Bun pada BT69 dan kad peristiwa.","BBM/ABM":"Gambar ingatan Kok Bun pada BT69 dan kad peristiwa.","PAK-21":"Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: maaf untuk perkara apa","execution_original":"Tindakan guru: Sebut Saya minta maaf tanpa konteks; tanya Adakah pendengar tahu apa yang berlaku?\nTunjuk gambar ingatan Kok Bun pada BT69. Tanya apa yang betul-betul dapat dilihat: kereta bercermin retak/pecah dan bola, tanpa mendakwa siapa menendang pada detik kejadian.\nTindakan murid: Nyatakan maklumat yang belum diketahui daripada ungkapan maaf sahaja.\nTunjuk kerosakan cermin dan bola pada gambar, kemudian bezakan pemerhatian itu daripada tekaan tentang pemilik kereta.\nSemakan: Jika murid menambah identiti pemilik atau cara cermin pecah yang tidak jelas, kembali kepada gambar dan tandakan butiran itu sebagai andaian, bukan bukti.\nBahan: Gambar ingatan Kok Bun pada BT69 dan kad peristiwa.","aids_and_pak21_original":"BBM/ABM: Gambar ingatan Kok Bun pada BT69 dan kad peristiwa.\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},{"phase_original":"Langkah 2\nBacaan dialog: bahasa yang santun","execution_original":"Tindakan guru: Baca dialog BT69 yang tersedia: Selamat pagi, cikgu; Saya ingin meminta maaf; Saya berjanji.\nTanya Siapakah yang ingin Kok Bun jumpa? Jawapan Cikgu Maria; bezakan maklumat teks daripada ruang dialog belum lengkap.\nTindakan murid: Jejak sapaan dan ungkapan maaf dalam teks.\nSebut dua ungkapan santun dan kenal pasti bahawa perkara yang berlaku perlu dijelaskan.\nSemakan: Kekalkan ungkapan santun serta watak yang dinamakan dalam teks. Gambar menyokong situasi kerosakan cermin, bukan semua butiran sebab atau pemilik.\nBahan: Dialog BT69 serta kad sapaan/maaf/berjanji.","aids_and_pak21_original":"BBM/ABM: Dialog BT69 serta kad sapaan/maaf/berjanji.\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},{"phase_original":"Langkah 3\nPemodelan: jelaskan dan baiki","execution_original":"Tindakan guru: Modelkan contoh pelengkap guru: Selamat pagi, cikgu. Saya ingin meminta maaf tentang kejadian yang menyebabkan cermin kereta itu pecah. Saya akan memaklumkan orang dewasa dan lebih berhati-hati.\nTanya bahagian yang menjelaskan kejadian dan bahagian yang mencadangkan tindakan susulan. Tindakan belum berlaku dalam teks; jangan mendakwa Kok Bun sudah membayar atau membaiki kereta.\nTindakan murid: Padankan bahagian penerangan dengan gambar kerosakan dan bahagian tindakan susulan dengan kad cadangan.\nLatih nada sopan serta janji yang relevan tanpa menambah pihak yang dipersalahkan atau menyentuh kaca sebagai lakonan.\nSemakan: Jika cadangan tidak selamat, seperti mengutip kaca sendiri, arahkan kepada meminta bantuan orang dewasa; jangan menilai berdasarkan janji paling besar.\nBahan: Gambar kerosakan cermin dan kad tindakan susulan selamat.","aids_and_pak21_original":"BBM/ABM: Gambar kerosakan cermin dan kad tindakan susulan selamat.\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},{"phase_original":"Langkah 4\nLatihan terbeza: main peranan bermaklumat","execution_original":"Tindakan guru: Laksanakan tiga laluan penerangan berpandukan situasi gambar yang sama: Kok Bun mahu meminta maaf tentang kerosakan cermin kereta.\nDengar pasangan bertukar peranan dan tanya Apa yang kamu lihat? atau Apa tindakan susulan yang selamat? Tarik balik rangka apabila murid boleh menjelaskan peristiwa serta janji sendiri.\nTindakan murid: Lakonkan Kok Bun memberi penerangan dan cikgu mendengar; selepas satu giliran, bertukar supaya setiap murid menjelaskan.\nBaiki satu ayat yang kabur atau menambah fakta tidak ditunjukkan, kemudian nyatakan tindakan susulan sebagai cadangan sendiri.\nSemakan: Pastikan setiap murid berpeluang menjelaskan, bukan memegang watak cikgu sahaja.\nBahan: BT69, rangka bantuan tiga laluan dan senarai giliran.","aids_and_pak21_original":"BBM/ABM: BT69, rangka bantuan tiga laluan dan senarai giliran.\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},{"phase_original":"Langkah 5\nPBD: penerangan individu kepada cikgu","execution_original":"Tindakan guru: Dengar penerangan individu merentas latihan dan giliran akhir; gunakan gambar tanpa skrip jawapan penuh.\nTanya Apakah yang akan kamu lakukan selepas ini? hanya apabila tindakan susulan belum disebut; catat soalan itu sebagai bantuan dan tandakan murid belum didengar sebagai belum diperhatikan.\nTindakan murid: Sapa cikgu, jelaskan kerosakan cermin dalam situasi gambar dan minta maaf secara santun.\nSebut satu tindakan susulan yang selamat serta janji berkaitan, kemudian ucap terima kasih selepas menerima respons.\nSemakan: Nilai kejelasan peristiwa dan kesantunan, bukan keberanian berlakon sahaja. Jangan meminta murid mendedahkan kesalahan peribadi sebenar.\nBahan: Gambar BT69 tanpa skrip penuh dan senarai semak nama.","aids_and_pak21_original":"BBM/ABM: Gambar BT69 tanpa skrip penuh dan senarai semak nama.\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},{"phase_original":"Langkah 6\nPenutup: penerangan yang bertanggungjawab","execution_original":"Tindakan guru: Tanya Apakah dua maklumat yang perlu selepas sapaan? Rumuskan perkara berlaku dan pembaikan.\nTegaskan meminta maaf tidak memerlukan murid menceritakan kesalahan peribadi di hadapan kelas.\nTindakan murid: Sebut satu ungkapan santun yang dipelajari.\nNyatakan bahagian penerangan yang masih memerlukan latihan.\nSemakan: Kenal pasti murid yang masih menyebut maaf sahaja untuk bimbingan susulan.\nBahan: Kad perkara–pembaikan–bahasa santun.","aids_and_pak21_original":"BBM/ABM: Kad perkara–pembaikan–bahasa santun.\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — tiga kad penjelasan","implementation_original":"Tugasan: Jelaskan situasi kerosakan cermin melalui kad peristiwa, tindakan susulan dan bahasa santun. Kad mengatur penerangan lisan, bukan hanya mengulang maaf tanpa menjelaskan kejadian.\nBahan: Gambar BT69 dan kad cermin retak/bola\nRangka Selamat pagi, cikgu; Saya ingin meminta maaf tentang …; Saya akan …\nKad meminta bantuan orang dewasa dan bermain dengan berhati-hati\nBimbingan guru: Tanya Apa terjadi pada cermin? kemudian Apakah tindakan susulan yang selamat? sambil meminta murid menunjuk bukti gambar.\nTutup rangka selepas latihan dan kekalkan hanya kad kata kunci supaya respons akhir datang daripada murid sendiri.\nLangkah murid: Lihat gambar dan pilih satu perkara yang jelas berlaku.\nSebut kerosakan cermin dengan ayat lengkap tanpa menamakan pemilik yang tidak dilabel.\nPilih cadangan tindakan susulan yang selamat dan berkaitan.\nGabungkan penerangan dengan sapaan serta permohonan maaf secara individu.\nHasil individu: Penerangan lisan individu dengan rekod bantuan kad atau soalan.\nKriteria: Peristiwa, pembaikan, sapaan dan maaf mesti hadir; maaf sahaja belum memenuhi objektif.\nSusulan: Jika isi lengkap, hilangkan kad beransur-ansur; jika tindakan susulan hilang, ulang soalan tentang meminta bantuan orang dewasa.","aids_and_pak21_original":"BBM/ABM: Gambar BT69 dan kad cermin retak/bola\nRangka Selamat pagi, cikgu; Saya ingin meminta maaf tentang …; Saya akan …\nKad meminta bantuan orang dewasa dan bermain dengan berhati-hati\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},"pembina":{"label":"Langkah 1\nPembina — dialog dengan penjelasan sendiri","implementation_original":"Tugasan: Susun penerangan berdasarkan gambar kerosakan cermin dengan bahasa sendiri. Pasangan menyemak sama ada peristiwa serta cadangan susulan dapat difahami pendengar, bukan panjang dialog atau banyaknya alasan.\nBahan: BT69 tanpa jawapan pelengkap\nKad semakan peristiwa–cadangan susulan–santun\nBimbingan guru: Minta pendengar bertanya satu soalan apabila maklumat belum jelas.\nHentikan bantuan pasangan sebelum giliran individu supaya bukti benar-benar milik penutur.\nLangkah murid: Teliti gambar dan tentukan perkara yang perlu dijelaskan tanpa mereka pemilik kereta.\nSapa cikgu dan jelaskan kejadian dengan sopan.\nNyatakan tindakan meminta bantuan atau janji berhati-hati sebagai cadangan, kemudian dengar pertanyaan pasangan.\nBaiki penerangan dan sampaikan semula seorang diri tanpa skrip lengkap.\nHasil individu: Satu giliran penerangan individu yang lengkap dan bertatasusila.\nKriteria: Peristiwa serta pembaikan jelas dengan sapaan dan maaf sesuai konteks.\nSusulan: Jika respons menjadi hafalan tanpa makna, tanya sebab pembaikan dipilih; jika jelas, tambah janji yang realistik.","aids_and_pak21_original":"BBM/ABM: BT69 tanpa jawapan pelengkap\nKad semakan peristiwa–cadangan susulan–santun\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."},"pencabar":{"label":"Langkah 1\nPencabar — jelaskan tanpa menyalahkan orang","implementation_original":"Tugasan: Jelaskan kejadian kerosakan cermin dan janji yang realistik tanpa menyalahkan rakan atau memastikan butiran yang tiada pada gambar. Bezakan pemerhatian dengan andaian sebelum memberi penerangan santun.\nBahan: BT69\nKad pertanyaan Apa yang jelas? dan Bagaimana mengelakkan kejadian berulang?\nBimbingan guru: Bandingkan janji bermain jauh daripada kenderaan dengan janji kabur Saya akan jadi baik; jelaskan kedua-duanya cadangan latihan, bukan teks asal.\nTarik balik contoh sebelum murid memilih tindakan susulan sendiri; jangan menawarkan bayaran atau pembaikan kaca oleh kanak-kanak sebagai kewajipan.\nLangkah murid: Kenal pasti fakta yang jelas pada gambar dan teks.\nTerangkan kejadian serta minta maaf tanpa menambah tuduhan kepada orang lain.\nPilih satu tindakan susulan dan janji berkaitan yang selamat.\nSampaikan penerangan sendiri dan jawab satu soalan susulan dengan sopan serta berasas.\nHasil individu: Penerangan individu dan respons susulan yang relevan.\nKriteria: Empat unsur objektif tetap digunakan; janji khusus serta respons susulan ialah perluasan.\nSusulan: Jika alasan masih direka, tunjuk semula perbezaan antara kerosakan yang kelihatan dengan detik kejadian yang tidak digambarkan.","aids_and_pak21_original":"BBM/ABM: BT69\nKad pertanyaan Apa yang jelas? dan Bagaimana mengelakkan kejadian berulang?\nPAK-21: Main Peranan Berpasangan: murid bergilir menjadi penutur dan cikgu; pendengar meminta penjelasan peristiwa sebelum mendengar pembaikan."}},"pbd_original":{"Kaedah Pentaksiran":"Pentaksiran lisan individu melalui situasi main peranan.","Evidens":"Catatan penerangan peristiwa, pembaikan dan bahasa santun setiap murid.","Kriteria Kejayaan":"Peristiwa dan pembaikan relevan dijelaskan dengan sapaan serta permohonan maaf yang sopan."},"closure_original":"Tindakan guru: Tanya Apakah dua maklumat yang perlu selepas sapaan? Rumuskan perkara berlaku dan pembaikan.\nTegaskan meminta maaf tidak memerlukan murid menceritakan kesalahan peribadi di hadapan kelas.\nTindakan murid: Sebut satu ungkapan santun yang dipelajari.\nNyatakan bahagian penerangan yang masih memerlukan latihan.\nSemakan: Kenal pasti murid yang masih menyebut maaf sahaja untuk bimbingan susulan.\nBahan: Kad perkara–pembaikan–bahasa santun.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M36-S1.docx","source_docx_sha256":"7c79c92e66a8ff97ba15e5b95824262afb96476aa89cd8b08f49665dc0913255","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":36,"session":1,"revision":"r2","title_original":"Minta Maaf, Cikgu","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.1","sp_support_original":"—","objective_original":"Murid dapat menjelaskan perkara yang berlaku dengan bahasa yang sopan semasa meminta maaf.","success_criteria_original":"Menjelaskan perkara yang berlaku dalam satu ayat mudah.; Menggunakan ungkapan maaf semasa bertutur.","textbook_pages_original":"m/s 69","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk gelembung ingatan Kok Bun pada BT69.\nTanya: Apakah yang berlaku pada cermin kereta?\nTindakan murid: Perhatikan kereta merah dan bola dalam gambar.\nSebut cermin kereta retak atau pecah.\nSemakan: Guru menerima perkara yang kelihatan dalam gambar.\nBahan: BT69.","BBM/ABM":"BT69.","PAK-21":"Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},"six_phases_original":[{"phase_original":"Langkah 1\nLihat situasi","execution_original":"Tindakan guru: Tunjuk gelembung ingatan Kok Bun pada BT69.\nTanya: Apakah yang berlaku pada cermin kereta?\nTindakan murid: Perhatikan kereta merah dan bola dalam gambar.\nSebut cermin kereta retak atau pecah.\nSemakan: Guru menerima perkara yang kelihatan dalam gambar.\nBahan: BT69.","aids_and_pak21_original":"BBM/ABM: BT69.\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},{"phase_original":"Langkah 2\nGuru contohkan dialog","execution_original":"Tindakan guru: Baca dialog Kok Bun dan Cikgu Maria yang tercetak.\nBeri contoh guru: Maaf, cikgu. Saya tidak sengaja menyebabkan cermin kereta pecah.\nTindakan murid: Dengar nada sopan guru.\nUlang contoh guru bersama-sama.\nSemakan: Contoh guru ialah cadangan mengisi dialog, bukan jawapan tunggal buku.\nBahan: BT69; kad ungkapan maaf.","aids_and_pak21_original":"BBM/ABM: BT69; kad ungkapan maaf.\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},{"phase_original":"Langkah 3\nCuba bersama pasangan","execution_original":"Tindakan guru: Contohkan sambungan guru: Saya berjanji akan lebih berhati-hati.\nBantu pasangan memulakan dialog dengan salam.\nTindakan murid: Lakonkan Kok Bun yang meminta maaf.\nTukar peranan supaya pasangan turut mencuba.\nSemakan: Dengar penjelasan perkara yang berlaku, bukan ungkapan maaf sahaja.\nBahan: BT69; kad dialog.","aids_and_pak21_original":"BBM/ABM: BT69; kad dialog.\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},{"phase_original":"Langkah 4\nGiliran sendiri dengan bantuan","execution_original":"Tindakan guru: Gunakan tiga pilihan bantuan di bawah semasa latihan dialog.\nTanya murid secara bergilir: Mengapa kamu meminta maaf?\nTindakan murid: Pilih ungkapan maaf yang sesuai.\nBeri penjelasan ringkas pada giliran sendiri.\nSemakan: Guru bantu dengan frasa cermin kereta pecah jika murid terhenti.\nBahan: Kad maaf; contoh guru; BT69.","aids_and_pak21_original":"BBM/ABM: Kad maaf; contoh guru; BT69.\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},{"phase_original":"Langkah 5\nSemakan kecil lisan","execution_original":"Tindakan guru: Dengar jawapan murid yang belum sempat diperhatikan.\nCatat penjelasan dan bantuan yang diberi.\nTindakan murid: Sebut ungkapan maaf dan satu ayat penjelasan.\nCuba semula dengan nada lebih sopan jika perlu.\nSemakan: Semakan dibuat sepanjang latihan supaya giliran kekal pendek.\nBahan: Senarai semak; kad ungkapan.","aids_and_pak21_original":"BBM/ABM: Senarai semak; kad ungkapan.\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Baca respons Cikgu Maria yang memaafkan Kok Bun.\nAjak kelas mengulang ungkapan Terima kasih, cikgu.\nTindakan murid: Dengar respons guru.\nSebut ungkapan terima kasih bersama-sama.\nSemakan: Guru mengingatkan adab meminta dan menerima maaf.\nBahan: BT69.","aids_and_pak21_original":"BBM/ABM: BT69.\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Dialog dengan guru","implementation_original":"Tugasan: Minta maaf dan jelaskan keadaan cermin dengan bantuan frasa.\nBahan: Gambar BT69\nKad Maaf, cikgu\nContoh dialog guru\nBimbingan guru: Tunjuk cermin dalam gambar.\nBantu melengkapkan Saya tidak sengaja menyebabkan cermin kereta pecah.\nLangkah murid: Sebut Maaf, cikgu.\nDengar contoh penjelasan guru.\nSebut penjelasan bersama guru pada giliran sendiri.\nHasil individu: Ungkapan maaf dan satu penjelasan lisan.\nKriteria: Murid menjelaskan perkara yang berlaku secara sopan walaupun dibantu.\nSusulan: Ulang frasa pendek sebelum mencuba ayat penuh semula.","aids_and_pak21_original":"BBM/ABM: Gambar BT69\nKad Maaf, cikgu\nContoh dialog guru\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},"pembina":{"label":"Langkah 1\nPembina — Lakon dengan pasangan","implementation_original":"Tugasan: Latih dialog pendek sebelum memberi penjelasan sendiri.\nBahan: BT69\nKad Saya ingin meminta maaf\nContoh guru\nBimbingan guru: Bantu pasangan menentukan giliran Kok Bun.\nBeri kata cermin kereta jika murid terlupa.\nLangkah murid: Latih ungkapan maaf dengan pasangan.\nSebut ayat penjelasan tentang cermin kereta.\nTuturkan dialog pendek pada giliran sendiri.\nHasil individu: Dialog lisan ringkas berdasarkan situasi buku.\nKriteria: Ada ungkapan maaf dan penjelasan mudah tentang perkara yang berlaku.\nSusulan: Kekalkan kad dan contoh guru sehingga murid yakin.","aids_and_pak21_original":"BBM/ABM: BT69\nKad Saya ingin meminta maaf\nContoh guru\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."},"pencabar":{"label":"Langkah 1\nPencabar — Tambah janji ringkas","implementation_original":"Tugasan: Jika bersedia, tambah satu janji selepas meminta maaf.\nBahan: BT69\nKad Saya berjanji\nBimbingan guru: Beri contoh guru Saya berjanji akan lebih berhati-hati.\nBantu murid menyebut janji dengan nada sopan.\nLangkah murid: Sebut ungkapan maaf.\nJelaskan perkara yang berlaku.\nTambah satu janji ringkas jika mahu.\nHasil individu: Dialog lisan dengan satu janji tambahan.\nKriteria: Penjelasan masih jelas; janji ialah tambahan pilihan.\nSusulan: Terima dialog asas jika murid belum bersedia menambah janji.","aids_and_pak21_original":"BBM/ABM: BT69\nKad Saya berjanji\nPAK-21: Lakon berpasangan: murid bergilir sebagai Kok Bun dan guru dalam dialog pendek."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian lisan individu semasa lakonan dan semakan kecil.","Evidens":"Ungkapan maaf serta satu ayat penjelasan daripada setiap murid.","Kriteria Kejayaan":"Murid menjelaskan perkara yang berlaku dengan bahasa sopan semasa meminta maaf."},"closure_original":"Tindakan guru: Baca respons Cikgu Maria yang memaafkan Kok Bun.\nAjak kelas mengulang ungkapan Terima kasih, cikgu.\nTindakan murid: Dengar respons guru.\nSebut ungkapan terima kasih bersama-sama.\nSemakan: Guru mengingatkan adab meminta dan menerima maaf.\nBahan: BT69.","reflection_original":"__ daripada __ murid dapat menjelaskan perkara secara sopan semasa meminta maaf. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M36-S1.docx","source_docx_sha256":"22547b758733fa4027b79a2cf2f500be51155d6941c05e4cbf2019d87c34cab2","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M36-S2","week_no":36,"session_no":2,"lesson_map":{"title":"Marilah Kawan-kawanku","sp":"2.3.1","page":70,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":36,"session":2,"revision":"r1","title_original":"Marilah Kawan-kawanku","sk_original":"2.3 Membaca dan mengapresiasi karya sastera dan bukan sastera","sp_original":"2.3.1","sp_support_original":"—","objective_original":"Selepas membaca seni kata Marilah Kawan-kawanku, setiap murid menyatakan dua nilai yang tepat, termasuk satu daripada rangkap ketiga atau keempat, serta menyokong setiap nilai dengan satu baris lirik yang berkaitan.","success_criteria_original":"Dua nilai dinyatakan berdasarkan perlakuan dalam lirik.; Setiap nilai mempunyai bukti baris yang relevan; sekurang-kurangnya satu daripada rangkap ketiga atau keempat.; Kefahaman nilai dinilai, bukan kemerduan nyanyian.","textbook_pages_original":"m/s 70","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Paparkan Patuhilah peraturan sekolah dan tanya Apakah sikap yang ditunjukkan?\nPadankan jawapan mematuhi peraturan dengan label tercetak; jelaskan nilai perlu dibuktikan melalui lirik.\nTindakan murid: Baca baris secara senyap dan sebut nilai yang sesuai.\nTunjuk perkataan patuhilah sebagai petunjuk pilihan.\nSemakan: Jika menjawab gembira, minta bukti perkataan dalam baris.\nBahan: BT70 dan jalur Patuhilah peraturan sekolah.","BBM/ABM":"BT70 dan jalur Patuhilah peraturan sekolah.","PAK-21":"Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: perbuatan menunjukkan nilai","execution_original":"Tindakan guru: Paparkan Patuhilah peraturan sekolah dan tanya Apakah sikap yang ditunjukkan?\nPadankan jawapan mematuhi peraturan dengan label tercetak; jelaskan nilai perlu dibuktikan melalui lirik.\nTindakan murid: Baca baris secara senyap dan sebut nilai yang sesuai.\nTunjuk perkataan patuhilah sebagai petunjuk pilihan.\nSemakan: Jika menjawab gembira, minta bukti perkataan dalam baris.\nBahan: BT70 dan jalur Patuhilah peraturan sekolah.","aids_and_pak21_original":"BBM/ABM: BT70 dan jalur Patuhilah peraturan sekolah.\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},{"phase_original":"Langkah 2\nBacaan: empat rangkap empat perlakuan","execution_original":"Tindakan guru: Bimbing bacaan lirik sebagai teks, bukan latihan menyanyi.\nTanya Apakah yang dilarang dalam rangkap ketiga? Model jawapan Mengganggu kawan-kawan di sebelah.\nTindakan murid: Baca bergilir dan tandakan patuhi, tekun, usah mengganggu serta jagalah.\nNyatakan perbuatan bagi setiap rangkap dengan merujuk perkataan yang ditandakan.\nSemakan: Jelaskan usah bermaksud jangan supaya larangan tidak ditafsir sebagai arahan mengganggu.\nBahan: BT70 dan penanda kertas.","aids_and_pak21_original":"BBM/ABM: BT70 dan penanda kertas.\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},{"phase_original":"Langkah 3\nPemodelan: nilai mesti ada bukti","execution_original":"Tindakan guru: Modelkan Tekun belajar kerana lirik menyebut Mesti tekun belajar dengar nasihat cikgu.\nTanya Adakah tamak sesuai dengan Jagalah kemudahan di sekolah? Tunjukkan bertanggungjawab lebih munasabah; label ini cadangan guru.\nTindakan murid: Padankan satu nilai dengan baris yang menyokongnya.\nTolak kad tamak dan jelaskan bahawa menjaga kemudahan memelihara kegunaan bersama.\nSemakan: Terima menjaga harta benda atau tanggungjawab jika penjelasan berpaut pada lirik.\nBahan: Kad nilai guru dan jalur rangkap keempat.","aids_and_pak21_original":"BBM/ABM: Kad nilai guru dan jalur rangkap keempat.\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},{"phase_original":"Langkah 4\nLatihan terbeza: cari pasangan nilai–bukti","execution_original":"Tindakan guru: Jalankan tiga laluan: Peneroka memadankan perlakuan tekun/tidak mengganggu dengan nilai; Pembina memilih dua rangkap; Pencabar membandingkan hormat-menghormati dan bertimbang rasa bagi baris larangan yang sama.\nMinta pasangan bertanya Baris mana menyokongnya? Pastikan satu pilihan daripada rangkap ketiga atau keempat, kemudian tarik balik kad nilai dan minta murid merumus sendiri.\nTindakan murid: Lengkapkan langkah laluan menggunakan sekurang-kurangnya satu rangkap akhir.\nSebut nilai kepada pasangan, tunjuk bukti dan baiki padanan yang tidak relevan.\nSemakan: Jangan menerima nilai umum tanpa bukti khusus daripada rangkap dipilih.\nBahan: BT70, kad pilihan dan slip latihan.","aids_and_pak21_original":"BBM/ABM: BT70, kad pilihan dan slip latihan.\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},{"phase_original":"Langkah 5\nPBD: dua nilai daripada lirik","execution_original":"Tindakan guru: Berikan slip individu dengan dua ruang nilai dan bukti. Murid membaca semula lirik, bukan menyalin dua label awal yang sudah dicetak sahaja.\nSemak bahawa sekurang-kurangnya satu pasangan daripada rangkap ketiga atau keempat. Jika istilah nilai berbeza, dengar alasan berdasarkan baris seperti usah mengganggu atau jagalah kemudahan sebelum memutuskan ketepatan.\nTindakan murid: Baca semula lirik dan tulis dua pasangan nilai–bukti sendiri.\nJelaskan satu padanan kepada guru tanpa bantuan rakan.\nSemakan: Nilai kefahaman bacaan; nyanyian dan hafalan lagu tidak diberi markah.\nBahan: BT70, slip individu dan senarai semak.","aids_and_pak21_original":"BBM/ABM: BT70, slip individu dan senarai semak.\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},{"phase_original":"Langkah 6\nPenutup: nilai untuk sekolah","execution_original":"Tindakan guru: Gunakan soalan buku Nyatakan nilai baik yang diamalkan di sekolah kamu.\nMinta murid menghubungkan contoh tindakan dengan baris sumber, misalnya tidak mengganggu pembaca.\nTindakan murid: Nyatakan satu tindakan yang sesuai diamalkan.\nTunjukkan nilai dan baris lirik yang mendasari tindakan itu.\nSemakan: Contoh amalan meluaskan kefahaman tetapi tidak menggantikan bukti dua nilai individu.\nBahan: Lirik dan slip hasil murid.","aids_and_pak21_original":"BBM/ABM: Lirik dan slip hasil murid.\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — daripada perbuatan kepada nilai","implementation_original":"Tugasan: Baca rangkap kedua dan ketiga dengan bantuan penjejak baris. Hubungkan tekun belajar dan tidak mengganggu rakan dengan nilai yang sesuai; murid tetap memberikan dua pasangan nilai–bukti, bukan memilih kad tanpa alasan.\nBahan: Jalur Mesti tekun belajar dan Usah mengganggu kawan-kawanmu di sebelah\nKad tekun belajar serta hormat-menghormati\nBimbingan guru: Tanya Adakah rakan dapat belajar jika diganggu? untuk menjelaskan makna larangan.\nTutup kad nilai selepas padanan pertama dan minta murid menyatakan semula dengan bahasa sendiri.\nLangkah murid: Baca baris sasaran bersama guru.\nSebut perbuatan yang diminta atau dilarang.\nPilih nilai dan tunjuk baris yang menyokong pilihan.\nCatat atau nyatakan dua pasangan nilai–bukti secara individu.\nHasil individu: Slip individu atau catatan respons lisan dua nilai dengan bukti.\nKriteria: Kedua-dua padanan tepat; menamakan nilai sahaja belum memenuhi objektif.\nSusulan: Jika keliru nilai dan tindakan, jelaskan tindakan dahulu; jika tepat, cuba rangkap kemudahan tanpa kad.","aids_and_pak21_original":"BBM/ABM: Jalur Mesti tekun belajar dan Usah mengganggu kawan-kawanmu di sebelah\nKad tekun belajar serta hormat-menghormati\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},"pembina":{"label":"Langkah 1\nPembina — buktikan tafsiran sendiri","implementation_original":"Tugasan: Baca empat rangkap dan pilih dua nilai untuk dijelaskan, termasuk rangkap ketiga atau keempat yang ruang nilainya belum lengkap. Gunakan kata sendiri dengan bukti lirik supaya jawapan tidak sekadar menyalin dua label tersedia.\nBahan: BT70 keseluruhan lirik\nSlip dua ruang nilai dan bukti\nBimbingan guru: Tanya apakah hubungan menjaga kemudahan dengan tanggungjawab bersama.\nBenarkan semakan rakan sekali, kemudian minta keputusan dan catatan individu.\nLangkah murid: Baca semua rangkap dan pilih dua perlakuan penting.\nNamakan nilai yang sesuai bagi setiap perlakuan.\nPetik atau tunjuk baris lirik yang menyokongnya.\nTerangkan padanan kepada pasangan lalu tulis jawapan sendiri.\nHasil individu: Dua pasangan nilai–bukti individu yang dapat dijejak pada teks.\nKriteria: Dua nilai tepat, bukti relevan dan satu daripada rangkap akhir.\nSusulan: Jika bukti tersalah rangkap, baca semula perlakuan; jika kukuh, bandingkan dua tafsiran munasabah.","aids_and_pak21_original":"BBM/ABM: BT70 keseluruhan lirik\nSlip dua ruang nilai dan bukti\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."},"pencabar":{"label":"Langkah 1\nPencabar — nilai berlainan, bukti yang sama","implementation_original":"Tugasan: Uji sama ada baris Usah mengganggu kawan-kawanmu di sebelah boleh menyokong hormat-menghormati atau bertimbang rasa. Pilih tafsiran yang boleh dijelaskan, kemudian nyatakan nilai kedua daripada rangkap lain dengan bukti sendiri.\nBahan: Kad hormat-menghormati dan bertimbang rasa sebagai cadangan guru\nBT70 dan slip bukti\nBimbingan guru: Tanya bagaimana tidak mengganggu menjaga keperluan rakan belajar.\nJangan menetapkan satu label tunggal; tarik balik kad apabila murid dapat memberi alasan teks.\nLangkah murid: Baca baris larangan dalam konteks seluruh rangkap.\nBandingkan dua label nilai dan pilih yang dapat dibuktikan.\nJelaskan hubungan tindakan dengan nilai secara lisan.\nTulis dua pasangan nilai–bukti daripada rangkap berlainan secara individu.\nHasil individu: Slip dua nilai serta penerangan perbandingan ringkas.\nKriteria: Dua padanan objektif mesti tepat; perbandingan istilah ialah perluasan, bukan ujian istilah moral semata-mata.\nSusulan: Jika alasan terlalu umum, minta rujukan perkataan usah mengganggu atau jagalah sebelum meneruskan.","aids_and_pak21_original":"BBM/ABM: Kad hormat-menghormati dan bertimbang rasa sebagai cadangan guru\nBT70 dan slip bukti\nPAK-21: Cari Bukti Berpasangan: pembaca menyatakan nilai, penyemak meminta bukti; tukar peranan dan hasilkan slip individu."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan respons individu selepas membaca lirik, secara bertulis atau lisan.","Evidens":"Dua pasangan nilai–baris bukti bagi setiap murid.","Kriteria Kejayaan":"Dua nilai tepat dengan bukti relevan, termasuk satu daripada rangkap ketiga atau keempat; tiada markah nyanyian."},"closure_original":"Tindakan guru: Gunakan soalan buku Nyatakan nilai baik yang diamalkan di sekolah kamu.\nMinta murid menghubungkan contoh tindakan dengan baris sumber, misalnya tidak mengganggu pembaca.\nTindakan murid: Nyatakan satu tindakan yang sesuai diamalkan.\nTunjukkan nilai dan baris lirik yang mendasari tindakan itu.\nSemakan: Contoh amalan meluaskan kefahaman tetapi tidak menggantikan bukti dua nilai individu.\nBahan: Lirik dan slip hasil murid.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M36-S2.docx","source_docx_sha256":"12ecb80f980e9a020a5e446806650a0134c1f969095c021a4f209c2e07e87ee1","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":36,"session":2,"revision":"r2","title_original":"Marilah Kawan-kawanku","sk_original":"2.3 Membaca dan mengapresiasi karya sastera dan bukan sastera","sp_original":"2.3.1","sp_support_original":"—","objective_original":"Murid dapat menyatakan nilai baik daripada seni kata lagu Marilah Kawan-kawanku.","success_criteria_original":"Membaca rangkap pilihan dengan bantuan jika perlu.; Menyatakan satu nilai yang sesuai dengan rangkap.","textbook_pages_original":"m/s 70","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca tajuk Marilah Kawan-kawanku.\nTanya: Bagaimanakah kita mendengar semasa guru mengajar?\nTindakan murid: Baca tajuk bersama guru.\nKongsi satu perbuatan yang baik.\nSemakan: Terima jawapan seperti beri perhatian atau tidak mengganggu kawan.\nBahan: BT70.","BBM/ABM":"BT70.","PAK-21":"Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},"six_phases_original":[{"phase_original":"Langkah 1\nPeraturan sekolah","execution_original":"Tindakan guru: Baca tajuk Marilah Kawan-kawanku.\nTanya: Bagaimanakah kita mendengar semasa guru mengajar?\nTindakan murid: Baca tajuk bersama guru.\nKongsi satu perbuatan yang baik.\nSemakan: Terima jawapan seperti beri perhatian atau tidak mengganggu kawan.\nBahan: BT70.","aids_and_pak21_original":"BBM/ABM: BT70.\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},{"phase_original":"Langkah 2\nGuru contohkan nilai","execution_original":"Tindakan guru: Baca dua rangkap awal bersama nilai yang tercetak.\nTunjuk padanan Mesti tekun belajar dengan nilai Tekun belajar.\nTindakan murid: Ikut bacaan guru.\nSebut nilai pada rangkap kedua.\nSemakan: Guru jelaskan nilai sebagai sikap baik yang diajar oleh lagu.\nBahan: BT70.","aids_and_pak21_original":"BBM/ABM: BT70.\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},{"phase_original":"Langkah 3\nBaca rangkap dengan pasangan","execution_original":"Tindakan guru: Baca rangkap Usah mengganggu kawan-kawanmu di sebelah.\nBaca rangkap Jagalah kemudahan di sekolah.\nTindakan murid: Baca kedua-dua rangkap bergilir dengan pasangan.\nPadankan frasa tidak mengganggu kawan dengan kad hormat.\nSemakan: Cadangan guru: hormat untuk rakan, tanggungjawab untuk kemudahan.\nBahan: BT70; kad nilai; kad frasa.","aids_and_pak21_original":"BBM/ABM: BT70; kad nilai; kad frasa.\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},{"phase_original":"Langkah 4\nCuba menyatakan nilai","execution_original":"Tindakan guru: Jalankan tiga pilihan bantuan di bawah semasa bacaan pasangan.\nBantu murid melengkapkan Nilai baik dalam rangkap ini ialah....\nTindakan murid: Pilih satu rangkap untuk dibaca semula.\nSebut nilai rangkap pada giliran sendiri.\nSemakan: Terima ungkapan mudah seperti menghormati kawan atau menjaga barang sekolah.\nBahan: BT70; kad nilai.","aids_and_pak21_original":"BBM/ABM: BT70; kad nilai.\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},{"phase_original":"Langkah 5\nSemakan kecil","execution_original":"Tindakan guru: Dengar satu jawapan daripada murid yang belum diperhatikan.\nCatat padanan nilai dan bantuan membaca.\nTindakan murid: Tunjuk rangkap pilihan.\nSebut satu nilai baik daripada rangkap itu.\nSemakan: Nilai sesuai dengan rangkap yang dipilih.\nBahan: Senarai semak; BT70.","aids_and_pak21_original":"BBM/ABM: Senarai semak; BT70.\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Baca semula Jagalah kemudahan di sekolah.\nTanya: Apakah barang sekolah yang perlu kita jaga?\nTindakan murid: Sebut nilai tanggungjawab bersama-sama.\nNamakan satu barang sekolah.\nSemakan: Guru kaitkan nilai lagu dengan amalan harian.\nBahan: BT70.","aids_and_pak21_original":"BBM/ABM: BT70.\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Baca bersama guru","implementation_original":"Tugasan: Baca rangkap tentang rakan sebelum menyebut nilai hormat.\nBahan: BT70\nKad hormat\nKad tidak mengganggu kawan\nBimbingan guru: Baca rangkap satu baris demi satu baris.\nTerangkan hormat dengan contoh memberi kawan peluang mendengar.\nLangkah murid: Ikut bacaan guru.\nPadankan frasa tidak mengganggu kawan dengan hormat.\nSebut nilai hormat dengan bantuan ayat guru.\nHasil individu: Satu respons lisan tentang nilai rangkap.\nKriteria: Murid menyebut nilai yang sesuai walaupun dibantu.\nSusulan: Baca semula baris yang sama sebelum mencuba rangkap lain.","aids_and_pak21_original":"BBM/ABM: BT70\nKad hormat\nKad tidak mengganggu kawan\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},"pembina":{"label":"Langkah 1\nPembina — Padan dengan pasangan","implementation_original":"Tugasan: Pilih nilai untuk satu rangkap selepas bacaan berpasangan.\nBahan: BT70\nKad hormat dan tanggungjawab\nBimbingan guru: Bantu membaca perkataan kemudahan.\nTanya Apakah sikap baik dalam rangkap ini?\nLangkah murid: Baca rangkap pilihan bersama pasangan.\nPilih kad nilai yang sesuai.\nSebut nilai itu pada giliran sendiri.\nHasil individu: Satu jawapan lisan individu tentang nilai lagu.\nKriteria: Hormat dipadankan dengan rakan atau tanggungjawab dengan kemudahan.\nSusulan: Kekalkan kad nilai sehingga murid boleh memilih dengan yakin.","aids_and_pak21_original":"BBM/ABM: BT70\nKad hormat dan tanggungjawab\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."},"pencabar":{"label":"Langkah 1\nPencabar — Satu nilai lagi","implementation_original":"Tugasan: Jika bersedia, nyatakan nilai daripada satu rangkap lagi.\nBahan: BT70\nKad nilai jika perlu\nBimbingan guru: Cadangkan rangkap yang belum dipilih.\nBantu murid menggunakan istilah nilai yang mudah.\nLangkah murid: Baca rangkap tambahan.\nCari perbuatan baik dalam rangkap.\nSebut satu nilai yang sesuai.\nHasil individu: Satu respons nilai tambahan pilihan.\nKriteria: Nilai tambahan sesuai dengan rangkap yang dibaca.\nSusulan: Tidak perlu menambah jawapan jika bacaan utama masih memerlukan bantuan.","aids_and_pak21_original":"BBM/ABM: BT70\nKad nilai jika perlu\nPAK-21: Baca dan padan berpasangan: murid memadankan perbuatan dalam lirik dengan nilai baik."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian bacaan dan respons lisan individu semasa latihan.","Evidens":"Satu nilai yang disebut selepas membaca rangkap pilihan.","Kriteria Kejayaan":"Murid menyatakan nilai baik yang sesuai dengan rangkap lagu."},"closure_original":"Tindakan guru: Baca semula Jagalah kemudahan di sekolah.\nTanya: Apakah barang sekolah yang perlu kita jaga?\nTindakan murid: Sebut nilai tanggungjawab bersama-sama.\nNamakan satu barang sekolah.\nSemakan: Guru kaitkan nilai lagu dengan amalan harian.\nBahan: BT70.","reflection_original":"__ daripada __ murid dapat menyatakan nilai baik daripada seni kata lagu. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M36-S2.docx","source_docx_sha256":"3a63d42348c8092a7c244d2075afffd5b36d561d5d6605bec358e87dfd153234","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M36-S3","week_no":36,"session_no":3,"lesson_map":{"title":"Menghargai Masa","sp":"3.3.2","page":71,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":36,"session":3,"revision":"r1","title_original":"Menghargai Masa","sk_original":"3.3 Menghasilkan penulisan","sp_original":"3.3.2","sp_support_original":"—","objective_original":"Setiap murid mengedit empat daripada lima penggunaan kata sasaran dalam Menghargai Masa dan menulis semula ayat berkaitan dengan kata gantian yang tepat, sambil mengekalkan perkataan lain yang sudah sesuai.","success_criteria_original":"Sekurang-kurangnya empat pembetulan tepat mengikut maksud ayat.; Ayat dimurnikan, bukan sekadar senarai pasangan kata.; Perkataan sesuai dikekalkan; bantuan pilihan kata direkod.","textbook_pages_original":"m/s 71","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca tepati dan gunakan jam dengan baiknya; tanya Adakah nasihat ini tentang alat atau pengurusan waktu?\nTunjuk tajuk Menghargai Masa dan modelkan pilihan masa sebagai konsep yang dimaksudkan.\nTindakan murid: Baca ayat akhir serta tajuk untuk menentukan konteks.\nJelaskan jam ialah alat, manakala masa berkaitan waktu melakukan aktiviti.\nSemakan: Minta alasan makna, bukan bunyi sedap sahaja.\nBahan: BT71 dan kad jam–masa.","BBM/ABM":"BT71 dan kad jam–masa.","PAK-21":"Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: masa bukan alat jam","execution_original":"Tindakan guru: Baca tepati dan gunakan jam dengan baiknya; tanya Adakah nasihat ini tentang alat atau pengurusan waktu?\nTunjuk tajuk Menghargai Masa dan modelkan pilihan masa sebagai konsep yang dimaksudkan.\nTindakan murid: Baca ayat akhir serta tajuk untuk menentukan konteks.\nJelaskan jam ialah alat, manakala masa berkaitan waktu melakukan aktiviti.\nSemakan: Minta alasan makna, bukan bunyi sedap sahaja.\nBahan: BT71 dan kad jam–masa.","aids_and_pak21_original":"BBM/ABM: BT71 dan kad jam–masa.\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},{"phase_original":"Langkah 2\nBacaan: fahami dahulu sebelum mengedit","execution_original":"Tindakan guru: Bimbing bacaan teks tentang tiba awal, menyiapkan kerja dan memulangkan buku.\nTanya Apakah yang berlaku jika kerja dilengah-lengahkan? Model jawapan Kerja semakin banyak, lalu kaitkan dengan sasaran bertingkat.\nTindakan murid: Baca keseluruhan teks dan kenal pasti nasihat utama.\nTandakan lima kata sasaran dengan pensel tanpa memadam perkataan lain.\nSemakan: Tegaskan istilah yang disasarkan kurang sesuai konteks, bukan semestinya salah ejaan.\nBahan: BT71 dan lima penanda sasaran.","aids_and_pak21_original":"BBM/ABM: BT71 dan lima penanda sasaran.\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},{"phase_original":"Langkah 3\nPemodelan: ganti kata, pulihkan ayat","execution_original":"Tindakan guru: Tukar loceng berbising kepada loceng berbunyi, kemudian modelkan ayat lengkap yang munasabah: Mereka perlu membiasakan diri untuk hadir sekurang-kurangnya 15 minit sebelum loceng berbunyi. Jelaskan pemurnian sedia kepada hadir ialah bantuan tambahan, bukan alasan membiarkan ayat janggal.\nBandingkan menepati masa yang sesuai dengan mahulah yang perlu menjadi mestilah; terangkan maksud kewajipan.\nTindakan murid: Salin satu model ayat yang dimurnikan sambil mengekalkan bahagian lain.\nSebut alasan berbunyi sesuai untuk loceng dan tunjuk perkataan yang tidak perlu diganti.\nSemakan: Jika murid memadam seluruh ayat, tunjuk semula sempadan satu kata sasaran.\nBahan: Jalur ayat loceng, jalur mahulah dan pen dua warna.","aids_and_pak21_original":"BBM/ABM: Jalur ayat loceng, jalur mahulah dan pen dua warna.\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},{"phase_original":"Langkah 4\nLatihan terbeza: meja penyunting","execution_original":"Tindakan guru: Laksanakan tiga laluan menyunting ayat sama; arahkan semakan makna sebelum menulis.\nTanya Adakah Hutang sesuai bagi bayaran lewat memulangkan buku? Bimbing pilihan Denda tanpa menukar fakta lain.\nTindakan murid: Ikuti langkah laluan dan cadangkan kata gantian dengan alasan.\nBaca ayat yang dimurnikan kepada pasangan lalu baiki cadangan sendiri.\nSemakan: Terima kata gantian yang gramatis dan bermakna. Lima sasaran bukan semua kesalahan teks; pemurnian sampingan dibimbing jika perlu, tetapi tidak menggandakan markah sasaran.\nBahan: Bank kata, jalur ayat dan kertas latihan.","aids_and_pak21_original":"BBM/ABM: Bank kata, jalur ayat dan kertas latihan.\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},{"phase_original":"Langkah 5\nPBD: suntingan ayat individu","execution_original":"Tindakan guru: Edarkan lima ayat asal berkaitan sasaran tanpa kata digaris atau bank jawapan.\nMinta murid tanda kata kurang sesuai dan tulis semula ayat; soal satu alasan untuk membezakan faham daripada menyalin.\nTindakan murid: Pilih kata yang perlu diubah, kemudian tulis lima ayat dimurnikan.\nSemak bahagian betul masih kekal dan jelaskan satu pembetulan kepada guru.\nSemakan: Nilai empat pembetulan tepat bersama pemurnian ayat, bukan bilangan perkataan ditukar.\nBahan: Lima ayat asal dan kertas individu bernama.","aids_and_pak21_original":"BBM/ABM: Lima ayat asal dan kertas individu bernama.\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},{"phase_original":"Langkah 6\nPenutup: editor tidak menukar semuanya","execution_original":"Tindakan guru: Minta satu contoh kata diganti dan satu frasa dikekalkan.\nRumuskan baca konteks, pilih kata, kemudian baca semula ayat lengkap.\nTindakan murid: Sebut bertingkat kepada bertambah serta frasa menepati masa yang dikekalkan.\nNyatakan langkah semakan yang masih perlu dilatih.\nSemakan: Catat kecenderungan mengganti semua kata untuk intervensi khusus.\nBahan: Hasil suntingan dan senarai semak.","aids_and_pak21_original":"BBM/ABM: Hasil suntingan dan senarai semak.\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — pilihan berdasarkan maksud","implementation_original":"Tugasan: Sunting lima ayat dengan pilihan kata berpasangan dan penanda sasaran sementara. Murid perlu membaca ayat lengkap selepas mengganti kata; menyalin bank jawapan tanpa memahami konteks belum menjadi pemurnian penulisan.\nBahan: Pilihan berbunyi/berlari, bertambah/terbang dan Denda/Hadiah\nJalur ayat serta penjejak bacaan\nBimbingan guru: Tanya Apakah yang dibuat loceng? dan Adakah kerja menjadi lebih banyak?\nTutup pilihan selepas alasan tepat, kemudian minta murid membina semula ayat tanpa model.\nLangkah murid: Baca ayat dan sebut maksud yang hendak disampaikan.\nPilih kata gantian yang sepadan dengan maksud.\nPotong kata sasaran sekali dan tulis pembetulan di atasnya.\nTulis ayat dimurnikan sambil mengekalkan perkataan sesuai.\nHasil individu: Lima ayat individu dengan jejak pembetulan dan bantuan direkod.\nKriteria: Empat pembetulan tepat dalam ayat memenuhi objektif; pilihan kad sahaja belum mencukupi.\nSusulan: Jika alasan masih rawak, gunakan satu ayat dahulu; jika tepat, kurangkan penanda sasaran.","aids_and_pak21_original":"BBM/ABM: Pilihan berbunyi/berlari, bertambah/terbang dan Denda/Hadiah\nJalur ayat serta penjejak bacaan\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},"pembina":{"label":"Langkah 1\nPembina — edit mengikut konteks","implementation_original":"Tugasan: Kenal pasti lima penggunaan kata kurang sesuai dan pilih pengganti tanpa bank jawapan. Murid memastikan perubahan membantu maksud nasihat tentang masa, bukan menghias teks dengan sinonim yang tidak diperlukan.\nBahan: Lima ayat asal BT71\nPen warna berbeza untuk teks asal dan pembetulan\nBimbingan guru: Tanya sebab mestilah lebih sesuai daripada mahulah dalam nasihat kewajipan.\nBerikan pertanyaan semakan sahaja selepas draf, tanpa menentukan kata akhir murid.\nLangkah murid: Baca ayat penuh sebelum menandakan kata.\nTulis cadangan gantian dan jelaskan maksud kepada pasangan.\nTulis semula ayat dengan kata yang dipilih.\nBandingkan dengan asal untuk memastikan isi serta perkataan sesuai dikekalkan.\nHasil individu: Lima ayat dimurnikan dan satu alasan pembetulan individu.\nKriteria: Sekurang-kurangnya empat kata diperbetul tepat dalam ayat; isi asal tidak berubah.\nSusulan: Jika kata gantian gramatis tetapi maksud berubah, baca konteks perenggan; jika tepat, audit suntingan berlebihan.","aids_and_pak21_original":"BBM/ABM: Lima ayat asal BT71\nPen warna berbeza untuk teks asal dan pembetulan\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."},"pencabar":{"label":"Langkah 1\nPencabar — bezakan pembetulan dan perubahan sia-sia","implementation_original":"Tugasan: Sunting lima sasaran dan audit cadangan guru yang menukar menepati masa kepada menepati meja. Murid perlu menolak perubahan tidak munasabah serta mempertahankan frasa asal yang betul dengan alasan konteks.\nBahan: BT71 dan lima ayat sasaran\nKad suntingan salah menepati meja, berlabel latihan guru\nBimbingan guru: Tanya sama ada perubahan menjadikan nasihat lebih tepat atau merosakkan maksud.\nSimpan kad audit sebelum murid menghasilkan ayat akhir secara kendiri.\nLangkah murid: Kenal pasti lima kata sasaran dalam ayat.\nCadangkan pengganti dan baca ayat penuh dengan suara perlahan.\nTolak suntingan menepati meja serta jelaskan mengapa masa dikekalkan.\nTulis lima ayat dimurnikan dan semak tiada perubahan isi yang tidak perlu.\nHasil individu: Ayat individu yang disunting serta alasan mempertahankan frasa betul.\nKriteria: Empat pembetulan tepat tetap sasaran; audit suntingan berlebihan ialah perluasan.\nSusulan: Jika murid menukar banyak kata tanpa alasan, hadkan semula kepada bukti konteks bagi setiap perubahan.","aids_and_pak21_original":"BBM/ABM: BT71 dan lima ayat sasaran\nKad suntingan salah menepati meja, berlabel latihan guru\nPAK-21: Editor Berpasangan: pembaca menjelaskan maksud, editor mencadangkan kata dan alasan; bertukar peranan sebelum pemurnian individu."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan hasil suntingan dan pemurnian ayat individu.","Evidens":"Lima ayat asal bertanda serta lima ayat dimurnikan oleh murid.","Kriteria Kejayaan":"Empat daripada lima kata sasaran diperbetul tepat dalam ayat, dengan perkataan sesuai serta maksud asal dikekalkan."},"closure_original":"Tindakan guru: Minta satu contoh kata diganti dan satu frasa dikekalkan.\nRumuskan baca konteks, pilih kata, kemudian baca semula ayat lengkap.\nTindakan murid: Sebut bertingkat kepada bertambah serta frasa menepati masa yang dikekalkan.\nNyatakan langkah semakan yang masih perlu dilatih.\nSemakan: Catat kecenderungan mengganti semua kata untuk intervensi khusus.\nBahan: Hasil suntingan dan senarai semak.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M36-S3.docx","source_docx_sha256":"bfdd121efe99bd3790b6e849b5d1e82b91697abd95fe81cfaea308da3e9e731e","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":36,"session":3,"revision":"r2","title_original":"Menghargai Masa","sk_original":"3.3 Menghasilkan penulisan","sp_original":"3.3.2","sp_support_original":"—","objective_original":"Murid dapat membaiki penggunaan kata dalam ayat mudah.","success_criteria_original":"Menggantikan tiga kata dengan kata yang sesuai.; Membaca semula ayat selepas dibaiki.","textbook_pages_original":"m/s 71","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Menghargai Masa.\nGuru tanya, “Bilakah loceng sekolah berbunyi?”\nTindakan murid: Murid melihat buku.\nMurid memberi jawapan berdasarkan rutin sekolah.\nSemakan: Bantu murid menyebut perkataan loceng.\nBahan: Buku teks halaman 71","BBM/ABM":"Buku teks halaman 71","PAK-21":"Semakan berpasangan untuk memilih perkataan yang sesuai."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali tajuk","execution_original":"Tindakan guru: Guru tunjuk tajuk Menghargai Masa.\nGuru tanya, “Bilakah loceng sekolah berbunyi?”\nTindakan murid: Murid melihat buku.\nMurid memberi jawapan berdasarkan rutin sekolah.\nSemakan: Bantu murid menyebut perkataan loceng.\nBahan: Buku teks halaman 71","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 71\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."},{"phase_original":"Langkah 2\nDengar contoh","execution_original":"Tindakan guru: Guru baca ayat murid-murid mahulah menepati masa.\nGuru ganti mahulah dengan mestilah sebagai contoh pembetulan.\nTindakan murid: Murid mengulang ayat yang dibaiki.\nMurid menyebut perkataan mestilah.\nSemakan: Terangkan bahawa kita memilih kata yang lebih sesuai dengan maksud ayat.\nBahan: Ayat pada papan putih","aids_and_pak21_original":"BBM/ABM: Ayat pada papan putih\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."},{"phase_original":"Langkah 3\nBaiki bersama","execution_original":"Tindakan guru: Guru baiki contoh ringkas “Loceng sekolah berbising.” kepada “Loceng sekolah berbunyi.”\nGuru baiki “Kerja itu akan bertingkat.” kepada “Kerja itu akan bertambah.”\nGuru baiki “Gunakan jam dengan baiknya.” kepada “Gunakan masa dengan baiknya.”\nTindakan murid: Murid membaca ayat selepas pembetulan.\nMurid memadankan kad dengan bahagian ayat yang sesuai.\nSemakan: Tiga ayat dipendekkan untuk latihan. Baca semula ayat asal bersama guru selepas latihan.\nBahan: Buku teks\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad perkataan\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri tiga ayat yang sama dengan kata sasaran bergaris.\nGuru bantu pasangan memilih berbunyi, bertambah dan masa.\nTindakan murid: Murid membaca ayat kepada rakan.\nMurid memilih kata yang sesuai sebelum bertukar giliran.\nSemakan: Bantu satu ayat pada satu masa.\nBahan: Lembaran latihan\nKad kata","aids_and_pak21_original":"BBM/ABM: Lembaran latihan\nKad kata\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."},{"phase_original":"Langkah 5\nTulis pembetulan","execution_original":"Tindakan guru: Guru beri lembaran individu tiga ayat.\nGuru semak kata gantian semasa murid menulis.\nTindakan murid: Murid menggantikan tiga kata yang bergaris.\nMurid membaca semula ayat yang telah dibaiki.\nSemakan: Tidak perlu menyalin seluruh petikan.\nBahan: Lembaran individu","aids_and_pak21_original":"BBM/ABM: Lembaran individu\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru baca semula tiga ayat yang betul.\nGuru ajak murid menyebut satu amalan menepati masa.\nTindakan murid: Murid mengikuti bacaan.\nMurid berkongsi satu amalan baik.\nSemakan: Ulang kata yang masih mengelirukan.\nBahan: Ayat pada papan putih","aids_and_pak21_original":"BBM/ABM: Ayat pada papan putih\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Memilih kata yang sesuai dengan bantuan guru.\nBahan: Kad berbunyi, bertambah dan masa\nAyat dengan ruang kosong\nBimbingan guru: Guru baca satu ayat dahulu.\nGuru beri dua pilihan kata pada satu masa.\nLangkah murid: Dengar ayat guru.\nPilih kad yang sesuai.\nLengkapkan ayat dan baca bersama guru.\nHasil individu: Ayat yang dibaiki dengan bantuan.\nKriteria: Kata dipilih mengikut maksud ayat.\nSusulan: Ulang ayat tentang loceng sebelum mencuba yang lain.","aids_and_pak21_original":"BBM/ABM: Kad berbunyi, bertambah dan masa\nAyat dengan ruang kosong\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Menggantikan tiga kata dalam ayat pendek.\nBahan: Lembaran tiga ayat\nKad kata rujukan\nBimbingan guru: Guru beri satu contoh.\nGuru bantu jika murid masih keliru tentang maksud.\nLangkah murid: Baca dengan rakan.\nPilih kata gantian.\nTulis pembetulan sendiri.\nHasil individu: Tiga kata gantian pada lembaran.\nKriteria: Kata berbunyi, bertambah dan masa digunakan dengan sesuai.\nSusulan: Baca semula ayat untuk menyemak maksud.","aids_and_pak21_original":"BBM/ABM: Lembaran tiga ayat\nKad kata rujukan\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Membaiki satu ayat tentang pemulangan buku.\nBahan: Ayat Hutang akan dikenakan sekiranya buku pinjaman lewat dipulangkan.\nKad denda\nBimbingan guru: Guru terangkan denda ialah bayaran kerana melanggar peraturan.\nGuru bantu menggantikan Hutang dengan Denda.\nLangkah murid: Baca ayat bersama guru.\nPilih kata denda.\nSebut ayat yang telah dibaiki.\nHasil individu: Satu pembetulan lisan tambahan.\nKriteria: Kata gantian sesuai dengan maksud ayat.\nSusulan: Gunakan ayat mudah tanpa meminta alasan panjang.","aids_and_pak21_original":"BBM/ABM: Ayat Hutang akan dikenakan sekiranya buku pinjaman lewat dipulangkan.\nKad denda\nPAK-21: Semakan berpasangan untuk memilih perkataan yang sesuai."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan lembaran pembetulan.","Evidens":"Tiga kata gantian setiap murid.","Kriteria Kejayaan":"Tiga kata digantikan dengan kata yang sesuai."},"closure_original":"Tindakan guru: Guru baca semula tiga ayat yang betul.\nGuru ajak murid menyebut satu amalan menepati masa.\nTindakan murid: Murid mengikuti bacaan.\nMurid berkongsi satu amalan baik.\nSemakan: Ulang kata yang masih mengelirukan.\nBahan: Ayat pada papan putih","reflection_original":"__ daripada __ murid dapat membaiki penggunaan kata dalam ayat. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M36-S3.docx","source_docx_sha256":"50d333aebec76cf0baa388c298277c6c67dda397baebdefb25422fa7605efb37","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M36-S4","week_no":36,"session_no":4,"lesson_map":{"title":"Amal Sikap Terpuji","sp":"4.3.3","page":72,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":36,"session":4,"revision":"r1","title_original":"Amal Sikap Terpuji","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan kesantunan bahasa serta mempersembahkannya secara kreatif","sp_original":"4.3.3","sp_support_original":"—","objective_original":"Setiap murid mempersembahkan petikan Amal Sikap Terpuji mengikut irama Jong Jong Inai dengan menyanyikan empat baris sasaran secara jelas dan berterusan sambil menghasilkan sekurang-kurangnya enam daripada lapan tepukan mengikut denyut lagu yang dimodelkan guru.","success_criteria_original":"Empat baris sasaran dinyanyikan dengan lirik tepat dan aliran melodi, bukan dibaca sahaja.; Sekurang-kurangnya enam tepukan bertepatan dalam jendela lapan denyut pemerhatian.; Nyanyian dan tepukan berlaku serentak; bantuan nada mula dicatat.","textbook_pages_original":"m/s 72","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tepuk denyut perlahan sambil menunjuk lapan bulatan; minta murid ikut tanpa berlumba.\nTanya Adakah tepukan paling kuat yang paling tepat? Jelaskan ketepatan rentak lebih penting daripada kekuatan.\nTindakan murid: Ikut tepukan setempat dengan ruang tangan sendiri.\nBandingkan tepukan teratur dengan tepukan tergesa-gesa yang dimodelkan guru.\nSemakan: Jika murid mempercepat, ulang denyut perlahan sebelum memasukkan melodi.\nBahan: Kad lapan bulatan dan demonstrasi tepukan.","BBM/ABM":"Kad lapan bulatan dan demonstrasi tepukan.","PAK-21":"Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: denyut yang teratur","execution_original":"Tindakan guru: Tepuk denyut perlahan sambil menunjuk lapan bulatan; minta murid ikut tanpa berlumba.\nTanya Adakah tepukan paling kuat yang paling tepat? Jelaskan ketepatan rentak lebih penting daripada kekuatan.\nTindakan murid: Ikut tepukan setempat dengan ruang tangan sendiri.\nBandingkan tepukan teratur dengan tepukan tergesa-gesa yang dimodelkan guru.\nSemakan: Jika murid mempercepat, ulang denyut perlahan sebelum memasukkan melodi.\nBahan: Kad lapan bulatan dan demonstrasi tepukan.","aids_and_pak21_original":"BBM/ABM: Kad lapan bulatan dan demonstrasi tepukan.\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 2\nPemodelan: melodi dan lirik rakyat","execution_original":"Tindakan guru: Nyanyikan petikan BT72 mengikut irama Jong Jong Inai tanpa tepukan dahulu.\nModelkan empat baris sasaran dan tanya Siapakah yang dihormati? Jawapan Cikgu dan rakan; jelaskan sebutan dihormati.\nTindakan murid: Jejak lirik sambil mendengar melodi guru.\nNyanyikan semula satu baris kemudian sambung baris berikut dengan sebutan jelas.\nSemakan: Jika respons menjadi bacaan, ulang model melodi satu frasa sebelum mencuba lagi.\nBahan: BT72, paparan lirik dan suara langsung guru.","aids_and_pak21_original":"BBM/ABM: BT72, paparan lirik dan suara langsung guru.\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 3\nLatihan gabungan: suara sambil tepuk","execution_original":"Tindakan guru: Gabungkan nyanyian dengan tepukan sederhana pada denyut tetap; isyaratkan jendela lapan denyut.\nTanya Adakah suara masih terdengar apabila tangan bertepuk? Modelkan tepukan lebih lembut jika lirik tenggelam.\nTindakan murid: Nyanyikan empat baris sasaran sambil mengekalkan tepukan.\nTukar peranan penyanyi dan pemerhati; beri semakan tentang aliran suara atau tepukan.\nSemakan: Asingkan masalah melodi daripada koordinasi, kemudian gabungkan semula; tepuk sahaja belum mencapai tugasan.\nBahan: Lirik sasaran dan kad denyut.","aids_and_pak21_original":"BBM/ABM: Lirik sasaran dan kad denyut.\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 4\nBengkel terbeza: koordinasi persembahan","execution_original":"Tindakan guru: Jalankan laluan berasingan sementara melodi/tepukan untuk Peneroka, rentak kendiri Pembina dan keseimbangan kelantangan Pencabar. Semua mesti kembali kepada nyanyian sambil bertepuk sebelum PBD.\nKurangkan isyarat guru secara bertahap. Jika murid berhenti menyanyi untuk mengira lapan bulatan, guru menjejak denyut; murid mengekalkan frasa Hormati cikgu hormati rakan sambil bertepuk sederhana.\nTindakan murid: Ikuti langkah laluan bagi memperkemas suara serta tepukan.\nUlang bahagian sukar dengan pasangan tanpa menambah lirik sendiri.\nSemakan: Jika murid berhenti menyanyi untuk mengira bulatan, guru mengambil alih penjejak supaya suara diteruskan.\nBahan: BT72, kad bulatan dan ruang latihan setempat.","aids_and_pak21_original":"BBM/ABM: BT72, kad bulatan dan ruang latihan setempat.\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 5\nPBD: empat baris dan lapan denyut","execution_original":"Tindakan guru: Dengar murid bergilir menyanyi empat baris sasaran sambil bertepuk dengan lirik tersedia. Bukti boleh direkod sejak latihan; tidak perlu menunggu semua persembahan di hadapan kelas.\nTanda satu jendela lapan denyut berturutan, ketepatan lirik dan kesinambungan melodi. Catat nada mula atau isyarat tambahan; individu belum sempat diperhatikan kekal ditanda susulan, bukan mewarisi markah kumpulan.\nTindakan murid: Persembahkan petikan seorang diri dengan tepukan sederhana.\nTeruskan nyanyian hingga hujung petikan dan dengar maklum balas khusus.\nSemakan: Perhatikan suara dan tepukan individu; persembahan kumpulan bukan pengganti bukti.\nBahan: Paparan lirik dan senarai semak individu.","aids_and_pak21_original":"BBM/ABM: Paparan lirik dan senarai semak individu.\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 6\nPenutup: kerjasama dalam lagu","execution_original":"Tindakan guru: Pimpin bahagian Amalkan sikap bekerjasama dan Kerja yang sukar akan menjadi mudah.\nMinta satu cadangan mengekalkan tepukan tanpa menenggelamkan suara rakan.\nTindakan murid: Nyanyi dan bertepuk bersama secara sederhana.\nNyatakan sama ada perlu latihan melodi atau koordinasi seterusnya.\nSemakan: Tentukan susulan tanpa menganggap nyanyian kelas bukti semua murid menguasai.\nBahan: BT72 keseluruhan lirik dan catatan guru.","aids_and_pak21_original":"BBM/ABM: BT72 keseluruhan lirik dan catatan guru.\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — gabung selepas stabil","implementation_original":"Tugasan: Latih melodi dan tepukan secara berasingan sebentar, kemudian gabungkan dalam petikan yang sama. Pecahan latihan menyokong koordinasi, tetapi hasil akhir tetap menyanyi sambil bertepuk, bukan memilih satu kemahiran sahaja.\nBahan: Lirik empat baris berjarak\nKad lapan bulatan dengan penjejak guru\nBimbingan guru: Nyanyikan satu baris untuk digemakan, kemudian modelkan tepukan perlahan tanpa suara.\nGabungkan kedua-duanya dan kurangkan bantuan kepada nada mula serta isyarat pertama sahaja.\nLangkah murid: Nyanyikan frasa Hormati cikgu hormati rakan dengan jelas.\nIkut denyut tepukan sambil mendengar model guru.\nGabungkan suara dengan tepukan, bermula satu baris kemudian sambung petikan.\nPersembahkan empat baris sendiri sambil guru memerhati lapan denyut.\nHasil individu: Persembahan individu dengan rekod suara, tepukan dan bantuan.\nKriteria: Empat baris tepat dan enam tepukan selaras memenuhi objektif; latihan berasingan sahaja belum mencukupi.\nSusulan: Jika koordinasi pecah, perlahan tempo latihan kemudian kembali kepada model persembahan.","aids_and_pak21_original":"BBM/ABM: Lirik empat baris berjarak\nKad lapan bulatan dengan penjejak guru\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},"pembina":{"label":"Langkah 1\nPembina — rentak kendiri yang bersambung","implementation_original":"Tugasan: Nyanyikan petikan empat baris sambil bertepuk pada denyut tetap tanpa penjejak berterusan. Pasangan memerhati supaya murid mengetahui sama ada tepukan mendahului suara atau suara terhenti ketika bertepuk.\nBahan: BT72 dan paparan empat baris\nKad semakan suara bersambung–tepukan selaras\nBimbingan guru: Berikan nada mula dan contoh satu sambungan frasa yang tidak terputus.\nHentikan tepukan model semasa percubaan kedua untuk menguji rentak kendiri.\nLangkah murid: Baca lirik sasaran dan ingat urutannya.\nNyanyikan sambil bertepuk dengan kekuatan sederhana.\nDengar semakan pasangan tentang satu bahagian yang tersasar.\nBaiki bahagian itu dan persembahkan semula secara individu.\nHasil individu: Nyanyian individu serentak dengan tepukan yang boleh diperhatikan.\nKriteria: Empat baris jelas dan tepat serta enam daripada lapan denyut tepukan selaras.\nSusulan: Jika tepukan stabil tetapi lirik kabur, latih sebutan dihormati dalam frasa sebelum gabungan semula.","aids_and_pak21_original":"BBM/ABM: BT72 dan paparan empat baris\nKad semakan suara bersambung–tepukan selaras\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."},"pencabar":{"label":"Langkah 1\nPencabar — seimbangkan suara dan tepukan","implementation_original":"Tugasan: Kekalkan melodi serta denyut sambil memilih kekuatan tepukan yang membolehkan mesej hormat didengar. Selepas petikan sasaran mantap, cuba bahagian kerjasama tanpa mengubah lirik atau menjadikan tepukan hiasan yang mengganggu lagu.\nBahan: BT72 seluruh lirik\nKad petunjuk suara jelas dan tepukan sederhana\nBimbingan guru: Tanya bagaimana pendengar dapat memahami lirik jika tepukan menutup suara.\nTarik balik kad setelah murid dapat mengawal keseimbangan sendiri dan mengekalkan denyut.\nLangkah murid: Persembahkan petikan sasaran dengan tepukan biasa.\nDengar semakan sama ada perkataan dihormati jelas.\nLaraskan kekuatan tepukan tanpa mempercepat denyut.\nPersembahkan sendiri, kemudian cuba sambungan bahagian kerjasama.\nHasil individu: Persembahan individu dengan keseimbangan suara–tepukan serta sambungan pilihan.\nKriteria: Rubrik empat baris dan enam tepukan tetap sama; keseimbangan serta sambungan ialah perluasan mutu.\nSusulan: Jika kawalan kekuatan mengganggu irama, kembali kepada denyut sederhana yang stabil sebelum perluasan.","aids_and_pak21_original":"BBM/ABM: BT72 seluruh lirik\nKad petunjuk suara jelas dan tepukan sederhana\nPAK-21: Pasangan Penyanyi–Pemerhati: seorang menyanyi sambil bertepuk, seorang menjejak denyut dan menyebut satu pembaikan; tukar peranan sebelum persembahan individu."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian nyanyian dan tepukan serentak secara individu.","Evidens":"Rekod empat baris sasaran dan jendela lapan denyut bagi setiap penyanyi.","Kriteria Kejayaan":"Empat baris dinyanyikan tepat, jelas dan berterusan dengan enam daripada lapan tepukan mengikut denyut Jong Jong Inai yang dimodelkan."},"closure_original":"Tindakan guru: Pimpin bahagian Amalkan sikap bekerjasama dan Kerja yang sukar akan menjadi mudah.\nMinta satu cadangan mengekalkan tepukan tanpa menenggelamkan suara rakan.\nTindakan murid: Nyanyi dan bertepuk bersama secara sederhana.\nNyatakan sama ada perlu latihan melodi atau koordinasi seterusnya.\nSemakan: Tentukan susulan tanpa menganggap nyanyian kelas bukti semua murid menguasai.\nBahan: BT72 keseluruhan lirik dan catatan guru.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M36-S4.docx","source_docx_sha256":"a4df55ab27a00b6e55870a4ebd98f428eabc2e74b87221a393658514d5a1141d","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":36,"session":4,"revision":"r2","title_original":"Amal Sikap Terpuji","sk_original":"4.3 Menghasilkan bahan sastera dengan menyerapkan keindahan dan kesantunan bahasa serta mempersembahkannya secara kreatif","sp_original":"4.3.3","sp_support_original":"—","objective_original":"Murid dapat menyanyikan lagu Amal Sikap Terpuji sambil bertepuk tangan mengikut rentak.","success_criteria_original":"Menyanyikan bahagian lagu yang dilatih.; Mengikut rentak tepukan dengan bantuan guru jika perlu.","textbook_pages_original":"m/s 72","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tepuk rentak yang perlahan dan tetap.\nGuru ajak murid mengikut tepukan.\nTindakan murid: Murid mendengar rentak.\nMurid mengikut tepukan guru.\nSemakan: Perlahankan tempo jika murid belum dapat mengikut.\nBahan: Tepukan guru","BBM/ABM":"Tepukan guru","PAK-21":"Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},"six_phases_original":[{"phase_original":"Langkah 1\nTepuk bersama","execution_original":"Tindakan guru: Guru tepuk rentak yang perlahan dan tetap.\nGuru ajak murid mengikut tepukan.\nTindakan murid: Murid mendengar rentak.\nMurid mengikut tepukan guru.\nSemakan: Perlahankan tempo jika murid belum dapat mengikut.\nBahan: Tepukan guru","aids_and_pak21_original":"BBM/ABM: Tepukan guru\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},{"phase_original":"Langkah 2\nDengar lagu","execution_original":"Tindakan guru: Guru nyanyikan bahagian awal menggunakan irama Jong Jong Inai yang dinyatakan dalam buku.\nGuru baca sebutan amalkan dan terpuji dengan jelas.\nTindakan murid: Murid mendengar nyanyian.\nMurid mengulang perkataan yang dibaca guru.\nSemakan: Gunakan contoh guru; tidak memerlukan audio QR.\nBahan: Buku teks halaman 72","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 72\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},{"phase_original":"Langkah 3\nNyanyi bersama","execution_original":"Tindakan guru: Guru nyanyi “Hai, hai, kawan, amalkan sikap terpuji” untuk diikuti kelas.\nGuru sambung “Sikap yang baik amalkanlah selalu.”\nTindakan murid: Murid menyanyi selepas guru.\nMurid mengulang bahagian awal bersama-sama.\nSemakan: Ulang perlahan sehingga murid dapat mengikut.\nBahan: Kad lirik","aids_and_pak21_original":"BBM/ABM: Kad lirik\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},{"phase_original":"Langkah 4\nTambah tepukan","execution_original":"Tindakan guru: Guru tunjuk tepukan semasa menyanyi bahagian yang sama.\nGuru bantu kumpulan kecil memulakan lagu.\nTindakan murid: Murid menyanyi sambil mengikut tepukan.\nMurid bergilir memulakan nyanyian dalam kumpulan.\nSemakan: Murid boleh cuba nyanyian dan tepukan berasingan dahulu.\nBahan: Kad lirik\nContoh guru","aids_and_pak21_original":"BBM/ABM: Kad lirik\nContoh guru\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},{"phase_original":"Langkah 5\nPersembahan ringkas","execution_original":"Tindakan guru: Guru dengar setiap murid semasa persembahan kumpulan kecil.\nGuru beri bantuan rentak kepada murid yang memerlukan.\nTindakan murid: Murid menyanyi bahagian yang dilatih.\nMurid bertepuk tangan mengikut rentak guru atau kumpulan.\nSemakan: Catat percubaan setiap murid sepanjang latihan, bukan kumpulan sahaja.\nBahan: Senarai nama","aids_and_pak21_original":"BBM/ABM: Senarai nama\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru nyanyikan baris tentang hormat dan kerjasama.\nGuru tanya satu contoh bekerjasama.\nTindakan murid: Murid menyertai nyanyian penutup.\nMurid menyebut satu amalan baik.\nSemakan: Puji keberanian mencuba.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Menyanyi dan bertepuk dengan contoh perlahan.\nBahan: Kad lirik\nGuru duduk berhampiran kumpulan\nBimbingan guru: Guru nyanyi satu baris pada satu masa.\nGuru tunjuk tepukan perlahan sebelum menggabungkannya dengan lagu.\nLangkah murid: Ikut satu baris nyanyian.\nCuba tepukan bersama guru.\nGabungkan nyanyian dan tepukan dengan bantuan.\nHasil individu: Percubaan nyanyian sambil bertepuk.\nKriteria: Murid dapat mengikut sebahagian rentak selepas contoh.\nSusulan: Ulang bahagian pendek yang sama tanpa mempercepat tempo.","aids_and_pak21_original":"BBM/ABM: Kad lirik\nGuru duduk berhampiran kumpulan\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Menyanyikan bahagian awal sambil bertepuk tangan.\nBahan: Kad lirik\nContoh nyanyian guru\nBimbingan guru: Guru beri isyarat mula.\nGuru kekalkan rentak supaya mudah diikuti.\nLangkah murid: Latih nyanyian bersama kumpulan.\nTambah tepukan.\nPersembahkan bahagian lagu yang dilatih.\nHasil individu: Nyanyian dengan tepukan setiap murid.\nKriteria: Nyanyian dan tepukan mengikut rentak yang dicontohkan.\nSusulan: Ulang latihan secara perlahan jika tepukan terlepas.","aids_and_pak21_original":"BBM/ABM: Kad lirik\nContoh nyanyian guru\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Memulakan lagu untuk diikuti rakan.\nBahan: Kad lirik bahagian awal\nBimbingan guru: Guru bantu memberi isyarat mula.\nGuru ingatkan murid mengekalkan tempo yang selesa.\nLangkah murid: Dengar rentak guru.\nMulakan satu baris lagu.\nTeruskan nyanyian dan tepukan bersama rakan.\nHasil individu: Satu giliran memulakan lagu.\nKriteria: Rakan dapat mengikuti tempo yang sama.\nSusulan: Beri peluang kepada murid lain selepas satu giliran.","aids_and_pak21_original":"BBM/ABM: Kad lirik bahagian awal\nPAK-21: Nyanyian berkumpulan kecil dengan giliran memulakan lagu."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian semasa nyanyian dan latihan kumpulan.","Evidens":"Nyanyian serta tepukan setiap murid.","Kriteria Kejayaan":"Murid menyanyi sambil mengikut rentak dengan bantuan jika perlu."},"closure_original":"Tindakan guru: Guru nyanyikan baris tentang hormat dan kerjasama.\nGuru tanya satu contoh bekerjasama.\nTindakan murid: Murid menyertai nyanyian penutup.\nMurid menyebut satu amalan baik.\nSemakan: Puji keberanian mencuba.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat menyanyi sambil bertepuk tangan mengikut rentak. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M36-S4.docx","source_docx_sha256":"d1fc76b41f47797dad4fa609600959007003d6bc16828d7197d9e702e2d4d1a7","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M36-S5","week_no":36,"session_no":5,"lesson_map":{"title":"Menjaga Adab di Perpustakaan","sp":"5.2.3","page":73,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":36,"session":5,"revision":"r1","title_original":"Menjaga Adab di Perpustakaan","sk_original":"5.2 Memahami dan menggunakan pembentukan kata mengikut konteks","sp_original":"5.2.3","sp_support_original":"—","objective_original":"Setiap murid dapat bercerita tentang suasana dan adab di perpustakaan dalam sekurang-kurangnya empat ayat berkaitan, menggunakan tiga kata ganda dengan makna yang tepat berdasarkan petikan serta gambar BT73.","success_criteria_original":"Cerita mempunyai urutan kegiatan, bukan senarai kata ganda.; Tiga kata ganda digunakan tepat dalam sekurang-kurangnya empat ayat berkaitan.; Penggunaan tidak berbual-bual mengekalkan adab; bantuan dicatat.","textbook_pages_original":"m/s 73","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk gambar perpustakaan pada BT73 dan tanya kata yang sesuai untuk murid yang sedang membaca.\nBandingkan contoh murid dengan murid-murid serta tunjuk papan tanda tolong senyap; elakkan menyatakan jumlah pembaca yang tidak dikira.\nTindakan murid: Sebut satu ayat tentang murid dalam gambar menggunakan kata ganda yang sesuai.\nCari satu objek yang boleh diterangkan, misalnya rak atau buku, dan bezakan daripada tindakan berbisik.\nSemakan: Jika murid menyebut burung sebenar terbang di perpustakaan, tunjuk panel gambar pemandangan; konteks objek mesti tepat.\nBahan: Gambar BT73, petikan dan papan tanda.","BBM/ABM":"Gambar BT73, petikan dan papan tanda.","PAK-21":"Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},"six_phases_original":[{"phase_original":"Langkah 1\nInduksi: seorang atau ramai","execution_original":"Tindakan guru: Tunjuk gambar perpustakaan pada BT73 dan tanya kata yang sesuai untuk murid yang sedang membaca.\nBandingkan contoh murid dengan murid-murid serta tunjuk papan tanda tolong senyap; elakkan menyatakan jumlah pembaca yang tidak dikira.\nTindakan murid: Sebut satu ayat tentang murid dalam gambar menggunakan kata ganda yang sesuai.\nCari satu objek yang boleh diterangkan, misalnya rak atau buku, dan bezakan daripada tindakan berbisik.\nSemakan: Jika murid menyebut burung sebenar terbang di perpustakaan, tunjuk panel gambar pemandangan; konteks objek mesti tepat.\nBahan: Gambar BT73, petikan dan papan tanda.","aids_and_pak21_original":"BBM/ABM: Gambar BT73, petikan dan papan tanda.\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 2\nPenerokaan: kata dalam konteks perpustakaan","execution_original":"Tindakan guru: Baca petikan Elis dan rakan-rakannya mengulang kaji serta tidak berbual-bual. Tunjuk murid berbisik pada gambar dan bezakan suara perlahan daripada berbual bising.\nBincang rangsangan terang/warna/rak: contoh guru terang-benderang, berwarna-warni dan rak-rak. Rama-rama ialah kata ganda semu; bentuknya tidak menentukan bilangan haiwan pada panel.\nTindakan murid: Cari dua bentuk ganda daripada teks dan padankan kad tambahan dengan bahagian gambar yang sebenar.\nNyatakan bahawa burung/gunung/rama-rama ialah unsur panel pemandangan, manakala buku dan rak berada dalam bilik.\nSemakan: Jangan mengubah mesej tidak berbual-bual menjadi cerita bising. Bentuk ganda harus sesuai dengan benda, tindakan atau suasana yang dirujuk.\nBahan: BT73 serta kad kata rangsangan dan bentuk ganda.","aids_and_pak21_original":"BBM/ABM: BT73 serta kad kata rangsangan dan bentuk ganda.\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 3\nPemodelan: kata menjadi cerita","execution_original":"Tindakan guru: Modelkan contoh guru: Elis dan rakan-rakannya ke perpustakaan. Murid-murid membaca dengan tekun. Buku yang berwarna-warni tersusun pada rak-rak. Mereka menjaga ketenangan dan tidak berbual-bual.\nTanya bagaimana ayat-ayat itu berkaitan; model merupakan olahan guru daripada petikan/gambar, bukan empat ayat bercetak yang perlu dihafal.\nTindakan murid: Kenal pasti kata ganda yang digunakan dan tunjuk objek atau perbuatan yang menyokongnya.\nRancang satu sambungan sendiri tentang panel pemandangan atau perbuatan berbisik, dengan memastikan ia masih menjaga konteks adab.\nSemakan: Jika kata ganda hanya menjadi senarai, minta murid menambah pelaku atau benda serta tindakannya supaya ayat membentuk cerita.\nBahan: Gambar asal BT73 dan model lisan guru berlabel.","aids_and_pak21_original":"BBM/ABM: Gambar asal BT73 dan model lisan guru berlabel.\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 4\nLatihan terbeza: bengkel pencerita","execution_original":"Tindakan guru: Jalankan tiga laluan bercerita menggunakan gambar BT73 yang sama, dengan kad bantuan berbeza.\nTanya Bahagian gambar mana? dan Bagaimana ayat ini bersambung? semasa pasangan berlatih; kurangkan rangka apabila murid dapat mengaitkan tiga kata ganda dalam cerita.\nTindakan murid: Pilih tiga kata ganda yang sesuai dan rancang suasana, bahan bacaan, kegiatan murid serta adab.\nBercerita kepada pasangan, tukar peranan, kemudian perbaiki satu ayat yang salah rujukan atau tidak bersambung.\nSemakan: Setiap murid perlu bercakap, bukan sekadar melengkapkan kad kumpulan. Cerita tidak boleh menukar panel burung kepada burung hidup dalam perpustakaan.\nBahan: BT73, kad rangsangan dan rangka bantuan tiga laluan.","aids_and_pak21_original":"BBM/ABM: BT73, kad rangsangan dan rangka bantuan tiga laluan.\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 5\nPBD: cerita perpustakaan individu","execution_original":"Tindakan guru: Dengar cerita individu semasa latihan dan giliran akhir dengan gambar BT73 tersedia, tanpa teks jawapan penuh.\nCatat empat ayat berkaitan serta tiga kata ganda yang benar-benar digunakan oleh murid. Murid belum didengar ditanda belum diperhatikan, bukan dianggap menguasai daripada cerita rakan.\nTindakan murid: Bercerita empat ayat atau lebih berdasarkan petikan dan gambar dengan tiga kata ganda bermakna.\nTunjuk bukti gambar bagi satu ayat apabila guru meminta penjelasan, kemudian sambung cerita tanpa bantuan suara pasangan.\nSemakan: Nilai penggunaan kata dalam cerita lisan, bukan hafalan model atau bilangan perkataan yang digaris. Pembetulan rujukan panel dan makna tidak direkod sebagai kegagalan total jika aspek lain sudah tepat.\nBahan: Gambar asal BT73 dan senarai semak nama.","aids_and_pak21_original":"BBM/ABM: Gambar asal BT73 dan senarai semak nama.\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},{"phase_original":"Langkah 6\nPenutup: adab dalam ayat","execution_original":"Tindakan guru: Tanya Bagaimana berbual-bual boleh digunakan untuk menunjukkan adab baik?\nRumuskan contoh Mereka tidak berbual-bual dan kaitkan dengan teks.\nTindakan murid: Sebut satu ayat cerita yang menggunakan kata ganda tepat.\nNyatakan pembaikan cerita selepas mendengar pasangan.\nSemakan: Catat pengguguran tidak untuk susulan makna ayat.\nBahan: Kad berbual-bual dan catatan cerita.","aids_and_pak21_original":"BBM/ABM: Kad berbual-bual dan catatan cerita.\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Gambar asal dan rangka lisan","implementation_original":"Tugasan: Bina cerita berpandukan gambar BT73 dan rangka siapa–buat apa. Bantuan memandu urutan serta kata ganda; murid masih menghasilkan cerita sendiri, bukan menyebut kad tanpa hubungan.\nBahan: Gambar asal perpustakaan BT73\nKad rakan-rakan/murid-murid/rak-rak/berbual-bual\nRangka Elis dan …; Buku …; Murid-murid …; Mereka tidak …\nBimbingan guru: Tanya Siapa datang? Apa dilakukan? dan Bahan apa kelihatan? sambil menunjuk gambar sebenar.\nTutup rangka selepas latihan dan kekalkan hanya gambar serta kad kata, supaya ayat akhir dibina murid.\nLangkah murid: Pilih empat perkara berkaitan daripada petikan/gambar, bukan menyusun gambar rekaan.\nSebut ayat lengkap bagi murid, buku atau rak dengan kata ganda.\nTambah ayat adab yang sesuai dengan papan tanda tolong senyap.\nCeritakan empat ayat bersambung secara individu dengan sekurang-kurangnya tiga kata ganda.\nHasil individu: Cerita lisan individu dengan catatan tiga kata ganda dan bantuan.\nKriteria: Empat ayat berkaitan serta tiga kata ganda tepat memenuhi objektif; senarai sahaja belum mencukupi.\nSusulan: Jika ayat terputus, gunakan soalan kemudian; jika lancar, hilangkan rangka sepenuhnya.","aids_and_pak21_original":"BBM/ABM: Gambar asal perpustakaan BT73\nKad rakan-rakan/murid-murid/rak-rak/berbual-bual\nRangka Elis dan …; Buku …; Murid-murid …; Mereka tidak …\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},"pembina":{"label":"Langkah 1\nPembina — cerita dengan semakan pendengar","implementation_original":"Tugasan: Ceritakan kegiatan serta suasana perpustakaan berdasarkan petikan dan gambar asal. Hubungkan kata ganda dengan watak, bahan bacaan serta tindakan; jangan memaksa semua rangsangan digunakan jika tidak sesuai cerita.\nBahan: BT73 dan kad kata rangsangan\nKad semakan hubungan ayat–makna kata–bukti gambar\nBimbingan guru: Tanya bagaimana rak-rak atau berwarna-warni menerangkan buku dalam gambar dan bezakan daripada panel pemandangan.\nBenarkan satu semakan pasangan, kemudian hentikan bantuan ketika cerita individu.\nLangkah murid: Pilih tiga kata ganda yang difahami daripada bahan.\nRancang permulaan, kegiatan membaca dan penutup adab.\nBercerita kepada pasangan dengan sekurang-kurangnya empat ayat.\nBaiki satu ayat berdasarkan semakan dan ceritakan semula sendiri.\nHasil individu: Cerita individu dengan tiga penggunaan kata ganda yang dapat dicatat guru.\nKriteria: Kata ganda tepat konteks dalam empat ayat berkaitan; sebutan kata terasing tidak dikira penggunaan.\nSusulan: Jika kata dipaksa masuk, pilih semula tindakan sesuai; jika tepat, tambah sebab menjaga ketenangan.","aids_and_pak21_original":"BBM/ABM: BT73 dan kad kata rangsangan\nKad semakan hubungan ayat–makna kata–bukti gambar\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."},"pencabar":{"label":"Langkah 1\nPencabar — Cerita dengan rujukan yang tepat","implementation_original":"Tugasan: Kembangkan cerita dengan satu ayat tentang panel pemandangan atau perbuatan berbisik, sambil mengekalkan mesej adab. Jelaskan mengapa gambar burung, gunung dan rama-rama tidak boleh diceritakan sebagai benda sebenar di dalam bilik.\nBahan: Gambar BT73\nKad rangsangan burung/gunung/rama-rama/bisik\nKad “pada panel gambar” untuk bantuan rujukan\nBimbingan guru: Tanya beza burung-burung pada panel dengan burung-burung terbang dalam perpustakaan; minta bukti sebelum menerima ayat.\nKurangkan petunjuk selepas murid menunjukkan rujukan yang tepat dan biarkan mereka memilih tiga kata ganda untuk cerita sendiri.\nLangkah murid: Rancang empat ayat atau lebih yang berkaitan dengan perpustakaan.\nPilih kata ganda yang sepadan benda, perasaan, keadaan atau tindakan dalam sumber.\nTambah ayat panel pemandangan atau berbisik dengan rujukan jelas dan adab sesuai.\nCeritakan sendiri dan jelaskan satu pilihan kata serta bukti gambar kepada guru.\nHasil individu: Cerita lisan individu dengan tiga kata ganda serta penjelasan satu rujukan gambar yang tepat.\nKriteria: Objektif empat ayat dan tiga kata tepat tetap digunakan; sambungan serta alasan ialah perluasan.\nSusulan: Jika ayat melampaui gambar, gunakan frasa pada panel atau dalam gambar, kemudian ulang cerita tanpa mengubah mesej adab.","aids_and_pak21_original":"BBM/ABM: Gambar BT73\nKad rangsangan burung/gunung/rama-rama/bisik\nKad “pada panel gambar” untuk bantuan rujukan\nPAK-21: Pencerita–Pendengar: pasangan menyebut satu kata ganda yang didengar dan meminta sambungan; tukar peranan sebelum persembahan individu."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian cerita lisan individu dengan gambar asal BT73 sebagai sokongan.","Evidens":"Catatan urutan cerita dan kata ganda sebenar setiap murid; lembaran persediaan bukan bukti utama.","Kriteria Kejayaan":"Sekurang-kurangnya empat ayat berkaitan dan tiga kata ganda tepat makna serta konteks perpustakaan."},"closure_original":"Tindakan guru: Tanya Bagaimana berbual-bual boleh digunakan untuk menunjukkan adab baik?\nRumuskan contoh Mereka tidak berbual-bual dan kaitkan dengan teks.\nTindakan murid: Sebut satu ayat cerita yang menggunakan kata ganda tepat.\nNyatakan pembaikan cerita selepas mendengar pasangan.\nSemakan: Catat pengguguran tidak untuk susulan makna ayat.\nBahan: Kad berbual-bual dan catatan cerita.","reflection_original":"____ / ____ murid mencapai objektif; ____ belum diperhatikan; bantuan: ____; susulan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M36-S5.docx","source_docx_sha256":"eb4eee5ae426f1eb45afd2b9a83cf1a32ca08d52793413866ff37abd642319ed","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":36,"session":5,"revision":"r2","title_original":"Menjaga Adab di Perpustakaan","sk_original":"5.2 Memahami dan menggunakan pembentukan kata mengikut konteks","sp_original":"5.2.3","sp_support_original":"—","objective_original":"Murid dapat bercerita tentang perpustakaan menggunakan kata ganda.","success_criteria_original":"Bercerita dengan dua ayat mudah berdasarkan gambar.; Menggunakan dua kata ganda yang sesuai.","textbook_pages_original":"m/s 73","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk gambar perpustakaan.\nGuru tanya, “Apakah yang murid sedang buat?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut membaca buku.\nSemakan: Bantu murid menamakan rak dan buku.\nBahan: Buku teks halaman 73","BBM/ABM":"Buku teks halaman 73","PAK-21":"Bercerita berpasangan tentang gambar perpustakaan."},"six_phases_original":[{"phase_original":"Langkah 1\nLihat perpustakaan","execution_original":"Tindakan guru: Guru tunjuk gambar perpustakaan.\nGuru tanya, “Apakah yang murid sedang buat?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut membaca buku.\nSemakan: Bantu murid menamakan rak dan buku.\nBahan: Buku teks halaman 73","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 73\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."},{"phase_original":"Langkah 2\nKenali kata ganda","execution_original":"Tindakan guru: Guru baca petikan tentang Elis dan rakan-rakannya.\nGuru contohkan murid menjadi murid-murid dan rak menjadi rak-rak.\nTindakan murid: Murid mengikuti bacaan.\nMurid mengulang kata ganda.\nSemakan: Tunjuk gambar untuk menjelaskan maksud.\nBahan: Buku teks\nKad kata ganda","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad kata ganda\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."},{"phase_original":"Langkah 3\nCerita bersama","execution_original":"Tindakan guru: Guru beri contoh “Murid-murid membaca buku di perpustakaan.”\nGuru sambung “Buku disusun pada rak-rak.”\nTindakan murid: Murid mengulang dua ayat cerita.\nMurid menunjukkan murid dan rak yang disebut.\nSemakan: Pastikan murid menyampaikan cerita, bukan menyebut senarai kata sahaja.\nBahan: Rangka dua ayat\nGambar buku","aids_and_pak21_original":"BBM/ABM: Rangka dua ayat\nGambar buku\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri kad murid-murid dan rak-rak kepada pasangan.\nGuru bantu murid memulakan ayat jika perlu.\nTindakan murid: Murid bercerita menggunakan dua kata ganda.\nMurid bertukar giliran sebagai pencerita dan pendengar.\nSemakan: Rangka ayat boleh dirujuk sepanjang latihan.\nBahan: Kad kata ganda","aids_and_pak21_original":"BBM/ABM: Kad kata ganda\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."},{"phase_original":"Langkah 5\nCerita sendiri","execution_original":"Tindakan guru: Guru dengar cerita murid semasa bergerak antara pasangan.\nGuru bantu murid yang belum dapat melengkapkan ayat.\nTindakan murid: Murid menyampaikan dua ayat tentang gambar.\nMurid mencuba semula ayat yang dibantu.\nSemakan: Catat penggunaan kata ganda setiap murid.\nBahan: Gambar buku\nSenarai nama","aids_and_pak21_original":"BBM/ABM: Gambar buku\nSenarai nama\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru tunjuk papan tanda tolong senyap.\nGuru tanya cara bercakap yang sesuai di perpustakaan.\nTindakan murid: Murid menyebut bercakap perlahan.\nMurid mengulang kata murid-murid dan rak-rak.\nSemakan: Kaitkan adab dengan aktiviti membaca.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Melengkapkan cerita dengan dua kad kata ganda.\nBahan: ___ membaca buku.\nBuku disusun pada ___.\nKad murid-murid dan rak-rak\nBimbingan guru: Guru baca awal ayat.\nGuru tunjuk gambar bagi setiap kata.\nLangkah murid: Pilih kad yang sesuai.\nUlang ayat bersama guru.\nCeritakan dua ayat kepada rakan dengan bantuan.\nHasil individu: Cerita lisan berpandu.\nKriteria: Kata ganda digunakan dalam ayat yang sesuai.\nSusulan: Ulang dua ayat yang sama dalam kumpulan kecil.","aids_and_pak21_original":"BBM/ABM: ___ membaca buku.\nBuku disusun pada ___.\nKad murid-murid dan rak-rak\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Bercerita menggunakan murid-murid dan rak-rak.\nBahan: Gambar buku\nKad kata ganda\nBimbingan guru: Guru beri satu contoh cerita pendek.\nGuru bantu jika murid terlupa perkataan.\nLangkah murid: Lihat gambar.\nLatih dua ayat dengan rakan.\nCeritakan sendiri menggunakan kad jika perlu.\nHasil individu: Dua ayat cerita lisan.\nKriteria: Dua kata ganda sesuai dengan gambar.\nSusulan: Baca semula rangka jika ayat belum lengkap.","aids_and_pak21_original":"BBM/ABM: Gambar buku\nKad kata ganda\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menambah satu ayat menggunakan berbisik-bisik.\nBahan: Gambar murid berbisik\nKad berbisik-bisik\nBimbingan guru: Guru tunjuk murid berbisik dalam gambar.\nGuru beri contoh “Murid itu berbisik-bisik dengan rakannya.”\nLangkah murid: Lihat gambar yang ditunjukkan.\nCuba satu ayat dengan berbisik-bisik.\nTambah ayat pada cerita jika sesuai.\nHasil individu: Satu ayat lisan tambahan.\nKriteria: Kata ganda sesuai dengan tindakan dalam gambar.\nSusulan: Ingatkan murid bahawa bercakap perlahan tidak boleh mengganggu pembaca lain.","aids_and_pak21_original":"BBM/ABM: Gambar murid berbisik\nKad berbisik-bisik\nPAK-21: Bercerita berpasangan tentang gambar perpustakaan."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian ketika bercerita berpasangan.","Evidens":"Cerita lisan setiap murid.","Kriteria Kejayaan":"Dua kata ganda digunakan dalam dua ayat yang sesuai."},"closure_original":"Tindakan guru: Guru tunjuk papan tanda tolong senyap.\nGuru tanya cara bercakap yang sesuai di perpustakaan.\nTindakan murid: Murid menyebut bercakap perlahan.\nMurid mengulang kata murid-murid dan rak-rak.\nSemakan: Kaitkan adab dengan aktiviti membaca.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat bercerita menggunakan kata ganda. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M36-S5.docx","source_docx_sha256":"9bc2ab72dc85206cada65d2446e4894f4e826aa4efa5d1d056425217e4d34563","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":36,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M37-S1","week_no":37,"session_no":1,"lesson_map":{"title":"Hargailah Kemudahan","sp":"1.2.2","page":75,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":37,"session":1,"revision":"r1","title_original":"Hargailah Kemudahan","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.2","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat menjelaskan secara lisan dua pasangan maklumat tersurat dan tafsiran tersirat yang munasabah daripada dialog Elis serta notis tuala Hotel Gemilang, dengan menyebut bukti bagi setiap tafsiran.","success_criteria_original":"Dua maklumat tersurat disebut tepat, misalnya tuala digantung untuk digunakan lagi dan tuala diletakkan dalam bakul untuk ditukar.; Setiap tafsiran mempunyai kaitan yang dapat dijelaskan dengan ayat notis atau pesanan Puan Zaidah; tidak menambah kadar bayaran atau peraturan hotel yang tiada dalam bahan.; Murid menggunakan ayat penerangan yang dapat difahami dan sekurang-kurangnya satu penghubung seperti kerana atau supaya; jenis bantuan dicatat.","textbook_pages_original":"m/s 75","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjukkan kad GANTUNG dan BAKUL. Bacakan dua arahan daripada notis tanpa memberi alasan; tanya, ‘Tuala yang hendak digunakan lagi perlu diletakkan di mana?’\nMinta satu murid menerangkan pilihannya. Jika murid belum mengenal istilah bakul, tunjuk lambang dan baca semula frasa yang berkaitan.\nTindakan murid: Angkat atau tunjuk kad mengikut arahan yang didengar; sebut ‘gantung’ atau ‘bakul’ dengan ayat pendek.\nBezakan jawapan yang benar-benar disebut dalam arahan daripada tekaan tentang sebabnya.\nSemakan: Semak kefahaman dua arahan dahulu. Murid yang tertukar kad menerima bacaan ulang, bukan terus diberi soalan inferens.\nBahan: Kad GANTUNG/BAKUL dan notis BT75.","BBM/ABM":"Kad GANTUNG/BAKUL dan notis BT75.","PAK-21":"Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Dua tempat untuk tuala","execution_original":"Tindakan guru: Tunjukkan kad GANTUNG dan BAKUL. Bacakan dua arahan daripada notis tanpa memberi alasan; tanya, ‘Tuala yang hendak digunakan lagi perlu diletakkan di mana?’\nMinta satu murid menerangkan pilihannya. Jika murid belum mengenal istilah bakul, tunjuk lambang dan baca semula frasa yang berkaitan.\nTindakan murid: Angkat atau tunjuk kad mengikut arahan yang didengar; sebut ‘gantung’ atau ‘bakul’ dengan ayat pendek.\nBezakan jawapan yang benar-benar disebut dalam arahan daripada tekaan tentang sebabnya.\nSemakan: Semak kefahaman dua arahan dahulu. Murid yang tertukar kad menerima bacaan ulang, bukan terus diberi soalan inferens.\nBahan: Kad GANTUNG/BAKUL dan notis BT75.","aids_and_pak21_original":"BBM/ABM: Kad GANTUNG/BAKUL dan notis BT75.\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},{"phase_original":"Langkah 2\nModelkan — Daripada ujaran kepada tafsiran","execution_original":"Tindakan guru: Baca dialog Elis dan Puan Zaidah. Tunjuk contoh buku ‘Wah, selesanya bilik ini, ibu!’ dan tafsiran bahawa Elis berasa seronok; jelaskan bahawa rasa seronok disimpulkan daripada ujarannya.\nModelkan jalur: bukti ‘banyak air digunakan’ → contoh tafsiran guru ‘Menggunakan tuala sekali lagi dapat mengurangkan basuhan.’ Tegaskan tafsiran perlu munasabah, bukan petikan yang diulang tanpa penjelasan.\nTindakan murid: Gariskan satu frasa bukti pada salinan guru atau tunjuk pada buku sendiri, tanpa menconteng buku pinjaman.\nSebut semula satu pasangan bukti–tafsiran dengan kata sendiri; pasangan memeriksa sama ada bukti itu memang terdapat dalam bahan.\nSemakan: Jika murid hanya mengulang arahan, tanya ‘Apakah kesannya?’ Jika mereka menambah denda, minta mereka mencari ayat yang membuktikannya.\nBahan: Dialog dan notis BT75; jalur Bukti–Tafsiran.","aids_and_pak21_original":"BBM/ABM: Dialog dan notis BT75; jalur Bukti–Tafsiran.\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},{"phase_original":"Langkah 3\nLatihan terbeza — Pusat penerangan Hotel Gemilang","execution_original":"Tindakan guru: Agihkan laluan sokongan, teras atau cabaran secara fleksibel berdasarkan respons awal. Semua murid tetap menyediakan dua pasangan maklumat untuk diterangkan secara lisan; gunakan perincian PdP terbeza di bawah.\nMulakan dengan murid yang memerlukan rangka ayat. Kemudian dengar pasangan lain dan tanya ‘Ayat mana menyokong alasan kamu?’ Catat sama ada alasan diberi sendiri atau selepas petunjuk.\nTindakan murid: Bekerja berpasangan sebagai pengunjung dan petugas. Pengunjung bertanya tentang tuala atau penjagaan barang; petugas menjawab menggunakan bukti dan sebab yang relevan.\nTukar peranan selepas satu penerangan supaya kedua-duanya bercakap. Baiki tafsiran yang tidak dapat disokong sebelum mencuba pasangan maklumat kedua.\nSemakan: Pilih dua pasangan maklumat yang berbeza, bukan mengulang contoh ‘bilik selesa’ dua kali. Jangan menerima jawapan kumpulan sebagai bukti semua ahli menguasai.\nBahan: Kad notis, rangka pilihan, jalur Bukti–Tafsiran dan senarai semak lisan.","aids_and_pak21_original":"BBM/ABM: Kad notis, rangka pilihan, jalur Bukti–Tafsiran dan senarai semak lisan.\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},{"phase_original":"Langkah 4\nUji dakwaan — Bukti atau rekaan?","execution_original":"Tindakan guru: Paparkan dakwaan guru ‘Hotel mengenakan denda RM10 jika tuala tidak digantung.’ Minta murid menilai sama ada bahan membolehkan dakwaan itu dibuat.\nTerima penolakan berserta alasan, bukan sekadar jawapan ‘salah’. Bandingkan dengan contoh munasabah ‘Menggunakan semula tuala membantu mengurangkan penggunaan air untuk membasuh.’\nTindakan murid: Seorang membaca bukti, seorang menilai dakwaan. Nyatakan ‘Notis menyebut … tetapi tidak menyebut …’.\nUbah satu dakwaan tidak disokong menjadi penerangan yang berpaut pada ayat notis tanpa mereka peraturan baharu.\nSemakan: Pastikan murid tahu bahawa tersirat bukan lesen menambah fakta sesuka hati. Soalan ini penjelasan lisan, bukan ujian harga atau polisi hotel.\nBahan: Kad dakwaan tanpa bukti dan notis asal.","aids_and_pak21_original":"BBM/ABM: Kad dakwaan tanpa bukti dan notis asal.\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},{"phase_original":"Langkah 5\nPBD — Dua penerangan individu","execution_original":"Tindakan guru: Dengar giliran individu sambil murid lain berlatih perlahan dengan pasangan. Setiap giliran menyebut dua bukti dan dua tafsiran ringkas; guru boleh merujuk bukti yang telah dicatat semasa latihan.\nTanda tepat/belum tepat serta bantuan yang digunakan. Murid yang belum sempat didengar ditanda ‘belum diperhatikan’ dan disambung pada peluang lisan seterusnya.\nTindakan murid: Terangkan satu pilihan tindakan berkaitan tuala dan satu maklumat lain daripada notis atau dialog; sebut bukti sebelum atau selepas alasan.\nDengar soalan penjelasan guru dan perbaiki ayat sendiri, tanpa pasangan membisikkan jawapan.\nSemakan: Objektif memerlukan dua pasangan maklumat dengan alasan, bukan dua tindakan sahaja. Catatan rakan menyokong latihan tetapi tidak menggantikan pemerhatian guru.\nBahan: BT75, jalur kata kunci dan borang catatan lisan individu.","aids_and_pak21_original":"BBM/ABM: BT75, jalur kata kunci dan borang catatan lisan individu.\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},{"phase_original":"Langkah 6\nPenutup — Pesanan untuk pengunjung","execution_original":"Tindakan guru: Minta kelas melengkapkan ‘Saya akan … kerana …’ dengan satu tindakan daripada notis.\nRumusan: tersurat ialah yang dinyatakan; tersirat ialah maksud atau sebab yang disimpulkan dengan bukti. Kaitkan dengan menjaga kemudahan untuk pengunjung lain.\nTindakan murid: Sebut satu pesanan ringkas yang berasas, bukan janji tentang semua hotel.\nPulangkan kad mengikut GANTUNG/BAKUL dan nyatakan satu soalan yang masih mengelirukan.\nSemakan: Gunakan kekeliruan yang dinyatakan untuk memilih intervensi, bukan mengisi refleksi sebagai semua murid berjaya.\nBahan: Kad notis dan respons penutup.","aids_and_pak21_original":"BBM/ABM: Kad notis dan respons penutup.\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bukti ditunjuk, alasan dibina","implementation_original":"Tugasan: Menjelaskan dua pasangan bukti–tafsiran daripada arahan tuala dengan rangka bahasa yang beransur-ansur dikurangkan.\nBahan: Dua kad arahan berikon GANTUNG dan BAKUL\nPilihan frasa ‘untuk digunakan lagi’, ‘hendak ditukar’, ‘mengurangkan basuhan’\nRangka ‘Notis meminta … . Ini membantu … kerana …’.\nBimbingan guru: Baca satu arahan, minta murid menunjuk tempat yang betul, kemudian modelkan hanya permulaan alasan.\nBagi pasangan kedua, tutup ayat model tetapi kekalkan ikon. Jika alasan tersasar, baca semula ayat tentang penggunaan air.\nLangkah murid: Padankan ikon dengan arahan dan baca bersama guru.\nPilih frasa sebab yang sepadan; tolak frasa yang tiada bukti.\nSebut bukti dan alasan sebagai dua ayat kepada pasangan.\nTukar kad, bina penerangan kedua dan cuba sebut tanpa meniru keseluruhan model.\nHasil individu: Dua penerangan lisan individu; jalur kata kunci hanya sokongan ingatan.\nKriteria: Dua arahan tepat dan dua tafsiran berkaitan. Jika baru satu pasangan dikuasai, catat kemajuan sokongan tetapi objektif penuh belum dicapai.\nSusulan: Kurangkan pilihan kepada kata kunci sahaja selepas dua padanan betul; jika masih tertukar, ulang beza gantung dengan bakul sebelum inferens.","aids_and_pak21_original":"BBM/ABM: Dua kad arahan berikon GANTUNG dan BAKUL\nPilihan frasa ‘untuk digunakan lagi’, ‘hendak ditukar’, ‘mengurangkan basuhan’\nRangka ‘Notis meminta … . Ini membantu … kerana …’.\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},"pembina":{"label":"Langkah 1\nPembina — Penjelasan daripada notis asal","implementation_original":"Tugasan: Memilih dua maklumat sendiri dan menjelaskan maksudnya tanpa pilihan jawapan bercetak.\nBahan: BT75\nJalur kosong Bukti–Tafsiran\nKad soalan ‘Apakah bukti?’ dan ‘Apakah kesannya?’\nBimbingan guru: Minta murid merujuk ayat sebenar sebelum menerima alasan; jangan menyediakan satu skrip untuk dihafal.\nTanya soalan susulan jika penerangan hanya menukar beberapa perkataan arahan tanpa menjelaskan sebab.\nLangkah murid: Pilih dua ayat daripada dialog atau notis dan catat kata kuncinya.\nSebut satu kesan munasabah bagi setiap ayat.\nLakonkan petugas yang menerangkan notis kepada pengunjung; pasangan meminta bukti.\nTukar peranan dan baiki satu penerangan selepas maklum balas sebelum giliran individu.\nHasil individu: Dua pasangan maklumat yang dapat dijelaskan dengan ayat sendiri, berserta jalur rujukan ringkas.\nKriteria: Kedua-dua bukti tepat, tafsiran tidak bercanggah, dan penghubung sebab digunakan dengan jelas; catat bantuan minimum jika diberi.\nSusulan: Jika tepat, cabar murid menguji dakwaan tanpa bukti; jika tidak, padankan setiap alasan dengan satu ayat sahaja dahulu.","aids_and_pak21_original":"BBM/ABM: BT75\nJalur kosong Bukti–Tafsiran\nKad soalan ‘Apakah bukti?’ dan ‘Apakah kesannya?’\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."},"pencabar":{"label":"Langkah 1\nPencabar — Membezakan inferens dan dakwaan","implementation_original":"Tugasan: Menjelaskan dua pasangan maklumat, kemudian membetulkan satu dakwaan yang melampaui bukti notis.\nBahan: Dialog dan notis BT75\nKad dakwaan denda RM10 berlabel contoh rekaan guru\nJalur ‘Boleh disimpulkan / Tidak dinyatakan’\nBimbingan guru: Tanya ‘Adakah satu notis membuktikan semua hotel menggunakan peraturan yang sama?’ supaya murid mengehadkan dakwaannya.\nMinta alasan bagi pembetulan, bukan menambah ayat panjang atau istilah sukar.\nLangkah murid: Sediakan dua penerangan lengkap bukti–tafsiran daripada bahan.\nKelaskan dakwaan denda sebagai tidak dinyatakan dan tunjuk jurang buktinya.\nGantikan dakwaan itu dengan satu saranan yang benar-benar berkaitan penggunaan air.\nTerangkan kepada pasangan mengapa saranan baharu munasabah; jawab satu bantahan dengan sopan.\nHasil individu: Dua penerangan lisan dan satu pembetulan dakwaan berserta alasan; tidak perlu esei atau fakta luar.\nKriteria: Mencapai sasaran teras dan membezakan maklumat bahan daripada andaian; tidak dinilai mengikut banyaknya fakta hotel yang diketahui.\nSusulan: Gunakan kemahiran yang sama pada satu pesanan Puan Zaidah; jika alasan tidak berpaut bukti, kembali pada jalur Bukti–Tafsiran.","aids_and_pak21_original":"BBM/ABM: Dialog dan notis BT75\nKad dakwaan denda RM10 berlabel contoh rekaan guru\nJalur ‘Boleh disimpulkan / Tidak dinyatakan’\nPAK-21: Think–Pair–Explain: murid memilih bukti sendiri, pasangan meminta alasan, kemudian bertukar peranan pemberi penerangan dan penyoal. Simulasi pengunjung–petugas digunakan untuk menjelaskan notis, bukan menghafal dialog baharu."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian penerangan lisan dan soal jawab individu semasa simulasi serta giliran PBD.","Evidens":"Dua bukti tersurat yang disebut dan dua tafsiran yang dijelaskan oleh murid sendiri; catatan guru mengekalkan jenis bantuan.","Kriteria Kejayaan":"Dua pasangan tepat dan munasabah, ayat dapat difahami, alasan disokong bahan serta tiada fakta hotel rekaan dianggap sumber."},"closure_original":"Tindakan guru: Minta kelas melengkapkan ‘Saya akan … kerana …’ dengan satu tindakan daripada notis.\nRumusan: tersurat ialah yang dinyatakan; tersirat ialah maksud atau sebab yang disimpulkan dengan bukti. Kaitkan dengan menjaga kemudahan untuk pengunjung lain.\nTindakan murid: Sebut satu pesanan ringkas yang berasas, bukan janji tentang semua hotel.\nPulangkan kad mengikut GANTUNG/BAKUL dan nyatakan satu soalan yang masih mengelirukan.\nSemakan: Gunakan kekeliruan yang dinyatakan untuk memilih intervensi, bukan mengisi refleksi sebagai semua murid berjaya.\nBahan: Kad notis dan respons penutup.","reflection_original":"____ / ____ murid menjelaskan dua pasangan maklumat; ____ masih memerlukan rangka alasan; ____ belum diperhatikan. Bukti/kekeliruan utama: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M37-S1.docx","source_docx_sha256":"4cf124c464e1675a563e3c2502492550edc25a3f8a9c82643dd7a5dfb5d2a513","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":37,"session":1,"revision":"r2","title_original":"Hargailah Kemudahan","sk_original":"1.2 Bertutur untuk menyampaikan maklumat dan idea bagi pelbagai tujuan","sp_original":"1.2.2","sp_support_original":"—","objective_original":"Murid dapat menjelaskan maklumat tersurat dan tersirat daripada dialog dan notis hotel.","success_criteria_original":"Menyebut satu arahan dalam notis.; Memberi satu sebab yang sesuai bagi arahan tersebut.","textbook_pages_original":"m/s 75","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Hargailah Kemudahan.\nGuru tanya, “Apakah kegunaan tuala?”\nTindakan murid: Murid melihat buku.\nMurid menjawab berdasarkan pengalaman.\nSemakan: Bantu murid menyebut kegunaan tuala.\nBahan: Buku teks halaman 75","BBM/ABM":"Buku teks halaman 75","PAK-21":"Soal jawab berpasangan tentang penggunaan tuala di hotel."},"six_phases_original":[{"phase_original":"Langkah 1\nBincang tentang tuala","execution_original":"Tindakan guru: Guru tunjuk tajuk Hargailah Kemudahan.\nGuru tanya, “Apakah kegunaan tuala?”\nTindakan murid: Murid melihat buku.\nMurid menjawab berdasarkan pengalaman.\nSemakan: Bantu murid menyebut kegunaan tuala.\nBahan: Buku teks halaman 75","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 75\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."},{"phase_original":"Langkah 2\nDengar dialog","execution_original":"Tindakan guru: Guru baca dialog Elis dan ibunya.\nGuru jelaskan “selesanya bilik ini” menunjukkan Elis berasa seronok.\nTindakan murid: Murid mengikuti dialog.\nMurid menyebut perasaan Elis.\nSemakan: Terangkan tersurat ialah maklumat yang disebut; tersirat ialah maksud yang kita fahami.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."},{"phase_original":"Langkah 3\nBaca notis bersama","execution_original":"Tindakan guru: Guru baca arahan menggantung tuala jika hendak digunakan lagi.\nGuru beri contoh sebab: “Tuala digantung supaya boleh digunakan semula.”\nTindakan murid: Murid menunjukkan arahan tersebut.\nMurid mengulang arahan dan sebab bersama guru.\nSemakan: Gunakan soalan “Apa kata notis?” dan “Mengapa agaknya?”\nBahan: Notis dalam buku\nKad bantuan","aids_and_pak21_original":"BBM/ABM: Notis dalam buku\nKad bantuan\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri soalan “Apakah yang dibuat jika tuala hendak digunakan lagi?”\nGuru bantu jawapan untuk soalan “Mengapa tuala itu digantung?”\nTindakan murid: Murid bertanya kepada pasangan.\nMurid menyebut arahan dan sebabnya sebelum bertukar giliran.\nSemakan: Bantu dengan frasa guna semula jika murid terlupa.\nBahan: Kad gantung tuala\nRangka ayat","aids_and_pak21_original":"BBM/ABM: Kad gantung tuala\nRangka ayat\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."},{"phase_original":"Langkah 5\nJawab sendiri","execution_original":"Tindakan guru: Guru dengar jawapan murid semasa melawat pasangan.\nGuru minta murid yang belum didengar menyebut jawapannya.\nTindakan murid: Murid menyebut satu arahan notis.\nMurid memberi satu sebab dengan ayat mudah.\nSemakan: Catat kefahaman melalui jawapan pendek, bukan huraian panjang.\nBahan: Buku teks\nSenarai nama","aids_and_pak21_original":"BBM/ABM: Buku teks\nSenarai nama\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru baca arahan meletakkan tuala ke dalam bakul jika hendak ditukar.\nGuru ingatkan penggunaan semula tuala boleh mengurangkan pembasuhan.\nTindakan murid: Murid mengulang dua tempat meletakkan tuala.\nMurid menyebut satu cara berjimat.\nSemakan: Kukuhkan perbezaan tuala digantung dan tuala hendak ditukar.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Menjawab dengan kad arahan dan sebab.\nBahan: Kad gantung tuala\nKad guna semula\nTuala digantung supaya ___.\nBimbingan guru: Guru baca soalan satu demi satu.\nGuru bantu murid memilih kad jawapan.\nLangkah murid: Dengar soalan.\nPilih kad yang sesuai.\nSebut jawapan bersama guru kemudian kepada rakan.\nHasil individu: Jawapan lisan dengan bantuan.\nKriteria: Arahan dan sebab dapat disampaikan.\nSusulan: Ulang menggunakan dua kad yang sama.","aids_and_pak21_original":"BBM/ABM: Kad gantung tuala\nKad guna semula\nTuala digantung supaya ___.\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Menjelaskan arahan dan sebab daripada notis.\nBahan: Buku teks\nKad soalan\nBimbingan guru: Guru beri contoh pasangan soalan.\nGuru bantu kata yang belum difahami.\nLangkah murid: Baca notis dengan rakan.\nCuba jawab kedua-dua soalan.\nSebut jawapan sendiri kepada guru.\nHasil individu: Satu arahan dan satu sebab secara lisan.\nKriteria: Jawapan sesuai dengan notis.\nSusulan: Rujuk notis semula jika jawapan masih keliru.","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad soalan\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menjelaskan arahan tuala yang hendak ditukar.\nBahan: Notis hotel\nBimbingan guru: Guru tunjuk ayat tentang bakul.\nGuru tanya “Mengapa tuala diletakkan di dalam bakul?”\nLangkah murid: Baca ayat pilihan.\nNyatakan tempat tuala diletakkan.\nSebut sebab tuala hendak ditukar.\nHasil individu: Satu penjelasan tambahan.\nKriteria: Arahan dan sebab sepadan.\nSusulan: Kongsi jawapan jika murid bersedia.","aids_and_pak21_original":"BBM/ABM: Notis hotel\nPAK-21: Soal jawab berpasangan tentang penggunaan tuala di hotel."}},"pbd_original":{"Kaedah Pentaksiran":"Soal jawab semasa latihan.","Evidens":"Jawapan lisan setiap murid.","Kriteria Kejayaan":"Satu arahan dan satu sebab yang sesuai dapat dijelaskan."},"closure_original":"Tindakan guru: Guru baca arahan meletakkan tuala ke dalam bakul jika hendak ditukar.\nGuru ingatkan penggunaan semula tuala boleh mengurangkan pembasuhan.\nTindakan murid: Murid mengulang dua tempat meletakkan tuala.\nMurid menyebut satu cara berjimat.\nSemakan: Kukuhkan perbezaan tuala digantung dan tuala hendak ditukar.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat menjelaskan maklumat daripada dialog dan notis. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M37-S1.docx","source_docx_sha256":"d14547fc401f369cdb7959d1ff189841470c70414a9a19f451be8ab76044d431","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":1,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M37-S2","week_no":37,"session_no":2,"lesson_map":{"title":"Anugerah Murid Contoh","sp":"2.3.2","page":76,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":37,"session":2,"revision":"r1","title_original":"Anugerah Murid Contoh","sk_original":"2.3 Membaca dan mengapresiasi karya sastera dan bukan sastera","sp_original":"2.3.2(iv)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat membaca dan mempersembahkan sekurang-kurangnya tiga ayat pilihan daripada buletin Anugerah Murid Contoh dengan sebutan yang dapat difahami, jeda pada akhir ayat dan intonasi penyampaian berita yang sesuai.","success_criteria_original":"Tiga ayat daripada petikan disampaikan oleh murid sendiri, bukan hanya bacaan beramai-ramai.; Nama atau kata penting dalam ayat pilihan disebut jelas tanpa mengubah maklumat buletin; kesilapan dibetulkan apabila disedari.; Jeda akhir ayat dan penekanan sekurang-kurangnya satu maklumat utama dapat didengar. Rekod bimbingan yang diperlukan.","textbook_pages_original":"m/s 76","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Baca tajuk ‘Anugerah Murid Contoh’ sekali terlalu pantas dan sekali dengan jelas. Tanya bacaan mana lebih mudah difahami dan mengapa.\nTunjuk bentuk buletin pada BT76; jelaskan bahawa isi hari ini disampaikan sebagai maklumat sekolah, bukan dialog watak.\nTindakan murid: Bandingkan kedua-dua bacaan menggunakan perkataan jelas, laju atau berhenti; cuba sebut tajuk dengan suara sendiri.\nCari nama murid yang menerima anugerah dan tunjuk bahagian buletin yang menyatakannya.\nSemakan: Jika murid menilai hanya kuatnya suara, ulang model pada kelantangan sama tetapi kadar berbeza untuk menonjolkan sebutan dan jeda.\nBahan: Tajuk dan bentuk buletin BT76.","BBM/ABM":"Tajuk dan bentuk buletin BT76.","PAK-21":"Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Suara pembaca buletin","execution_original":"Tindakan guru: Baca tajuk ‘Anugerah Murid Contoh’ sekali terlalu pantas dan sekali dengan jelas. Tanya bacaan mana lebih mudah difahami dan mengapa.\nTunjuk bentuk buletin pada BT76; jelaskan bahawa isi hari ini disampaikan sebagai maklumat sekolah, bukan dialog watak.\nTindakan murid: Bandingkan kedua-dua bacaan menggunakan perkataan jelas, laju atau berhenti; cuba sebut tajuk dengan suara sendiri.\nCari nama murid yang menerima anugerah dan tunjuk bahagian buletin yang menyatakannya.\nSemakan: Jika murid menilai hanya kuatnya suara, ulang model pada kelantangan sama tetapi kadar berbeza untuk menonjolkan sebutan dan jeda.\nBahan: Tajuk dan bentuk buletin BT76.","aids_and_pak21_original":"BBM/ABM: Tajuk dan bentuk buletin BT76.\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},{"phase_original":"Langkah 2\nModel bacaan — Nama, jeda dan makna","execution_original":"Tindakan guru: Modelkan bacaan nama Nur Qasrina Balqis dan nama sekolah secara berbahagian, kemudian sambungkan dengan lancar. Jangan menukar nama panjang kepada nama rekaan.\nBaca ayat tentang membantu rakan. Tanda jeda akhir ayat dan beri penekanan pada perbuatan membantu; jelaskan ‘ringan tulang’ sebagai suka membantu, bukannya tubuh yang ringan.\nTindakan murid: Ikut bacaan frasa nama dan dua kata sukar, kemudian cuba tanpa suara guru.\nPada salinan latihan, tandakan akhir ayat dan gariskan satu maklumat yang hendak ditekankan; sebut sebab memilihnya kepada pasangan.\nSemakan: Dengar sebutan nama dan perbezaan frasa. Pembetulan dibuat pada frasa pendek dahulu sebelum membaca semula seluruh ayat.\nBahan: Kad nama, salinan latihan dan pen penanda.","aids_and_pak21_original":"BBM/ABM: Kad nama, salinan latihan dan pen penanda.\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},{"phase_original":"Langkah 3\nLatihan terbeza — Studio Buletin Keramat","execution_original":"Tindakan guru: Tetapkan latihan tiga ayat pilihan mengikut keperluan murid; terangkan laluan Peneroka, Pembina dan Pencabar di bawah. Semua laluan melibatkan bacaan yang boleh didengar.\nLawati pasangan dan minta setiap ahli membaca sekurang-kurangnya satu ayat. Tunjuk titik jeda atau ulang satu frasa hanya apabila perlu; catat bantuan dan tarik balik model beransur-ansur.\nTindakan murid: Berlatih sebagai pembaca dan jurulatih. Jurulatih menunggu ayat selesai sebelum memberi satu maklum balas khusus, contohnya ‘Berhenti sebentar selepas pelajaran’.\nTukar peranan; ulang tiga ayat selepas pembaikan. Murid yang telah lancar memilih penekanan isi tanpa mengubah fakta buletin.\nSemakan: Pastikan jurulatih tidak membaca semua ayat bagi pihak rakan. Bacaan kendiri selepas bantuan ialah evidens yang perlu didengar.\nBahan: BT76, salinan bertanda atau tanpa tanda mengikut laluan, kad maklum balas.","aids_and_pak21_original":"BBM/ABM: BT76, salinan bertanda atau tanpa tanda mengikut laluan, kad maklum balas.\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},{"phase_original":"Langkah 4\nPersembahan berpasangan — Isi didengar","execution_original":"Tindakan guru: Jalankan persembahan kecil dalam kelompok, bukan menunggu semua murid di hadapan kelas. Dengar kelompok yang dipilih sambil yang lain bergilir.\nSelepas satu penyampaian, tanya pendengar apakah bantuan yang dilakukan Nur Qasrina. Gunakan respons itu untuk menyemak sama ada penekanan pembaca menyampaikan makna.\nTindakan murid: Persembahkan tiga ayat pilihan seperti pembaca berita sekolah; pegang buku pada aras yang membolehkan suara didengar.\nPendengar memberi satu komen tentang sebutan atau jeda dan menyebut satu isi yang didengar, bukan markah berdasarkan gaya pakaian atau props.\nSemakan: Jika pendengar tidak menangkap isi kerana bacaan laju, pembaca mengulang satu ayat dengan kadar lebih sesuai; ini pembaikan, bukan hukuman.\nBahan: Petikan buletin dan kad pendengar.","aids_and_pak21_original":"BBM/ABM: Petikan buletin dan kad pendengar.\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},{"phase_original":"Langkah 5\nPBD — Bacaan individu dan ulangan sasaran","execution_original":"Tindakan guru: Dengar tiga ayat daripada murid yang belum diperhatikan atau perlu semakan semula. Rekod bukti daripada latihan awal jika sudah mencukupi.\nTanda sebutan, jeda dan intonasi secara berasingan. Murid yang belum mendapat giliran ditanda belum diperhatikan; jangan menyamakan persembahan kumpulan dengan penguasaan semua ahli.\nTindakan murid: Baca tiga ayat kepada guru secara kendiri; pilih semula segmen yang telah dilatih dan nyatakan maklumat yang hendak ditekankan.\nUlang frasa yang kurang jelas selepas satu petunjuk dan dengar perbezaan bacaan sendiri.\nSemakan: Sasaran ialah bacaan dan persembahan, bukan empat jawapan bertulis atau hafalan teks. Rangka jeda boleh digunakan dan jenis bantuan direkod.\nBahan: Senarai nama, rubrik bacaan tiga aspek dan petikan pilihan.","aids_and_pak21_original":"BBM/ABM: Senarai nama, rubrik bacaan tiga aspek dan petikan pilihan.\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},{"phase_original":"Langkah 6\nPenutup — Bacaan yang menyampaikan teladan","execution_original":"Tindakan guru: Minta dua contoh cara pembaca membantu pendengar memahami maklumat: sebutan jelas dan berhenti pada tempat yang betul.\nRumusan isi buletin: kecemerlangan serta sikap membantu menjadi teladan. Terangkan latihan susulan berdasarkan frasa yang masih sukar.\nTindakan murid: Baca satu ayat pilihan dengan pembaikan yang dipelajari.\nSebut satu maklum balas sopan yang membantu rakan berlatih.\nSemakan: Rekod jenis kesukaran sebenar untuk intervensi; refleksi pencapaian tidak diisi sebelum PdP dilaksanakan.\nBahan: Ayat pilihan BT76 dan rekod latihan.","aids_and_pak21_original":"BBM/ABM: Ayat pilihan BT76 dan rekod latihan.\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Frasa pendek ke tiga ayat","implementation_original":"Tugasan: Membaca tiga ayat terpilih dengan penanda jeda dan model frasa yang dikurangkan secara beransur-ansur.\nBahan: Salinan tiga ayat pilihan dengan jarak jelas\nKad ‘membantu’, ‘pembimbing’, ‘buku-buku latihan’\nTanda jeda akhir ayat\nBimbingan guru: Pilih ayat daripada petikan, bukan mengganti seluruh buletin dengan teks baharu. Bacakan frasa sukar dahulu dan minta murid mengulang tanpa menjerit.\nTutup kad sebutan selepas murid berjaya; kekalkan tanda jeda sehingga mereka boleh membaca ayat tanpa model suara.\nLangkah murid: Dengar satu frasa dan ikut sebutannya.\nSambungkan frasa menjadi satu ayat sambil menunjuk perkataan.\nBaca tiga ayat kepada pasangan dengan jeda yang ditanda.\nCuba semula kepada guru tanpa suara rakan dan betulkan satu frasa sendiri.\nHasil individu: Persembahan lisan tiga ayat daripada buletin; salinan bertanda menjadi bahan latihan.\nKriteria: Tiga ayat dapat difahami dan jeda akhir ayat digunakan; bantuan sebutan dicatat. Jika hanya dua ayat dibaca, rekod kemajuan tetapi sasaran penuh belum selesai.\nSusulan: Ulang frasa bermasalah dalam ayat asal; selepas lancar, hilangkan satu tanda jeda supaya murid menentukan tempat berhenti sendiri.","aids_and_pak21_original":"BBM/ABM: Salinan tiga ayat pilihan dengan jarak jelas\nKad ‘membantu’, ‘pembimbing’, ‘buku-buku latihan’\nTanda jeda akhir ayat\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},"pembina":{"label":"Langkah 1\nPembina — Membaca dengan penekanan isi","implementation_original":"Tugasan: Memilih dan mempersembahkan tiga ayat yang menjelaskan sebab Nur Qasrina menjadi murid contoh.\nBahan: BT76 tanpa penanda siap\nPen penanda pada salinan\nKad jurulatih sebutan–jeda–intonasi\nBimbingan guru: Tanya maklumat yang murid mahu pendengar ingat sebelum latihan, supaya penekanan tidak dibuat secara rawak.\nBeri satu petunjuk bacaan pada satu masa; jangan membetulkan semua aspek serentak sehingga murid hilang aliran.\nLangkah murid: Pilih segmen bantuan kepada rakan atau guru.\nTanda akhir ayat dan satu frasa yang hendak ditekankan.\nBaca kepada jurulatih, dengar komen, kemudian tukar peranan.\nPersembahkan semula tiga ayat dengan penekanan yang lebih jelas.\nHasil individu: Bacaan individu tiga ayat dan salinan beranotasi ringkas.\nKriteria: Maklumat asal kekal, kata penting disebut jelas, jeda dan intonasi sesuai dengan petikan berita; bukan intonasi berlakon yang mengubah maksud.\nSusulan: Jika bacaan mantap, sampaikan segmen tanpa semua tanda bantuan; jika tergesa-gesa, pecahkan ayat panjang kepada frasa makna dahulu.","aids_and_pak21_original":"BBM/ABM: BT76 tanpa penanda siap\nPen penanda pada salinan\nKad jurulatih sebutan–jeda–intonasi\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."},"pencabar":{"label":"Langkah 1\nPencabar — Penyampai buletin berasas makna","implementation_original":"Tugasan: Menyampaikan sekurang-kurangnya tiga ayat dengan penekanan terancang dan menjelaskan pilihan persembahan kepada pendengar.\nBahan: Buletin penuh BT76\nKad ‘maklumat utama’ dan ‘maklumat sokongan’\nSenarai semak kendiri\nBimbingan guru: Minta murid membandingkan penekanan pada nama penerima anugerah dengan penekanan pada tindakan membantu; tanya pilihan yang paling sesuai pada ayat tertentu.\nPastikan pembukaan tambahan, jika digunakan, dilabel gaya penyampai dan tidak mencipta anugerah atau fakta sekolah lain.\nLangkah murid: Pilih tiga atau lebih ayat yang membentuk satu segmen bermakna.\nTentukan jeda, kadar dan satu penekanan utama setiap bahagian.\nPersembahkan kepada kumpulan kecil tanpa bergantung sepenuhnya pada tanda.\nDengar isi yang diingati pendengar, jelaskan pilihan gaya, kemudian baik pulih satu ayat.\nHasil individu: Persembahan buletin dan alasan ringkas tentang satu pilihan intonasi; tiada esei tambahan diperlukan.\nKriteria: Sasaran teras dicapai serta pilihan intonasi membantu makna. Kepantasan atau hafalan bukan ukuran aras tinggi.\nSusulan: Latih menukar kadar pada ayat panjang sambil mengekalkan ketepatan nama dan isi; elakkan menambah fakta demi persembahan yang lebih dramatik.","aids_and_pak21_original":"BBM/ABM: Buletin penuh BT76\nKad ‘maklumat utama’ dan ‘maklumat sokongan’\nSenarai semak kendiri\nPAK-21: Latihan pembaca–jurulatih: seorang membaca segmen buletin, seorang menunjuk satu bahagian yang perlu diulang, kemudian bertukar peranan. Persembahan gaya pembaca buletin mengekalkan teks bukan sastera, bukan lakonan cerita rekaan."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian bacaan dan persembahan lisan individu semasa latihan serta semakan terfokus.","Evidens":"Tiga ayat daripada petikan dibaca oleh murid, dengan contoh sebutan, jeda dan penekanan yang direkod guru.","Kriteria Kejayaan":"Ayat boleh difahami, isi tidak berubah, jeda akhir ayat dan intonasi sesuai; jumlah bantuan dinyatakan tanpa TP automatik."},"closure_original":"Tindakan guru: Minta dua contoh cara pembaca membantu pendengar memahami maklumat: sebutan jelas dan berhenti pada tempat yang betul.\nRumusan isi buletin: kecemerlangan serta sikap membantu menjadi teladan. Terangkan latihan susulan berdasarkan frasa yang masih sukar.\nTindakan murid: Baca satu ayat pilihan dengan pembaikan yang dipelajari.\nSebut satu maklum balas sopan yang membantu rakan berlatih.\nSemakan: Rekod jenis kesukaran sebenar untuk intervensi; refleksi pencapaian tidak diisi sebelum PdP dilaksanakan.\nBahan: Ayat pilihan BT76 dan rekod latihan.","reflection_original":"____ / ____ murid menyampaikan tiga ayat dengan jelas; ____ memerlukan latihan frasa; ____ belum diperhatikan. Perkataan atau jeda yang sukar: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M37-S2.docx","source_docx_sha256":"407d93faf1e6b82d2bcb3d0e57523f4161771d99e9f6fba6465f6003b9f68748","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":37,"session":2,"revision":"r2","title_original":"Anugerah Murid Contoh","sk_original":"2.3 Membaca dan mengapresiasi karya sastera dan bukan sastera","sp_original":"2.3.2(iv)","sp_support_original":"—","objective_original":"Murid dapat membaca petikan buletin dengan sebutan yang jelas dan intonasi yang sesuai.","success_criteria_original":"Membaca dua ayat pilihan dalam petikan.; Berhenti seketika pada tanda noktah.","textbook_pages_original":"m/s 76","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk buletin.\nGuru tanya, “Apakah sikap baik seorang murid?”\nTindakan murid: Murid melihat tajuk.\nMurid menyebut satu sikap baik.\nSemakan: Terima perkataan mudah seperti rajin atau baik hati.\nBahan: Buku teks halaman 76","BBM/ABM":"Buku teks halaman 76","PAK-21":"Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali murid contoh","execution_original":"Tindakan guru: Guru tunjuk tajuk buletin.\nGuru tanya, “Apakah sikap baik seorang murid?”\nTindakan murid: Murid melihat tajuk.\nMurid menyebut satu sikap baik.\nSemakan: Terima perkataan mudah seperti rajin atau baik hati.\nBahan: Buku teks halaman 76","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 76\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},{"phase_original":"Langkah 2\nDengar bacaan guru","execution_original":"Tindakan guru: Guru baca petikan tentang Nur Qasrina Balqis.\nGuru jelaskan ringan tulang bermaksud suka membantu.\nTindakan murid: Murid mendengar bacaan.\nMurid menyebut satu bantuan yang dilakukan oleh Qasrina.\nSemakan: Bimbing sebutan nama watak tanpa mewajibkan hafalan nama penuh.\nBahan: Buku teks\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad perkataan\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},{"phase_original":"Langkah 3\nBaca ayat bersama","execution_original":"Tindakan guru: Guru baca “Nur Qasrina Balqis juga ringan tulang membantu guru-guru di sekolah.”\nGuru sambung “Dia tidak keberatan membantu guru-guru melakukan kerja-kerja yang mudah.”\nTindakan murid: Murid membaca setiap ayat selepas guru.\nMurid berhenti seketika pada noktah.\nSemakan: Pecahkan bacaan kepada frasa jika ayat terasa panjang.\nBahan: Dua ayat pilihan","aids_and_pak21_original":"BBM/ABM: Dua ayat pilihan\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},{"phase_original":"Langkah 4\nBaca dengan rakan","execution_original":"Tindakan guru: Guru susun pasangan untuk bacaan bergilir.\nGuru bantu frasa yang masih sukar disebut.\nTindakan murid: Murid membaca dua ayat kepada rakan.\nMurid mendengar rakan dan mengulang perkataan yang dibantu guru.\nSemakan: Dengar bacaan setiap murid semasa latihan.\nBahan: Buku teks\nSalinan ayat besar","aids_and_pak21_original":"BBM/ABM: Buku teks\nSalinan ayat besar\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},{"phase_original":"Langkah 5\nPersembahkan bacaan","execution_original":"Tindakan guru: Guru dengar murid yang belum diperhatikan membaca dua ayat.\nGuru beri contoh semula pada satu perkataan yang kurang jelas.\nTindakan murid: Murid membaca kepada guru atau kumpulan kecil.\nMurid mencuba semula perkataan yang dibantu.\nSemakan: Murid boleh melihat teks sepanjang bacaan.\nBahan: Dua ayat pilihan\nSenarai nama","aids_and_pak21_original":"BBM/ABM: Dua ayat pilihan\nSenarai nama\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru ajak kelas membaca ayat tentang membantu guru.\nGuru tanya satu bantuan yang boleh dibuat di kelas.\nTindakan murid: Murid membaca bersama.\nMurid berkongsi cadangan bantuan.\nSemakan: Puji usaha membaca dan sikap saling membantu.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Membaca dua ayat sedikit demi sedikit.\nBahan: Salinan tulisan besar\nTanda garis miring antara frasa\nBimbingan guru: Guru baca satu frasa dahulu.\nGuru menuding perkataan semasa murid membaca.\nLangkah murid: Dengar satu frasa.\nBaca frasa selepas guru.\nSambung frasa menjadi ayat dengan bantuan.\nHasil individu: Bacaan dua ayat berpandu.\nKriteria: Perkataan disebut dengan lebih jelas selepas contoh.\nSusulan: Ulang hanya frasa yang masih sukar.","aids_and_pak21_original":"BBM/ABM: Salinan tulisan besar\nTanda garis miring antara frasa\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Membaca dua ayat dengan sebutan jelas.\nBahan: Buku teks\nSalinan ayat pilihan\nBimbingan guru: Guru beri contoh jeda pada noktah.\nGuru bantu sebutan apabila diminta.\nLangkah murid: Latih bacaan bersama rakan.\nTandakan tempat berhenti.\nBaca sendiri kepada guru atau kumpulan kecil.\nHasil individu: Bacaan petikan pendek.\nKriteria: Ayat dapat dibaca dan jeda pada noktah sesuai.\nSusulan: Baca semula ayat yang masih tersekat.","aids_and_pak21_original":"BBM/ABM: Buku teks\nSalinan ayat pilihan\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Membaca ayat yang sama dengan suara lebih menarik.\nBahan: Dua ayat pilihan\nBimbingan guru: Guru contohkan nada mesra semasa menyebut sikap baik.\nGuru ingatkan murid tidak perlu membaca terlalu cepat.\nLangkah murid: Baca dua ayat.\nLaraskan suara supaya jelas.\nPersembahkan bacaan kepada rakan.\nHasil individu: Bacaan yang lebih lancar dan sesuai.\nKriteria: Nada sesuai dan perkataan masih jelas.\nSusulan: Beri peluang membaca ayat seterusnya jika murid mahu.","aids_and_pak21_original":"BBM/ABM: Dua ayat pilihan\nPAK-21: Bacaan berpasangan: seorang membaca dan seorang mendengar sebelum bertukar giliran."}},"pbd_original":{"Kaedah Pentaksiran":"Pemerhatian bacaan semasa latihan dan persembahan.","Evidens":"Bacaan dua ayat setiap murid.","Kriteria Kejayaan":"Dua ayat dibaca dengan sebutan jelas dan jeda pada noktah."},"closure_original":"Tindakan guru: Guru ajak kelas membaca ayat tentang membantu guru.\nGuru tanya satu bantuan yang boleh dibuat di kelas.\nTindakan murid: Murid membaca bersama.\nMurid berkongsi cadangan bantuan.\nSemakan: Puji usaha membaca dan sikap saling membantu.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat membaca petikan dengan sebutan yang jelas. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M37-S2.docx","source_docx_sha256":"d7d5ec562f1f36cdd91a98bd6d4d40017ce35932132f9aa33fab006dd8987da0","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":2,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M37-S3","week_no":37,"session_no":3,"lesson_map":{"title":"Bas Kita","sp":"3.3.2","page":77,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":37,"session":3,"revision":"r1","title_original":"Bas Kita","sk_original":"3.3 Menghasilkan penulisan","sp_original":"3.3.2(i)(ii)(iii)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat mengedit sekurang-kurangnya lima bahagian petikan Bas Kita yang merangkumi ejaan, tanda baca dan pemurnian penggunaan kata, kemudian menulis semula satu perenggan pilihan dengan pembetulan yang sesuai.","success_criteria_original":"Lima bahagian yang disunting meliputi sekurang-kurangnya satu ejaan, satu tanda baca dan satu pemurnian kata; menyunting semua ayat bukan syarat.; Bentuk asal dan pembetulan dapat dikenal pasti, contohnya cereta → cerita, dudok → duduk, dan tempat perumahan → kawasan perumahan.; Satu perenggan ditulis semula tanpa mengubah watak, perjalanan atau maksud utama cerita. Bentuk yang sudah betul tidak ditandai salah semata-mata untuk mencukupkan bilangan.","textbook_pages_original":"m/s 77","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tulis contoh guru ‘Terima kasih pak salim.’ dan baca tanpa jeda. Tanya bahagian yang menunjukkan nama orang dan cara memisahkan ucapan daripada sapaan.\nBandingkan dengan bentuk ‘Terima kasih, Pak Salim.’ untuk memperkenalkan penyuntingan, bukan memberi semua jawapan petikan.\nTindakan murid: Tunjuk huruf besar atau koma yang membantu pembacaan dan cuba baca kedua-dua versi.\nSebut sebab satu perubahan dengan bahasa mudah, misalnya ‘Pak Salim nama orang’.\nSemakan: Jika murid hanya menyebut ayat kedua lebih cantik, minta mereka menunjuk perubahan yang menyebabkan bacaan lebih jelas.\nBahan: Dua ayat contoh guru, kad koma dan huruf besar.","BBM/ABM":"Dua ayat contoh guru, kad koma dan huruf besar.","PAK-21":"Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Mesej yang sukar dibaca","execution_original":"Tindakan guru: Tulis contoh guru ‘Terima kasih pak salim.’ dan baca tanpa jeda. Tanya bahagian yang menunjukkan nama orang dan cara memisahkan ucapan daripada sapaan.\nBandingkan dengan bentuk ‘Terima kasih, Pak Salim.’ untuk memperkenalkan penyuntingan, bukan memberi semua jawapan petikan.\nTindakan murid: Tunjuk huruf besar atau koma yang membantu pembacaan dan cuba baca kedua-dua versi.\nSebut sebab satu perubahan dengan bahasa mudah, misalnya ‘Pak Salim nama orang’.\nSemakan: Jika murid hanya menyebut ayat kedua lebih cantik, minta mereka menunjuk perubahan yang menyebabkan bacaan lebih jelas.\nBahan: Dua ayat contoh guru, kad koma dan huruf besar.","aids_and_pak21_original":"BBM/ABM: Dua ayat contoh guru, kad koma dan huruf besar.\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},{"phase_original":"Langkah 2\nModel editor — Ejaan, tanda baca dan kata","execution_original":"Tindakan guru: Baca perenggan awal BT77. Tunjuk bahawa ucapan balas Pak Salim mempunyai tanda petik penutup tetapi kehilangan pembuka; modelkan penandaan kod T dan sebabnya.\nModelkan satu pasangan ejaan ‘cereta → cerita’, kemudian jelaskan kod K melalui ‘tempat perumahan → kawasan perumahan’. Terangkan bahawa ‘senyuman manis’ boleh dikekalkan; tidak semua perkataan perlu diubah.\nTindakan murid: Catat satu contoh dalam jadual Asal–Cadangan–Sebab dan sebut kod yang sepadan.\nBezakan membetulkan ejaan daripada memilih ungkapan yang lebih tepat; tunjuk satu bahagian petikan yang tidak perlu diubah.\nSemakan: Pembetulan mesti sepadan kategori. Jangan menggunakan perubahan tulisan cantik sebagai bukti penyuntingan bahasa.\nBahan: BT77, jadual editor dan kad E/T/K.","aids_and_pak21_original":"BBM/ABM: BT77, jadual editor dan kad E/T/K.\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},{"phase_original":"Langkah 3\nLatihan terbeza — Bengkel editor Bas Kita","execution_original":"Tindakan guru: Agihkan salinan bertanda lokasi, salinan tanpa tanda atau kad perbandingan alasan mengikut keperluan; laksanakan tiga laluan di bawah dalam masa yang sama.\nSemak pasangan yang menyunting senarai nama: Seok Ling dan Kok Bun masing-masing satu nama, jadi koma tidak diletakkan di tengah nama. Galakkan murid membaca ayat untuk memeriksa noktah selepas ‘sekolah’.\nTindakan murid: Pilih lima bahagian sasaran yang meliputi E, T dan K. Editor menanda asal; penyemak menyebut cadangan dan sebab; peranan ditukar.\nUji pembetulan dengan membaca ayat sebelum dan selepas disunting. Kekalkan fakta watak serta elakkan menambah kejadian baharu dalam perjalanan bas.\nSemakan: Pastikan kedua-dua ahli mempunyai rekod sendiri. Untuk dialog akhir, satu pembetulan bahagian boleh melibatkan tanda petik, koma dan huruf besar; jangan mengira setiap tanda kecil sebagai ayat baharu.\nBahan: Salinan Bas Kita, pen dua warna, jadual editor dan kad bantuan.","aids_and_pak21_original":"BBM/ABM: Salinan Bas Kita, pen dua warna, jadual editor dan kad bantuan.\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},{"phase_original":"Langkah 4\nPerenggan individu — Tulis versi yang dimurnikan","execution_original":"Tindakan guru: Minta setiap murid memilih satu perenggan yang telah disunting dan menulis semula. Ingatkan bahawa jadual pembetulan tidak menggantikan perenggan akhir.\nBeri soalan semakan ‘Siapa bercakap?’ bagi murid yang menulis ucapan terakhir. Contoh pembetulan guru: ‘“Terima kasih, Pak Salim,” kata mereka sambil turun dari bas.’\nTindakan murid: Tulis perenggan dengan pembetulan sendiri dan semak silang dengan rekod Asal–Cadangan–Sebab.\nGariskan satu perubahan E, T atau K yang terdapat dalam perenggan pilihan; lima bahagian keseluruhan masih dibuktikan melalui jadual.\nSemakan: Nilai pembetulan bahasa, bukan panjang perenggan. Murid yang baru menyalin versi rakan perlu menerangkan satu perubahan sendiri sebelum direkod menguasai.\nBahan: Buku latihan atau lembaran perenggan, jadual editor individu.","aids_and_pak21_original":"BBM/ABM: Buku latihan atau lembaran perenggan, jadual editor individu.\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},{"phase_original":"Langkah 5\nPBD — Jelaskan keputusan editor","execution_original":"Tindakan guru: Kumpulkan jadual dan perenggan. Tanya murid terpilih mengapa sesuatu dibetulkan dan mengapa ‘senyuman manis’ dikekalkan.\nSemak lima bahagian serta liputan tiga aspek. Catat kesalahan bahasa yang masih tinggal dan jenis bantuan, bukan terus menetapkan TP.\nTindakan murid: Sebut satu sebab pembetulan dan tunjuk bukti pada versi asal.\nPerbaiki satu kesalahan yang masih tinggal selepas maklum balas tanpa memadam jejak pembetulan awal.\nSemakan: Jika lima perubahan hanya ejaan, sasaran tiga aspek belum dipenuhi. Beri satu item tanda baca atau kata untuk semakan susulan.\nBahan: Jadual lima bahagian, perenggan akhir dan senarai semak guru.","aids_and_pak21_original":"BBM/ABM: Jadual lima bahagian, perenggan akhir dan senarai semak guru.\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},{"phase_original":"Langkah 6\nPenutup — Editor tidak mengubah sesuka hati","execution_original":"Tindakan guru: Rumusan tiga kod E, T dan K menggunakan contoh murid yang tidak mendedahkan nama atau memalukan kesilapan mereka.\nTekankan bahawa penyuntingan mengekalkan cerita asal sambil menjelaskan bahasa. Pilih intervensi mengikut kategori yang belum kukuh.\nTindakan murid: Sebut satu pembetulan yang membantu pembaca dan satu bentuk yang patut dikekalkan.\nSusun kad E/T/K dan serahkan hasil akhir bersama jadual asal.\nSemakan: Gunakan respons penutup untuk mengenal pasti perbezaan salah ejaan dengan pilihan gaya yang masih kabur.\nBahan: Kad kategori dan contoh suntingan.","aids_and_pak21_original":"BBM/ABM: Kad kategori dan contoh suntingan.\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Lokasi diberi, keputusan dijelaskan","implementation_original":"Tugasan: Menyunting lima bahagian terpilih dengan lokasi bergaris dan pilihan terhad, kemudian menulis satu perenggan pendek yang telah dimurnikan.\nBahan: Salinan dengan lima lokasi ditandai, bukan jawapan diisi\nPilihan cerita/cereta dan duduk/dudok\nKad koma/noktah/tanda petik serta tempat/kawasan\nBimbingan guru: Baca ayat bersama murid dan modelkan satu perubahan sahaja. Untuk senarai nama, sebut setiap nama penuh sebelum menyisipkan koma.\nTarik balik pilihan selepas dua pembetulan bersebab; minta murid memilih tanda atau kata tanpa kad jawapan.\nLangkah murid: Baca bahagian bergaris dan tentukan kod E, T atau K.\nPilih pembetulan, tulis di sebelah asal dan sebut sebab ringkas.\nLengkapkan lima bahagian dengan bantuan yang dicatat.\nTulis semula satu perenggan dan baca untuk memeriksa jeda serta nama orang.\nHasil individu: Jadual lima bahagian dan perenggan individu dengan pembetulan boleh dijejaki.\nKriteria: Lima bahagian meliputi tiga aspek dengan bantuan dibenarkan. Pencapaian separa dicatat jika hanya ejaan dikuasai, bukan ditanda mencapai semua objektif.\nSusulan: Ulang dialog akhir menggunakan kad ‘ucapan’ dan ‘kata mereka’; kurangkan tanda bantuan pada percubaan kedua.","aids_and_pak21_original":"BBM/ABM: Salinan dengan lima lokasi ditandai, bukan jawapan diisi\nPilihan cerita/cereta dan duduk/dudok\nKad koma/noktah/tanda petik serta tempat/kawasan\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},"pembina":{"label":"Langkah 1\nPembina — Mengesan dan menyunting sendiri","implementation_original":"Tugasan: Mengesan lima atau lebih bahagian yang wajar diperbaiki daripada petikan tanpa lokasi jawapan ditandai.\nBahan: BT77 atau salinan asal\nJadual Asal–Cadangan–Sebab\nPen dua warna\nBimbingan guru: Tanya kategori perubahan sebelum menerima cadangan supaya murid tidak mengubah ayat betul secara rawak.\nSemak penggunaan koma pada nama majmuk Seok Ling/Kok Bun dan ingatkan tujuan kata ‘kawasan’ dalam konteks perumahan.\nLangkah murid: Baca petikan untuk mendapatkan maksud cerita.\nTanda sasaran E/T/K dan tulis pembetulan berserta sebab.\nBandingkan dengan rakan, pertahankan atau baiki pilihan berdasarkan konteks.\nTulis satu perenggan dimurnikan secara individu dan baca semula tanpa bantuan rakan.\nHasil individu: Lima suntingan bersebab merentas tiga aspek serta perenggan yang mengekalkan isi asal.\nKriteria: Pembetulan tepat, liputan aspek lengkap dan perenggan tidak menambah kejadian rekaan; kata yang betul tidak dipaksa berubah.\nSusulan: Jika tepat, bezakan satu pembetulan wajib dengan satu pemurnian pilihan; jika lemah, fokus satu kategori sebelum mencuba petikan semula.","aids_and_pak21_original":"BBM/ABM: BT77 atau salinan asal\nJadual Asal–Cadangan–Sebab\nPen dua warna\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."},"pencabar":{"label":"Langkah 1\nPencabar — Menilai keperluan sesuatu pembetulan","implementation_original":"Tugasan: Menyunting petikan dan mempertahankan keputusan mengubah atau mengekalkan sesuatu ungkapan, bukan sekadar menambah bilangan suntingan.\nBahan: Petikan penuh\nKad cadangan ‘senyuman manis → senyuman gembira’ dan ‘tempat perumahan → kawasan perumahan’\nJadual Wajib dibetulkan / Pemurnian / Dikekalkan\nBimbingan guru: Minta murid menjelaskan mengapa penggantian yang gramatis belum tentu diperlukan. Terima alasan munasabah yang mengekalkan makna asal.\nUji dialog akhir: mengapa ‘Kata’ menjadi huruf kecil selepas ujaran dihubungkan kepada klausa pelapor?\nLangkah murid: Lengkapkan sasaran lima bahagian merentas E/T/K.\nKelaskan dua cadangan pemurnian dan jelaskan perbezaan antara salah dengan kurang tepat.\nTulis perenggan akhir dan semak konsistensi tanda petik.\nTerangkan satu perubahan yang diterima dan satu yang ditolak kepada rakan.\nHasil individu: Perenggan dimurnikan, jadual suntingan dan dua alasan penilaian bahasa.\nKriteria: Sasaran teras dicapai serta keputusan dapat dijelaskan tanpa melabel semua variasi sebagai salah; tidak dinilai berdasarkan istilah tatabahasa yang sukar.\nSusulan: Cuba menyemak perenggan lain sambil mengekalkan nama, fakta dan suara pencerita; kembali pada contoh dialog jika tanda petik masih tidak konsisten.","aids_and_pak21_original":"BBM/ABM: Petikan penuh\nKad cadangan ‘senyuman manis → senyuman gembira’ dan ‘tempat perumahan → kawasan perumahan’\nJadual Wajib dibetulkan / Pemurnian / Dikekalkan\nPAK-21: Editor–penyemak berpasangan: editor menandakan satu bahagian, penyemak meminta sebab, kemudian bertukar peranan. Hasil akhir ialah perenggan individu; bukan seorang menyalin semua pembetulan untuk kumpulan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan jadual suntingan dan perenggan individu, disokong soal jawab alasan editor.","Evidens":"Lima bahagian asal–pembetulan dengan liputan ejaan, tanda baca dan penggunaan kata, serta satu perenggan dimurnikan.","Kriteria Kejayaan":"Ketepatan pembetulan, liputan tiga aspek dan pemeliharaan maksud cerita; bantuan direkod secara berasingan daripada hasil."},"closure_original":"Tindakan guru: Rumusan tiga kod E, T dan K menggunakan contoh murid yang tidak mendedahkan nama atau memalukan kesilapan mereka.\nTekankan bahawa penyuntingan mengekalkan cerita asal sambil menjelaskan bahasa. Pilih intervensi mengikut kategori yang belum kukuh.\nTindakan murid: Sebut satu pembetulan yang membantu pembaca dan satu bentuk yang patut dikekalkan.\nSusun kad E/T/K dan serahkan hasil akhir bersama jadual asal.\nSemakan: Gunakan respons penutup untuk mengenal pasti perbezaan salah ejaan dengan pilihan gaya yang masih kabur.\nBahan: Kad kategori dan contoh suntingan.","reflection_original":"____ / ____ murid menyunting lima bahagian merentas tiga aspek; ____ masih keliru dialog/tanda baca; ____ perlu bantuan membaca petikan. Bukti utama: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M37-S3.docx","source_docx_sha256":"f7bfdee3a14415917b7066e2eb554441310f828ffa9207011d44793ed41a0a8c","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":37,"session":3,"revision":"r2","title_original":"Bas Kita","sk_original":"3.3 Menghasilkan penulisan","sp_original":"3.3.2(i)(ii)(iii)","sp_support_original":"—","objective_original":"Murid dapat membaiki ayat dari segi ejaan, tanda baca dan penggunaan kata.","success_criteria_original":"Membaiki tiga bahagian ayat yang ditunjukkan.; Membaca semula ayat yang telah dibaiki.","textbook_pages_original":"m/s 77","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk Bas Kita.\nGuru tanya cara menjaga bas sekolah.\nTindakan murid: Murid melihat buku.\nMurid memberi satu cadangan mudah.\nSemakan: Bantu murid menyebut duduk dengan tertib.\nBahan: Buku teks halaman 77","BBM/ABM":"Buku teks halaman 77","PAK-21":"Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali cerita bas","execution_original":"Tindakan guru: Guru tunjuk tajuk Bas Kita.\nGuru tanya cara menjaga bas sekolah.\nTindakan murid: Murid melihat buku.\nMurid memberi satu cadangan mudah.\nSemakan: Bantu murid menyebut duduk dengan tertib.\nBahan: Buku teks halaman 77","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 77\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},{"phase_original":"Langkah 2\nLihat contoh pembetulan","execution_original":"Tindakan guru: Guru baca ayat yang mengandungi tempat dudok.\nGuru tunjuk ejaan betul duduk.\nTindakan murid: Murid membandingkan dua ejaan.\nMurid membaca semula frasa tempat duduk.\nSemakan: Terangkan bahawa petikan ini perlu disemak sebelum ditulis semula.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},{"phase_original":"Langkah 3\nBaiki bersama","execution_original":"Tindakan guru: Guru bimbing pembetulan cereta kepada cerita.\nGuru tambah noktah selepas tugasan sekolah sebelum ayat Mereka tidak membuang masa.\nGuru cadangkan kawasan perumahan sebagai frasa yang lebih sesuai daripada tempat perumahan.\nTindakan murid: Murid membaca ayat selepas dibaiki.\nMurid menunjukkan ejaan, noktah dan kata yang diganti.\nSemakan: Bezakan ejaan salah dengan pilihan kata yang boleh diperelok.\nBahan: Kad pembetulan\nAyat di papan putih","aids_and_pak21_original":"BBM/ABM: Kad pembetulan\nAyat di papan putih\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri tiga ayat pilihan yang sama.\nGuru tanda bahagian yang perlu disemak untuk pasangan yang memerlukan bantuan.\nTindakan murid: Murid mencari cereta, tempat noktah dan tempat perumahan.\nMurid berbincang tentang pembetulan sebelum membaca ayat semula.\nSemakan: Bantu satu bahagian pada satu masa.\nBahan: Lembaran ayat\nKad perkataan","aids_and_pak21_original":"BBM/ABM: Lembaran ayat\nKad perkataan\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},{"phase_original":"Langkah 5\nTulis pembetulan","execution_original":"Tindakan guru: Guru minta murid menulis pembetulan pada lembaran sendiri.\nGuru semak setiap lembaran semasa murid membaca ayat.\nTindakan murid: Murid menulis cerita dan kawasan perumahan pada ruang yang betul.\nMurid menambah noktah sebelum Mereka tidak membuang masa.\nSemakan: Tiga bahagian ringkas sahaja disemak; tidak perlu menyalin seluruh petikan.\nBahan: Lembaran individu","aids_and_pak21_original":"BBM/ABM: Lembaran individu\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru ajak murid membaca ayat yang betul.\nGuru ulang cara menyemak ejaan, noktah dan pilihan kata.\nTindakan murid: Murid membaca ayat bersama.\nMurid menyebut satu pembetulan yang dipelajari.\nSemakan: Ulang pembetulan yang masih mengelirukan.\nBahan: Ayat di papan putih","aids_and_pak21_original":"BBM/ABM: Ayat di papan putih\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Membaiki ayat menggunakan pilihan jawapan.\nBahan: Lembaran bahagian bergaris\nKad cerita dan kawasan perumahan\nBimbingan guru: Guru baca satu ayat dahulu.\nGuru tunjuk tempat ayat berakhir.\nLangkah murid: Pilih kad ejaan betul.\nLetakkan noktah dengan bantuan.\nLengkapkan frasa kawasan perumahan.\nHasil individu: Lembaran pembetulan berpandu.\nKriteria: Pembetulan sesuai selepas contoh guru.\nSusulan: Ulang satu ayat sahaja sebelum menambah ayat lain.","aids_and_pak21_original":"BBM/ABM: Lembaran bahagian bergaris\nKad cerita dan kawasan perumahan\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Membaiki tiga bahagian dalam ayat pilihan.\nBahan: Lembaran tiga ayat\nKad rujukan\nBimbingan guru: Guru ingatkan murid membaca ayat hingga selesai.\nGuru bantu mencari bahagian yang belum dibaiki.\nLangkah murid: Baca dengan rakan.\nBaiki ejaan, noktah dan frasa pilihan.\nTulis pembetulan pada lembaran sendiri.\nHasil individu: Tiga pembetulan pada lembaran.\nKriteria: Ayat menjadi jelas selepas pembetulan.\nSusulan: Baca semula ayat untuk menyemak hasil.","aids_and_pak21_original":"BBM/ABM: Lembaran tiga ayat\nKad rujukan\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Membaiki nama Pak Salim pada ucapan akhir.\nBahan: Ayat akhir dalam buku\nBimbingan guru: Guru tunjuk pak salim.\nGuru ingatkan nama orang bermula dengan huruf besar.\nLangkah murid: Cari nama pada ayat akhir.\nTulis Pak Salim dengan betul.\nBaca ucapan terima kasih dengan nada sopan.\nHasil individu: Satu pembetulan tambahan.\nKriteria: Huruf besar nama orang digunakan dengan betul.\nSusulan: Murid boleh membantu rakan membaca tanpa memberi semua jawapan.","aids_and_pak21_original":"BBM/ABM: Ayat akhir dalam buku\nPAK-21: Semakan berpasangan: murid membaca ayat dan memilih pembetulan bersama."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan lembaran pembetulan.","Evidens":"Tiga bahagian ayat yang dibaiki setiap murid.","Kriteria Kejayaan":"Pembetulan ejaan, noktah dan pilihan kata sesuai."},"closure_original":"Tindakan guru: Guru ajak murid membaca ayat yang betul.\nGuru ulang cara menyemak ejaan, noktah dan pilihan kata.\nTindakan murid: Murid membaca ayat bersama.\nMurid menyebut satu pembetulan yang dipelajari.\nSemakan: Ulang pembetulan yang masih mengelirukan.\nBahan: Ayat di papan putih","reflection_original":"__ daripada __ murid dapat membaiki ayat yang diberikan. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M37-S3.docx","source_docx_sha256":"3567ce79b9c140f99a7824ade998acc832cc6e1d107c2086c523f4be0a9dedc9","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":3,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M37-S4","week_no":37,"session_no":4,"lesson_map":{"title":"Elis yang Baik Hati","sp":"5.3.2","page":78,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":37,"session":4,"revision":"r1","title_original":"Elis yang Baik Hati","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2(ii)(iii)","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat melengkapkan tiga bahagian perenggan Elis yang Baik Hati dengan sekurang-kurangnya empat ayat yang merangkumi ayat tunggal dan ayat majmuk, menggunakan lalu atau serta mengikut urutan serta gambar buku.","success_criteria_original":"Tiga bahagian yang dilengkapkan ialah Elis di meja Puan Siti, Elis menghiburkan anak kecil dan penutup ucapan terima kasih; murid merujuk kedua-dua halaman.; Hasil keseluruhan mengandungi sekurang-kurangnya satu ayat tunggal dan dua ayat majmuk yang menghubungkan tindakan secara sesuai, bukan satu senarai frasa.; Ayat mengekalkan bukti gambar: kereta sorong bayi dan patung beruang pada bahagian menghiburkan. Watak dan urutan tidak berubah menjadi cerita lain.","textbook_pages_original":"m/s 78,79","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjukkan bahagian awal BT78: keluarga Elis makan malam di Restoran Kantan dan Puan Siti memangku anak kecil yang menangis. Tanya ‘Apakah masalah yang perlu diselesaikan?’\nTulis ayat buku ‘Anak kecil itu menangis.’ Minta murid mengenal pasti siapa dan apa yang berlaku untuk mengingat semula ayat tunggal.\nTindakan murid: Sebut masalah berdasarkan teks atau gambar, bukan mereka sebab kesihatan anak kecil.\nTunjuk subjek dan predikat pada ayat pendek; cadangkan bahawa Elis hendak membantu tetapi perlu meminta izin.\nSemakan: Jika murid menambah fakta bayi lapar atau sakit, bezakan tekaan daripada perkara yang dinyatakan; fokus pada menangis dan Puan Siti belum dapat menikmati makanan.\nBahan: Gambar awal dan ayat contoh BT78.","BBM/ABM":"Gambar awal dan ayat contoh BT78.","PAK-21":"Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Anak menangis, ibu belum dapat makan","execution_original":"Tindakan guru: Tunjukkan bahagian awal BT78: keluarga Elis makan malam di Restoran Kantan dan Puan Siti memangku anak kecil yang menangis. Tanya ‘Apakah masalah yang perlu diselesaikan?’\nTulis ayat buku ‘Anak kecil itu menangis.’ Minta murid mengenal pasti siapa dan apa yang berlaku untuk mengingat semula ayat tunggal.\nTindakan murid: Sebut masalah berdasarkan teks atau gambar, bukan mereka sebab kesihatan anak kecil.\nTunjuk subjek dan predikat pada ayat pendek; cadangkan bahawa Elis hendak membantu tetapi perlu meminta izin.\nSemakan: Jika murid menambah fakta bayi lapar atau sakit, bezakan tekaan daripada perkara yang dinyatakan; fokus pada menangis dan Puan Siti belum dapat menikmati makanan.\nBahan: Gambar awal dan ayat contoh BT78.","aids_and_pak21_original":"BBM/ABM: Gambar awal dan ayat contoh BT78.\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},{"phase_original":"Langkah 2\nModel — Dua tindakan, satu hubungan","execution_original":"Tindakan guru: Baca bahagian Elis meminta kebenaran di BT79, kemudian tunjuk ayat ‘Dia ___ lalu ___.’ Susun frasa berkata sesuatu dan mengambil anak kecil itu mengikut urutan.\nModelkan contoh pelengkap guru: ‘Dia berkata sesuatu lalu mengambil anak kecil itu.’ Tanda dua tindakan, terangkan lalu menghubungkan tindakan berturutan; bandingkan dengan ayat tunggal ‘Elis pergi ke meja Puan Siti.’\nTindakan murid: Baca dua ayat dan sebut tindakan yang digabungkan dalam ayat majmuk.\nTukar dua jalur tindakan secara sengaja, baca semula dan jelaskan mengapa urutannya kurang sesuai dalam cerita.\nSemakan: Jangan mengajar bahawa semua ayat panjang semestinya majmuk. Semak hubungan tindakan dan binaan ayat, bukan bilangan perkataan sahaja.\nBahan: Jalur tindakan pergi/berkata/mengambil, kad lalu dan BT79.","aids_and_pak21_original":"BBM/ABM: Jalur tindakan pergi/berkata/mengambil, kad lalu dan BT79.\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},{"phase_original":"Langkah 3\nLatihan terbeza — Sambungkan babak dengan bukti","execution_original":"Tindakan guru: Jalankan tiga laluan terbeza di bawah untuk bahagian meja Puan Siti, kereta sorong bayi dan penutup. Semua murid mengusahakan bentuk perenggan, bukan sekadar memilih jenis ayat.\nBimbing murid menggunakan gambar: anak diletakkan di dalam kereta sorong bayi dan dihiburkan dengan patung beruang. Tanya ‘Bahagian mana menunjukkan hal itu?’ sebelum menerima pelengkap; jangan menambah katil, buaian atau makanan.\nTindakan murid: Susun frasa dan penghubung mengikut bahagian cerita. Dalam pasangan, seorang menerangkan gambar, seorang mencadangkan ayat, kemudian bertukar peranan.\nCuba satu ayat tunggal dan satu ayat majmuk bagi babak menghiburkan; baca untuk memastikan siapa melakukan setiap tindakan jelas.\nSemakan: Semak penggunaan kata ganti supaya ‘dia’ tidak menukar rujukan antara Elis dan Puan Siti tanpa penjelasan. Bantuan gambar dan rangka direkod.\nBahan: BT78–79, lembaran tiga kotak, kad lalu/serta/dan dan frasa bantuan.","aids_and_pak21_original":"BBM/ABM: BT78–79, lembaran tiga kotak, kad lalu/serta/dan dan frasa bantuan.\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},{"phase_original":"Langkah 4\nPenulisan individu — Lengkapkan tiga bahagian","execution_original":"Tindakan guru: Minta murid menulis pelengkap sendiri bagi tiga bahagian. Cadangan guru untuk babak menghiburkan boleh menggunakan serta dan diikuti ayat tunggal ‘Anak kecil itu berhenti menangis.’\nPada penutup, arah murid kembali kepada frasa bersalaman dan mengucapkan terima kasih di BT78. Jika subjek dalam gambar tidak pasti, gunakan rujukan watak yang disokong dan semak bersama guru; jangan meninggalkan penutup.\nTindakan murid: Tulis sekurang-kurangnya empat ayat keseluruhan dalam bahagian perenggan, merangkumi dua ayat majmuk dan satu ayat tunggal.\nGariskan kata hubung dan tandakan dua tindakan yang digabungkan; baca seluruh sambungan agar cerita tidak terputus.\nSemakan: Empat ayat terpisah tanpa kaitan perenggan belum menepati tugasan. Murid menyusun semula ayat supaya urutan bantuan dapat diikuti.\nBahan: Lembaran individu dan buku sebagai rujukan gambar.","aids_and_pak21_original":"BBM/ABM: Lembaran individu dan buku sebagai rujukan gambar.\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},{"phase_original":"Langkah 5\nPBD — Uji ayat dengan cerita","execution_original":"Tindakan guru: Semak tiga bahagian lengkap, liputan ayat tunggal/majmuk dan penghubung. Tanya murid menerangkan satu pilihan lalu atau serta.\nBezakan masalah tatabahasa daripada salah butiran gambar. Catat kedua-duanya untuk bimbingan, tanpa memadam idea murid yang masih munasabah.\nTindakan murid: Tukar hasil dengan pasangan untuk semakan urutan, kemudian buat sendiri satu pembetulan yang diperlukan.\nTunjuk ayat tunggal dan dua ayat majmuk kepada guru; jelaskan tindakan yang disambungkan.\nSemakan: Hasil pasangan hanya maklum balas. Guru menilai tulisan individu dan mencatat bantuan atau aspek yang belum diperiksa.\nBahan: Perenggan individu dan senarai semak bentuk ayat/urutan/bukti.","aids_and_pak21_original":"BBM/ABM: Perenggan individu dan senarai semak bentuk ayat/urutan/bukti.\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},{"phase_original":"Langkah 6\nPenutup — Ayat menghubungkan tindakan baik","execution_original":"Tindakan guru: Baca satu contoh ayat tunggal dan satu ayat majmuk tanpa menyebut nama penulis. Tanya perbezaan cara maklumat disampaikan.\nRumusan urutan meminta izin, membantu dan menerima penghargaan. Ingatkan bahawa membantu kanak-kanak kecil dilakukan dengan izin serta pengawasan orang dewasa.\nTindakan murid: Sebut satu ayat lengkap menggunakan lalu atau serta berdasarkan babak pilihan.\nSerahkan tiga bahagian perenggan dan nyatakan bahagian yang masih memerlukan bantuan.\nSemakan: Catat kesalahan penghubung yang berulang untuk intervensi, bukan menganggap semua murid mencapai objektif kerana cerita telah tamat.\nBahan: Ayat pilihan daripada hasil murid.","aids_and_pak21_original":"BBM/ABM: Ayat pilihan daripada hasil murid.\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bina perenggan dengan jalur tindakan","implementation_original":"Tugasan: Melengkapkan tiga bahagian perenggan menggunakan jalur frasa bergambar, kemudian mengurangkan bantuan pada ayat penutup.\nBahan: Rangka ‘Dia ___ lalu ___.’ dan ‘Elis ___ serta ___.’\nPilihan kereta sorong bayi/patung beruang yang sepadan gambar\nKad ayat tunggal ‘Anak kecil itu berhenti menangis.’\nBimbingan guru: Modelkan satu cantuman dan minta murid menunjuk kedua-dua tindakan. Jangan membacakan semua ayat untuk disalin tanpa pilihan murid.\nSelepas babak pertama, simpan ayat model tetapi biarkan kata kunci. Bantu mengenal subjek untuk babak penutup.\nLangkah murid: Padankan frasa dengan gambar yang betul.\nSusun dua tindakan dan pilih lalu atau serta daripada kad.\nBaca ayat majmuk dan tambahkan ayat tunggal tentang anak berhenti menangis.\nTulis pelengkap tiga bahagian dan semak bahawa sekurang-kurangnya empat ayat terbentuk.\nHasil individu: Tiga bahagian perenggan individu dengan empat ayat dan kata hubung ditandai.\nKriteria: Jenis ayat dan urutan betul dengan bantuan direkod; jika hanya satu bahagian siap, catat pencapaian separa dan sambung sasaran yang belum selesai.\nSusulan: Buang satu rangka pada percubaan berikutnya. Jika pelaku keliru, tulis nama Elis/Puan Siti pada kad sebelum menggunakan dia.","aids_and_pak21_original":"BBM/ABM: Rangka ‘Dia ___ lalu ___.’ dan ‘Elis ___ serta ___.’\nPilihan kereta sorong bayi/patung beruang yang sepadan gambar\nKad ayat tunggal ‘Anak kecil itu berhenti menangis.’\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},"pembina":{"label":"Langkah 1\nPembina — Ayat dibina daripada frasa buku","implementation_original":"Tugasan: Membina sambungan perenggan dengan frasa panduan asal tanpa pilihan ayat penuh.\nBahan: BT78–79\nLembaran tiga kotak kosong\nKad semakan ‘siapa–tindakan–hubungan’\nBimbingan guru: Tanya apakah hubungan antara dua tindakan sebelum murid memilih kata hubung.\nSemak bahawa perenggan ketiga menutup cerita melalui bersalaman atau ucapan terima kasih, bukan mengulang babak anak menangis.\nLangkah murid: Baca bahagian sedia ada dan kenal pasti tempat sambungan.\nDraf pelengkap meja Puan Siti dengan lalu.\nTulis babak kereta sorong dan patung beruang menggunakan serta serta satu ayat tunggal.\nLengkapkan penutup, baca sambungan keseluruhan dan betulkan rujukan kata ganti.\nHasil individu: Tiga bahagian lengkap yang boleh dibaca sebagai sambungan cerita, dengan satu tunggal dan dua majmuk ditunjukkan.\nKriteria: Sekurang-kurangnya empat ayat, penghubung sesuai dan isi berdasarkan gambar/frasa, tanpa memerlukan teks jawapan seragam.\nSusulan: Jika tepat, cuba ungkap semula satu ayat sambil mengekalkan hubungan tindakan; jika tidak, asingkan dua klausa sebelum mencantum semula.","aids_and_pak21_original":"BBM/ABM: BT78–79\nLembaran tiga kotak kosong\nKad semakan ‘siapa–tindakan–hubungan’\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — Pilihan penghubung yang bersebab","implementation_original":"Tugasan: Menulis sambungan dan menilai bagaimana perubahan penghubung mempengaruhi urutan atau penambahan maklumat.\nBahan: BT78–79\nKad lalu/serta/dan\nJalur dua versi ayat guru untuk dibandingkan\nBimbingan guru: Tanya sama ada menukar lalu kepada serta mengekalkan maksud yang hendak ditekankan. Terima penjelasan mudah tanpa memaksa istilah linguistik.\nMinta murid mengesan satu rujukan dia yang kabur dan menukarnya kepada nama, bukan menambah kejadian atau dialog rekaan.\nLangkah murid: Tulis tiga sambungan dengan liputan bentuk ayat sasaran.\nPilih satu ayat majmuk dan cuba penghubung lain.\nBandingkan maksud kedua-dua versi dengan babak buku dan pilih yang lebih sesuai.\nSemak subjek serta urutan, kemudian terangkan satu keputusan bahasa kepada pasangan.\nHasil individu: Perenggan lengkap dan satu perbandingan ayat bersebab; bukan karangan lebih panjang semata-mata.\nKriteria: Mencapai sasaran teras serta menjelaskan fungsi satu penghubung dan membaiki rujukan yang kabur tanpa meninggalkan konteks.\nSusulan: Gunakan pemeriksaan siapa–tindakan–hubungan pada ayat penutup; jika alasan tidak jelas, kembali kepada urutan gambar dan baca kedua-dua versi.","aids_and_pak21_original":"BBM/ABM: BT78–79\nKad lalu/serta/dan\nJalur dua versi ayat guru untuk dibandingkan\nPAK-21: Sentence Combining berpasangan: seorang menyusun dua tindakan, seorang memilih penghubung dan menyemak makna. Pasangan bertukar peranan sebelum masing-masing menulis perenggan sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan perenggan individu dan soal jawab tentang bentuk ayat serta pilihan penghubung.","Evidens":"Tiga bahagian perenggan dengan sekurang-kurangnya empat ayat, termasuk satu tunggal dan dua majmuk; tanda kata hubung dan alasan lisan ringkas.","Kriteria Kejayaan":"Bentuk ayat, hubungan tindakan, urutan dan butiran gambar tepat; tahap bantuan direkod, bukan bilangan ayat sahaja."},"closure_original":"Tindakan guru: Baca satu contoh ayat tunggal dan satu ayat majmuk tanpa menyebut nama penulis. Tanya perbezaan cara maklumat disampaikan.\nRumusan urutan meminta izin, membantu dan menerima penghargaan. Ingatkan bahawa membantu kanak-kanak kecil dilakukan dengan izin serta pengawasan orang dewasa.\nTindakan murid: Sebut satu ayat lengkap menggunakan lalu atau serta berdasarkan babak pilihan.\nSerahkan tiga bahagian perenggan dan nyatakan bahagian yang masih memerlukan bantuan.\nSemakan: Catat kesalahan penghubung yang berulang untuk intervensi, bukan menganggap semua murid mencapai objektif kerana cerita telah tamat.\nBahan: Ayat pilihan daripada hasil murid.","reflection_original":"____ / ____ murid melengkapkan tiga bahagian dengan jenis ayat sasaran; ____ memerlukan rangka; ____ masih keliru penghubung atau kata ganti. Bahagian belum disemak: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M37-S4.docx","source_docx_sha256":"71d225551d3e2ed9bacd9cf4517b5062715930bd31dbc71b6fa5cb5dd99a1808","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":37,"session":4,"revision":"r2","title_original":"Elis yang Baik Hati","sk_original":"5.3 Memahami dan membina ayat mengikut konteks","sp_original":"5.3.2(ii)(iii)","sp_support_original":"—","objective_original":"Murid dapat menulis perenggan pendek menggunakan ayat tunggal dan ayat majmuk.","success_criteria_original":"Menulis satu perenggan pendek dengan bantuan rangka.; Menggunakan ayat tunggal dan ayat majmuk dalam perenggan.","textbook_pages_original":"m/s 78,79","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk gambar anak kecil menangis.\nGuru tanya, “Siapakah yang mahu membantu?”\nTindakan murid: Murid melihat gambar dalam buku.\nMurid menyebut Elis.\nSemakan: Bantu murid mengenali watak melalui teks.\nBahan: Buku teks halaman 78–79","BBM/ABM":"Buku teks halaman 78–79","PAK-21":"Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali cerita","execution_original":"Tindakan guru: Guru tunjuk gambar anak kecil menangis.\nGuru tanya, “Siapakah yang mahu membantu?”\nTindakan murid: Murid melihat gambar dalam buku.\nMurid menyebut Elis.\nSemakan: Bantu murid mengenali watak melalui teks.\nBahan: Buku teks halaman 78–79","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 78–79\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},{"phase_original":"Langkah 2\nBaca bahagian awal","execution_original":"Tindakan guru: Guru baca kisah Elis makan malam bersama keluarga.\nGuru jelaskan Elis meminta kebenaran sebelum membantu Puan Siti.\nTindakan murid: Murid mengikuti bacaan.\nMurid menyebut tindakan baik Elis.\nSemakan: Terima jawapan lisan yang pendek.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},{"phase_original":"Langkah 3\nBina perenggan bersama","execution_original":"Tindakan guru: Guru beri contoh “Elis meletakkan anak kecil itu di dalam kereta sorong.”\nGuru sambung “Dia menghiburkan anak itu dengan patung beruang lalu anak itu berhenti menangis.”\nTindakan murid: Murid mengulang ayat satu demi satu.\nMurid membaca dua ayat itu sebagai satu perenggan.\nSemakan: Tunjuk bahawa ayat berkaitan ditulis bersama dalam satu perenggan.\nBahan: Gambar halaman 79\nRangka perenggan","aids_and_pak21_original":"BBM/ABM: Gambar halaman 79\nRangka perenggan\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri rangka dua ayat dengan kata bantuan.\nGuru bantu pasangan memilih kereta sorong, patung beruang dan lalu.\nTindakan murid: Murid melengkapkan perenggan bersama rakan.\nMurid bergilir membaca perenggan yang lengkap.\nSemakan: Bantu penggunaan Dia supaya masih merujuk kepada Elis.\nBahan: Kad perkataan\nRangka perenggan","aids_and_pak21_original":"BBM/ABM: Kad perkataan\nRangka perenggan\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},{"phase_original":"Langkah 5\nTulis sendiri","execution_original":"Tindakan guru: Guru minta murid menulis perenggan pendek yang dilatih.\nGuru semak ayat dan tanda noktah.\nTindakan murid: Murid menulis dua ayat dalam satu perenggan.\nMurid membaca semula hasil sendiri dengan bantuan jika perlu.\nSemakan: Rangka dan buku boleh dirujuk.\nBahan: Buku latihan\nBuku teks","aids_and_pak21_original":"BBM/ABM: Buku latihan\nBuku teks\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru baca bahagian bersalaman dan mengucapkan terima kasih.\nGuru ajak murid menyebut cara membantu orang dengan baik.\nTindakan murid: Murid mendengar pengakhiran cerita.\nMurid berkongsi satu sikap baik Elis.\nSemakan: Kukuhkan nilai prihatin.\nBahan: Buku teks","aids_and_pak21_original":"BBM/ABM: Buku teks\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Melengkapkan perenggan dengan tiga kata pilihan.\nBahan: Rangka dua ayat\nKad kereta sorong, patung beruang dan lalu\nBimbingan guru: Guru baca ayat sambil menunjuk gambar.\nGuru bantu memilih kata pada setiap ruang.\nLangkah murid: Lihat gambar.\nLengkapkan ayat bersama guru.\nTulis perenggan dengan merujuk contoh.\nHasil individu: Perenggan pendek berpandu.\nKriteria: Ayat sesuai dengan gambar dan dibaca sebagai satu cerita.\nSusulan: Baca semula satu ayat pada satu masa.","aids_and_pak21_original":"BBM/ABM: Rangka dua ayat\nKad kereta sorong, patung beruang dan lalu\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Menulis perenggan tentang Elis menghiburkan anak kecil.\nBahan: Buku teks\nRangka awal ayat\nBimbingan guru: Guru beri contoh ayat tunggal.\nGuru bantu menyambung dua tindakan dengan lalu.\nLangkah murid: Cuba ayat bersama rakan.\nSusun dua ayat yang berkaitan.\nTulis dalam satu perenggan.\nHasil individu: Perenggan dua ayat.\nKriteria: Terdapat ayat tunggal dan ayat majmuk yang sesuai.\nSusulan: Bantu membetulkan ayat yang belum lengkap.","aids_and_pak21_original":"BBM/ABM: Buku teks\nRangka awal ayat\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menambah satu ayat penutup tentang ucapan terima kasih.\nBahan: Gambar akhir\nKad mengucapkan terima kasih\nBimbingan guru: Guru tunjuk gambar bersalaman.\nGuru beri awal ayat “Puan Siti...”\nLangkah murid: Lihat gambar akhir.\nBina satu ayat penutup.\nTambah ayat pada perenggan jika sesuai.\nHasil individu: Perenggan dengan satu ayat tambahan.\nKriteria: Ayat penutup berkaitan dengan cerita.\nSusulan: Kongsi perenggan kepada rakan jika mahu.","aids_and_pak21_original":"BBM/ABM: Gambar akhir\nKad mengucapkan terima kasih\nPAK-21: Bincang berpasangan untuk melengkapkan perenggan tentang Elis."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan perenggan dalam buku latihan.","Evidens":"Perenggan pendek setiap murid.","Kriteria Kejayaan":"Perenggan mengandungi ayat tunggal dan ayat majmuk yang sesuai."},"closure_original":"Tindakan guru: Guru baca bahagian bersalaman dan mengucapkan terima kasih.\nGuru ajak murid menyebut cara membantu orang dengan baik.\nTindakan murid: Murid mendengar pengakhiran cerita.\nMurid berkongsi satu sikap baik Elis.\nSemakan: Kukuhkan nilai prihatin.\nBahan: Buku teks","reflection_original":"__ daripada __ murid dapat menulis perenggan pendek yang sesuai. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M37-S4.docx","source_docx_sha256":"f3a46e084577648185c32751782fdae5aca077fce79f2a9de740a2a714ada610","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":4,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}},{"session_id":"BM2-M37-S5","week_no":37,"session_no":5,"lesson_map":{"title":"Si Tompok","sp":"5.2.3","page":80,"verification_status":"needs_review"},"r1":{"source":"Hermes DOCX","week":37,"session":5,"revision":"r1","title_original":"Si Tompok","sk_original":"5.2 Memahami dan menggunakan pembentukan kata mengikut konteks","sp_original":"5.2.3","sp_support_original":"—","objective_original":"Pada akhir PdP, murid dapat menghasilkan karangan pendek empat perenggan berdasarkan cerita Si Tompok dengan menggunakan sekurang-kurangnya lima kata ganda secara tepat, termasuk mengiau-ngiau dan mengusap-usap dalam ayat yang dibina sendiri.","success_criteria_original":"Karangan mempunyai urutan pengenalan Si Tompok, kehilangan, berada di rumah Elis dan pemulangan kepada Amira; perenggan boleh pendek tetapi bersambung.; Sekurang-kurangnya lima kata ganda digunakan mengikut maksud dan ejaan, termasuk dua kata panduan yang pada buku belum menjadi ayat lengkap.; Ayat mengiau-ngiau dan mengusap-usap dibina sendiri berdasarkan konteks; kata ganda tidak sekadar disenaraikan tanpa ayat.","textbook_pages_original":"m/s 80","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Tunjuk tajuk dan ayat bahawa anak kucing itu mempunyai tompok-tompok hitam. Tanya apa beza nama Si Tompok dengan perkataan tompok-tompok dalam ayat.\nBaca bahagian Amira kehilangan kucing dan minta murid memilih perasaan risau atau gembira dengan alasan daripada cerita.\nTindakan murid: Sebut nama kucing dan contoh kata ganda tanpa mencampurkan kedua-duanya.\nPadankan gundah-gulana dengan peristiwa kehilangan dan jelaskan secara mudah bahawa Amira risau.\nSemakan: Jika murid menyebut semua perkataan berulang sebagai nama, ulang ayat konteks dan tunjuk fungsi kata tersebut dalam cerita.\nBahan: BT80 dan kad Si Tompok/tompok-tompok/gundah-gulana.","BBM/ABM":"BT80 dan kad Si Tompok/tompok-tompok/gundah-gulana.","PAK-21":"Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},"six_phases_original":[{"phase_original":"Langkah 1\nSet induksi — Tompok pada badan, Si Tompok namanya","execution_original":"Tindakan guru: Tunjuk tajuk dan ayat bahawa anak kucing itu mempunyai tompok-tompok hitam. Tanya apa beza nama Si Tompok dengan perkataan tompok-tompok dalam ayat.\nBaca bahagian Amira kehilangan kucing dan minta murid memilih perasaan risau atau gembira dengan alasan daripada cerita.\nTindakan murid: Sebut nama kucing dan contoh kata ganda tanpa mencampurkan kedua-duanya.\nPadankan gundah-gulana dengan peristiwa kehilangan dan jelaskan secara mudah bahawa Amira risau.\nSemakan: Jika murid menyebut semua perkataan berulang sebagai nama, ulang ayat konteks dan tunjuk fungsi kata tersebut dalam cerita.\nBahan: BT80 dan kad Si Tompok/tompok-tompok/gundah-gulana.","aids_and_pak21_original":"BBM/ABM: BT80 dan kad Si Tompok/tompok-tompok/gundah-gulana.\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},{"phase_original":"Langkah 2\nModel bahasa — Kata ganda menjadi ayat","execution_original":"Tindakan guru: Baca empat bahagian sumber dan susun peristiwa. Tunjukkan bahawa mengiau-ngiau serta mengusap-usap ialah kata panduan berbulet, belum dicetak sebagai ayat lengkap.\nModelkan contoh guru ‘Si Tompok mengiau-ngiau di rumah Elis.’ Bincangkan siapa melakukan bunyi itu. Untuk mengusap-usap, rujuk gerak tangan Elis dalam gambar dan bezakan daripada Amira yang memegang kucing.\nTindakan murid: Padankan kata ganda dengan maksud menggunakan peristiwa, bukan hafalan senarai sahaja.\nCadangkan satu ayat dengan mengusap-usap, sebut pelakunya dan tunjuk gambar yang menyokong pilihan.\nSemakan: Jangan menerima ‘Elis mengiau-ngiau’ sebagai ayat cerita biasa jika tiada konteks meniru bunyi. Pembetulan menumpukan kesesuaian pelaku dan tindakan.\nBahan: Kad kata ganda, kad peristiwa dan gambar BT80.","aids_and_pak21_original":"BBM/ABM: Kad kata ganda, kad peristiwa dan gambar BT80.\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},{"phase_original":"Langkah 3\nLatihan terbeza — Bina rangka empat perenggan","execution_original":"Tindakan guru: Agihkan bantuan mengikut laluan di bawah. Semua murid menghasilkan karangan pendek daripada empat peristiwa; tidak menukar tugasan menjadi padanan perkataan sahaja.\nBimbing murid meletakkan kata ganda pada perenggan yang sesuai. Tanya ‘Perasaan siapa?’ atau ‘Tindakan siapa?’ apabila perkataan betul ejaan tetapi tidak tepat makna.\nTindakan murid: Dalam pasangan, pilih kata ganda untuk setiap peristiwa dan jelaskan satu sebab pemilihan.\nBina rangka sendiri dengan sekurang-kurangnya lima kata sasaran. Susun ayat untuk perenggan rumah Elis dan pemulangan tanpa menambah cara pengangkutan atau dialog yang tiada dalam buku.\nSemakan: Pastikan mengiau-ngiau dan mengusap-usap digunakan dalam ayat baharu, bukan hanya ditulis sebagai tajuk atau senarai. Murid boleh menggunakan lebih lima kata jika tepat.\nBahan: Lembaran empat perenggan, kad maksud, rangka ayat terhad.","aids_and_pak21_original":"BBM/ABM: Lembaran empat perenggan, kad maksud, rangka ayat terhad.\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},{"phase_original":"Langkah 4\nPenulisan individu — Cerita yang bersambung","execution_original":"Tindakan guru: Minta murid menulis empat perenggan pendek berdasarkan rangka. Bahagian awal boleh diparafrasa atau dilengkapkan dengan bantuan; dua kata panduan mesti menjadi ayat sendiri.\nIngatkan bahawa hasil bukan salinan penuh teks rakan. Semak satu ayat setiap murid ketika bergerak dan nyatakan bantuan yang diberi.\nTindakan murid: Tulis pengenalan, kehilangan, pertemuan dan pemulangan dalam urutan.\nGariskan sekurang-kurangnya lima kata ganda serta semak tanda sempang dan rujukan nama Amira/Elis/Si Tompok.\nSemakan: Jika masa terhad, kekalkan perenggan satu atau dua ayat yang bermakna; tidak menambah panjang karangan dengan peristiwa rekaan.\nBahan: Buku latihan atau lembaran empat perenggan dan BT80.","aids_and_pak21_original":"BBM/ABM: Buku latihan atau lembaran empat perenggan dan BT80.\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},{"phase_original":"Langkah 5\nPBD — Lima kata, dua ayat ciptaan sendiri","execution_original":"Tindakan guru: Semak kata ganda mengikut ejaan dan makna. Minta murid membaca dua ayat baharu yang menggunakan mengiau-ngiau serta mengusap-usap.\nCatat sama ada lima kata digunakan dalam ayat serta empat peristiwa lengkap. Jumlah perkataan sahaja tidak membuktikan penguasaan konteks.\nTindakan murid: Bertukar hasil untuk menanda kata yang tidak sesuai peristiwa, kemudian penulis sendiri membetulkannya.\nBaca dua ayat pilihan kepada guru atau jelaskan semasa guru menyemak, tanpa rakan menggantikan respons.\nSemakan: Hasil dengan lima kata tetapi tanpa perenggan atau ayat lengkap memerlukan susulan. Perenggan yang sudah baik tidak perlu ditulis semula seluruhnya kerana satu kata salah.\nBahan: Karangan individu, senarai semak kata/peristiwa/ayat.","aids_and_pak21_original":"BBM/ABM: Karangan individu, senarai semak kata/peristiwa/ayat.\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},{"phase_original":"Langkah 6\nPenutup — Kata yang tepat menceritakan perubahan","execution_original":"Tindakan guru: Bandingkan kata gundah-gulana semasa kehilangan dengan tindakan mengusap-usap selepas pemulangan. Tanya bagaimana kata itu membantu pembaca memahami cerita.\nRumusan maksud kata ganda dan tindakan prihatin Elis. Pilih contoh masalah konteks untuk intervensi seterusnya.\nTindakan murid: Sebut satu kata ganda dan ayatnya daripada karangan sendiri.\nSerahkan karangan serta rangka dan nyatakan kata yang masih sukar difahami.\nSemakan: Refleksi diisi selepas hasil disemak, bukan menggunakan angka pencapaian yang diandaikan.\nBahan: Kad kata ganda dan hasil karangan.","aids_and_pak21_original":"BBM/ABM: Kad kata ganda dan hasil karangan.\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Empat peristiwa dengan rangka terhad","implementation_original":"Tugasan: Membina karangan empat perenggan pendek dengan kad peristiwa dan pilihan kata, sambil menghasilkan sendiri ayat bagi dua kata panduan.\nBahan: Empat kotak bernama Kenal–Hilang–Ditemui–Dipulangkan\nRangka ‘Amira berasa … kerana …’ dan ‘Si Tompok … di rumah Elis’\nKad makna risau/bunyi kucing/membelai\nBimbingan guru: Padankan satu peristiwa dengan kata ganda bersama murid, kemudian minta mereka memilih sendiri untuk peristiwa berikutnya.\nBantu menyebut ayat secara lisan sebelum menulis. Kurangkan rangka pada ayat pemulangan, tetapi kekalkan kad kata mengusap-usap.\nLangkah murid: Susun empat peristiwa mengikut buku.\nLetakkan kata ganda pada kotak peristiwa yang sesuai.\nSebut dan tulis satu atau dua ayat setiap kotak, termasuk dua ayat panduan yang dibina sendiri.\nGariskan lima kata sasaran dan baca urutan cerita bersama guru.\nHasil individu: Karangan pendek empat perenggan dengan bantuan ditandai, bukan sekadar kad yang sudah dipadankan.\nKriteria: Lima kata digunakan dengan makna sesuai termasuk dua kata panduan. Jika hanya padanan siap tetapi ayat belum terbina, sasaran penulisan belum selesai.\nSusulan: Ulang satu ayat yang pelakunya salah menggunakan kad Amira/Elis/kucing, kemudian tulis tanpa rangka pada percubaan seterusnya.","aids_and_pak21_original":"BBM/ABM: Empat kotak bernama Kenal–Hilang–Ditemui–Dipulangkan\nRangka ‘Amira berasa … kerana …’ dan ‘Si Tompok … di rumah Elis’\nKad makna risau/bunyi kucing/membelai\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},"pembina":{"label":"Langkah 1\nPembina — Karangan daripada kata kunci","implementation_original":"Tugasan: Menulis semula aliran cerita dengan kata sendiri dan mengembangkan dua bahagian akhir menggunakan kata ganda yang disediakan.\nBahan: BT80\nLembaran perenggan tanpa ayat model\nSenarai kata ganda dan semakan sempang\nBimbingan guru: Tanya pelaku serta maksud kata pada ayat yang kabur; elakkan memberikan keseluruhan karangan untuk disalin.\nSemak bahawa murid membezakan maklumat asal dengan ayat pengembangan, khususnya tindakan mengusap dalam gambar terakhir.\nLangkah murid: Catat kata kunci setiap peristiwa.\nPilih sekurang-kurangnya lima kata ganda yang meliputi dua kata panduan.\nTulis empat perenggan yang bersambung dengan rujukan watak jelas.\nBaca kepada pasangan, semak konteks dan ejaan, kemudian baiki sendiri dua ayat akhir jika perlu.\nHasil individu: Karangan empat perenggan serta lima kata sasaran digariskan.\nKriteria: Konteks, urutan dan ejaan tepat; dua ayat panduan dihasilkan sendiri dan bukan salinan jawapan pasangan.\nSusulan: Jika tepat, cuba menukar satu ayat tanpa kehilangan maksud kata ganda; jika tidak, kembali pada pasangan peristiwa–kata sebelum menulis semula ayat itu sahaja.","aids_and_pak21_original":"BBM/ABM: BT80\nLembaran perenggan tanpa ayat model\nSenarai kata ganda dan semakan sempang\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."},"pencabar":{"label":"Langkah 1\nPencabar — Memurnikan pilihan kata dan pelaku","implementation_original":"Tugasan: Menghasilkan karangan dan menilai satu pilihan kata ganda yang tidak sepadan peristiwa, dengan menjelaskan kesan pembetulan kepada maksud.\nBahan: BT80\nKad ayat rekaan guru ‘Amira gundah-gulana kerana kucingnya sudah dipulangkan dengan selamat’\nSenarai semak siapa–tindakan–perasaan\nBimbingan guru: Minta murid membezakan kemungkinan cerita rekaan dengan konteks buku; untuk tugas ini, pilihan perkataan mesti berpaut kepada urutan sumber.\nGalakkan ayat yang lebih jelas, bukan menambah kemalangan, kenderaan atau dialog semata-mata untuk menjadikan karangan panjang.\nLangkah murid: Tulis empat perenggan dengan sasaran teras lengkap.\nBandingkan ayat kad guru dengan peristiwa pemulangan dan jelaskan ketidakpadanan perasaan.\nBaiki satu ayat karangan sendiri dari segi rujukan pelaku atau ketepatan kata.\nTerangkan dua ayat menggunakan kata panduan kepada rakan dan pertahankan pilihan berdasarkan gambar/teks.\nHasil individu: Karangan lengkap dan satu nota pemurnian ringkas tentang pilihan kata, bukan karangan tambahan.\nKriteria: Sasaran teras dicapai serta pembetulan dapat dijelaskan berasaskan konteks; banyak kata ganda tanpa makna tepat tidak dinilai sebagai pengayaan.\nSusulan: Periksa kata merata-rata dan merayau-rayau dalam ayat berbeza untuk membezakan tempat pencarian dengan pergerakan kucing.","aids_and_pak21_original":"BBM/ABM: BT80\nKad ayat rekaan guru ‘Amira gundah-gulana kerana kucingnya sudah dipulangkan dengan selamat’\nSenarai semak siapa–tindakan–perasaan\nPAK-21: Story Building berpasangan: murid memilih kata ganda yang sesuai untuk satu peristiwa dan menerangkan sebab, kemudian masing-masing menyambung karangan sendiri. Semak rakan digunakan untuk makna dan urutan, bukan menyalin satu jawapan kumpulan."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan karangan individu serta bacaan dua ayat ciptaan sendiri dan alasan pemilihan kata.","Evidens":"Empat perenggan mengikut urutan, lima kata ganda digunakan dalam konteks dan dua ayat baharu yang menggunakan mengiau-ngiau/mengusap-usap.","Kriteria Kejayaan":"Penggunaan kata, ejaan, rujukan pelaku dan urutan cerita tepat; bantuan dicatat dan TP tidak dijana automatik."},"closure_original":"Tindakan guru: Bandingkan kata gundah-gulana semasa kehilangan dengan tindakan mengusap-usap selepas pemulangan. Tanya bagaimana kata itu membantu pembaca memahami cerita.\nRumusan maksud kata ganda dan tindakan prihatin Elis. Pilih contoh masalah konteks untuk intervensi seterusnya.\nTindakan murid: Sebut satu kata ganda dan ayatnya daripada karangan sendiri.\nSerahkan karangan serta rangka dan nyatakan kata yang masih sukar difahami.\nSemakan: Refleksi diisi selepas hasil disemak, bukan menggunakan angka pencapaian yang diandaikan.\nBahan: Kad kata ganda dan hasil karangan.","reflection_original":"____ / ____ murid menghasilkan karangan dengan lima kata ganda tepat; ____ masih memerlukan rangka; ____ belum melengkapkan dua ayat panduan. Kata/peristiwa yang mengelirukan: ____.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r1/BM2-M37-S5.docx","source_docx_sha256":"4b756ee0a5603185e92a9645c2e96ce2ee5fbb9095a788b5389090fe1a1fdb91","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false},"r2":{"source":"Hermes DOCX","week":37,"session":5,"revision":"r2","title_original":"Si Tompok","sk_original":"5.2 Memahami dan menggunakan pembentukan kata mengikut konteks","sp_original":"5.2.3","sp_support_original":"—","objective_original":"Murid dapat menulis karangan pendek tentang Si Tompok menggunakan kata ganda.","success_criteria_original":"Menulis cerita pendek dengan bantuan rangka empat ayat.; Menggunakan dua kata ganda yang sesuai.","textbook_pages_original":"m/s 80","progression_original":"Aplikasi","induction_original":{"Aktiviti":"Tindakan guru: Guru tunjuk tajuk dan gambar kucing.\nGuru tanya, “Apakah bunyi kucing?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut bunyi kucing secara ringkas.\nSemakan: Kaitkan bunyi dengan perkataan mengiau.\nBahan: Buku teks halaman 80","BBM/ABM":"Buku teks halaman 80","PAK-21":"Cerita berpasangan sebelum menulis cerita sendiri."},"six_phases_original":[{"phase_original":"Langkah 1\nKenali Si Tompok","execution_original":"Tindakan guru: Guru tunjuk tajuk dan gambar kucing.\nGuru tanya, “Apakah bunyi kucing?”\nTindakan murid: Murid melihat gambar.\nMurid menyebut bunyi kucing secara ringkas.\nSemakan: Kaitkan bunyi dengan perkataan mengiau.\nBahan: Buku teks halaman 80","aids_and_pak21_original":"BBM/ABM: Buku teks halaman 80\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."},{"phase_original":"Langkah 2\nBaca cerita","execution_original":"Tindakan guru: Guru baca cerita Amira kehilangan Si Tompok.\nGuru jelaskan merayau-rayau bermaksud berjalan ke sana sini.\nTindakan murid: Murid mengikuti cerita.\nMurid menyebut tempat Si Tompok ditemui.\nSemakan: Tunjuk ayat tentang rumah Elis.\nBahan: Buku teks\nKad kata ganda","aids_and_pak21_original":"BBM/ABM: Buku teks\nKad kata ganda\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."},{"phase_original":"Langkah 3\nBina cerita bersama","execution_original":"Tindakan guru: Guru beri contoh “Si Tompok ialah kucing Amira. Si Tompok hilang lalu merayau-rayau ke rumah Elis.”\nGuru sambung “Si Tompok mengiau-ngiau di situ. Elis memulangkan Si Tompok kepada Amira.”\nTindakan murid: Murid mengulang cerita mengikut urutan.\nMurid menyebut dua kata ganda dalam contoh.\nSemakan: Nyatakan cerita ringkas ini ialah contoh guru berdasarkan buku.\nBahan: Rangka empat ayat","aids_and_pak21_original":"BBM/ABM: Rangka empat ayat\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."},{"phase_original":"Langkah 4\nCuba dengan rakan","execution_original":"Tindakan guru: Guru beri rangka cerita dengan ruang kata ganda.\nGuru bantu pasangan membaca ayat satu demi satu.\nTindakan murid: Murid melengkapkan merayau-rayau dan mengiau-ngiau.\nMurid menceritakan semula cerita pendek kepada pasangan.\nSemakan: Gunakan kad bantuan mengikut keperluan.\nBahan: Rangka cerita\nBuku teks","aids_and_pak21_original":"BBM/ABM: Rangka cerita\nBuku teks\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."},{"phase_original":"Langkah 5\nTulis cerita sendiri","execution_original":"Tindakan guru: Guru minta murid menulis cerita dengan bantuan rangka.\nGuru semak urutan cerita dan kata ganda.\nTindakan murid: Murid menulis empat ayat sebagai cerita pendek.\nMurid membaca semula cerita yang ditulis.\nSemakan: Tidak perlu menghasilkan karangan panjang.\nBahan: Buku latihan\nRangka cerita","aids_and_pak21_original":"BBM/ABM: Buku latihan\nRangka cerita\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."},{"phase_original":"Langkah 6\nPenutup","execution_original":"Tindakan guru: Guru baca semula pengakhiran cerita.\nGuru tanya perasaan Amira selepas menerima kucingnya.\nTindakan murid: Murid berkongsi jawapan pendek.\nMurid menyebut semula dua kata ganda.\nSemakan: Kukuhkan ejaan kata ganda.\nBahan: Kad perkataan","aids_and_pak21_original":"BBM/ABM: Kad perkataan\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."}],"differentiation_original":{"peneroka":{"label":"Langkah 1\nPeneroka — Bantuan tambahan","implementation_original":"Tugasan: Melengkapkan cerita dengan kad kata ganda.\nBahan: Cerita empat ayat dengan ruang kosong\nKad merayau-rayau dan mengiau-ngiau\nBimbingan guru: Guru baca satu ayat dahulu.\nGuru tunjuk gambar untuk membantu pilihan kata.\nLangkah murid: Pilih kad untuk ruang kosong.\nBaca cerita bersama guru.\nTulis cerita dengan merujuk rangka lengkap.\nHasil individu: Cerita pendek berpandu.\nKriteria: Kata ganda sesuai dengan perbuatan Si Tompok.\nSusulan: Ulang bacaan dua ayat tengah sebelum menulis.","aids_and_pak21_original":"BBM/ABM: Cerita empat ayat dengan ruang kosong\nKad merayau-rayau dan mengiau-ngiau\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."},"pembina":{"label":"Langkah 1\nPembina — Latihan utama","implementation_original":"Tugasan: Menulis cerita pendek menggunakan dua kata ganda.\nBahan: Rangka empat ayat\nBuku teks\nBimbingan guru: Guru semak urutan hilang, ditemui dan dipulangkan.\nGuru bantu ejaan kata ganda apabila perlu.\nLangkah murid: Ceritakan kepada rakan.\nLengkapkan rangka sendiri.\nTulis dan baca semula cerita.\nHasil individu: Karangan pendek empat ayat.\nKriteria: Cerita tersusun dan dua kata ganda sesuai.\nSusulan: Bimbing pembetulan ejaan yang belum tepat.","aids_and_pak21_original":"BBM/ABM: Rangka empat ayat\nBuku teks\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."},"pencabar":{"label":"Langkah 1\nPencabar — Latihan tambahan","implementation_original":"Tugasan: Menambah satu ayat menggunakan mengusap-usap.\nBahan: Gambar akhir\nKad mengusap-usap\nBimbingan guru: Guru tunjuk Elis menghulurkan tangan kepada kucing.\nGuru beri awal ayat “Elis mengusap-usap...”\nLangkah murid: Lihat gambar akhir.\nBina satu ayat tentang mengusap kucing.\nTambah ayat jika sesuai dengan cerita.\nHasil individu: Satu ayat tambahan dalam karangan.\nKriteria: Kata ganda digunakan mengikut gambar.\nSusulan: Beri peluang membaca cerita kepada rakan.","aids_and_pak21_original":"BBM/ABM: Gambar akhir\nKad mengusap-usap\nPAK-21: Cerita berpasangan sebelum menulis cerita sendiri."}},"pbd_original":{"Kaedah Pentaksiran":"Semakan cerita dalam buku latihan.","Evidens":"Cerita pendek setiap murid.","Kriteria Kejayaan":"Cerita menggunakan dua kata ganda yang sesuai dan mengikut urutan."},"closure_original":"Tindakan guru: Guru baca semula pengakhiran cerita.\nGuru tanya perasaan Amira selepas menerima kucingnya.\nTindakan murid: Murid berkongsi jawapan pendek.\nMurid menyebut semula dua kata ganda.\nSemakan: Kukuhkan ejaan kata ganda.\nBahan: Kad perkataan","reflection_original":"__ daripada __ murid dapat menulis cerita pendek menggunakan kata ganda. Murid yang memerlukan bantuan: __.","source_file_path":"RPH-Semua-Subjek-FormatHub/bm-year2-source-review-r2/BM2-M37-S5.docx","source_docx_sha256":"259c1ddb2364d2198a0a8c1b3e7155ff0c54ecc83575b8bb49d97d0f5000e400","source_identity_raw":{"subject":"Subjek","class_year":"Kelas / Tahun 1","date":"2026-10-05"},"metadata_for_import":{"subject_key":"bm","year":2,"academic_year":2026,"week_no":37,"session_no":5,"lesson_date":null,"class_id":null,"teacher_id":null,"duration_minutes":60},"lesson_map_review_status":"needs_review","import_status":"DRAFT_CANDIDATE_ONLY","approved":false}}]};

function response(body,status=200){
 return Response.json(body,{status,headers:{'cache-control':'private, no-store, max-age=0','vary':'Authorization','x-content-type-options':'nosniff'}});
}
export async function onRequestGet({request,env}){
 const bearer=String(request.headers.get('authorization')||'');
 if(!/^Bearer \S+$/.test(bearer))return response({error:'Login diperlukan'},401);
 if(!env?.SUPABASE_URL||!env?.SUPABASE_ANON_KEY)return response({error:'Konfigurasi pengesahan tidak tersedia'},503);
 const headers={authorization:bearer,apikey:env.SUPABASE_ANON_KEY};
 try{
  const userResponse=await fetch(env.SUPABASE_URL+'/auth/v1/user',{headers,cache:'no-store'});
  if(!userResponse.ok)return response({error:'Sesi login tidak sah'},401);
  const profile=await userResponse.json();
  if(!profile?.id||!profile?.email)return response({error:'Identiti pengguna tidak lengkap'},401);
  const url=env.SUPABASE_URL+'/rest/v1/authorized_users?select=role,status&email=eq.'+encodeURIComponent(profile.email)+'&limit=1';
  const permission=await fetch(url,{headers,cache:'no-store'});
  if(!permission.ok)return response({error:'Akses admin gagal disahkan'},403);
  const rows=await permission.json();
  if(!Array.isArray(rows)||!rows.some(x=>x.role==='admin'&&x.status==='allowed'))return response({error:'Semakan draf Hermes hanya untuk admin RPH Hub'},403);
  return response(HERMES_CANDIDATES);
 }catch(e){
  return response({error:'Sambungan pengesahan tidak tersedia; sila cuba lagi'},503);
 }
}
